@charset "utf-8";

    :root{
      /* ── VocabuQuiz Design System v2 ── */
      --bg:#f8fafc;
      --panel:#ffffff;
      --panel2:#f1f5f9;
      --text:#1e293b;
      --muted:rgba(30,41,59,.5);
      --border:rgba(0,0,0,.08);
      --shadow:0 2px 8px rgba(0,0,0,.06), 0 1px 2px rgba(0,0,0,.04);
      --bar-bg:rgba(248,250,252,.92);
      --bar-text:#1e293b;
      --bar-border:rgba(0,0,0,.08);
      --chip-bg:rgba(255,255,255,.95);
      --chip-text:#334155;
      --input-bg:#ffffff;
      --input-text:#1e293b;
      --input-border:rgba(0,0,0,.12);
      --btn-bg:#ffffff;
      --btn-text:#1e293b;
      --btn-border:rgba(0,0,0,.12);
      --inverse-text:#f8fafc;
      --chart-grid:rgba(99,102,241,.08);
      --chart-axis:rgba(99,102,241,.15);
      --chart-label:#64748b;
      --chart-line:#6366f1;
      --chart-bar:#6366f1;
      --chart-bar-bg:rgba(99,102,241,.1);
      --chart-area:rgba(99,102,241,.12);
      --chart-track:rgba(0,0,0,.06);
      --chart-dot-stroke:#ffffff;
      --chart-value:#334155;

      --accent:#6366f1;
      --accent-hover:#4f46e5;
      --accent-light:rgba(99,102,241,.1);
      --radius:12px;
      --radius-sm:8px;
      --radius-lg:16px;
      --fade:.15s;
      --ok:#16a34a;
      --ng:#dc2626;
      --okbg:rgba(34,197,94,.1);
      --ngbg:rgba(239,68,68,.1);
      --maru:#22c55e;
      --batsu:#ef4444;
      --quiz-mark-correct:#22c55e;
      --quiz-mark-correct-bg:rgba(34,197,94,.12);
      --quiz-mark-wrong:#ef4444;
      --quiz-mark-wrong-bg:rgba(239,68,68,.12);
      --quiz-font-scale:1;
      --ui-font-scale:1;
      --base-font-size:16px;

      /* Semantic colors */
      --primary:#6366f1;
      --primary-hover:#4f46e5;
      --primary-light:rgba(99,102,241,.1);
      --success:#22c55e;
      --success-light:rgba(34,197,94,.1);
      --danger:#ef4444;
      --danger-light:rgba(239,68,68,.1);
      --warning:#f59e0b;
      --warning-light:rgba(245,158,11,.1);
      --info:#3b82f6;
      --info-light:rgba(59,130,246,.1);

      --hairline:var(--border);
      --glass:var(--panel);
      --glass-strong:var(--panel);
      --focus:rgba(99,102,241,.25);
    }
    :root[data-theme-mode="dark"]{
      --bg:#0f172a;
      --panel:#1e293b;
      --panel2:#1e293b;
      --text:#f1f5f9;
      --muted:rgba(241,245,249,.55);
      --border:rgba(255,255,255,.1);
      --shadow:0 8px 30px rgba(0,0,0,.4);
      --bar-bg:rgba(15,23,42,.9);
      --bar-text:#f1f5f9;
      --bar-border:rgba(255,255,255,.1);
      --chip-bg:rgba(255,255,255,.08);
      --chip-text:rgba(241,245,249,.9);
      --input-bg:rgba(255,255,255,.06);
      --input-text:#f1f5f9;
      --input-border:rgba(255,255,255,.14);
      --btn-bg:linear-gradient(180deg, var(--legacy-surface), var(--legacy-surface-soft));
      --btn-text:#f5f5f7;
      --btn-border:rgba(255,255,255,.14);
      --inverse-text:#f5f5f7;
      --chart-grid:rgba(216,225,255,.12);
      --chart-axis:rgba(216,225,255,.18);
      --chart-label:rgba(226,232,240,.76);
      --chart-line:rgba(216,225,255,.96);
      --chart-bar:rgba(216,225,255,.88);
      --chart-bar-bg:rgba(216,225,255,.12);
      --chart-area:rgba(216,225,255,.14);
      --chart-track:rgba(255,255,255,.08);
      --chart-dot-stroke:rgba(15,23,42,.98);
      --chart-value:rgba(226,232,240,.88);

      --accent:#818cf8;
      --accent-hover:#6366f1;
      --accent-light:rgba(129,140,248,.15);
      --ok:#4ade80;
      --ng:#f87171;
      --okbg:rgba(34,197,94,.2);
      --ngbg:rgba(239,68,68,.2);
      --primary:#818cf8;
      --primary-hover:#6366f1;
      --primary-light:rgba(129,140,248,.15);
      --success:#4ade80;
      --success-light:rgba(74,222,128,.15);
      --danger:#f87171;
      --danger-light:rgba(248,113,113,.15);
      --warning:#fbbf24;
      --warning-light:rgba(251,191,36,.15);
      --info:#60a5fa;
      --info-light:rgba(96,165,250,.15);
      --hairline:var(--border);
      --glass:var(--panel);
      --glass-strong:var(--panel2);
      --focus:rgba(129,140,248,.25);
    }
    :root[data-font-size="SMALL"]{
      --quiz-font-scale:.88;
      --ui-font-scale:.92;
      --base-font-size:15px;
    }
    :root[data-font-size="DEFAULT"]{
      --quiz-font-scale:1;
      --ui-font-scale:1;
      --base-font-size:16px;
    }
    :root[data-font-size="LARGE"]{
      --quiz-font-scale:1.2;
      --ui-font-scale:1.16;
      --base-font-size:18px;
    }

    /* ── Low-perf mode: 低スペ端末自動検知時のみ適用 ── */
    body.low-perf *,body.low-perf *::before,body.low-perf *::after{backdrop-filter:none !important;-webkit-backdrop-filter:none !important;}
    /* ★ かつて ここに animation-duration:.08s !important が あった。
       これが 低スペック端末で Lumi の フチが **チカチカする 真因**（2026-08-27）。
       すべての 要素に かかるので、繰り返す 飾り（infinite）は
       周期が 0.08 秒 ＝ **1 秒に 12.5 回**の 明滅に なっていた。
       画面いっぱいの 光が この速さで 明滅するのは 気持ち悪いだけでなく、
       光の 過敏（3〜30Hz）の 範囲に 入る。
       そもそも 動きを 短くしても 描き直しは 減らない。むしろ 1 秒あたりの
       仕事は 増える。軽くしたいなら 止めるのが 正しい。 */
    body.low-perf *{transition-duration:.08s !important;}
    /* 繰り返す 飾りを 止めるのは **その飾りを 持っている ファイル側**でやる
       （ここで まとめて 止めると 読み込み中の ぐるぐるまで 止まり、
         固まったように 見える）。Lumi の フチは vq-live 側で 止めている。 */
    body.low-perf .sede-preview-frame{will-change:auto !important;}
    @media (prefers-reduced-motion:reduce){
      *,*::before,*::after{animation-duration:.01s !important;transition-duration:.01s !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;}
    }

    *{ box-sizing:border-box; }
    html,body{ height:100%; }
    /* ══ 地色は **1 か所**にまとめる ══════════════════════════════════
       ここが食い違うと、面が届かない所に **色の違う帯**が残る。
       実機の写真を測ったら、下 56pt がまるごと #0f172a（旧 --bg のダーク）で、
       その上の画面は明るい #fcfbfe だった（実測 2026-08-13）。

       食い違っていたのは 3 つ:
         body            … var(--bg)   … 明 #f8fafc / 暗 #0f172a
         body[data-ui-v2] … #f5f5f7    … 直書き
         新しい画面       … --vq-bg-canvas … 明 #F7F6FB / 暗 #131218
       いまはぜんぶ --vq-bg-canvas（:root で明暗が切り替わる）に寄せる。

       html にも同じ色を置く。html が透明のままだと body の色が
       画面全体へ持ち上げられるので今までも同じ見た目になっていたが、
       body に overflow や transform が付いた瞬間にその持ち上げが止まり、
       白（既定）が出る。明示しておけばその抜けが起きない。 */
    html{
      font-size: var(--base-font-size);
      background-color: var(--vq-bg-canvas, var(--bg));
    }
    body{
      margin:0;
      background-color: var(--vq-bg-canvas, var(--bg));
      color:var(--text);
      font-size:1rem;
      font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", system-ui, "Hiragino Sans", "Hiragino Kaku Gothic ProN", "Noto Sans JP", sans-serif;
      -webkit-font-smoothing:antialiased;
      -moz-osx-font-smoothing:grayscale;
      letter-spacing: -0.01em;
    }
    button,
    input,
    select,
    textarea{
      font-size: inherit;
    }

    :root[data-animations="off"]{
      scroll-behavior:auto !important;
    }
    :root[data-animations="off"] *,
    :root[data-animations="off"] *::before,
    :root[data-animations="off"] *::after{
      animation:none !important;
      transition:none !important;
      transition-duration:0s !important;
      animation-duration:0s !important;
      animation-delay:0s !important;
      scroll-behavior:auto !important;
    }

    .app{
      min-height:100%;
      display:flex;
      flex-direction:column;
      align-items:center;
    }

    .topbar{
      width:100%;
      max-width:980px;
      padding:14px 18px;
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap:10px;
    }

    .brand{
      display:flex;
      align-items:baseline;
      gap:10px;
      min-width:0;
    }
    .brand-title{
      font-weight:650;
      letter-spacing:.02em;
      color:var(--accent);
      cursor:pointer;
      white-space:nowrap;
      overflow:hidden;
      text-overflow:ellipsis;
    }
    .brand-sub{
      font-size:12px;
      color:var(--muted);
      white-space:nowrap;
      overflow:hidden;
      text-overflow:ellipsis;
    }

    .icon-btn{
      appearance:none;
      border:1px solid var(--border);
      background:var(--panel);
      color:var(--accent);
      border-radius:999px;
      position:relative;
      width:40px;
      height:40px;
      display:inline-flex;
      align-items:center;
      justify-content:center;
      cursor:pointer;
      box-shadow: 0 1px 3px rgba(0,0,0,.04), 0 0 0 0.5px rgba(0,0,0,.03);
      transition: transform .2s cubic-bezier(.22,1,.36,1), opacity var(--fade) ease, background var(--fade) ease, box-shadow .2s ease;
    }
    .icon-btn:hover{ box-shadow: 0 2px 8px rgba(0,0,0,.08), 0 0 0 0.5px rgba(0,0,0,.04); }
    .icon-btn:active{ transform: scale(.96); }
    .icon-btn[disabled]{ opacity:.45; cursor:not-allowed; }

    /* ===== Phase 1 Frame Refresh ===== */
    .topbar{
      position:sticky;
      top:0;
      display:block;
      z-index:50;
      width:100%;
      max-width:none;
      padding: 10px 14px;
      border-bottom: 1px solid var(--bar-border);
      background: var(--bar-bg);
    }
    @supports (backdrop-filter: blur(1px)){
      .topbar{ backdrop-filter: blur(10px); }
    }
    .topbar-inner{
      width:100%;
      max-width: 1040px;
      margin:0 auto;
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap:12px;
    }
    .topbar-left{
      display:flex;
      align-items:center;
      gap:12px;
      min-width:0;
    }
    .topbar-actions{
      display:flex;
      align-items:center;
      gap:10px;
    }
    /* Hide topbar when chat sidebar is open — sidebar overlaps topbar */
    body.chat-sidebar-open #topbar{ opacity:0 !important; pointer-events:none !important; transition:opacity .2s ease !important; }

    /* Chat-only topbar buttons: hidden by default, shown on chat tab */
    .topbar-chat-btns{ display:none !important; align-items:center; gap:8px; margin-left:auto; }
    body[data-app-tab="chat"] .topbar-chat-btns{ display:flex !important; }
    body[data-app-tab="chat"] .vq-topbar-model-wrap{ display:inline-flex !important; }
    body[data-app-tab="chat"] .vq-topbar-model-btn{ display:inline-flex !important; }
    .topbar-chat-sidebar{ flex:0 0 auto; }
    /* Topbar model — hide legacy xselect remnants */
    .topbar-chat-model-select{ display:none !important; }
    .topbar-chat-btns .xselect{ display:none !important; }

    .ms{
      font-family: "Material Symbols Rounded";
      font-weight: 500;
      font-style: normal;
      font-size: 20px;
      line-height: 1;
      display:inline-block;
      letter-spacing: normal;
      text-transform: none;
      white-space: nowrap;
      word-wrap: normal;
      direction: ltr;
      -webkit-font-feature-settings: "liga";
      -webkit-font-smoothing: antialiased;
    }

    .notif-dot{
      position:absolute;
      right:10px;
      top:10px;
      width:8px;
      height:8px;
      border-radius:999px;
      background:#d11f2a;
      box-shadow: 0 0 0 2px var(--panel);
    }

    /* Start view */
    .start-wrap{
      min-height: min(72vh, 620px);
      display:flex;
      align-items:center;
      justify-content:center;
      padding: 28px 0 6px;
    }
    .start-hero{
      width:100%;
      border:1px solid var(--border);
      background: var(--panel);
      border-radius: calc(var(--radius) + 4px);
      padding: 34px 26px 26px;
      box-shadow: var(--shadow);
      text-align:center;
    }
    .start-kicker{
      font-size:12px;
      letter-spacing:.18em;
      text-transform:uppercase;
      color:var(--muted);
      margin-bottom:10px;
    }
    .start-title{
      margin:0;
      font-size: clamp(40px, 6vw, 64px);
      font-weight: 760;
      letter-spacing: .02em;
      color: var(--accent);
      line-height:1.04;
    }
    .start-sub{
      margin: 14px auto 0;
      max-width: 52ch;
      color: var(--muted);
      font-size: 14px;
      line-height: 1.7;
    }
    .start-actions{
      margin-top: 22px;
      display:flex;
      justify-content:center;
    }
    .start-primary{
      appearance:none;
      border:1px solid rgba(31,42,68,.22);
      background: linear-gradient(180deg, rgba(31,42,68,.10), rgba(31,42,68,.06));
      color: var(--accent);
      border-radius: 999px;
      padding: 12px 18px;
      font-weight: 700;
      letter-spacing: .01em;
      cursor:pointer;
      display:inline-flex;
      align-items:center;
      gap:10px;
      box-shadow: 0 10px 24px rgba(17,18,20,.08);
      transition: transform var(--fade) ease, box-shadow var(--fade) ease, background var(--fade) ease, border-color var(--fade) ease;
    }
    .start-primary:hover{
      border-color: rgba(31,42,68,.34);
      box-shadow: 0 12px 30px rgba(17,18,20,.10);
    }
    .start-primary:active{ transform: translateY(1px) scale(.99); }
    .start-note{
      margin-top: 18px;
      display:flex;
      gap:8px;
      justify-content:center;
      flex-wrap:wrap;
    }
    /* ── start-chip: VQ Design System v2 ── */
    .start-chip{
      display:inline-flex;align-items:center;gap:4px;
      font-size:12px;
      font-weight:500;
      color: var(--text-sub, #64748b);
      border:1px solid var(--border);
      background: var(--chip-bg);
      border-radius:var(--radius-full, 9999px);
      padding: 5px 12px;
      transition:all .15s ease;
    }

    /* Notifications */
    .notify-sheet{ max-width: 720px; }
    .notify-body{ padding-top: 12px; }
    .notify-list{ display:flex; flex-direction:column; gap:10px; }
    .notify-pane.hidden{ display:none; }
    .notify-item{
      border:1px solid var(--border);
      border-radius: var(--radius, 12px);
      padding: 12px 12px;
      background: var(--panel);
      box-shadow: 0 2px 10px rgba(17,18,20,.04);
      display:grid;
      gap:8px;
    }
    .notify-item.unread{
      border-color: rgba(31,42,68,.26);
      background: rgba(31,42,68,.04);
    }
    .notify-title{
      font-weight: 720;
      letter-spacing:.01em;
      color: var(--accent);
      margin:0;
      font-size: 14px;
      line-height: 1.35;
    }
    .notify-bodytext{
      margin:6px 0 0;
      color: var(--text);
      font-size: 13px;
      line-height: 1.6;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
      word-break: break-word;
    }
    .notify-time{
      margin-top:8px;
      color: var(--muted);
      font-size: 12px;
      display:flex;
      align-items:center;
      gap:6px;
    }
    .notify-actions{
      margin-top: 4px;
      display:flex;
      justify-content:flex-end;
    }
    .notify-detail-wrap{
      display:grid;
      gap:10px;
      min-height: 160px;
    }
    .notify-detail-head{
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap:10px;
      flex-wrap: wrap;
    }
    .notify-detail-title{
      margin:0;
      font-weight: 760;
      color: var(--accent);
      font-size: 16px;
      line-height: 1.4;
    }
    .notify-detail-meta{
      font-size: 12px;
      color: var(--muted);
      display:flex;
      flex-wrap: wrap;
      gap:8px;
    }
    .notify-detail-content{
      display:grid;
      gap:10px;
    }
    .notify-detail-content h3{
      margin: 6px 0 2px;
      font-size: 15px;
      color: var(--accent);
      letter-spacing: .01em;
    }
    .notify-detail-text{
      color: var(--text);
      font-size: 13px;
      line-height: 1.7;
      word-break: break-word;
    }
    .notify-detail-text.is-small{
      font-size: 12px;
      color: var(--muted);
      line-height: 1.6;
    }
    .notify-detail-text a{
      color: var(--accent);
      text-decoration: underline;
      text-underline-offset: 2px;
    }
    .notify-invalid{
      font-size: 12px;
      color: #b42318;
      border: 1px solid rgba(180,35,24,.22);
      background: rgba(180,35,24,.06);
      border-radius: 10px;
      padding: 7px 10px;
    }
    .notify-media{
      display:grid;
      gap:6px;
    }
    .notify-media img{
      width:100%;
      max-width:100%;
      height:auto;
      border-radius: 12px;
      border:1px solid var(--border);
      display:block;
      background:var(--panel);
    }
    .notify-video{
      border:1px solid var(--border);
      border-radius: 12px;
      background: var(--panel);
      overflow: hidden;
    }
    .notify-video-screen{
      width:100%;
      display:block;
      background:var(--panel2);
    }
    .notify-video-controls{
      display:grid;
      gap:8px;
      padding:10px;
    }
    .notify-video-row{
      display:flex;
      align-items:center;
      gap:8px;
      flex-wrap: wrap;
    }
    .notify-video-time{
      font-size:12px;
      color: var(--muted);
      min-width: 76px;
      text-align: right;
      font-variant-numeric: tabular-nums;
    }
    .notify-video-seek{
      width:100%;
    }
    .notify-empty{
      color: var(--muted);
      font-size: 13px;
      padding: 14px 6px;
    }

    main{
      width:100%;
      max-width:980px;
      padding: 0 18px 110px;
      display:flex;
      justify-content:center;
    }

    .stage{
      width:100%;
      max-width:720px;
    }

    .view{ display:none; }
    .view.active{ display:block; }

    /* Title view */
    .hero{
      background: linear-gradient(180deg, rgba(31,42,68,.06), rgba(31,42,68,0) 62%);
      border:1px solid var(--border);
      border-radius: var(--radius);
      padding: 22px 22px 20px;
      box-shadow: var(--shadow);
      overflow:hidden;
      position:relative;
    }
    .hero::after{
      content:"";
      position:absolute;
      inset:-40% -30%;
      background: radial-gradient(closest-side, rgba(31,42,68,.10), rgba(31,42,68,0));
      opacity:.45;
      pointer-events:none;
    }

    .h1{
      margin:0;
      font-size:26px;
      font-weight:720;
      letter-spacing:.02em;
      color:var(--accent);
    }
    .subtitle{
      margin:10px 0 0;
      color:var(--muted);
      font-size:14px;
      line-height:1.6;
    }

    .section{
      margin-top:14px;
      display:flex;
      flex-direction:column;
      gap:10px;
    }
    .section-title{
      font-size:12px;
      color:var(--muted);
      letter-spacing:.08em;
      text-transform:uppercase;
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap:10px;
    }
    .section-title .right{
      font-size:12px;
      color:var(--muted);
      letter-spacing:normal;
      text-transform:none;
    }

    .actions{
      margin-top:8px;
      display:grid;
      grid-template-columns: 1fr 1fr;
      gap:10px;
    }
    @media (max-width:520px){
      .actions{ grid-template-columns:1fr; }
    }

    .btn{
      appearance:none;
      border:1px solid var(--border);
      background:var(--panel);
      color:var(--text);
      border-radius: var(--radius-sm);
      padding: 14px 16px;
      cursor:pointer;
      text-align:left;
      box-shadow: 0 1px 3px rgba(0,0,0,.04), 0 0 0 0.5px rgba(0,0,0,.03);
      transition: transform .2s cubic-bezier(.22,1,.36,1), border-color var(--fade) ease, opacity var(--fade) ease, box-shadow .2s ease;
      display:flex;
      flex-direction:column;
      gap:4px;
      min-height:58px;
    }
    .btn:hover{ border-color: rgba(0,0,0,.12); box-shadow: 0 2px 10px rgba(0,0,0,.07), 0 0 0 0.5px rgba(0,0,0,.04); }
    .btn:active{ transform: scale(.98); }
    .btn[disabled]{ opacity:.45; cursor:not-allowed; }

    .btn .label{
      font-weight:650;
      letter-spacing:.01em;
      color:var(--accent);
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap:10px;
    }
    .btn .desc{
      font-size:12px;
      color:var(--muted);
      line-height:1.5;
    }

    .fineprint{
      margin-top:14px;
      font-size:12px;
      color:var(--muted);
      line-height:1.6;
      display:flex;
      align-items:flex-start;
      gap:8px;
    }
    /* ── badge: VQ Design System v2 ── */
    .badge{
      display:inline-flex;align-items:center;gap:4px;
      border:none;
      background: var(--accent-light, rgba(99,102,241,.1));
      border-radius:var(--radius-full, 9999px);
      padding:3px 10px;
      font-size:11px;
      font-weight:600;
      color:var(--accent, #6366f1);
      white-space:nowrap;
    }

    /* ── Seg (tabs): VQ Design System v2 ── */
    .seg{
      display:inline-flex;
      border:1px solid var(--border);
      border-radius:var(--radius, 12px);
      overflow:hidden;
      background: rgba(0,0,0,.04);
      flex-shrink:0;
      padding: 3px;
      gap: 2px;
    }
    .seg button{
      appearance:none;
      border:0;
      background:transparent;
      padding:8px 14px;
      font-size:12px;
      cursor:pointer;
      color:var(--muted);
      border-radius:var(--radius-sm, 8px);
      transition: all .15s ease;
      white-space:nowrap;
      font-weight:500;
    }
    .seg button.active{
      background: var(--panel);
      color: var(--text);
      font-weight:600;
      box-shadow: 0 1px 3px rgba(0,0,0,.06);
    }

    /* Quiz view */
    .quiz-header{
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap:12px;
      margin: 4px 2px 10px;
    }
    /* ── pill: VQ Design System v2 ── */
    .pill{
      display:inline-flex;align-items:center;gap:4px;
      border:1px solid var(--border);
      border-radius:var(--radius-full, 9999px);
      padding:5px 12px;
      font-size:12px;
      font-weight:500;
      color:var(--text-sub, #64748b);
      background: var(--chip-bg);
      white-space:nowrap;
      transition:all .15s ease;
    }
    .progress{
      font-size:12px;
      color:var(--muted);
      display:flex;
      align-items:center;
      gap:10px;
      min-width:0;
    }
    .progress strong{ color:var(--accent); }

    .card{
      position:relative;
      overflow:hidden;
      border:1px solid var(--border);
      border-radius: var(--radius);
      background:var(--panel);
      box-shadow: 0 2px 12px rgba(0,0,0,.04), 0 0 0 0.5px rgba(0,0,0,.02);
      padding: 20px 20px 18px;
      transition: opacity var(--fade) ease, transform .25s cubic-bezier(.22,1,.36,1), box-shadow .25s ease;
    }
    .card.fade-out{
      opacity:0;
      transform: translateY(2px);
    }

    .mark-layer{
      position:absolute;
      top:10px;
      right:10px;
      width:74px;
      height:74px;
      pointer-events:none;
      opacity:0;
      transform: translateY(-2px) scale(.98);
      transition: opacity .18s ease, transform .18s ease;
      filter: drop-shadow(0 8px 18px rgba(17,18,20,.10));
    }
    .mark-layer.show{
      opacity:1;
      transform: translateY(0) scale(1);
    }
    .mark-layer svg{
      width:100%;
      height:100%;
      display:block;
    }
    .mark-layer .ring{
      fill:none;
      stroke: var(--maru);
      stroke-width:8.5;
      stroke-linecap:round;
      stroke-dasharray: 310;
      stroke-dashoffset: 310;
    }
    .mark-layer .xline{
      stroke: var(--batsu);
      stroke-width:9;
      stroke-linecap:round;
      stroke-dasharray: 120;
      stroke-dashoffset: 120;
    }
    .mark-layer.ok .ring{ animation: drawRing .55s ease forwards; }
    .mark-layer.ng .x1{ animation: drawLine .40s ease forwards; }
    .mark-layer.ng .x2{ animation: drawLine .40s .10s ease forwards; }

    @keyframes drawRing{ to{ stroke-dashoffset: 0; } }
    @keyframes drawLine{ to{ stroke-dashoffset: 0; } }

    .meta{
      display:flex;
      justify-content:space-between;
      align-items:baseline;
      gap:10px;
      margin-bottom:10px;
    }
    .no{
      font-size:12px;
      color:var(--muted);
    }
    .dir{
      font-size:12px;
      color:var(--muted);
      white-space:nowrap;
      display:flex;
      align-items:center;
      gap:8px;
    }
    .judge{
      font-size:11px;
      padding:3px 8px;
      border-radius:999px;
      border:1px solid rgba(31,42,68,.16);
      background: var(--chip-bg);
      color: var(--muted);
    }
    .judge.ok{
      border-color: rgba(15,81,50,.22);
      background: var(--okbg);
      color: var(--ok);
      font-weight:650;
    }
    .judge.ng{
      border-color: rgba(132,32,41,.22);
      background: var(--ngbg);
      color: var(--ng);
      font-weight:650;
    }

    .prompt{
      font-size:26px;
      font-weight:720;
      letter-spacing:.02em;
      line-height:1.2;
      color:var(--text);
      word-break:break-word;
    }

    .answer-wrap{
      margin-top:14px;
      padding-top:14px;
      border-top:1px dashed rgba(31,42,68,.18);
    }
    .answer-label{
      font-size:11px;
      text-transform:uppercase;
      letter-spacing:.10em;
      color:var(--muted);
      margin-bottom:6px;
    }
    .answer{
      font-size:18px;
      line-height:1.55;
      color:var(--accent);
      word-break:break-word;
    }
    .prompt{
      font-size: calc(26px * var(--quiz-font-scale));
    }
    .answer{
      font-size: calc(18px * var(--quiz-font-scale));
    }
    #yourText{
      font-size: calc(13px * var(--quiz-font-scale)) !important;
    }
    #spellInput{
      font-size: calc(16px * var(--quiz-font-scale));
    }
    .hidden{ display:none !important; }

    .prompt-diagram-wrap{
      margin-bottom: 12px;
      border: 1px solid var(--border);
      border-radius: 12px;
      background: var(--panel2);
      padding: 8px;
    }
    .prompt-diagram-wrap img{
      width: 100%;
      height: auto;
      max-height: 220px;
      object-fit: contain;
      display: block;
      border-radius: 10px;
      background: var(--panel);
      border: 1px solid var(--border);
    }

    .math-symbol-row{
      display: flex;
      gap: 8px;
      overflow-x: auto;
      padding-bottom: 2px;
      -webkit-overflow-scrolling: touch;
    }
    .math-symbol-row .textbtn{
      min-height: 34px;
      height: 34px;
      padding: 6px 10px;
      border-radius: 999px;
      white-space: nowrap;
      font-size: 12px;
      font-weight: 650;
    }
    .math-symbol-row .textbtn:focus-visible{
      outline: 2px solid color-mix(in srgb, var(--accent) 42%, transparent);
      outline-offset: 1px;
    }
    /* DRAW_EDITOR_V1 */
    .math-diagram-toolbar{
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
    }
    /* DRAW_EDITOR_V2V3 */
    .math-diagram-toolgroup{
      display: grid;
      gap: 6px;
    }
    .math-diagram-toolbar-wrap{
      padding: 10px 12px;
      border-bottom: 1px solid var(--border);
      background: var(--panel);
      display: grid;
      gap: 10px;
    }
    .math-diagram-editops{
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      flex-wrap: wrap;
      padding: 8px 10px;
      border: 1px dashed var(--border);
      border-radius: 10px;
      background: var(--panel2);
    }
    .math-diagram-opts{
      display:flex;
      gap:12px;
      align-items:center;
      flex-wrap:wrap;
    }
    .math-diagram-editops .textbtn{
      min-height: 34px;
      height: 34px;
      padding: 6px 10px;
      border-radius: 10px;
      font-size: 12px;
    }
    .math-diagram-toolbar .textbtn.is-active{
      border-color: color-mix(in srgb, var(--accent) 42%, var(--border));
      background: color-mix(in srgb, var(--accent) 10%, var(--panel2));
      color: var(--text);
    }
    .math-diagram-canvas-wrap{
      border: 1px solid var(--border);
      border-radius: 0;
      background: var(--panel2);
      padding: 10px;
      flex: 1 1 auto;
      min-height: 240px;
      overflow: hidden;
    }
    /* DRAW_EDITOR_V2V3 */
    .math-diagram-canvas-wrap.is-debug{
      box-shadow: inset 0 0 0 1px rgba(220,80,80,.35);
      outline: 1px dashed rgba(220,80,80,.5);
      outline-offset: -2px;
    }
    .math-diagram-backdrop{
      display: none !important;
    }
    #mathDiagramSection{
      position: fixed;
      z-index: 99995;
      inset: 0;
      transform: none;
      width: 100vw;
      height: 100dvh;
      max-height: none;
      overflow: hidden;
      box-shadow: none;
      background: var(--panel);
      border-radius: 0;
      padding: 0 !important;
      display: flex;
      flex-direction: column;
    }
    .math-diagram-header{
      position: sticky;
      top: 0;
      z-index: 2;
      display: grid;
      grid-template-columns: auto 1fr auto;
      align-items: center;
      gap: 10px;
      padding: 10px 12px;
      background: var(--panel);
      border-bottom: 1px solid var(--border);
    }
    .math-diagram-headmeta{
      min-width: 0;
      display: grid;
      gap: 2px;
    }
    .math-diagram-title{
      font-size: 16px;
      font-weight: 700;
      line-height: 1.2;
    }
    #mathDiagramStatus.ok{
      color: #198754;
    }
    #mathDiagramStatus.error{
      color: #b42318;
    }
    #mathDiagramCanvas{
      width: 100%;
      height: 100%;
      display: block;
      border-radius: 10px;
      background: #ffffff;
      border: 1px solid var(--border);
      touch-action: none;
      cursor: crosshair;
    }
    #mathDiagramCanvas.is-tool-select{ cursor: move; }
    #mathDiagramCanvas.is-tool-pan{ cursor: grab; }
    #mathDiagramCanvas.is-tool-eraser{ cursor: cell; }
    #mathDiagramCanvas.is-tool-point{ cursor: copy; }
    .math-diagram-footer{
      border-top: 1px solid var(--border);
      padding: 8px 12px calc(8px + env(safe-area-inset-bottom, 0px));
      background: var(--panel);
      min-height: 38px;
      display: flex;
      align-items: center;
    }
    body.math-diagram-open{
      overflow: hidden;
      touch-action: none;
    }
    @media (max-width: 640px){
      #mathDiagramSection{
        width: 100vw;
        height: 100dvh;
      }
      .math-diagram-toolbar-wrap{
        gap: 8px;
        padding: 8px;
      }
      .math-diagram-toolbar{
        flex-wrap: nowrap;
        overflow-x: auto;
        -webkit-overflow-scrolling: touch;
      }
      .math-diagram-editops{
        padding: 8px;
      }
      .math-diagram-editops .textbtn{
        min-height: 32px;
        height: 32px;
        padding: 5px 8px;
      }
      .math-diagram-opts{
        gap: 8px;
      }
    }

    /* Preset/Auth forms: back to compact usable size */
    #presetOverlay .spell-input,
    #presetOverlay .select,
    #presetOverlay input[type="text"],
    #presetOverlay input[type="search"],
    #presetOverlay input[type="number"],
    #presetOverlay textarea,
    #presetOverlay select{
      min-height: 44px !important;
      font-size: 15px !important;
      padding: 10px 12px !important;
    }
    #presetOverlay textarea.spell-input{
      min-height: 112px !important;
    }
    #presetOverlay .navbtn,
    #presetOverlay .textbtn,
    #presetOverlay .btn{
      min-height: 44px !important;
      padding: 10px 14px !important;
      font-size: 15px;
    }
    #authGate .auth-gate-btn,
    #authGate .navbtn,
    #authGate .textbtn{
      min-height: 44px !important;
      padding-top: 10px !important;
      padding-bottom: 10px !important;
    }
    #authGate .spell-input,
    #authGate .select{
      min-height: 44px !important;
      font-size: 15px !important;
    }

    .hand-wrap{
      margin-top:12px;
      padding-top:12px;
      border-top:1px dashed rgba(31,42,68,.18);
    }
    .hand-title{
      font-size:11px;
      text-transform:uppercase;
      letter-spacing:.10em;
      color:var(--muted);
      margin-bottom:8px;
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap:10px;
    }
    .hand-title .mini{
      font-size:11px;
      color:var(--muted);
      letter-spacing:normal;
      text-transform:none;
      white-space:nowrap;
    }
    .hand-canvas{
      width:100%;
      height:220px;
      border:1px solid var(--border);
      border-radius:12px;
      background:var(--input-bg);
      display:block;
      touch-action:none;
      box-shadow: 0 2px 10px rgba(17,18,20,.04) inset;
    }
    .hand-controls{
      margin-top:8px;
      display:flex;
      gap:10px;
      flex-wrap:wrap;
      align-items:center;
      justify-content:space-between;
    }
    .hand-controls .left,
    .hand-controls .right{
      display:flex;
      gap:10px;
      flex-wrap:wrap;
      align-items:center;
    }
    .hand-note{
      font-size:12px;
      color:var(--muted);
      line-height:1.5;
    }

    
    .choice-wrap{
      margin-top:12px;
      padding-top:12px;
      border-top:1px dashed rgba(31,42,68,.18);
    }
    .choice-label{
      font-size:11px;
      text-transform:uppercase;
      letter-spacing:.10em;
      color:var(--muted);
      margin-bottom:8px;
    }
    .choices{
      display:grid;
      grid-template-columns: 1fr;
      gap:10px;
    }
    .choice-btn{
      appearance:none;
      border:1px solid var(--border);
      background: var(--panel);
      color: var(--text);
      border-radius: 12px;
      padding: 12px 12px;
      cursor:pointer;
      text-align:left;
      line-height:1.45;
      transition: transform var(--fade) ease, border-color var(--fade) ease, background var(--fade) ease, opacity var(--fade) ease;
      box-shadow: 0 2px 10px rgba(17,18,20,.04);
    }
    .choice-btn:hover{ border-color: rgba(31,42,68,.32); }
    .choice-btn:active{ transform: translateY(1px); }
    .choice-btn[disabled]{ opacity:.70; cursor:not-allowed; }
    .choice-btn.correct{
      border-color: rgba(15,81,50,.24);
      background: var(--okbg);
    }
    .choice-btn.wrong{
      border-color: rgba(132,32,41,.24);
      background: var(--ngbg);
    }
    .choice-btn .k{
      font-size:12px;
      color: var(--muted);
      margin-bottom:4px;
      display:inline-block;
      min-width: 16px;
    }
.spell-wrap{
      margin-top:12px;
      display:flex;
      flex-direction:column;
      gap:8px;
    }
    .spell-row{
      display:flex;
      gap:10px;
      align-items:center;
      flex-wrap:wrap;
    }
    .spell-label{
      font-size:11px;
      text-transform:uppercase;
      letter-spacing:.10em;
      color:var(--muted);
    }
    .spell-input{
      flex:1 1 240px;
      min-width:220px;
      border:1px solid var(--border);
      border-radius:var(--radius-lg, 16px);
      padding:12px 16px;
      font-size:16px;
      line-height:1.2;
      outline:none;
      background:var(--input-bg);
      color:var(--input-text);
      box-shadow: 0 1px 3px rgba(0,0,0,.06), 0 0 0 0.5px rgba(0,0,0,.04);
      transition: border-color .2s ease, box-shadow .2s ease;
