    .controls .right{
      display:flex;
      gap:10px;
      align-items:center;
      flex-wrap:wrap;
    }

    .cta{
      appearance:none;
      border:1px solid rgba(31,42,68,.24);
      background: rgba(31,42,68,.06);
      color:var(--accent);
      border-radius: 999px;
      padding: 10px 14px;
      cursor:pointer;
      font-weight:650;
      letter-spacing:.01em;
      transition: transform var(--fade) ease, background var(--fade) ease, opacity var(--fade) ease;
    }
    .cta:hover{ background: rgba(31,42,68,.085); }
    .cta:active{ transform: translateY(1px); }
    .cta[disabled]{ opacity:.50; cursor:not-allowed; }

    .navbtn{
      appearance:none;
      border:1px solid var(--border);
      background:var(--panel);
      color:var(--text);
      border-radius: 999px;
      padding: 10px 14px;
      cursor:pointer;
      transition: transform var(--fade) ease, opacity var(--fade) ease, border-color var(--fade) ease;
    }
    .navbtn:hover{ border-color: rgba(31,42,68,.32); }
    .navbtn:active{ transform: translateY(1px); }
    .navbtn[disabled]{ opacity:.45; cursor:not-allowed; }

    .hint{
      margin-top:10px;
      font-size:12px;
      color:var(--muted);
      line-height:1.6;
      padding-left:2px;
    }

    .debug-bar{
      margin-top:10px;
      font-size:11px;
      color:var(--muted);
      line-height:1.5;
      padding: 10px 12px;
      border:1px dashed rgba(31,42,68,.18);
      border-radius: var(--radius-sm);
      background: var(--panel2);
