/* =========================================================
   Apple Website UI Refresh (UI-only) v13
   - No logic changes
   - Pure CSS overrides + animations
   ========================================================= */

:root{
  --radius:18px;
  --radius-sm:14px;
  --fade:.32s;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

/* Global typography */
body{
  /* 地色は html と同じ 1 つの値（上の「地色は 1 か所にまとめる」を参照） */
  background-color: var(--vq-bg-canvas, var(--bg));
  color: var(--text);
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "SF Pro Text",
    "SF Pro Display",
    system-ui,
    "Hiragino Sans",
    "Hiragino Kaku Gothic ProN",
    Meiryo,
    sans-serif;
  letter-spacing: -0.01em;
}

a{ color: inherit; }
::selection{ background: rgba(0,0,0,.10); }

/* Layout breathing room */
.topbar{
  padding:18px 18px;
}
.brand-title{
  font-weight: 650;
  letter-spacing: -0.02em;
  color: var(--text);
}
.brand-sub{
  color: var(--muted);
}

/* ── icon-btn: VQ Design System v2 ── */
.icon-btn{
  border:1px solid var(--border);
  background: var(--panel);
  color: var(--text);
  border-radius: var(--radius, 12px);
  box-shadow: var(--shadow);
  transition: all .15s ease;
}
.icon-btn:hover{
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(0,0,0,.1);
  border-color: rgba(0,0,0,.15);
}
.icon-btn:active{
  transform: translateY(0) scale(.97);
}

/* ── Hero: VQ Design System v2 ── */
.hero{
  border:1px solid var(--border);
  background:
    radial-gradient(800px 500px at 20% -10%, rgba(99,102,241,.06), transparent 60%),
    radial-gradient(600px 400px at 80% -5%, rgba(168,85,247,.04), transparent 55%),
    var(--panel);
  box-shadow: var(--shadow);
  border-radius: var(--radius-lg, 16px);
  padding: 32px 28px 24px;
}
.hero::after{ display:none !important; }

.h1{
  font-size: clamp(32px, 4.6vw, 48px);
  line-height: 1.06;
  font-weight: 780;
  letter-spacing: -0.03em;
  color: var(--text);
}
.subtitle{
  font-size: 15px;
  color: var(--muted);
  margin-top: 14px;
}
.section{ margin-top: 18px; gap:12px; }
.section-title{
  color: var(--muted);
  letter-spacing: .14em;
}

/* Mode cards */
/* ── btn: VQ Design System v2 (card-style) ── */
.btn{
  border:1px solid var(--border);
  border-radius:var(--radius-lg,16px);
  background:var(--panel);
  box-shadow:var(--shadow);
  padding:18px 18px;
  min-height:76px;
  transition:all .2s ease;
  will-change:transform;
  cursor:pointer;
}
.btn:hover{
  transform:translateY(-2px);
  box-shadow:0 8px 24px rgba(0,0,0,.1);
  border-color:rgba(0,0,0,.12);
}
.btn:active{
  transform:translateY(0) scale(.98);
}
.btn .label{
  font-size:15px;
  font-weight:700;
  letter-spacing:-0.02em;
  color:var(--text);
}
.btn .desc{
  font-size:13px;
  color:var(--muted);
}

/* Quiz header pills */
.quiz-header{
  display:grid;
  grid-template-columns: 1fr auto 1fr;
  align-items:center;
  gap:12px;
  margin: 10px 0 18px;
}
@media (max-width:520px){
  .quiz-header{
    grid-template-columns: 1fr;
    justify-items: stretch;
    gap:10px;
    margin: 10px 0 14px;
  }
}

.progress, .pill{
  border:1px solid var(--hairline);
  background: var(--glass-strong);
  box-shadow: 0 10px 30px rgba(0,0,0,.10);
}
@supports ((-webkit-backdrop-filter: blur(1px)) or (backdrop-filter: blur(1px))){
  .progress, .pill{
    background: var(--glass);
    -webkit-backdrop-filter: blur(14px) saturate(180%);
    backdrop-filter: blur(14px) saturate(180%);
  }
}
.progress{
  justify-self:start;
  padding: 10px 12px;
  border-radius: 999px;
}
#modePill{
  justify-self:end;
}
#timerPill{
  justify-self:center;
  padding: 12px 18px;
  font-size: clamp(26px, 4.8vw, 46px);
  font-weight: 800;
  letter-spacing: -0.03em;
  border-radius: 999px;
  box-shadow: 0 22px 70px rgba(0,0,0,.16);
}

/* Card */
/* ── card: VQ Design System v2 ── */
.card{
  border:1px solid var(--border);
  border-radius:var(--radius-lg,16px);
  background:var(--panel);
  box-shadow:0 2px 8px rgba(0,0,0,.06);
  padding:24px;
  transition:all .2s ease;
}
.card:hover{
  box-shadow:0 4px 16px rgba(0,0,0,.08);
}
.card.fade-out{
  opacity:0;
  transform: translateY(14px) scale(.985);
  filter: blur(2px);
}
@media (max-width:520px){
  .card{ padding: 22px 18px 18px; }
}

.meta .no{
  font-weight: 650;
  letter-spacing: -0.01em;
}
.prompt{
  font-size: calc(clamp(22px, 4.4vw, 34px) * var(--quiz-font-scale));
  font-weight: 760;
  letter-spacing: -0.03em;
  line-height: 1.18;
}
.prompt-media-wrap{
  display:grid;
  gap:12px;
  margin-top:16px;
}
.quiz-media-card{
  position:relative;
  overflow:hidden;
  border:1px solid rgba(15,23,42,.08);
  border-radius: 22px;
  background:
    linear-gradient(180deg, var(--legacy-surface), var(--legacy-surface-soft));
  box-shadow: 0 18px 42px rgba(15,23,42,.08);
}
.quiz-media-card-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  padding: 14px 16px 0;
  font-size: 11px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: rgba(71,85,105,.78);
}
.quiz-media-card figcaption{
  padding: 0 16px 14px;
  font-size: 12px;
  color: rgba(71,85,105,.82);
}
.quiz-media-card img{
  width:100%;
  display:block;
  background:
    radial-gradient(circle at top left, rgba(255,255,255,.72), rgba(241,245,249,.94));
}
.quiz-media-card.is-image img,
.quiz-media-card.is-asset-image img{
  max-height: min(38vh, 320px);
  object-fit: contain;
}
.quiz-media-card.is-pdf object{
  width:100%;
  height:min(42vh, 320px);
  display:block;
  background: rgba(248,250,252,.92);
}
.quiz-media-file{
  display:flex;
  align-items:flex-start;
  gap:14px;
  padding: 16px;
}
.quiz-media-file-icon{
  width:44px;
  height:44px;
  border-radius: var(--radius, 12px);
  display:grid;
  place-items:center;
  background: rgba(15,23,42,.06);
  color: rgba(15,23,42,.68);
  flex: 0 0 auto;
}
.quiz-media-file-copy{
  min-width:0;
  display:grid;
  gap:4px;
  flex:1;
}
.quiz-media-file-copy strong{
  font-size:14px;
  color: var(--text);
  line-height:1.35;
  word-break:break-word;
}
.quiz-media-file-copy span{
  font-size:12px;
  color: rgba(71,85,105,.82);
  line-height:1.5;
}
.quiz-media-link{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-height:36px;
  padding: 0 12px;
  border-radius: 999px;
  border:1px solid rgba(15,23,42,.10);
  color: var(--text);
  background: rgba(255,255,255,.82);
  text-decoration:none;
  font-size:13px;
  font-weight:650;
}
.quiz-media-link:hover{
  background: rgba(255,255,255,.96);
}
.answer-wrap{
  margin-top:16px;
  padding:16px 16px 14px;
  border:1px solid rgba(15,23,42,.08);
  border-radius: 20px;
  background: rgba(248,250,252,.72);
  transition:
    border-color .26s var(--ease),
    background .26s var(--ease),
    box-shadow .26s var(--ease),
    transform .26s var(--ease);
}
.answer-wrap.is-correct{
  border-color: rgba(40,168,106,.22);
  background: linear-gradient(180deg, rgba(236,252,243,.92), rgba(245,253,248,.9));
  box-shadow: 0 18px 34px rgba(40,168,106,.10);
}
.answer-wrap.is-wrong{
  border-color: rgba(223,89,96,.18);
  background: linear-gradient(180deg, rgba(254,243,244,.94), rgba(255,248,248,.92));
  box-shadow: 0 18px 34px rgba(223,89,96,.08);
}

/* Controls */
.controls{ margin-top: 16px; }
.cta{
  border:1px solid var(--btn-border);
  background: var(--btn-bg);
  color: var(--text);
  box-shadow: 0 16px 46px rgba(0,0,0,.10);
  transition:
    transform .22s var(--ease),
    box-shadow .35s var(--ease),
    background .35s var(--ease),
    border-color .35s var(--ease);
}
@supports ((-webkit-backdrop-filter: blur(1px)) or (backdrop-filter: blur(1px))){
  .cta{
    background: var(--glass);
    -webkit-backdrop-filter: blur(14px) saturate(180%);
    backdrop-filter: blur(14px) saturate(180%);
  }
}
@media (hover:hover){
  .cta:hover{
    transform: translateY(-1px);
    box-shadow: 0 22px 64px rgba(0,0,0,.14);
    border-color: var(--border);
  }
}
.cta:active{ transform: translateY(1px) scale(.99); }

/* ── navbtn: VQ Design System v2 ── */
.navbtn{
  display:inline-flex;align-items:center;justify-content:center;gap:6px;
  border:1px solid var(--border);
  background:var(--panel);
  color:var(--text);
  font-weight:600;font-family:var(--font,inherit);
  border-radius:var(--radius);
  padding:10px 18px;font-size:14px;
  cursor:pointer;
  box-shadow:var(--shadow);
  transition:all .15s ease;
}
.navbtn:hover{
  border-color:rgba(0,0,0,.18);
  box-shadow:0 4px 12px rgba(0,0,0,.08);
  transform:translateY(-1px);
}
.navbtn:active{transform:translateY(0) scale(.98);}
.navbtn.primary,.navbtn.is-primary{
  background:var(--accent,#6366f1);color:#fff;border-color:var(--accent,#6366f1);
}
.navbtn.primary:hover,.navbtn.is-primary:hover{
  background:var(--accent-hover,#4f46e5);
