  box-shadow:0 4px 14px rgba(239,68,68,.3);
}
.navbtn[disabled]{opacity:.45;cursor:not-allowed;transform:none;box-shadow:none;}

/* Choices */
.choice-wrap{
  border-top:1px solid var(--border);
}
.choice-label{
  letter-spacing: .14em;
}
.choice-btn{
  border:1px solid var(--hairline);
  border-radius: 16px;
  background: var(--panel);
  box-shadow: 0 18px 50px rgba(0,0,0,.10);
  padding: 14px 14px;
  display:flex;
  align-items:center;
  gap:12px;
  position:relative;
  overflow:hidden;
  transition:
    transform .22s var(--ease),
    box-shadow .35s var(--ease),
    border-color .35s var(--ease),
    background .35s var(--ease),
    opacity .35s var(--ease);
}
.choice-btn .choice-copy{
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 8px;
}
.choice-btn .choice-text{
  min-width: 0;
}
.choice-btn .choice-media{
  width: min(100%, 220px);
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid rgba(15,23,42,.08);
  background: rgba(248,250,252,.96);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.85);
}
.choice-btn .choice-media img{
  display: block;
  width: 100%;
  height: auto;
  object-fit: cover;
}
.choice-btn .k{
  flex: 0 0 auto;
  width:34px;
  height:34px;
  border-radius: 12px;
  display:grid;
  place-items:center;
  background: rgba(15,23,42,.06);
  color: rgba(15,23,42,.76);
  font-weight: 760;
  transition: background .24s var(--ease), color .24s var(--ease), transform .24s var(--ease);
}
.choice-btn .choice-state{
  margin-left:auto;
  flex: 0 0 auto;
  width:26px;
  height:26px;
  border-radius: 999px;
  display:grid;
  place-items:center;
  font-size: 13px;
  font-weight: 800;
  opacity:0;
  transform: scale(.8);
  transition: opacity .2s var(--ease), transform .2s var(--ease), background .2s var(--ease), color .2s var(--ease);
}
.choice-btn.correct .choice-state,
.choice-btn.wrong .choice-state{
  opacity:1;
  transform: scale(1);
}
.choice-btn.correct .choice-state::before{
  content:"○";
}
.choice-btn.wrong .choice-state::before{
  content:"×";
}
@media (hover:hover){
  .choice-btn:hover{
    transform: translateY(-1px);
    box-shadow: 0 24px 76px rgba(0,0,0,.14);
    border-color: var(--border);
  }
}
.choice-btn:active{ transform: translateY(1px) scale(.99); }
.choice-btn.correct{
  animation: choiceRevealCorrect .52s var(--ease) both;
}
.choice-btn.wrong{
  animation: choiceRevealWrong .48s var(--ease) both;
}
@keyframes choiceRevealCorrect{
  0%{ transform: translateY(0) scale(1); }
  35%{ transform: translateY(-2px) scale(1.016); }
  100%{ transform: translateY(0) scale(1); }
}
@keyframes choiceRevealWrong{
  0%{ transform: translateX(0) scale(1); }
  22%{ transform: translateX(-2px) scale(1.005); }
  44%{ transform: translateX(2px) scale(1.005); }
  100%{ transform: translateX(0) scale(1); }
}
.choice-btn.correct{
  background: rgba(209,31,42,.06);
  border-color: rgba(209,31,42,.20);
  animation: choicePop .42s var(--ease) both;
}
.choice-btn.wrong{
  background: rgba(28,79,214,.06);
  border-color: rgba(28,79,214,.20);
  animation: choicePop .42s var(--ease) both;
}

@keyframes choicePop{
  0%{ transform: translateY(0) scale(1); }
  45%{ transform: translateY(-2px) scale(1.015); }
  100%{ transform: translateY(0) scale(1); }
}

/* Mark layer (maru/batsu) */
.mark-layer{
  width:84px;
  height:84px;
  top:12px;
  right:12px;
  filter: drop-shadow(0 18px 40px rgba(15,23,42,.16));
  transition: opacity .35s var(--ease), transform .35s var(--ease);
}
.mark-layer::before{
  content:"";
  position:absolute;
  inset:10px;
  border-radius:999px;
  opacity:0;
  transform: scale(.72);
}
.mark-layer.ok::before{
  background: radial-gradient(circle, var(--quiz-mark-correct-bg), transparent 72%);
  animation: markGlow .58s var(--ease) both;
}
.mark-layer.ng::before{
  background: radial-gradient(circle, var(--quiz-mark-wrong-bg), transparent 72%);
  animation: markGlow .58s var(--ease) both;
}
.mark-layer.show{
  transform: translateY(0) scale(1);
  animation: markPop .55s var(--ease) both;
}
@keyframes markPop{
  0%{ opacity:0; transform: translateY(-6px) scale(.92); }
  55%{ opacity:1; transform: translateY(0) scale(1.06); }
  100%{ opacity:1; transform: translateY(0) scale(1); }
}
@keyframes markGlow{
  0%{ opacity:0; transform: scale(.68); }
  55%{ opacity:.9; transform: scale(1); }
  100%{ opacity:.6; transform: scale(1.04); }
}

/* Overlays (settings / time select) */
.overlay{
  background: rgba(0,0,0,.40);
}
@supports ((-webkit-backdrop-filter: blur(1px)) or (backdrop-filter: blur(1px))){
  .overlay{
    -webkit-backdrop-filter: blur(10px) saturate(160%);
    backdrop-filter: blur(10px) saturate(160%);
  }
}
.overlay:not(.hidden){
  animation: overlayIn .45s var(--ease) both;
}
@keyframes overlayIn{
  from{ opacity:0; }
  to{ opacity:1; }
}
.overlay:not(.hidden) .sheet{
  animation: sheetIn .55s var(--ease) both;
}
@keyframes sheetIn{
  from{ transform: translateY(24px) scale(.985); opacity:0; }
  to{ transform: translateY(0) scale(1); opacity:1; }
}
.sheet{
  border:1px solid var(--border);
  box-shadow: 0 40px 120px rgba(0,0,0,.35);
}

/* Result view */
.result-box{
  border:1px solid var(--hairline);
  background: var(--glass-strong);
  box-shadow: 0 20px 70px rgba(0,0,0,.12);
}
@supports ((-webkit-backdrop-filter: blur(1px)) or (backdrop-filter: blur(1px))){
  .result-box{
    background: var(--glass);
    -webkit-backdrop-filter: blur(14px) saturate(180%);
    backdrop-filter: blur(14px) saturate(180%);
  }
}
.wrong-item{
  border:1px solid var(--border);
  background: var(--panel);
  box-shadow: 0 14px 40px rgba(0,0,0,.08);
}

/* Focus rings (Apple-like) */
:focus-visible{
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

/* View entrance animation */
.view.active{
  animation: viewIn .70s var(--ease) both;
}
@keyframes viewIn{
  from{ opacity:0; transform: translateY(14px) scale(.985); }
  to{ opacity:1; transform: translateY(0) scale(1); }
}

/* Stagger inside title view */
#viewTitle.active .hero{ animation: riseIn .85s var(--ease) both; }
#viewTitle.active .actions .btn{
  animation: riseIn .75s var(--ease) both;
}
#viewTitle.active .actions .btn:nth-child(1){ animation-delay: .06s; }
#viewTitle.active .actions .btn:nth-child(2){ animation-delay: .12s; }
#viewTitle.active .actions .btn:nth-child(3){ animation-delay: .18s; }
#viewTitle.active .actions .btn:nth-child(4){ animation-delay: .24s; }

@keyframes riseIn{
  from{ opacity:0; transform: translateY(16px); }
  to{ opacity:1; transform: translateY(0); }
}

/* Stagger inside result view */
#viewResult.active .hero{ animation: riseIn .85s var(--ease) both; }
#viewResult.active .wrong-item{ animation: riseIn .65s var(--ease) both; }
#viewResult.active .wrong-item:nth-child(1){ animation-delay:.06s; }
#viewResult.active .wrong-item:nth-child(2){ animation-delay:.12s; }
#viewResult.active .wrong-item:nth-child(3){ animation-delay:.18s; }
#viewResult.active .wrong-item:nth-child(4){ animation-delay:.24s; }
#viewResult.active .wrong-item:nth-child(5){ animation-delay:.30s; }
#viewResult.active .wrong-item:nth-child(6){ animation-delay:.36s; }
#viewResult.active .wrong-item:nth-child(7){ animation-delay:.42s; }
#viewResult.active .wrong-item:nth-child(8){ animation-delay:.48s; }
#viewResult.active .wrong-item:nth-child(9){ animation-delay:.54s; }
#viewResult.active .wrong-item:nth-child(10){ animation-delay:.60s; }

/* Reduced motion */
@media (prefers-reduced-motion: reduce){
  *{
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
  .card.fade-out{ filter:none !important; }
}


