    /* Custom Select (non-native UI) */
    .xselect{
      position: relative;
      display: inline-block;
      vertical-align: middle;
      min-width: 220px;
      max-width: min(100%, 460px);
    }
    .xselect.settings-select{
      min-width: 108px;
      max-width: min(55vw, 260px);
    }
    .settings-row .xselect{
      margin-left: auto;
    }
    .xselect-native{
      position: absolute !important;
      width: 1px !important;
      height: 1px !important;
      padding: 0 !important;
      margin: 0 !important;
      border: 0 !important;
      opacity: 0 !important;
      pointer-events: none !important;
      clip: rect(0 0 0 0) !important;
      clip-path: inset(50%) !important;
      overflow: hidden !important;
      white-space: nowrap !important;
    }
    .xselect-trigger{
      appearance: none;
      width: 100%;
      min-height: 42px;
      border: 0;
      border-radius: var(--radius, 12px);
      background: var(--input-bg);
      color: var(--input-text);
      padding: 10px 38px 10px 12px;
      text-align: left;
      font-size: 14px;
      line-height: 1.25;
      cursor: pointer;
      transition: border-color var(--fade) ease, filter var(--fade) ease;
      box-sizing: border-box;
      position: relative;
    }
    .xselect-trigger::after{
      content: "";
      position: absolute;
      right: 13px;
      top: 50%;
      width: 8px;
      height: 8px;
      border-right: 2px solid currentColor;
      border-bottom: 2px solid currentColor;
      transform: translateY(-62%) rotate(45deg);
      opacity: .68;
      pointer-events: none;
      transition: transform var(--fade) ease;
    }
    .xselect.is-open .xselect-trigger::after{
      transform: translateY(-40%) rotate(-135deg);
    }
    .xselect-trigger:hover{
      filter: brightness(1.03);
    }
    .xselect-trigger:focus-visible{
      outline: none;
      border-color: transparent;
      box-shadow: 0 0 0 3px rgba(31,42,68,.14);
    }
    .xselect-label{
      display: block;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
      color: var(--input-text);
    }
    .xselect.is-disabled .xselect-trigger{
      opacity: .62;
      cursor: not-allowed;
      filter: none;
    }
    .xselect-portal{
      position: fixed;
      inset: 0;
      z-index: 21000;
      background: transparent;
    }
