      isolation:isolate;
      overflow:visible;
      padding:18px;
      border-radius:28px;
      border:1px solid rgba(148,163,184,.14);
      background:linear-gradient(180deg, var(--legacy-surface), var(--legacy-surface-soft));
      box-shadow:0 10px 24px rgba(15,23,42,.04);
    }
    .app-library-section.is-menu-open{
      z-index:680;
    }
    .app-library-section-head{
      display:flex;
      align-items:flex-start;
      justify-content:space-between;
      gap:16px;
      margin-bottom:14px;
      flex-wrap:wrap;
    }
    .app-library-section-copy{
      display:grid;
      gap:5px;
      min-width:0;
    }
    .app-library-section-copy strong{
      color:var(--text);
      font-size:18px;
      line-height:1.2;
      font-weight:760;
      letter-spacing:-.02em;
    }
    .app-library-section-copy p{
      margin:0;
      color:rgba(71,85,105,.78);
      font-size:13px;
      line-height:1.55;
    }
    .app-library-section-kicker{
      color:rgba(71,85,105,.7);
      font-size:11px;
      line-height:1.2;
      font-weight:760;
      letter-spacing:.1em;
      text-transform:uppercase;
    }
    .app-library-section-actions{
      display:flex;
      align-items:center;
      gap:10px;
      flex-wrap:wrap;
    }
    .app-library-section-meta{
      display:inline-flex;
      align-items:center;
      min-height:28px;
      padding:0 12px;
      border-radius:999px;
      background:rgba(15,23,42,.05);
      color:rgba(15,23,42,.58);
      font-size:12px;
      font-weight:700;
      letter-spacing:.02em;
      white-space:nowrap;
    }
    .app-library-list{
      display:grid;
      gap:12px;
      isolation:isolate;
    }
    .app-library-item{
      position:relative;
      display:grid;
      grid-template-columns:minmax(0, 1fr) auto;
      gap:16px;
      padding:18px;
      border-radius:24px;
      border:1px solid rgba(148,163,184,.14);
      background:
        radial-gradient(circle at top right, rgba(255,255,255,.78), transparent 34%),
        linear-gradient(180deg, var(--legacy-surface), var(--legacy-surface-soft));
      box-shadow:0 10px 28px rgba(15,23,42,.045);
      transition:transform .18s ease, box-shadow .18s ease, border-color .18s ease;
      z-index:0;
      overflow:visible;
    }
    .app-library-item:hover{
      transform:translateY(-1px);
      box-shadow:0 16px 34px rgba(15,23,42,.07);
      border-color:rgba(148,163,184,.22);
    }
    .app-library-item.is-menu-open{
      z-index:720;
    }
    .app-library-item-main{
      display:flex;
      align-items:flex-start;
      gap:14px;
      min-width:0;
    }
    .app-library-item-copy{
      min-width:0;
      display:grid;
      gap:8px;
      align-content:start;
    }
    .app-library-item-top{
      display:flex;
      align-items:flex-start;
      justify-content:space-between;
      gap:10px;
      min-width:0;
      flex-wrap:wrap;
    }
    .app-library-item-title-wrap{
      min-width:0;
      display:grid;
      gap:6px;
    }
    .app-library-item .title{
      color:var(--text);
      font-size:18px;
      line-height:1.22;
      font-weight:760;
      letter-spacing:-.02em;
      word-break:break-word;
    }
    .app-library-item-updated{
      color:rgba(71,85,105,.66);
      font-size:12px;
      line-height:1.4;
      white-space:nowrap;
    }
    .app-library-item-meta{
      display:flex;
      flex-wrap:wrap;
      align-items:center;
      gap:8px;
      color:rgba(71,85,105,.78);
      font-size:13px;
      line-height:1.5;
    }
    .app-library-item-meta-sep{
      color:rgba(148,163,184,.9);
    }
    .app-library-item-badges{
      display:flex;
      align-items:center;
      gap:8px;
      flex-wrap:wrap;
    }
    .app-library-state-badge{
      display:inline-flex;
      align-items:center;
      min-height:28px;
      padding:0 10px;
      border-radius:999px;
      border:1px solid rgba(148,163,184,.18);
      background:rgba(255,255,255,.9);
      color:rgba(15,23,42,.7);
      font-size:11px;
      line-height:1;
      font-weight:760;
      letter-spacing:.06em;
      text-transform:uppercase;
    }
    .app-library-state-badge.is-public{
      background:rgba(37,99,235,.09);
      border-color:rgba(37,99,235,.16);
      color:rgba(30,64,175,.84);
    }
    .app-library-state-badge.is-builtin{
      background:rgba(15,23,42,.06);
      border-color:rgba(15,23,42,.08);
      color:rgba(15,23,42,.6);
    }
    .app-library-state-badge.is-official{
      background:rgba(16,185,129,.1);
      border-color:rgba(16,185,129,.2);
      color:rgba(6,95,70,.85);
    }
    .app-library-state-badge.is-tag{
      text-transform:none;
      letter-spacing:0;
      font-weight:650;
    }
    .app-library-item-actions{
      display:flex;
      align-items:flex-start;
      justify-content:flex-end;
      gap:8px;
      flex-wrap:wrap;
      flex:0 0 auto;
    }
    .app-library-item-actions .navbtn,
    .app-library-item-actions .btn,
    .app-library-item-actions .textbtn{
      min-height:38px;
    }
    .app-library-more{
      position:relative;
      flex:0 0 auto;
      z-index:4;
      isolation:isolate;
    }
    .app-library-more[open]{
      z-index:760;
    }
    .app-library-more summary{
      list-style:none;
      display:grid;
      place-items:center;
      width:38px;
      height:38px;
      border-radius:999px;
      border:1px solid rgba(148,163,184,.18);
      background:rgba(255,255,255,.88);
      color:rgba(15,23,42,.72);
      cursor:pointer;
      transition:background-color .16s ease, border-color .16s ease, transform .16s ease;
    }
    .app-library-more summary::-webkit-details-marker{
      display:none;
    }
    .app-library-more summary .ms{
      font-size:20px;
    }
    .app-library-more[open] summary,
    .app-library-more summary:hover{
      background:rgba(255,255,255,.98);
      border-color:rgba(148,163,184,.28);
      transform:translateY(-1px);
    }
    .app-library-more-menu{
      position:absolute;
      top:calc(100% + 8px);
      right:0;
      min-width:190px;
      display:grid;
      gap:6px;
      padding:8px;
      border-radius:var(--radius-lg, 16px);
      border:1px solid rgba(148,163,184,.16);
      background:rgba(255,255,255,.98);
      box-shadow:0 18px 38px rgba(15,23,42,.12);
      z-index:900;
    }
    .app-library-more-action{
      justify-content:flex-start;
      width:100%;
      min-height:38px;
      padding:0 12px;
      border-radius:12px;
      border:0;
      background:transparent;
      color:var(--text);
      font-size:13px;
      font-weight:650;
      text-align:left;
      cursor:pointer;
    }
    .app-library-more-action:hover{
      background:rgba(15,23,42,.05);
    }
    .app-library-more-action.is-danger{
      color:#b42318;
    }
    .app-library-public-summary{
      color:rgba(71,85,105,.74);
      font-size:12px;
    }
    .app-library-item .app-preset-card-icon{
      width:54px;
      height:54px;
      border-radius:var(--radius-lg, 16px);
      box-shadow:inset 0 0 0 1px rgba(255,255,255,.2), 0 10px 18px rgba(15,23,42,.08);
    }
    .app-library-item .app-preset-card-icon .ms{
      font-size:24px;
    }
    .app-library-empty{
      padding:20px 18px;
      border-radius:20px;
      background:rgba(248,250,252,.84);
      border:1px dashed rgba(148,163,184,.28);
      color:rgba(71,85,105,.78);
      font-size:13px;
      line-height:1.6;
      text-align:center;
    }
    @media (max-width: 860px){
      .app-library-page .app-library-filters{
        flex-direction:column;
        align-items:stretch;
      }
      .app-library-page .app-library-filters > .settings-row,
      .app-library-page .app-library-filters > .settings-row:first-child,
      .app-library-search-row{
        flex:1 1 auto !important;
        min-width:0;
        max-width:none;
      }
    }
    @media (max-width: 720px){
      .app-library-toolbar,
      .app-library-section{
        padding:16px;
        border-radius:22px;
      }
      .app-library-item{
        grid-template-columns:1fr;
        padding:16px;
      }
      .app-library-item-actions{
        justify-content:flex-start;
      }
      .app-library-more-menu{
        left:0;
        right:auto;
        min-width:min(220px, calc(100vw - 64px));
      }
      .app-library-item .title{
        font-size:17px;
      }
    }
    @media (max-width: 520px){
      .app-library-section-head{
        gap:12px;
      }
      .app-library-section-actions{
        width:100%;
        justify-content:space-between;
      }
      .app-library-item-main{
        gap:12px;
      }
      .app-library-item .app-preset-card-icon{
        width:48px;
        height:48px;
        border-radius:16px;
      }
    }


    /* ===== Preset empty state ===== */
    .empty-state{
      margin-top:18px;
      padding: 28px 18px;
      text-align:center;
      border-radius: var(--radius);
      background: var(--panel);
      box-shadow: inset 0 0 0 1px rgba(17,18,20,.06);
      min-height: 180px;
      display:flex;
      flex-direction:column;
      align-items:center;
      justify-content:center;
    }
    .empty-state.hidden{ display:none; }
    .empty-title{
      font-size:18px;
      font-weight:700;
      letter-spacing:.02em;
      color:var(--text);
    }
    .empty-desc{
      margin-top:8px;
      font-size:13px;
      color:var(--muted);
      line-height:1.55;
    }

    /* Keep preset editor actions reachable even with many words */
    .preset-edit-toolbar{
      position: sticky;
      top: 0;
      z-index: 6;
      background: var(--panel);
      padding: 10px 0 12px;
      margin: -6px 0 10px;
      border-bottom: 1px solid rgba(17,18,20,.06);
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
    }

    body.preset-engine-open{
      overflow: hidden;
    }
    .app-preset-engine-overlay{
      position: fixed;
      inset: 0;
      z-index: 2450;
      display: grid;
      place-items: center;
      padding:
        calc(env(safe-area-inset-top, 0px) + 12px)
        max(12px, calc(env(safe-area-inset-right, 0px) + 12px))
        calc(env(safe-area-inset-bottom, 0px) + 12px)
        max(12px, calc(env(safe-area-inset-left, 0px) + 12px));
      background: rgba(255,255,255,.6);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
    }
    .app-preset-engine-overlay.hidden{
      display: none !important;
    }
    .app-preset-engine-shell{
      width: min(960px, 100%);
      max-height: min(860px, calc(100dvh - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px) - 24px));
      min-height: min(680px, calc(100dvh - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px) - 24px));
      display: grid;
      grid-template-rows: auto 1fr;
      border-radius: 20px;
      border: 1px solid #e2e8f0;
      background: #fff;
      box-shadow: 0 8px 32px rgba(15,23,42,.08), 0 2px 8px rgba(15,23,42,.04);
      overflow: hidden;
    }
    .app-preset-engine-topbar{
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 14px 20px;
      border-bottom: 1px solid #f1f5f9;
      background: #fff;
    }
    .app-preset-engine-topmeta{
      display: grid;
      gap: 2px;
      min-width: 0;
    }
    .app-preset-engine-topkicker{
      display: none;
    }
    .app-preset-engine-toptitle{
      font-size: 15px;
      font-weight: 600;
      color: #0f172a;
      line-height: 1.3;
    }
    .app-preset-engine-stage{
      min-height: 0;
      overflow: auto;
      padding: 24px clamp(18px, 3vw, 28px) calc(24px + env(safe-area-inset-bottom, 0px));
      display: grid;
      gap: 18px;
      align-content: start;
      background: #fff;
    }
    .app-preset-engine-intro{
      min-height: 100%;
      display: grid;
      place-items: center;
      padding: 18px 0;
    }
    .app-preset-engine-intro-shell{
      width: min(760px, 100%);
      display: grid;
      gap: 28px;
      justify-items: center;
      text-align: center;
    }
    .app-preset-engine-intro-art{
      position: relative;
      width: min(420px, 100%);
      aspect-ratio: 1.1 / 1;
      display: grid;
      place-items: center;
      border-radius: 32px;
      background:
        radial-gradient(circle at 20% 20%, rgba(204, 219, 248, 0.7), transparent 35%),
        radial-gradient(circle at 78% 24%, rgba(238, 243, 255, 0.86), transparent 34%),
        linear-gradient(180deg, var(--legacy-surface), var(--legacy-surface-soft));
      border: 1px solid rgba(15,23,42,0.06);
      overflow: hidden;
    }
    .app-preset-engine-intro-art::after{
      content: "";
      position: absolute;
      inset: auto 12% 10% 12%;
      height: 28px;
      border-radius: 999px;
      background: radial-gradient(circle, rgba(15,23,42,0.14), transparent 72%);
      filter: blur(16px);
      opacity: 0.45;
    }
    .app-preset-engine-intro-stack{
      position: relative;
      width: min(300px, 72%);
      aspect-ratio: 1.58 / 1;
      border-radius: 28px;
      background:
        linear-gradient(145deg, rgba(255,255,255,0.98), rgba(230,236,244,0.9));
      border: 1px solid rgba(15,23,42,0.06);
      box-shadow: 0 22px 45px rgba(15,23,42,0.12);
      transform: translateY(-4px) rotate(-8deg);
    }
    .app-preset-engine-intro-stack::before,
    .app-preset-engine-intro-stack::after{
      content: "";
      position: absolute;
      inset: 0;
      border-radius: inherit;
      border: 1px solid rgba(15,23,42,0.05);
      background:
        linear-gradient(145deg, rgba(255,255,255,0.95), rgba(241,245,251,0.82));
      box-shadow: 0 18px 34px rgba(15,23,42,0.08);
    }
    .app-preset-engine-intro-stack::before{
      transform: translate(26px, 16px) rotate(11deg);
    }
    .app-preset-engine-intro-stack::after{
      transform: translate(-18px, 24px) rotate(-5deg);
    }
    .app-preset-engine-intro-card{
      position: absolute;
      inset: 14%;
      z-index: 2;
      border-radius: 24px;
      background:
        linear-gradient(180deg, rgba(20,26,37,0.05), transparent 30%),
        linear-gradient(145deg, rgba(255,255,255,0.98), rgba(244,248,255,0.92));
      border: 1px solid rgba(15,23,42,0.08);
      display: grid;
      grid-template-rows: auto 1fr auto;
      gap: 12px;
      padding: 18px;
      text-align: left;
    }
    .app-preset-engine-intro-card-top,
    .app-preset-engine-intro-card-bottom{
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
    }
    .app-preset-engine-intro-card-kicker{
      font-size: 11px;
      letter-spacing: .16em;
      text-transform: uppercase;
      color: rgba(75,85,99,0.72);
      font-weight: 700;
    }
    .app-preset-engine-intro-card-balance{
      font-size: clamp(34px, 5vw, 46px);
      font-weight: 800;
      line-height: .95;
      color: #111827;
    }
    .app-preset-engine-intro-copy{
      display: grid;
      gap: 10px;
      max-width: 560px;
    }
    .app-preset-engine-intro-card.front{
      z-index: 3;
    }
    .app-preset-engine-intro-card-title{
      margin: 4px 0 0;
      font-size: clamp(20px, 3vw, 28px);
      line-height: 1.02;
      letter-spacing: -0.03em;
      color: #111827;
      font-weight: 800;
    }
    .app-preset-engine-intro-card-lines{
      display: grid;
      gap: 10px;
      align-content: center;
    }
    .app-preset-engine-intro-card-lines span{
      display: block;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(90deg, rgba(148,163,184,0.28), rgba(226,232,240,0.82));
    }
    .app-preset-engine-intro-card-lines span.is-wide{ width: 92%; }
    .app-preset-engine-intro-card-lines span.is-mid{ width: 76%; }
    .app-preset-engine-intro-card-lines span.is-short{ width: 54%; }
    .app-preset-engine-intro-chiprow{
      display: flex;
      align-items: center;
      gap: 8px;
      flex-wrap: wrap;
    }
    .app-preset-engine-intro-chip{
      display: inline-flex;
      align-items: center;
      gap: 6px;
      min-height: 28px;
      padding: 0 12px;
      border-radius: 999px;
      border: 1px solid rgba(15,23,42,0.08);
      background: rgba(255,255,255,0.78);
      color: rgba(31,41,55,0.78);
      font-size: 12px;
      font-weight: 700;
      letter-spacing: .02em;
    }
    .app-preset-engine-intro-copy h2{
      margin: 0;
      font-size: clamp(34px, 5vw, 54px);
      line-height: .98;
      letter-spacing: -0.03em;
      color: #111827;
    }
    .app-preset-engine-intro-copy p{
      margin: 0;
      font-size: 16px;
      line-height: 1.7;
      color: rgba(55,65,81,0.8);
    }
    .app-preset-engine-intro-points{
      display: grid;
      gap: 10px;
      width: min(520px, 100%);
      text-align: left;
    }
    .app-preset-engine-intro-point{
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 14px;
      color: rgba(31,41,55,0.84);
    }
    .app-preset-engine-intro-point .ms{
      font-size: 18px;
      color: rgba(67, 90, 160, 0.78);
    }
    .app-preset-engine-intro-actions{
      width: min(360px, 100%);
      display: grid;
      justify-self: center;
    }
    .app-preset-engine-flow{
      display: grid;
      gap: 18px;
      width: min(960px, 100%);
      margin: 0 auto;
    }
    .app-preset-engine-progress{
      display: grid;
      gap: 8px;
      width: min(760px, 100%);
      margin: 0 auto;
    }
    .app-preset-engine-progress-track{
      display: grid;
      grid-template-columns: repeat(5, minmax(0, 1fr));
      gap: 0;
      align-items: center;
      position: relative;
      padding: 0 8px;
    }
    .app-preset-engine-progress-track::before{
      content: "";
      position: absolute;
      left: 22px;
      right: 22px;
      top: 8px;
      height: 1px;
      background: rgba(148,163,184,0.24);
      z-index: 0;
    }
    .app-preset-engine-progress-step{
      display: grid;
      justify-items: center;
      gap: 7px;
      text-align: center;
      padding: 0 6px;
      position: relative;
      z-index: 1;
    }
    .app-preset-engine-progress-dot{
      width: 28px;
      height: 28px;
      border-radius: 999px;
      border: 2px solid #cbd5e1;
      background: #fff;
      box-shadow: none;
      z-index: 1;
      display: grid;
      place-items: center;
      font-size: 12px;
      font-weight: 700;
      color: #94a3b8;
    }
    .app-preset-engine-progress-step.is-active .app-preset-engine-progress-dot{
      background: #6366f1;
      border-color: #6366f1;
      color: #fff;
    }
    .app-preset-engine-progress-step.is-done .app-preset-engine-progress-dot{
      background: #22c55e;
      border-color: #22c55e;
      color: #fff;
    }
    .app-preset-engine-progress-label{
      font-size: 11px;
      color: #94a3b8;
      font-weight: 500;
      line-height: 1.3;
    }
    .app-preset-engine-progress-step.is-active .app-preset-engine-progress-label{
      color: #6366f1;
      font-weight: 600;
    }
    .app-preset-engine-progress-step.is-done .app-preset-engine-progress-label{
      color: #22c55e;
      font-weight: 600;
    }
    .app-preset-engine-head{
      display: grid;
      gap: 6px;
      width: min(760px, 100%);
      margin: 0 auto;
    }
    .app-preset-engine-kicker{
      font-size: 12px;
      letter-spacing: .06em;
      text-transform: uppercase;
      color: #6366f1;
      font-weight: 600;
    }
    .app-preset-engine-title{
      margin: 0;
      font-size: clamp(22px, 3vw, 30px);
      line-height: 1.15;
      letter-spacing: -0.02em;
      color: #0f172a;
    }
    .app-preset-engine-sub{
      margin: 0;
      font-size: 14px;
      line-height: 1.6;
      color: #64748b;
      max-width: 600px;
    }
    .app-preset-engine-grid{
      display: grid;
      gap: 16px;
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
    .app-preset-engine-grid.is-quad{
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
    .app-preset-engine-tile{
      position: relative;
      border: 1.5px solid #e2e8f0;
      border-radius: var(--radius, 12px);
      background: #fff;
      overflow: hidden;
      cursor: pointer;
      transition: border-color .15s ease, box-shadow .15s ease;
