    /* ===== Scan Generator ===== */
    .scan-gen-overlay{
      position: fixed;
      inset: 0;
      z-index: 2300;
      display: flex;
      align-items: flex-end;
      justify-content: center;
      opacity: 0;
      pointer-events: none;
      transition: opacity .26s ease;
    }
    .scan-gen-overlay.hidden{
      display: none !important;
    }
    .scan-gen-overlay.is-open{
      opacity: 1;
      pointer-events: auto;
    }
    .scan-gen-backdrop{
      position: absolute;
      inset: 0;
      border: 0;
      background: rgba(12,14,18,.34);
      cursor: pointer;
      padding: 0;
    }
    @supports ((-webkit-backdrop-filter: blur(1px)) or (backdrop-filter: blur(1px))){
      .scan-gen-backdrop{
        -webkit-backdrop-filter: blur(6px);
        backdrop-filter: blur(6px);
      }
    }
    .scan-gen-sheet{
      position: relative;
      width: min(960px, 100vw);
      height: 92vh;
      max-height: 92vh;
      border: 1px solid var(--border);
      border-bottom: 0;
      border-radius: var(--radius-lg, 16px) 18px 0 0;
      background: var(--panel);
      box-shadow: 0 -18px 54px rgba(0,0,0,.16);
      transform: translateY(28px);
      transition: transform .26s ease;
      overflow: hidden;
      display: grid;
      grid-template-rows: auto 1fr auto;
    }
    .scan-gen-overlay.is-open .scan-gen-sheet{
      transform: translateY(0);
    }
    .scan-gen-head{
      position: sticky;
      top: 0;
      z-index: 2;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      padding: 14px 16px;
      border-bottom: 1px solid var(--border);
      background: color-mix(in srgb, var(--panel) 94%, #fff 6%);
    }
    .scan-gen-title{
      font-weight: 700;
      color: var(--text);
      font-size: 15px;
      letter-spacing: .01em;
    }
    .scan-gen-body{
      overflow: auto;
      -webkit-overflow-scrolling: touch;
      padding: 14px 16px 16px;
      display: grid;
      gap: 12px;
      align-content: start;
    }
    .scan-gen-foot{
      border-top: 1px solid var(--border);
      background: color-mix(in srgb, var(--panel) 96%, #fff 4%);
      padding: 10px 16px;
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      justify-content: flex-end;
    }
    .scan-card{
      border: 1px solid var(--border);
      border-radius: var(--radius, 12px);
      background: var(--panel2);
      padding: 12px;
      display: grid;
      gap: 10px;
    }
    .scan-card h4{
      margin: 0;
      font-size: 13px;
      color: var(--text);
      letter-spacing: .01em;
    }
    .scan-sub{
      margin: 0;
      font-size: 12px;
      color: var(--muted);
      line-height: 1.5;
    }
    .scan-row{
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      align-items: center;
    }
    .scan-type-chip{
      border: 1px solid var(--border);
      background: var(--panel);
      border-radius: 999px;
      min-height: 34px;
      padding: 6px 12px;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      color: var(--text);
    }
    .scan-file-btn{
      position: relative;
      overflow: hidden;
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }
    .scan-file-btn input[type="file"]{
      position: absolute;
      inset: 0;
      opacity: 0;
      cursor: pointer;
    }
    .scan-thumb-list{
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
    }
    .scan-thumb{
      position: relative;
      width: 112px;
      height: 112px;
      border-radius: 10px;
      overflow: hidden;
      border: 1px solid var(--border);
      background: var(--panel);
      box-shadow: inset 0 0 0 1px rgba(17,18,20,.03);
    }
    .scan-thumb img{
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }
    .scan-thumb button{
      position: absolute;
      top: 6px;
      right: 6px;
      width: 26px;
      height: 26px;
      border: 1px solid rgba(255,255,255,.8);
      border-radius: 999px;
      background: rgba(0,0,0,.55);
      color: #fff;
      cursor: pointer;
      line-height: 1;
      font-size: 13px;
    }
    .scan-grid{
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 10px;
    }
    .scan-grid .scan-field{
      display: grid;
      gap: 6px;
    }
    .scan-grid label{
      font-size: 12px;
      color: var(--muted);
    }
    .scan-grid .spell-input,
    .scan-grid .select{
      min-width: 0;
      width: 100%;
