    .scan-status{
      min-height: 18px;
      font-size: 12px;
      color: var(--muted);
      line-height: 1.5;
    }
    .scan-status.error{
      color: #b42318;
    }
    .scan-status.ok{
      color: #198754;
    }
    .scan-steps{
      margin: 0;
      padding: 0;
      list-style: none;
      display: grid;
      gap: 6px;
    }
    .scan-step{
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      color: var(--muted);
    }
    .scan-step .dot{
      width: 8px;
      height: 8px;
      border-radius: 999px;
      background: rgba(31,42,68,.2);
      flex-shrink: 0;
    }
    .scan-step.is-active{
      color: var(--text);
    }
    .scan-step.is-active .dot{
      background: rgba(31,42,68,.55);
      animation: scanPulse 1s ease infinite;
    }
    .scan-step.is-done{
      color: var(--text);
    }
    .scan-step.is-done .dot{
      background: rgba(25,135,84,.56);
      animation: none;
    }
    @keyframes scanPulse{
      0%{ transform: scale(1); opacity: .95; }
      50%{ transform: scale(1.22); opacity: .55; }
      100%{ transform: scale(1); opacity: .95; }
    }
    .scan-result{
      display: grid;
      gap: 10px;
    }
    .scan-result-meta{
      font-size: 12px;
      color: var(--muted);
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
