    .scan-question-q{
      font-size: 13px;
      color: var(--text);
      line-height: 1.55;
    }
    .scan-question-a{
      font-size: 12px;
      color: var(--muted);
      line-height: 1.5;
    }
    .scan-question-type{
      display: inline-flex;
