    /* ===== In-app alert / confirm modal ===== */
    .ui-modal{
      position:fixed;
      inset:0;
      display:flex;
      align-items:center;
      justify-content:center;
      z-index:200000;
      pointer-events:none;
      opacity:0;
      overflow-y:auto;
      overscroll-behavior:contain;
      padding:
        max(18px, calc(env(safe-area-inset-top, 0px) + 16px))
        max(14px, calc(env(safe-area-inset-right, 0px) + 14px))
        max(18px, calc(env(safe-area-inset-bottom, 0px) + 16px))
        max(14px, calc(env(safe-area-inset-left, 0px) + 14px));
      transition: opacity .28s cubic-bezier(0.22, 1, 0.36, 1);
    }
    .ui-modal.is-open{
      opacity:1;
      pointer-events:auto;
    }
    .ui-modal-backdrop{
      position:absolute;
      inset:0;
      background: rgba(17,18,20,.38);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      opacity:0;
      transition: opacity .28s cubic-bezier(0.22, 1, 0.36, 1);
    }
    .ui-modal.is-open .ui-modal-backdrop{ opacity:1; }
    .ui-modal-card{
      position:relative;
      z-index:1;
      width: min(520px, calc(100vw - 44px));
      background: var(--panel);
      border: 1px solid rgba(17,18,20,.08);
      border-radius: var(--radius-lg, 16px);
      box-shadow: 0 24px 90px rgba(0,0,0,.22);
      padding: 18px 18px 16px;
      margin: 0 auto;
      max-height: calc(100dvh - max(36px, calc(env(safe-area-inset-top, 0px) + 32px)) - max(36px, calc(env(safe-area-inset-bottom, 0px) + 24px)));
      overflow:auto;
      overscroll-behavior:contain;
      transform: translateY(18px) scale(.98);
      opacity:0;
      transition:
        transform .42s cubic-bezier(0.22, 1, 0.36, 1),
        opacity .32s cubic-bezier(0.22, 1, 0.36, 1);
    }
    .ui-modal.is-open .ui-modal-card{
      transform: translateY(0) scale(1);
      opacity:1;
    }
    .ui-modal-title{
      font-weight:700;
      font-size:16px;
      color:var(--text);
      letter-spacing:.01em;
    }
    .ui-modal-message{
      margin-top:10px;
      font-size:14px;
      color:var(--text);
      line-height:1.6;
      white-space:pre-wrap;
      word-break:break-word;
    }
    .ui-modal-actions{
      margin-top:16px;
      display:flex;
      gap:10px;
      justify-content:flex-end;
      flex-wrap:wrap;
    }
    .ui-modal-actions .textbtn,
    .ui-modal-actions .navbtn{ min-width: 118px; }
    .ui-modal-card.is-danger .navbtn{
      background: var(--maru);
      border-color: transparent;
      color:var(--inverse-text);
    }
    .ui-modal-card.is-danger .navbtn:hover{ filter: brightness(0.98); }
    .ui-toast{
      position: fixed;
      left: 50%;
      bottom: 24px;
      transform: translateX(-50%) translateY(10px);
      background: rgba(17,18,20,0.92);
      color: var(--inverse-text);
      border-radius: 999px;
      padding: 10px 14px;
      font-size: 12px;
      z-index: 2400;
      opacity: 0;
      pointer-events: none;
      transition: opacity .2s ease, transform .2s ease;
    }
    .ui-toast.show{
      opacity: 1;
      transform: translateX(-50%) translateY(0);
    }

    @media (prefers-reduced-motion: reduce){
      .ui-modal,
      .ui-modal-backdrop,
      .ui-modal-card{
        transition:none !important;
      }
      .ui-modal-card{ transform:none !important; }
    }


