/* =========================
   Topbar labels + Notify dropdown
   ========================= */

/* Icon hover labels */
.icon-btn{ position: relative; overflow: visible; }
.icon-btn .icon-label{
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translate(-50%, -4px);
  opacity: 0;
  pointer-events: none;
  white-space: nowrap;
  font-size: 12px;
  letter-spacing: .02em;
  padding: 6px 10px;
  border-radius: 999px;
  background: var(--panel2);
  color: var(--text);
  border: 1px solid var(--border);
  box-shadow: 0 10px 26px rgba(0,0,0,.10);
  transition: opacity .22s cubic-bezier(0.22, 1, 0.36, 1), transform .22s cubic-bezier(0.22, 1, 0.36, 1);
  z-index: 50;
}
@media (hover:hover) and (pointer:fine){
  .icon-btn:hover .icon-label,
  .icon-btn:focus-visible .icon-label{
    opacity: 1;
    transform: translate(-50%, 0);
  }
}
@media (hover:none), (pointer:coarse){
  .icon-btn .icon-label{ display:none; }
}

#notifyBtn{
  overflow: visible;
}
.notify-latest-hint{
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translate(-50%, -4px);
  opacity: 0;
  pointer-events: none;
  white-space: nowrap;
  font-size: 11px;
  letter-spacing: .01em;
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: color-mix(in srgb, var(--panel2) 92%, #ffffff 8%);
  color: var(--text);
  box-shadow: 0 10px 22px rgba(0,0,0,.10);
  z-index: 56;
  transition: opacity .24s cubic-bezier(0.22, 1, 0.36, 1), transform .24s cubic-bezier(0.22, 1, 0.36, 1);
}
.notify-latest-hint.is-show{
  opacity: 1;
  transform: translate(-50%, 0);
}
@media (prefers-reduced-motion: reduce){
  .notify-latest-hint{
    transition: none;
  }
}

/* Notifications dropdown: show as topbar popover */
#notifyOverlay{
  background: transparent !important;
  align-items: flex-start !important;
  justify-content: flex-end !important;
  padding: calc(var(--topbar-h, 56px) + 10px) 16px 16px !important;
