/* =========================================================
   Theme Normalization Layer
   ========================================================= */
:root{
  color-scheme: light;
}
:root[data-theme-mode="dark"]{
  color-scheme: dark;
}

html, body, .app, main{
  background: var(--bg);
  color: var(--text);
}

.topbar{
  background: var(--bar-bg) !important;
  border-bottom: 1px solid var(--bar-border) !important;
}
.topbar .brand-title,
.topbar .brand-sub{
  color: var(--bar-text) !important;
}
.topbar .icon-btn{
  background: var(--btn-bg) !important;
  color: var(--bar-text) !important;
  border-color: var(--btn-border) !important;
  box-shadow: 0 10px 26px rgba(15,23,42,.06), 0 1px 0 rgba(255,255,255,.82) inset !important;
}
.topbar .icon-btn .ms{
  color: currentColor !important;
}

.overlay{
  background: rgba(29,35,45,.18);
}

.sheet,
.menu-panel,
.menu-header,
.menu-content,
.result-box,
.wrong-item,
.notify-item,
.notify-video,
.search-item,
.insight-card,
.summary-card,
.drawer-share-panel,
.admin-notif-item,
.admin-notif-editor,
.settings-group{
  background: var(--panel) !important;
  color: var(--text) !important;
  border-color: var(--border) !important;
  box-shadow: var(--shadow);
}

.card,
.ui-modal-card{
  background: var(--panel) !important;
  color: var(--text) !important;
  border-color: var(--border) !important;
}

.settings-nav,
.settings-statusbar,
.sheet-header,
.sheet-footer,
.menu-header,
.table-wrap th{
  background: color-mix(in srgb, var(--panel) 92%, var(--bg)) !important;
  color: var(--text) !important;
  border-color: var(--border) !important;
}

.settings-row,
.menu-item{
  background: var(--panel) !important;
  color: var(--text) !important;
  border-color: var(--border) !important;
}

.settings-row .value,
.menu-item .meta,
.sheet-sub,
.note,
.mini,
.notify-time,
.drawer-share-sub,
.drawer-share-link,
.drawer-share-status,
.insight-note,
.summary-k,
.admin-notif-meta,
.menu-article .mini{
  color: var(--muted) !important;
}

/* ── VQ v2: button theme (skip primary/danger variants) ── */
.btn:not(.primary):not(.is-primary):not(.danger):not(.is-danger),
.navbtn:not(.primary):not(.is-primary):not(.danger):not(.is-danger),
.textbtn,
.icon-btn{
  background: var(--btn-bg) !important;
  color: var(--btn-text) !important;
  border-color: var(--btn-border) !important;
}
/* Quiz control buttons should stay readable in both light/dark themes */
#viewQuiz .controls .navbtn{
  background: var(--panel2) !important;
  color: var(--text) !important;
  border-color: var(--border) !important;
}
#viewQuiz .controls .navbtn[disabled]{
  background: var(--panel2) !important;
  color: var(--muted) !important;
  opacity: .72;
}
.btn:hover,
.navbtn:hover,
.textbtn:hover,
.icon-btn:hover{
  filter: brightness(1.01);
}
.btn[disabled],
.navbtn[disabled],
.textbtn[disabled],
.icon-btn[disabled]{
  opacity: .62;
  color: var(--muted) !important;
}

.spell-input,
.select,
/* ── VQ Design System v2: Global Input Styles ── */
input[type="text"],
input[type="email"],
input[type="number"],
input[type="search"],
input[type="password"],
input[type="url"],
input[type="tel"],
input[type="datetime-local"],
textarea,
select{
  background: var(--input-bg) !important;
  color: var(--input-text) !important;
  border: 1px solid var(--input-border) !important;
  border-radius: var(--radius-sm, 8px) !important;
  font-family: inherit;
  font-size: 14px;
  transition: border-color .15s ease, box-shadow .15s ease !important;
}
input[type="text"]:focus,
input[type="email"]:focus,
input[type="number"]:focus,
input[type="search"]:focus,
input[type="password"]:focus,
input[type="url"]:focus,
input[type="tel"]:focus,
input[type="datetime-local"]:focus,
textarea:focus,
select:focus{
  outline: none !important;
  border-color: var(--accent, #6366f1) !important;
  box-shadow: 0 0 0 3px var(--accent-light, rgba(99,102,241,.15)) !important;
}
input::placeholder,
textarea::placeholder{
  color: var(--muted) !important;
}
input,
textarea,
select{
  caret-color: var(--accent, #6366f1);
}

/* ── VQ Design System v2: Chips & Badges ── */
.start-chip,
.badge,
.fineprint .badge,
.deck-tab,
.pill{
  background: var(--chip-bg) !important;
  color: var(--chip-text) !important;
  border-color: var(--border) !important;
  border-radius: var(--radius-sm, 8px) !important;
  font-weight: 600 !important;
}

#notifyOverlay .notify-sheet,
#searchOverlay .search-sheet,
#menuPanel,
#insightsPanel,
#settingsOverlay .settings-fullsheet{
  background: var(--panel) !important;
  border-color: var(--border) !important;
}

.notify-bodytext,
.notify-detail-text,
.menu-article,
.admin-notif-body,
.update-content,
.result-box,
.wrong-item .mid{
  color: var(--text) !important;
}

.menu-article,
.menu-article h2,
.menu-article h3,
.menu-article h4{
  color: var(--text) !important;
}
.menu-article hr{
  border-top-color: var(--border) !important;
}
.menu-article .embed,
.menu-article .codeblock{
  background: var(--panel2) !important;
  border-color: var(--border) !important;
  color: var(--text) !important;
}

.table-wrap{
  border-color: var(--border) !important;
  background: var(--panel) !important;
}
.table-wrap table{
  width: 100%;
  border-collapse: collapse;
  background: var(--panel) !important;
  color: var(--text) !important;
}
.table-wrap th,
.table-wrap td{
  border-color: var(--border) !important;
  color: var(--text) !important;
}
.table-wrap td .muted,
.table-wrap .muted{
  color: var(--muted) !important;
}

.version{
  background: var(--panel2) !important;
  color: var(--muted) !important;
  border-color: var(--border) !important;
}

:root[data-theme-mode="dark"] .ui-modal-backdrop{
  background: rgba(0,0,0,.58);
}
