  font-weight: 700;
}
.app-feed-editor-tip span:last-child{
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}
.app-feed-editor-status{
  margin-top: -2px;
}
.app-feed-reply-sheet{
  width: min(760px, calc(100vw - 24px));
  max-height: min(92dvh, 900px);
  overflow: hidden;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
}
.app-feed-reply-body{
  display: grid;
  gap: 10px;
  overflow: auto;
  -webkit-overflow-scrolling: touch;
}
.app-feed-reply-target{
  border: 1px solid var(--border);
  border-radius: var(--radius, 12px);
  background: color-mix(in srgb, var(--panel2) 72%, var(--panel));
