  background: color-mix(in srgb, var(--panel) 98%, transparent);
  padding: 10px 11px;
}
.app-feed-reply-avatar{
  width: 40px;
  height: 40px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--panel2) 82%, transparent);
  color: var(--text);
  font-weight: 700;
  overflow: hidden;
  cursor: pointer;
  align-self: start;
}
.app-feed-reply-main{
  min-width: 0;
}
.app-feed-reply-head{
  display: grid;
  gap: 2px;
  min-width: 0;
}
.app-feed-reply-name{
  color: var(--text);
  font-size: 13px;
  font-weight: 700;
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.app-feed-reply-sub{
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
