  gap: 12px;
}
.app-feed-inline-reply-title{
  color: var(--text);
  font-size: 15px;
  font-weight: 760;
  letter-spacing: -.01em;
}
.app-feed-inline-reply-meta{
  margin-top: 4px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.55;
