.app-feed-inline-reply-actions{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}
.app-feed-inline-reply-foot{
  display: inline-flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
