@media (max-width: 640px){
  .app-feed-item{
    grid-template-columns: 40px minmax(0, 1fr);
    gap: 8px;
    padding: 10px 8px;
  }
  .app-feed-avatar{
    width: 40px;
    height: 40px;
  }
