    width: calc(100vw - 12px);
  }
  .app-feed-inline-reply{
    margin-left: 0;
  }
  .app-feed-inline-reply-card{
    padding: 12px;
    border-radius: var(--radius-lg, 16px);
  }
  .app-feed-inline-reply-actions{
    align-items: stretch;
  }
  .app-feed-inline-reply-foot{
    width: 100%;
    justify-content: flex-end;
  }
  .app-feed-profile-head{
    grid-template-columns: 60px minmax(0, 1fr);
    gap: 10px;
  }
  .app-feed-profile-avatar{
    width: 60px;
    height: 60px;
    top: -6px;
    font-size: 18px;
  }
  .app-feed-profile-name{
    font-size: 19px;
  }
  .app-feed-profile-actions{
    gap: 8px;
