.app-chat-md pre code{
  display:block;
  background:transparent !important;
  padding:0 !important;
  border-radius:0;
  font-size:13px;
  font-family:'Fira Code',ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  white-space:pre;
  color:#abb2bf;
}
.app-chat-md pre .hljs{background:transparent !important;}
.app-chat-md-code-copy-btn{
  position:absolute;top:8px;right:8px;
  background:rgba(255,255,255,0.1);color:rgba(255,255,255,0.7);
  border:1px solid rgba(255,255,255,0.2);border-radius:6px;
  padding:3px 8px;font-size:11px;cursor:pointer;
  transition:all 0.15s;z-index:1;
}
.app-chat-md-code-copy-btn:hover{background:rgba(255,255,255,0.2);color:#fff;}
.app-chat-md-code-preview-btn{
  position:absolute;top:8px;right:80px;
  background:rgba(92,75,232,0.3);color:#a594f9;
  border:1px solid rgba(92,75,232,0.4);border-radius:6px;
  padding:3px 8px;font-size:11px;cursor:pointer;
  transition:all 0.15s;z-index:1;
}
.app-chat-md-code-preview-btn:hover{background:rgba(92,75,232,0.5);}
.app-chat-md-preview-area{
  margin-top:8px;border-radius:10px;overflow:hidden;
  border:1px solid rgba(255,255,255,0.1);
}
.app-chat-md-preview-head{
  background:rgba(255,255,255,0.05);padding:6px 12px;
  display:flex;align-items:center;justify-content:space-between;
  border-bottom:1px solid rgba(255,255,255,0.08);
}
.app-chat-md-preview-iframe{transition:height 0.2s ease;}
.app-chat-md blockquote{
  margin:6px 0;
  padding:4px 12px;
  border-left:3px solid var(--border);
  color:var(--muted);
}
.app-chat-md p{
  margin:6px 0;
}
.app-chat-md p:first-child{
  margin-top:0;
}
.app-chat-msg.is-user .app-chat-bubble{
  background: var(--panel);
  background: color-mix(in oklab, var(--primary) 14%, var(--panel));
  border-color: color-mix(in oklab, var(--primary) 34%, var(--border));
}
.app-chat-msg.is-typing .app-chat-bubble{
  color:var(--muted);
}
.app-chat-time{
  font-size: 11px;
  color: var(--muted);
}
.app-chat-actions{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-top:2px;
}
.app-chat-action{
  min-height:34px;
  border:1px solid var(--border);
  border-radius:999px;
  background:var(--btn-bg);
  color:var(--btn-text);
  font-size:12px;
  padding:7px 11px;
  cursor:pointer;
}
.app-chat-chart-grid{
  margin-top: 6px;
  display: grid;
  gap: 8px;
}
.app-chat-chart-card{
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--panel2);
  padding: 8px;
}
.app-chat-chart-title{
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 6px;
}
.app-chat-chart-svg{
  width: 100%;
  height: auto;
  display: block;
}
.app-chat-sources{
  margin-top: 6px;
  display: grid;
  gap: 4px;
}
.app-chat-sources-toggle{
  display:inline-flex;
  align-items:center;
  gap:6px;
  margin-top:8px;
  padding:0;
  border:0;
  background:transparent;
  color:var(--muted);
  font-size:11px;
  font-weight:700;
  cursor:pointer;
}
.app-chat-sources-toggle .ms{
  font-size:16px;
  line-height:1;
}
.app-chat-source{
  font-size: 11px;
  color: var(--muted);
  line-height: 1.45;
}
.app-chat-meta-details{
  margin-top: 6px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--panel2);
  overflow: hidden;
}
.app-chat-meta-details > summary{
  cursor: pointer;
  list-style: none;
  padding: 7px 10px;
  font-size: 11px;
  color: var(--muted);
  font-weight: 700;
}
.app-chat-meta-details > summary::-webkit-details-marker{
  display: none;
}
.app-chat-meta-grid{
  border-top: 1px solid var(--border);
  padding: 8px 10px;
  display: grid;
  gap: 4px;
  font-size: 11px;
  color: var(--muted);
  line-height: 1.45;
}
.app-chat-msg.is-ai.intent-match .app-chat-bubble{
  background: color-mix(in oklab, var(--panel2) 84%, var(--panel));
}
/* ── Suggest banner ── */
.vq-suggest-banner{
  display:flex;align-items:center;gap:12px;
  padding:12px 16px;background:var(--panel);
  border:1px solid var(--border);border-radius:12px;
  margin:0 0 8px;font-size:13px;color:var(--text);
  animation:vq-suggest-slide 0.3s ease-out;
  box-shadow:0 2px 8px rgba(0,0,0,0.06);
}
.vq-suggest-banner-icon{font-size:20px;flex-shrink:0;}
.vq-suggest-banner-text{flex:1;line-height:1.5;}
.vq-suggest-banner-action{
  padding:6px 14px;background:#1a1a2e;color:white;
  border:none;border-radius:8px;font-size:12px;
  cursor:pointer;white-space:nowrap;flex-shrink:0;
}
.vq-suggest-banner-action:hover{opacity:0.85;}
.vq-suggest-banner-close{
  padding:4px;background:none;border:none;
  cursor:pointer;color:var(--muted);font-size:18px;
  line-height:1;flex-shrink:0;
}
@keyframes vq-suggest-slide{from{opacity:0;transform:translateY(10px);}to{opacity:1;transform:translateY(0);}}
@keyframes vq-ob-blink{0%,100%{opacity:1;}50%{opacity:0;}}
@keyframes vq-ob-bounce{0%,100%{transform:translateY(0);}50%{transform:translateY(-8px);}}
.app-chat-composer{
  position: sticky;
  bottom: calc(env(safe-area-inset-bottom, 0px) + 8px);
  z-index: 2;
  display: flex;
  align-items: flex-end;
  gap: 8px;
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 8px;
  background: var(--panel);
  background: color-mix(in oklab, var(--panel) 92%, transparent);
  backdrop-filter: saturate(135%) blur(6px);
}
.app-chat-input{
  flex: 1;
  min-height: 44px;
  max-height: 160px;
  border: 1px solid var(--input-border);
  border-radius: 12px;
  background: var(--inputBg, var(--input-bg));
  color: var(--inputText, var(--input-text));
  font-size: 14px;
  line-height: 1.45;
  resize: none;
  padding: 10px 12px;
  box-sizing: border-box;
}
.app-chat-input::placeholder{
  color: var(--muted);
}
.app-chat-send{
  flex: 0 0 auto;
  min-width: 78px;
  min-height: 44px;
}
.app-settings-row{
  border: 1px solid var(--border);
  background: var(--panel2);
  color: var(--text);
  border-radius: var(--radius, 12px);
  min-height: 44px;
  padding: 10px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
}
.app-subscription-head{
  align-items: flex-start;
  gap: 12px;
}
.app-subscription-head-main{
  display: grid;
  gap: 6px;
}
.app-subscription-head-badge{
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--border));
  background: color-mix(in srgb, var(--panel2) 86%, #ffffff);
  color: var(--accent);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .02em;
}
.app-subscription-shell{
  display: grid;
  gap: 18px;
}
.app-subscription-hero{
  position: relative;
  overflow: hidden;
  border-radius: 28px;
  padding: 24px;
  background:
    radial-gradient(circle at top right, color-mix(in srgb, var(--accent) 22%, transparent), transparent 32%),
    linear-gradient(160deg, color-mix(in srgb, var(--panel) 92%, #ffffff), color-mix(in srgb, var(--panel2) 80%, #f8fbff));
  border: 1px solid color-mix(in srgb, var(--accent) 10%, var(--border));
  box-shadow: 0 18px 38px rgba(20, 28, 44, .07);
}
.app-subscription-hero::after{
  content: "";
  position: absolute;
  inset: auto -38px -56px auto;
  width: 180px;
  height: 180px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 10%, #ffffff);
}
.app-subscription-hero-inner{
  position: relative;
  z-index: 1;
  display: grid;
  gap: 16px;
}
.app-subscription-hero-top,
.app-subscription-pill-row,
.app-subscription-cta-row,
.app-subscription-section-head{
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.app-subscription-kicker,
.app-subscription-pill{
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 999px;
  padding: 7px 12px;
  background: color-mix(in srgb, var(--panel) 90%, #ffffff);
  border: 1px solid color-mix(in srgb, var(--accent) 12%, var(--border));
  color: var(--text);
  font-size: 12px;
  font-weight: 700;
}
.app-subscription-hero-title{
  margin: 0;
  font-size: clamp(28px, 4vw, 42px);
  line-height: 1.06;
  letter-spacing: -.03em;
  color: var(--text);
}
.app-subscription-hero-copy,
.app-subscription-foot p{
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.75;
}
.app-subscription-grid{
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}
.app-subscription-plan{
  display: grid;
  gap: 16px;
  padding: 20px;
  border-radius: 24px;
  background: color-mix(in srgb, var(--panel) 93%, #ffffff);
  border: 1px solid var(--border);
  box-shadow: 0 12px 28px rgba(17, 18, 20, .05);
}
.app-subscription-plan.is-featured{
  border-color: color-mix(in srgb, var(--accent) 18%, var(--border));
  background: linear-gradient(180deg, color-mix(in srgb, var(--panel) 88%, #ffffff), color-mix(in srgb, var(--panel2) 92%, #eef5ff));
  box-shadow: 0 18px 36px rgba(35, 74, 169, .12);
}
.app-subscription-plan.is-future{
  background: color-mix(in srgb, var(--panel) 90%, #fbfaf7);
}
.app-subscription-plan-head{
  display: grid;
  gap: 8px;
}
.app-subscription-plan-top{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.app-subscription-plan-name{
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 20px;
  font-weight: 800;
  color: var(--text);
  letter-spacing: -.02em;
}
.app-subscription-plan-badge{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 12%, #ffffff);
  color: var(--accent);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.app-subscription-plan-price{
  display: flex;
  align-items: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}
.app-subscription-plan-price strong{
  font-size: 28px;
  line-height: 1;
  letter-spacing: -.04em;
  color: var(--text);
}
.app-subscription-plan-price span{
  font-size: 12px;
  color: var(--muted);
}
.app-subscription-plan-note{
  display: block;
  margin-top: 6px;
  color: #74809b;
  font-size: 11px;
}
.app-subscription-plan-desc{
  margin: 0;
  color: var(--muted);
  line-height: 1.7;
}
.app-subscription-feature-list{
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 10px;
}
.app-subscription-feature-list li{
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  gap: 8px;
  align-items: start;
  color: var(--text);
  font-size: 13px;
  line-height: 1.6;
}
.app-subscription-feature-list li .ms,
.app-subscription-mark .ms{
  margin-top: 2px;
  font-size: 16px;
  color: var(--accent);
}
.app-subscription-section{
  display: grid;
  gap: 12px;
}
.app-subscription-section-head{
  justify-content: space-between;
}
.app-subscription-section-head h3{
  margin: 0;
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -.02em;
  color: var(--text);
}
.app-subscription-section-head p{
  margin: 0;
  color: var(--muted);
  font-size: 13px;
}
.app-subscription-compare-wrap{
  overflow: auto;
  -webkit-overflow-scrolling: touch;
  border-radius: 22px;
  border: 1px solid var(--border);
  background: color-mix(in srgb, var(--panel) 94%, #ffffff);
}
.app-subscription-compare{
  width: 100%;
  min-width: 640px;
  border-collapse: separate;
  border-spacing: 0;
}
.app-subscription-compare th,
.app-subscription-compare td{
  padding: 14px 16px;
  text-align: left;
  font-size: 13px;
  border-bottom: 1px solid color-mix(in srgb, var(--border) 82%, transparent);
}
.app-subscription-compare th{
  background: color-mix(in srgb, var(--panel2) 74%, #ffffff);
  color: var(--text);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.app-subscription-compare td{
  color: var(--muted);
  line-height: 1.55;
}
.app-subscription-compare tbody tr:last-child td{
  border-bottom: 0;
}
.app-subscription-mark{
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text);
  font-weight: 700;
}
.app-subscription-faq{
  display: grid;
  gap: 10px;
}
.app-subscription-faq-item{
  border: 1px solid var(--border);
  border-radius: 20px;
  background: color-mix(in srgb, var(--panel) 94%, #ffffff);
  overflow: hidden;
}
.app-subscription-faq-item summary{
  list-style: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  font-size: 14px;
  font-weight: 700;
  color: var(--text);
}
.app-subscription-faq-item summary::-webkit-details-marker{
  display: none;
}
.app-subscription-faq-item summary .ms{
  font-size: 18px;
  color: var(--muted);
  transition: transform .18s ease;
}
.app-subscription-faq-item[open] summary .ms{
  transform: rotate(180deg);
}
.app-subscription-faq-body{
  padding: 0 18px 18px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.75;
}
.app-subscription-foot{
  display: grid;
  gap: 8px;
  padding: 18px 20px;
  border-radius: 22px;
  background: color-mix(in srgb, var(--panel2) 74%, #ffffff);
  border: 1px dashed color-mix(in srgb, var(--accent) 16%, var(--border));
}
.app-subscription-foot strong{
  color: var(--text);
}
.app-subscription-status-cell{
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.app-subscription-status-icon{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 999px;
  border: 1px solid rgba(17,24,39,.12);
  background: rgba(255,255,255,.86);
  font-size: 13px;
  font-weight: 800;
  color: #111827;
}
.app-subscription-status-icon.is-yes{
  background: rgba(230, 245, 236, .9);
  color: #17603f;
}
.app-subscription-status-icon.is-partial{
  background: rgba(255, 244, 220, .96);
  color: #8a5c08;
}
.app-subscription-status-icon.is-no{
  background: rgba(245, 233, 233, .96);
  color: #8b2431;
}
.app-subscription-status-note{
  color: #4b5563;
  font-size: 12px;
  font-weight: 600;
}
body[data-app-tab="subscription"] main .stage{
  max-width: 1240px;
}
@media (max-width: 980px){
  .app-subscription-grid{
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 720px){
  .app-subscription-hero{
    padding: 20px 18px;
    border-radius: 24px;
  }
  .app-subscription-grid{
    grid-template-columns: 1fr;
  }
  .app-subscription-cta-row{
    display: grid;
    grid-template-columns: 1fr;
  }
  .app-subscription-head{
    align-items: stretch;
  }
}

.app-home-quick{
  margin-top: 10px;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.app-home-current{
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--panel);
  padding: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
}
.app-home-current-main{
  min-width: 0;
}
.app-home-current-k{
  color: var(--muted);
  font-size: 12px;
}
.app-home-current-v{
  margin-top: 4px;
  color: var(--text);
  font-size: 18px;
  font-weight: 700;
}
.app-home-current-sub{
  margin-top: 4px;
  color: var(--muted);
  font-size: 12px;
}
.app-home-reco{
  margin-top: 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius, 12px);
  background: var(--panel2);
  padding: 10px 12px;
}
.home-preset-termination-notice{
  position: relative;
  border: 1px solid #f5a7a7;
  background: linear-gradient(135deg, #fff1b8 0%, #ffd6c9 72%);
  color: #5a2f00;
  border-radius: var(--radius, 12px);
  padding: 10px 10px 10px 30px;
  margin-bottom: 10px;
  font-size: 12px;
  line-height: 1.5;
}
.home-preset-termination-notice.is-post{
  border-color: #ef8484;
  background: linear-gradient(135deg, #ffe2c8 0%, #ffd2d2 72%);
  color: #6f2800;
}
.home-preset-termination-notice.hidden{
  display: none !important;
}
.home-preset-termination-notice .notice-title{
  margin: 0 0 2px;
  font-weight: 700;
  font-size: 13px;
}
.home-preset-termination-close{
  position: absolute;
  left: 8px;
  top: 8px;
  width: 20px;
  min-height: 20px;
  height: 20px;
  border-radius: 999px;
  border: 1px solid #d98d6a;
  background: rgba(255, 255, 255, 0.75);
  color: #7a3100;
  font-size: 12px;
  line-height: 1;
  cursor: pointer;
  padding: 0;
}
.app-home-reco-title{
  color: var(--text);
  font-size: 13px;
  font-weight: 700;
}
.app-home-reco-body{
  color: var(--muted);
  font-size: 12px;
  margin-top: 4px;
}

.app-tabbar{
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 40;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  padding: 8px 10px calc(env(safe-area-inset-bottom, 0px) + 10px);
  background: color-mix(in srgb, var(--bg) 84%, transparent);
  border-top: 1px solid var(--border);
  backdrop-filter: saturate(130%) blur(8px);
}
.app-tab-btn{
  border: 1px solid var(--border);
  background: var(--panel2);
  color: var(--muted);
  border-radius: var(--radius, 12px);
  min-height: 44px;
  padding: 6px 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  font-size: 11px;
  cursor: pointer;
}
.app-tab-btn .ms{
  font-size: 18px;
  line-height: 1;
}
.app-tab-btn.is-active{
  background: var(--panel);
  color: var(--text);
  border-color: var(--btn-border);
}
@media (min-width: 880px){
  .app-tabbar{
    left: 50%;
    transform: translateX(-50%);
    max-width: 1000px;
    border-left: 1px solid var(--border);
    border-right: 1px solid var(--border);
    border-top-left-radius: 16px;
    border-top-right-radius: 16px;
  }
}
@media (max-width: 680px){
  .app-insights-grid{
    grid-template-columns: 1fr;
  }
  .app-insight-filters{
    grid-template-columns: 1fr;
  }
  .app-profile-grid{
    grid-template-columns: 1fr;
  }
  .app-profile-stats{
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .app-home-progress-cards{
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 480px){
  .app-profile-stats,
  .app-home-progress-cards{
    grid-template-columns: 1fr;
  }
}

/* =========================================================
   Final Product UI Layer (visual only, no logic changes)
   ========================================================= */
:root{
  --primary:#6366f1;
  --primaryText:#ffffff;
  --danger:#ef4444;
  --dangerText:#ffffff;
  --chipBg:var(--chip-bg);
  --chipText:var(--chip-text);
  --inputBg:var(--input-bg);
  --inputText:var(--input-text);
  --inputBorder:var(--input-border);
  --tabBg:rgba(247,247,249,.88);
  --tabText:var(--muted);
  --tabActiveBg:var(--panel);
  --tabActiveText:var(--text);

  --accent:var(--primary);
  --radius:18px;
  --radius-sm:12px;
  --shadow:0 18px 42px rgba(15,23,42,.06), 0 1px 0 rgba(255,255,255,.8) inset;
}
:root[data-theme-mode="dark"]{
  --primary:#818cf8;
  --primaryText:#0c111f;
  --danger:#f87171;
  --dangerText:#2a1110;
  --tabBg:rgba(11,11,15,.86);
  --tabText:rgba(245,245,247,.72);
  --tabActiveBg:var(--panel2);
  --tabActiveText:var(--text);
  --shadow:0 18px 42px rgba(0,0,0,.34), 0 1px 0 rgba(255,255,255,.02) inset;
}

html, body{
  /* 地色は 1 つだけ（先頭の「地色は 1 か所にまとめる」を参照）。
     ここは後ろにあるぶん先頭の指定より強い。実測で html だけ #0f131a に
     なって body(#131218) と食い違っていた（2026-08-13）。 */
  background-color:var(--vq-bg-canvas, var(--bg));
  color:var(--text);
}
body{
  letter-spacing:-.01em;
}
main{
  width:min(1100px, 100%);
  margin:0 auto;
  padding-left:16px;
  padding-right:16px;
}

.topbar{
  background:var(--bar-bg) !important;
  border-bottom:1px solid var(--bar-border) !important;
  box-shadow:0 1px 0 rgba(127,127,127,.06);
}
.topbar-inner{
  max-width:1100px;
}
.topbar .brand-title{
  font-weight:740;
  letter-spacing:-.02em;
}
.topbar .brand-sub{
  color:var(--muted);
}

.hero,
.card,
.sheet,
.menu-panel,
.app-page-block,
.app-home-current,
.app-home-reco,
.app-preset-card,
.app-inbox-item,
.app-ins-card,
.summary-card,
.insight-card,
.notify-item,
.search-item,
.wrong-item,
.admin-notif-item,
.admin-notif-editor,
.settings-group,
.backup-settings-card,
.drawer-share-panel,
.ui-modal-card{
  background:var(--panel) !important;
  color:var(--text);
  border:1px solid var(--border) !important;
  border-radius:var(--radius-lg, 16px);
  box-shadow:var(--shadow);
}
.app-preset-card,
.app-ins-card,
.app-home-reco,
.app-settings-row,
.settings-row,
.app-inbox-item{
