}

/* Settings: unify all settings pages with Sound-like card rows */
#settingsOverlay #settingsMainPane .settings-group{
  display:grid;
  gap:10px;
  padding:0;
  border:0 !important;
  background:transparent !important;
  box-shadow:none !important;
  border-radius:0 !important;
  overflow:visible !important;
}
#settingsOverlay #settingsMainPane .settings-row,
#settingsOverlay #settingsMainPane .settings-cell{
  display:flex;
  align-items:center;
  justify-content:space-between;
  min-height:52px;
  padding:0 16px;
  border-radius:20px;
  border:1px solid var(--border) !important;
  background:color-mix(in srgb, var(--panel) 97%, var(--bg)) !important;
  box-shadow:0 12px 28px rgba(15,23,42,.04), 0 1px 0 rgba(255,255,255,.78) inset;
  box-sizing:border-box;
  gap:12px;
