}
#settingsOverlay #settingsMainPane .settings-row .right,
#settingsOverlay #settingsMainPane .settings-cell .right{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:10px;
  line-height:1;
  min-height:32px;
  flex-shrink:0;
  margin-left:auto;
}
#settingsOverlay #settingsMainPane .settings-row .toggle{
  display:flex;
  align-items:center;
}
#settingsOverlay #settingsMainPane .settings-row .settings-seg{
  display:inline-flex;
  align-items:center;
  justify-content:flex-end;
  gap:6px;
}
#settingsOverlay #settingsMainPane .settings-row .settings-select{
  margin-left:0;
}
#settingsOverlay #settingsMainPane .settings-row:last-child{
  border-bottom:1px solid var(--border) !important;
}

.sheet-header,
.sheet-footer,
.settings-nav,
.menu-header{
  background:color-mix(in srgb, var(--panel) 94%, var(--bg)) !important;
  border-color:var(--border) !important;
}
.menu-header{
  position:sticky;
  top:0;
  z-index:3;
}
.menu-content{
  padding-top:8px;
}
.menu-title{
  letter-spacing:.04em;
}

.app-push-status-card{
  margin-top:18px;
  padding:20px;
  border-radius:24px;
  border:1px solid rgba(15,23,42,.07);
  background:linear-gradient(180deg, var(--legacy-surface), var(--legacy-surface-soft));
  box-shadow:0 20px 44px rgba(15,23,42,.06), 0 1px 0 rgba(255,255,255,.84) inset;
}
.app-push-status-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  margin-bottom:14px;
}
.app-push-status-title{
  font-size:16px;
  font-weight:800;
  color:#0f172a;
}
.app-push-status-badge{
  display:inline-flex;
  align-items:center;
  gap:6px;
  min-height:32px;
  padding:0 12px;
  border-radius:999px;
  border:1px solid rgba(15,23,42,.08);
  background:rgba(255,255,255,.96);
  color:#334155;
  font-size:12px;
  font-weight:800;
  letter-spacing:.02em;
}
.app-push-status-badge[data-tone="ok"]{
  color:#166534;
  border-color:rgba(22,101,52,.22);
  background:rgba(240,253,244,.96);
}
.app-push-status-badge[data-tone="warn"]{
  color:#92400e;
  border-color:rgba(146,64,14,.2);
  background:rgba(255,247,237,.96);
}
.app-push-status-badge[data-tone="muted"]{
  color:#475569;
  border-color:rgba(71,85,105,.16);
  background:rgba(248,250,252,.96);
}
.app-push-status-copy{
  margin:0;
  color:#475569;
  font-size:14px;
  line-height:1.7;
}
.app-push-status-grid{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:12px;
  margin-top:16px;
}
.app-push-status-cell{
  min-width:0;
  padding:14px 16px;
  border-radius:var(--radius-lg, 16px);
  background:rgba(255,255,255,.94);
  border:1px solid rgba(15,23,42,.07);
  box-shadow:0 10px 24px rgba(15,23,42,.04);
}
.app-push-status-cell .k{
  display:block;
  margin-bottom:6px;
