.btn,
.navbtn,
.textbtn,
.cta,
.icon-btn,
.choice-btn,
.search-item,
.app-chat-intent-btn,
.xselect-trigger,
.xselect-option,
.app-tab-btn,
.drawer-share-tab,
.menu-item,
.settings-row,
.app-settings-row{
  min-height:44px;
  border-radius:var(--radius-lg, 16px);
  border:1px solid var(--btn-border) !important;
  background:var(--btn-bg) !important;
  color:var(--btn-text) !important;
  box-shadow: 0 12px 28px rgba(15,23,42,.05), 0 1px 0 rgba(255,255,255,.82) inset;
  transition:
    transform .24s cubic-bezier(0.22, 1, 0.36, 1),
    opacity .24s cubic-bezier(0.22, 1, 0.36, 1),
    filter .24s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow .24s cubic-bezier(0.22, 1, 0.36, 1),
    border-color .24s cubic-bezier(0.22, 1, 0.36, 1),
    background .24s cubic-bezier(0.22, 1, 0.36, 1);
  transition-property: transform, opacity, filter, box-shadow, border-color, background;
}
@media (hover:hover) and (pointer:fine){
  .btn:hover,
  .navbtn:hover,
  .textbtn:hover,
  .cta:hover,
  .icon-btn:hover,
  .choice-btn:hover,
  .search-item:hover,
  .app-chat-intent-btn:hover,
  .xselect-trigger:hover,
  .xselect-option:hover,
  .app-tab-btn:hover,
  .drawer-share-tab:hover,
  .menu-item:hover,
  .settings-row:hover,
  .app-settings-row:hover{
    transform:none !important;
    filter:brightness(1.01);
    box-shadow:0 14px 30px rgba(15,23,42,.06), 0 1px 0 rgba(255,255,255,.84) inset;
    border-color:var(--border);
  }
}
.xselect-trigger,
.xselect-option{
  border:0 !important;
}
.xselect-option{
  border-radius:0 !important;
  background:transparent !important;
  box-shadow:none !important;
  padding:13px 16px !important;
  font-size:15px !important;
  font-weight:500 !important;
  color:#1e293b !important;
}
.xselect-menu{
  border:0 !important;
  background:#fff !important;
  box-shadow:0 2px 8px rgba(15,23,42,.06), 0 12px 36px rgba(15,23,42,.12) !important;
  padding:8px 4px !important;
  border-radius:var(--radius-lg, 16px) !important;
}
.xselect-option.is-selected{
  border-color:transparent !important;
  box-shadow:none !important;
  background:#f0f5ff !important;
  color:#1a40b5 !important;
  font-weight:600 !important;
}
.xselect-trigger:focus-visible{
  border-color:transparent !important;
}
@media (hover:hover) and (pointer:fine){
  .xselect-trigger:hover,
  .xselect-option:hover{
    border-color:transparent !important;
    box-shadow:none !important;
  }
}
.btn:active,
.navbtn:active,
.textbtn:active,
.cta:active,
.icon-btn:active,
.app-tab-btn:active,
.drawer-share-tab:active,
.menu-item:active,
.settings-row:active,
.app-settings-row:active{
  transform:translateY(1px) scale(.99);
}
.btn[disabled],
.navbtn[disabled],
.textbtn[disabled],
.cta[disabled],
.icon-btn[disabled],
.app-tab-btn[disabled],
.drawer-share-tab[disabled],
.menu-item[disabled],
.settings-row[disabled],
.app-settings-row[disabled]{
  opacity:.56;
  cursor:not-allowed;
  box-shadow:none;
}
.app-tab-btn{
  border-radius: 999px;
}

.btn.primary,
.navbtn.primary,
.textbtn.primary,
.cta.primary{
  background:var(--primary) !important;
  color:var(--primaryText) !important;
  border-color:transparent !important;
}
.btn.secondary,
.navbtn.secondary,
.textbtn.secondary,
.cta.secondary{
  background:color-mix(in srgb, var(--panel) 96%, var(--bg)) !important;
  color:var(--text) !important;
  border-color:var(--border) !important;
}
.btn.danger,
.navbtn.danger,
.textbtn.danger,
.cta.danger{
  background:var(--danger) !important;
  color:var(--dangerText) !important;
  border-color:transparent !important;
}

#viewQuiz .controls .navbtn{
  background:var(--panel2) !important;
  color:var(--text) !important;
  border-color:var(--border) !important;
}
#viewQuiz .controls .navbtn[disabled]{
  background:var(--panel2) !important;
  color:var(--muted) !important;
}

/* hover jitter fix (PC): keep hitbox stable, avoid hover on/off loops */
@media (hover:hover) and (pointer:fine){
  button:not(.btn):not(.navbtn):not(.textbtn):not(.app-tab-btn):not(.search-item):hover,
  [role="button"]:not(.btn):not(.navbtn):not(.textbtn):not(.app-tab-btn):not(.search-item):hover,
  [data-action]:hover,
  [data-rt-battle-action]:hover{
    transform:none !important;
  }
}

/* decorative overlays should not steal hover/click */
#onlineOverlay .ov-bg,
#rt3dOverlay .b3d-bg{
  pointer-events:none;
}
#onlineOverlay .ov-shell,
#rt3dOverlay .b3d-shell{
  pointer-events:auto;
}

.choice-btn{
  border-radius:var(--radius, 12px);
  background:var(--panel) !important;
  border:1px solid var(--border) !important;
}

input[type="text"],
input[type="email"],
input[type="number"],
input[type="datetime-local"],
input[type="search"],
textarea,
select,
.select,
.spell-input{
  min-height:44px;
  border-radius:var(--radius-lg, 16px);
  border:1px solid var(--inputBorder) !important;
  background:var(--inputBg) !important;
  color:var(--inputText) !important;
  box-shadow:0 10px 26px rgba(15,23,42,.04), 0 1px 0 rgba(255,255,255,.82) inset;
  transition:
    border-color .22s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow .22s cubic-bezier(0.22, 1, 0.36, 1),
    background-color .22s cubic-bezier(0.22, 1, 0.36, 1);
}
textarea{
  min-height:96px;
}
input::placeholder,
textarea::placeholder{
  color:var(--muted);
}
input:focus,
textarea:focus,
select:focus{
  outline:none;
  border-color:color-mix(in srgb, var(--primary) 24%, var(--inputBorder)) !important;
  box-shadow:0 0 0 3px rgba(133,171,226,.18), 0 10px 26px rgba(15,23,42,.05), 0 1px 0 rgba(255,255,255,.85) inset;
}

.subject-badge,
.tag-chip,
.badge,
.pill,
.start-chip,
.deck-tab{
  background:color-mix(in srgb, var(--chipBg) 92%, var(--panel)) !important;
  color:var(--chipText) !important;
  border:1px solid var(--border) !important;
  box-shadow:0 8px 18px rgba(15,23,42,.04);
}
.tag-chip.is-selected{
  background:color-mix(in srgb, var(--primary) 14%, var(--chipBg)) !important;
  color:var(--text) !important;
  border-color:color-mix(in srgb, var(--primary) 42%, var(--border)) !important;
}

.table-wrap{
  border:1px solid var(--border) !important;
  border-radius:var(--radius, 12px);
  overflow:hidden;
  background:var(--panel) !important;
}
.table-wrap table,
table{
  width:100%;
  border-collapse:collapse;
  background:transparent;
  color:var(--text);
}
.table-wrap th,
.table-wrap td,
table th,
table td{
  border-bottom:1px solid var(--border);
  padding:10px 12px;
  text-align:left;
  vertical-align:top;
}
.table-wrap th,
table thead th{
  background:var(--panel2) !important;
  color:var(--text);
  font-weight:700;
}
.table-wrap tr:last-child td,
table tbody tr:last-child td{
  border-bottom:0;
}

.app-page-head h2{
  font-size:24px;
  letter-spacing:-.02em;
}
.app-page-head p,
.app-home-current-k,
.app-home-current-sub,
.app-home-reco-body,
.app-inbox-meta,
.app-empty,
.summary-k,
.insight-note,
.drawer-share-status,
.drawer-share-sub,
.drawer-share-link,
.menu-item .meta,
.settings-row .value,
.sheet-sub{
  color:var(--muted) !important;
