/* =========================
   Chat UI Refresh (white / ChatGPT-like)
   ========================= */
:root{
  --chat-page-bg:#f6f6f8;
  --chat-surface:#ffffff;
  --chat-surface-soft:#fbfbfc;
  --chat-bubble-user:#f5f7fb;
  --chat-bubble-ai:#ffffff;
  --chat-border:rgba(15,23,42,.08);
  --chat-muted:rgba(31,36,48,.58);
  --chat-text:var(--text, #1d1d1f);
  --chat-send-bg:linear-gradient(180deg, var(--legacy-surface), var(--legacy-surface-soft));
  --chat-send-text:#1f2430;
}
:root[data-theme-mode="dark"]{
  --chat-page-bg:#11131a;
  --chat-surface:#171b24;
  --chat-surface-soft:#1e2430;
  --chat-bubble-user:#1f2937;
  --chat-bubble-ai:#171b24;
  --chat-border:rgba(255,255,255,.14);
  --chat-muted:rgba(245,246,247,.68);
  --chat-text:var(--text, #f3f5f8);
  --chat-send-bg:linear-gradient(180deg, rgba(30,37,49,.98), rgba(24,30,40,.94));
  --chat-send-text:#f4f7fb;
}
#appChatPage{
  padding-top: 2px;
  padding-bottom: calc(220px + env(safe-area-inset-bottom, 0px));
}
.app-chat-shell{
  border: 1px solid var(--chat-border) !important;
  border-radius: 24px !important;
  background: var(--chat-page-bg) !important;
  min-height: calc(100dvh - 210px) !important;
  padding: 0 !important;
  gap: 0 !important;
  overflow: hidden;
}
.app-chat-head{
  position: sticky;
  top: 0;
  z-index: 4;
  margin: 0 !important;
  padding: 16px 16px 12px !important;
  border-bottom: 1px solid var(--chat-border) !important;
  background: color-mix(in srgb, var(--chat-surface) 94%, var(--chat-page-bg)) !important;
  backdrop-filter: none !important;
}
.app-chat-head h2{
  font-size: 21px;
  font-weight: 740;
}
.app-chat-head p,
.app-chat-mode-note{
  color: var(--chat-muted) !important;
}
.app-chat-mode-row{
  margin-top: 10px;
  gap: 7px;
}
.app-chat-mode-btn{
  min-height: 36px;
  border-radius: 999px;
  border: 1px solid var(--chat-border);
  background: var(--chat-surface-soft);
  color: var(--text);
}
.app-chat-mode-btn.is-active{
  background: color-mix(in srgb, var(--chat-surface) 82%, var(--accentSoft, rgba(37,99,235,.16)));
  border-color: color-mix(in srgb, var(--chat-border) 58%, var(--accent, #2563eb));
}
.app-chat-intent-browser{
  margin: 12px 14px 0;
  border: 1px solid var(--chat-border);
  background: var(--chat-surface);
  border-radius: 20px;
  padding: 10px;
  box-shadow: 0 16px 36px rgba(15,23,42,.05), 0 1px 0 rgba(255,255,255,.8) inset;
}
.app-chat-intent-search{
  background: var(--chat-surface-soft);
  border-color: var(--chat-border);
  border-radius: var(--radius-lg, 16px);
}
.app-chat-intent-auto{
  border-color: var(--chat-border);
  background: var(--chat-surface-soft);
  color: var(--text);
}
.app-chat-intent-groups{
  max-height: min(28dvh, 240px);
}
.app-chat-intent-group{
  background: var(--chat-surface-soft);
  border-color: var(--chat-border);
}
.app-chat-intent-group-body{
  border-top-color: var(--chat-border);
}
.app-chat-intent-btn,
.app-chat-chip,
.app-chat-action{
  border: 1px solid var(--chat-border);
  background: var(--chat-surface);
  color: var(--text);
}
.app-chat-chip-row{
  margin: 10px 14px 0;
  gap: 7px;
}
.app-chat-meta{
  margin: 8px 14px 0;
  padding: 0 2px;
  color: var(--chat-muted);
}
.app-chat-scroll{
  margin: 10px 14px 0;
  border: 1px solid var(--chat-border);
  border-radius: 24px;
  background: var(--chat-page-bg);
  padding: 14px 12px;
  min-height: 340px;
  padding-bottom: 20px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.48);
}
.app-chat-list{
  gap: 14px;
}
.app-chat-msg{
  max-width: min(86%, 760px);
}
.app-chat-msg.is-user{
  margin-left: auto;
}
.app-chat-msg.is-ai,
.app-chat-msg.is-typing{
  margin-right: auto;
}
.app-chat-role,
.app-chat-time{
  color: var(--chat-muted);
  font-size: 11px;
}
.app-chat-bubble{
  border: 1px solid var(--chat-border);
  border-radius: 20px;
  background: var(--chat-bubble-ai);
  color: var(--chat-text);
  padding: 11px 14px;
  line-height: 1.65;
  font-size: 14px;
  box-shadow: 0 12px 28px rgba(15,23,42,.05), 0 1px 0 rgba(255,255,255,.84) inset;
}
.app-chat-msg.is-user .app-chat-bubble{
  background: var(--chat-bubble-user);
  border-color: color-mix(in srgb, var(--chat-border) 84%, rgba(93,125,168,.12));
}
.app-chat-msg.is-typing .app-chat-bubble{
  background: var(--chat-surface-soft);
  color: var(--chat-muted);
}
.app-chat-msg.is-ai.intent-match .app-chat-bubble{
  background: var(--chat-bubble-ai);
}
.app-chat-chart-card,
.app-chat-meta-details{
  border-color: var(--chat-border);
  background: var(--chat-surface);
}
.app-chat-source,
.app-chat-meta-grid,
.app-chat-meta-details > summary{
  color: var(--chat-muted);
}
.app-chat-composer{
  position: fixed;
  left: 50%;
  transform: translateX(-50%);
  bottom: calc(env(safe-area-inset-bottom, 0px) + 80px);
  z-index: 25;
  margin: 0;
  width: min(1080px, calc(100vw - 20px));
  border: 1px solid var(--chat-border);
  border-radius: 22px;
  background: var(--chat-surface);
  backdrop-filter: none !important;
  padding: 8px;
  box-shadow: 0 22px 48px rgba(15,23,42,.08), 0 1px 0 rgba(255,255,255,.82) inset;
}
.app-chat-input{
  min-height: 44px;
  border-radius: var(--radius-lg, 16px);
  border: 1px solid var(--chat-border);
  background: var(--chat-surface-soft);
  color: var(--chat-text);
  font-size: 14px;
  line-height: 1.55;
  padding: 10px 12px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.72);
}
.app-chat-input::placeholder{
  color: var(--chat-muted);
}
.app-chat-send,
.app-chat-send.btn.primary{
  min-height: 44px;
  min-width: 74px;
  border-radius: var(--radius-lg, 16px) !important;
  border: 1px solid var(--chat-border) !important;
  background: var(--chat-send-bg) !important;
  color: var(--chat-send-text) !important;
  box-shadow: 0 12px 24px rgba(15,23,42,.06), 0 1px 0 rgba(255,255,255,.88) inset !important;
}
.app-chat-send:disabled{
  opacity: .45;
  cursor: not-allowed;
}
.app-chat-send.is-locked{
  filter: grayscale(.2);
}
@media (max-width: 720px){
  .app-chat-shell{
    border-radius: var(--radius-lg, 16px) !important;
    min-height: calc(100dvh - 192px) !important;
  }
  .app-chat-head{
    padding: 12px 12px 10px !important;
  }
  .app-chat-intent-browser,
  .app-chat-chip-row,
  .app-chat-meta,
  .app-chat-scroll,
  .app-chat-composer{
    margin-left: 10px;
    margin-right: 10px;
  }
  .app-chat-scroll{
    min-height: 300px;
    padding: 10px 9px;
  }
  .app-chat-composer{
    width: calc(100vw - 14px);
    bottom: calc(env(safe-area-inset-bottom, 0px) + 74px);
    border-radius: 20px;
  }
  .app-chat-msg{
    max-width: 96%;
  }
}

