/* ── New Model Dropdown ── */
.vq-model-dropdown{
  position:absolute !important;
  left:0;bottom:calc(100% + 8px);
  z-index:72;
  min-width:240px;
  padding:6px;
  border-radius:var(--radius, 12px);
  border:0 !important;
  background:var(--panel, #fff);
  box-shadow:0 8px 32px rgba(0,0,0,.14), 0 2px 8px rgba(0,0,0,.06);
  display:flex !important;flex-direction:column;gap:2px;
  opacity:1;transform:translateY(0);
  transition:opacity .18s ease, transform .18s ease;
}
.vq-model-dropdown.hidden{
  display:none !important;opacity:0;transform:translateY(6px);pointer-events:none;
}
.vq-model-item{
  display:flex;align-items:center;gap:10px;
  min-height:48px;padding:8px 12px;
  border:0;border-radius:10px;
  background:transparent;color:var(--text, #111827);
  cursor:pointer;text-align:left;
  transition:background .12s;
}
.vq-model-item:hover{background:var(--chip-bg, rgba(0,0,0,.04));}
.vq-model-item.is-active{background:var(--chip-bg, rgba(0,0,0,.04));}
.vq-model-item.is-locked{opacity:.45;cursor:not-allowed;}
.vq-model-item.is-locked:hover{background:transparent;}
.vq-model-item-text{flex:1;min-width:0;}
.vq-model-item-name{font-size:14px;font-weight:700;line-height:1.3;color:var(--text, #111827);}
.vq-model-item-desc{font-size:11px;color:var(--muted, #6b7280);line-height:1.3;margin-top:1px;}
.vq-model-check{
  font-size:18px;color:var(--accent, #6366f1);
  opacity:0;transition:opacity .12s;flex-shrink:0;
}
.vq-model-item.is-active .vq-model-check{opacity:1;}
.vq-model-upgrade{
  font-size:10px;font-weight:700;
  padding:2px 8px;border-radius:99px;
  background:var(--accent, #6366f1);color:#fff;
  white-space:nowrap;flex-shrink:0;cursor:pointer;
}
.vq-model-upgrade.hidden{display:none !important;}
/* ── Topbar model dropdown ── */
.vq-topbar-model-wrap{position:relative;display:inline-flex;}
.vq-topbar-model-btn{
  display:inline-flex;align-items:center;gap:6px;
