/* ── Thinking stream display (Professor / Seed Pro / Deepthink) ── */

/* ① Shimmer text */
.thinking-shimmer-container{padding:6px 0 10px;}
.thinking-shimmer-text{
  font-size:13px;font-weight:500;
  background:linear-gradient(90deg,rgba(0,0,0,.25) 0%,rgba(0,0,0,.6) 20%,rgba(99,102,241,1) 50%,rgba(0,0,0,.6) 80%,rgba(0,0,0,.25) 100%);
  background-size:200% auto;
  -webkit-background-clip:text;-webkit-text-fill-color:transparent;
  background-clip:text;
  animation:textShimmer 2s linear infinite;
}
.app-chat-think-stream-container.deepthink-mode .thinking-shimmer-text{
  background:linear-gradient(90deg,rgba(0,0,0,.25) 0%,rgba(139,92,246,.7) 20%,rgba(59,130,246,1) 50%,rgba(139,92,246,.7) 80%,rgba(0,0,0,.25) 100%);
  background-size:200% auto;
  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
  animation:textShimmer 1.5s linear infinite;
}
@keyframes textShimmer{
  0%{background-position:200% center;}
  100%{background-position:-200% center;}
}

/* ② Thinking steps — vertical timeline */
.thinking-steps{margin:4px 0;padding-left:4px;}
.thinking-step-item{display:flex;gap:8px;margin:3px 0;}
.step-connector{display:flex;flex-direction:column;align-items:center;width:16px;flex-shrink:0;}
.connector-dot{width:7px;height:7px;border-radius:50%;background:rgba(99,102,241,.45);flex-shrink:0;margin-top:7px;}
.connector-line{width:2px;flex:1;min-height:12px;background:rgba(0,0,0,.08);margin-top:3px;}
.thinking-step-item:last-child .connector-line{display:none;}
.step-header{
  display:flex;align-items:center;gap:6px;cursor:pointer;
  padding:3px 6px;border-radius:6px;transition:background .15s;user-select:none;
}
.step-header:hover{background:rgba(0,0,0,.04);}
.step-toggle{font-size:9px;color:rgba(0,0,0,.3);transition:transform .2s;flex-shrink:0;display:inline-block;}
.step-toggle.open{transform:rotate(90deg);}
.step-label{font-size:12px;color:rgba(0,0,0,.5);line-height:1.4;}
.step-detail{
  display:none;margin:3px 0 3px 20px;padding-left:10px;
  border-left:2px solid rgba(0,0,0,.07);
}
.step-detail.open{display:block;}
.step-detail-line{font-size:12px;color:rgba(0,0,0,.4);line-height:1.8;margin:1px 0;}

/* Sources inside steps */
.step-sources{margin-top:8px;}
.sources-header{font-size:11px;color:rgba(0,0,0,.3);margin-bottom:4px;}
.sources-list{display:flex;flex-direction:column;gap:2px;}
.source-item{
  display:flex;align-items:center;gap:6px;padding:3px 6px;border-radius:4px;
  text-decoration:none;font-size:12px;color:rgba(0,0,0,.5);
  transition:background .15s;margin:2px 0;max-width:280px;
}
.source-item:hover{background:rgba(0,0,0,.04);color:rgba(0,0,0,.75);}
.source-favicon{width:14px;height:14px;border-radius:2px;flex-shrink:0;}
.source-title{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}

/* Spinner for streaming */
.app-chat-think-stream-spinner{
  display:inline-block;width:10px;height:10px;
  border:2px solid rgba(0,0,0,.12);border-top-color:rgba(0,0,0,.35);
  border-radius:50%;animation:chatThinkSpin .7s linear infinite;
  margin-right:6px;vertical-align:middle;
}

/* ③ Completion */
.thinking-complete{
  display:flex;align-items:center;gap:6px;
  font-size:13px;color:rgba(0,0,0,.4);padding:4px 0 6px;
  animation:thinkFadeIn .3s ease;
}
.complete-check{color:#22c55e;font-weight:bold;font-size:14px;}
@keyframes thinkFadeIn{
  from{opacity:0;transform:translateY(-3px);}
  to{opacity:1;transform:translateY(0);}
}

/* Divider */
.thinking-divider{border:none;border-top:1px solid rgba(0,0,0,.08);margin:6px 0 8px;}

/* Fallback plain thinking text */
.app-chat-think-stream{margin-bottom:4px;}
.app-chat-think-stream-line{
  font-size:12px;color:rgba(0,0,0,.4);line-height:1.7;padding:1px 0;
  animation:chatThinkLineIn .3s ease both;
}
@keyframes chatThinkLineIn{
  from{opacity:0;transform:translateY(4px);}
  to{opacity:1;transform:translateY(0);}
}
@keyframes chatThinkSpin{
  to{transform:rotate(360deg);}
}
/* Image generation shimmer placeholder (shown in typing bubble) */
.app-chat-img-gen-placeholder{
  width:100%;
  max-width:280px;
  aspect-ratio:1/1;
  border-radius:12px;
  background:linear-gradient(90deg,#d4e4f7 25%,#eaf2fc 50%,#d4e4f7 75%);
  background-size:400% 100%;
  animation:imgGenShimmer 1.8s ease-in-out infinite;
  margin:10px 0 4px;
}
@keyframes imgGenShimmer{
  0%{background-position:100% 50%;}
  100%{background-position:-100% 50%;}
}
/* Generated image result */
.app-chat-img-gen-result{
  margin-top:10px;
  display:flex;
  flex-direction:column;
  gap:8px;
}
.app-chat-gen-image{
  max-width:100%;
  width:360px;
  border-radius:12px;
  border:1px solid #e2e8f0;
  box-shadow:0 2px 8px rgba(0,0,0,.08);
  display:block;
  cursor:zoom-in;
  transition:transform .15s ease,box-shadow .15s ease;
}
.app-chat-gen-image:hover{
  transform:scale(1.015);
  box-shadow:0 4px 16px rgba(0,0,0,.14);
}
.app-chat-gen-caption{
  font-size:12px;
  color:#888;
  margin:0;
  line-height:1.5;
}

/* ── Skills / Apps Page ── */
.skills-overlay{
  position:fixed;inset:0;z-index:130;background:var(--bg);
  display:flex;flex-direction:column;
  transform:translateX(100%);transition:transform .3s cubic-bezier(.22,1,.36,1);
}
.skills-overlay.is-open{transform:translateX(0);}
.skills-topbar{
  display:flex;align-items:center;gap:12px;
  padding:12px 16px;border-bottom:1px solid var(--border);
  background:var(--bar-bg);backdrop-filter:blur(12px);
}
.skills-topbar-title{font-size:17px;font-weight:700;color:var(--text);flex:1;}
.skills-body{flex:1;overflow-y:auto;padding:20px 16px 40px;}
.skills-grid{display:grid;grid-template-columns:1fr;gap:12px;max-width:480px;margin:0 auto;}
.skill-card{
  background:var(--panel);border:1px solid var(--border);border-radius:16px;
  padding:20px;display:flex;flex-direction:column;gap:12px;
  box-shadow:0 2px 8px rgba(0,0,0,.04);transition:box-shadow .15s;
}
.skill-card:hover{box-shadow:0 4px 16px rgba(0,0,0,.08);}
.skill-card-head{display:flex;align-items:center;gap:12px;}
.skill-card-icon{
  width:44px;height:44px;border-radius:12px;display:grid;place-items:center;
  font-size:22px;flex-shrink:0;
}
.skill-card-icon.cal{background:#e8f5e9;} .skill-card-icon.voice{background:#e3f2fd;}
.skill-card-icon.clip{background:#fff3e0;} .skill-card-icon.translate{background:#f3e5f5;}
.skill-card-icon.drive{background:#e8eaf6;}
.skill-card-info{flex:1;min-width:0;}
.skill-card-name{font-size:15px;font-weight:700;color:var(--text);}
.skill-card-desc{font-size:12px;color:var(--muted);margin-top:2px;}
.skill-card-status{
  display:inline-flex;align-items:center;gap:4px;
  font-size:11px;font-weight:600;border-radius:99px;padding:2px 10px;
}
.skill-card-status.connected{background:#e8f5e9;color:#2e7d32;}
.skill-card-status.not-connected{background:var(--chip-bg);color:var(--muted);}
.skill-card-actions{display:flex;gap:8px;margin-top:4px;}
.skill-setup-btn{
  flex:1;height:38px;border:0;border-radius:10px;font-size:13px;font-weight:600;
  cursor:pointer;transition:background .15s;
  background:var(--accent);color:#fff;
}
.skill-setup-btn:hover{opacity:.88;}
.skill-setup-btn.connected{background:var(--chip-bg);color:var(--muted);cursor:default;}
.skill-disconnect-btn{
  height:38px;padding:0 14px;border:1px solid var(--border);border-radius:10px;
  font-size:12px;color:var(--muted);background:transparent;cursor:pointer;
}
/* ── Skill Consent Modal ── */
.skill-consent-modal{
  position:fixed;inset:0;z-index:140;display:flex;align-items:center;justify-content:center;
  pointer-events:none;opacity:0;transition:opacity .25s;
}
.skill-consent-modal.is-open{opacity:1;pointer-events:auto;}
.skill-consent-backdrop{position:absolute;inset:0;background:rgba(0,0,0,.4);backdrop-filter:blur(8px);}
.skill-consent-card{
  position:relative;width:340px;max-height:80vh;overflow-y:auto;
  background:var(--panel);border-radius:20px;padding:28px 24px 20px;
  box-shadow:0 20px 60px rgba(0,0,0,.18);
  transform:translateY(20px);transition:transform .3s cubic-bezier(.22,1,.36,1);
}
.skill-consent-modal.is-open .skill-consent-card{transform:translateY(0);}
.skill-consent-icons{display:flex;align-items:center;justify-content:center;gap:16px;margin-bottom:20px;}
.skill-consent-user-icon,.skill-consent-app-icon{
  width:52px;height:52px;border-radius:var(--radius, 12px);display:grid;place-items:center;font-size:24px;
}
.skill-consent-user-icon{background:var(--chip-bg);color:var(--text);}
.skill-consent-app-icon{background:#e3f2fd;font-size:28px;}
.skill-consent-arrow{font-size:18px;color:var(--muted);}
.skill-consent-name{font-size:18px;font-weight:700;color:var(--text);text-align:center;margin-bottom:16px;}
.skill-consent-perms{list-style:none;padding:0;margin:0 0 20px;display:flex;flex-direction:column;gap:10px;}
.skill-consent-perms li{
  display:flex;align-items:flex-start;gap:10px;font-size:13px;color:var(--text);line-height:1.5;
}
.skill-consent-perms li .perm-icon{font-size:18px;flex-shrink:0;margin-top:1px;}
.skill-consent-btns{display:flex;gap:10px;}
.skill-consent-deny{
  flex:1;height:42px;border:1px solid var(--border);border-radius:12px;
  background:transparent;color:var(--muted);font-size:14px;font-weight:600;cursor:pointer;
}
.skill-consent-allow{
  flex:1;height:42px;border:0;border-radius:12px;
  background:var(--accent);color:#fff;font-size:14px;font-weight:600;cursor:pointer;
}
.skill-consent-allow:hover{opacity:.88;}
/* ── Chat Voice Button ── */
.app-chat-mic-btn{
  width:36px;height:36px;border:0;border-radius:50%;
  background:var(--accent);color:#fff;cursor:pointer;
  display:inline-grid;place-items:center;flex-shrink:0;
  transition:background .15s;
}
.app-chat-mic-btn:hover{opacity:.85;}
.app-chat-mic-btn.is-recording{background:#ef4444;animation:vqMicPulse 1s infinite;}
.app-chat-mic-btn .ms{font-size:20px;}
@keyframes vqMicPulse{
  0%,100%{box-shadow:0 0 0 0 rgba(239,68,68,.4);}
  50%{box-shadow:0 0 0 8px rgba(239,68,68,0);}
}

/* ── Image Lightbox ── */
#vqImgLightbox{
  position:fixed;inset:0;z-index:9200;
  display:flex;align-items:center;justify-content:center;
  background:rgba(0,0,0,.85);
  backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);
  opacity:0;pointer-events:none;
  transition:opacity .22s ease;
}
#vqImgLightbox.is-open{
  opacity:1;pointer-events:auto;
}
#vqImgLightbox.is-closing{
  opacity:0;pointer-events:none;
  transition:opacity .2s ease;
}
.vq-img-lb-inner{
  display:flex;flex-direction:column;align-items:flex-end;
  transform:scale(.88) translateY(12px);
  transition:transform .28s cubic-bezier(.34,1.4,.64,1);
}
#vqImgLightbox.is-open .vq-img-lb-inner{
  transform:scale(1) translateY(0);
}
#vqImgLightbox.is-closing .vq-img-lb-inner{
  transform:scale(.88) translateY(12px);
  transition:transform .2s ease;
}
.vq-img-lb-topbar{
  width:100%;display:flex;justify-content:flex-end;
  padding-bottom:10px;
}
.vq-img-lb-close{
  display:inline-flex;align-items:center;gap:5px;
  padding:6px 14px 6px 10px;border-radius:8px;border:0;
  background:rgba(255,255,255,.16);color:#fff;
  font-size:13px;font-weight:500;cursor:pointer;
  transition:background .15s ease;
  font-family:inherit;
}
.vq-img-lb-close:hover{background:rgba(255,255,255,.28);}
.vq-img-lb-close .ms{font-size:17px;line-height:1;}
.vq-img-lb-img{
  display:block;
  max-width:min(90vw,900px);max-height:78vh;
  border-radius:12px;
  box-shadow:0 12px 48px rgba(0,0,0,.55);
  object-fit:contain;
}
.vq-img-lb-bottombar{
  width:100%;display:flex;justify-content:flex-end;
  padding-top:10px;
}
.vq-img-lb-download{
  display:inline-flex;align-items:center;gap:5px;
  padding:6px 14px 6px 10px;border-radius:8px;border:0;
  background:rgba(255,255,255,.16);color:#fff;
  font-size:13px;font-weight:500;cursor:pointer;
  transition:background .15s ease;
  font-family:inherit;
}
.vq-img-lb-download:hover{background:rgba(255,255,255,.28);}
.vq-img-lb-download .ms{font-size:17px;line-height:1;}
body[data-app-tab="chat"] .app-chat-msg.is-typing .app-chat-bubble{
  box-shadow:
    0 14px 28px rgba(56, 117, 176, .10),
