  line-height:1.55;
}
.app-chat-support-phone{
  color:#111827;
  font-size:15px;
  font-weight:800;
}
.app-chat-empty-state{
  display:grid !important;
  place-items:center;
  min-height:54dvh;
  padding:18px 0 8px;
}
.app-chat-empty-shell{
  width:min(880px, 100%);
  display:grid !important;
  gap:18px;
}
.app-chat-empty-hero{
  display:grid !important;
  gap:10px;
  padding:24px 24px 22px;
  border-radius:28px;
  border:1px solid rgba(96, 162, 213, .14);
  background:
    radial-gradient(circle at top left, rgba(170, 239, 255, .42), transparent 32%),
    linear-gradient(135deg, rgba(255,255,255,.96), rgba(244,251,255,.88));
  box-shadow:0 22px 50px rgba(52, 118, 179, .08);
}
.app-chat-empty-kicker{
  font-size:11px;
  font-weight:800;
  letter-spacing:.18em;
  color:#0f6e9a;
}
.app-chat-empty-hero h3{
  margin:0;
  font-size:28px;
  line-height:1.24;
  letter-spacing:-.03em;
  color:#07131f;
}
.app-chat-empty-hero p{
  margin:0;
  max-width:620px;
  color:#4d6a80;
  line-height:1.8;
}
.app-chat-empty-panel{
  display:grid !important;
  gap:14px;
  padding:20px;
  border-radius:24px;
  border:1px solid rgba(96, 162, 213, .12);
  background:rgba(255,255,255,.8);
}
.app-chat-empty-panel-head{
  display:grid !important;
  gap:4px;
}
.app-chat-empty-panel-head strong{
  font-size:16px;
}
.app-chat-empty-panel-head span{
  color:#5f7a90;
  font-size:13px;
}
.app-chat-empty-chip-grid{
  display:grid !important;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:10px;
}
.app-chat-welcome-chip{
  min-height:50px;
  padding:12px 14px;
  text-align:left;
  border-radius:var(--radius-lg, 16px);
  border:1px solid rgba(96, 162, 213, .12);
  background:rgba(255,255,255,.96);
  color:#0c2136;
  font-size:14px;
  font-weight:700;
}
body[data-app-tab="chat"] .app-chat-composer{
  width:min(1000px, calc(100vw - 24px));
  border-radius:26px;
  border:1px solid rgba(96, 162, 213, .15);
  background:rgba(255,255,255,.86);
  backdrop-filter:blur(18px);
  box-shadow:0 24px 56px rgba(52, 118, 179, .14);
  padding:12px;
}
.app-chat-composer-inner{
  display:grid !important;
  gap:10px;
}
body[data-app-tab="chat"] .app-chat-input{
  min-height:56px;
  max-height:240px;
  border-radius:var(--radius-lg, 16px);
  background:rgba(243, 249, 255, .92);
  border:1px solid rgba(96, 162, 213, .12);
  padding:14px 16px;
  font-size:15px;
}
.app-chat-composer-bottom{
  display:flex !important;
  align-items:center;
  justify-content:space-between;
  gap:12px;
}
.app-chat-compose-hint{
  color:#5f7a90;
  font-size:12px;
}
/* ── Slash command popup ── */
.app-chat-slash-popup{
  position:absolute;bottom:100%;left:0;right:0;
  margin-bottom:6px;z-index:40;
  background:rgba(15,10,40,.97);
  border:0.5px solid rgba(255,255,255,.1);
  border-radius:12px;
  padding:6px 0;
  max-height:340px;overflow-y:auto;
  backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);
  box-shadow:0 8px 32px rgba(0,0,0,.35);
}
.app-chat-slash-popup.hidden{display:none;}
.app-chat-slash-recent{
  padding:6px 14px 4px;font-size:11px;color:rgba(255,255,255,.4);
  display:flex;align-items:center;gap:6px;flex-wrap:wrap;
}
.app-chat-slash-recent-cmd{
  display:inline-block;padding:2px 8px;border-radius:6px;
  background:rgba(255,255,255,.07);color:rgba(255,255,255,.6);
  font-size:11px;cursor:pointer;
}
.app-chat-slash-recent-cmd:hover{background:rgba(255,255,255,.12);}
.app-chat-slash-item{
  display:grid;grid-template-columns:1fr auto;align-items:center;
  padding:9px 14px;cursor:pointer;transition:background .1s ease;
}
.app-chat-slash-item:hover,
.app-chat-slash-item.is-selected{
  background:rgba(92,75,232,.4);
}
.app-chat-slash-item-left{display:flex;flex-direction:column;gap:1px;min-width:0;}
.app-chat-slash-cmd{color:#fff;font-size:14px;font-weight:500;white-space:nowrap;}
.app-chat-slash-desc{color:rgba(255,255,255,.45);font-size:12px;}
.app-chat-slash-badge{
  font-size:11px;color:rgba(255,255,255,.5);
  padding:2px 8px;border-radius:6px;
  background:rgba(255,255,255,.06);white-space:nowrap;
}
/* ── Slash command mode banner ── */
.app-chat-slash-banner{
  display:flex;align-items:center;gap:8px;
  padding:8px 14px;
  background:rgba(92,75,232,.15);
  border:1px solid rgba(92,75,232,.25);
  border-radius:10px;font-size:13px;color:#c4b8ff;
  margin-bottom:6px;
}
.app-chat-slash-banner.hidden{display:none;}
.app-chat-slash-banner-label{flex:1;min-width:0;}
.app-chat-slash-banner-meta{color:rgba(255,255,255,.45);font-size:12px;}
.app-chat-slash-banner-close{
  border:0;background:transparent;color:rgba(255,255,255,.5);
  cursor:pointer;font-size:18px;line-height:1;padding:0 2px;
}
.app-chat-slash-banner-close:hover{color:#fff;}
/* Slash usage card */
.app-chat-usage-card{
  background:#1a1432;
  border:1px solid rgba(255,255,255,.1);
  border-radius:12px;padding:16px;margin:4px 0;
  color:#e2e8f0;
}
.app-chat-usage-head{
  display:flex;align-items:center;justify-content:space-between;
  margin-bottom:12px;
}
.app-chat-usage-head-title{font-size:15px;font-weight:600;color:#fff;}
.app-chat-usage-head-label{font-size:12px;color:rgba(255,255,255,.5);
  padding:2px 8px;border-radius:6px;background:rgba(255,255,255,.1);
}
.app-chat-usage-row{
  display:grid;grid-template-columns:130px 1fr 60px;align-items:center;
  gap:8px;padding:6px 0;
}
.app-chat-usage-label{font-size:13px;color:rgba(255,255,255,.7);}
.app-chat-usage-bar{height:6px;border-radius:3px;background:rgba(255,255,255,.15);overflow:hidden;}
.app-chat-usage-bar-fill{height:100%;border-radius:3px;transition:width .3s ease;}
.app-chat-usage-count{font-size:12px;color:rgba(255,255,255,.5);text-align:right;}
.app-chat-usage-footer{
  margin-top:12px;padding-top:10px;
  border-top:1px solid rgba(255,255,255,.12);
  display:flex;flex-direction:column;gap:4px;
  font-size:12px;color:rgba(255,255,255,.5);
}
/* ── citation badges ── */
.vq-citation{
  display:inline-flex;align-items:center;gap:4px;
  background:rgba(92,75,232,0.15);
  border:1px solid rgba(92,75,232,0.3);
  border-radius:20px;padding:2px 8px;
  font-size:11px;color:#7c6eef;
  cursor:pointer;margin:0 2px;
  vertical-align:middle;position:relative;
  white-space:nowrap;transition:background 0.15s;
  text-decoration:none;
}
.vq-citation:hover{background:rgba(92,75,232,0.25);}
.vq-citation-tooltip{
  display:none;position:absolute;bottom:calc(100% + 8px);
  left:50%;transform:translateX(-50%);
  background:rgba(15,10,40,0.97);border:1px solid rgba(255,255,255,0.1);
  border-radius:10px;padding:10px 12px;width:260px;z-index:9999;
  box-shadow:0 4px 20px rgba(0,0,0,0.4);
}
.vq-citation:hover .vq-citation-tooltip,
.vq-citation.active .vq-citation-tooltip{display:block;}
.vq-citation-tooltip-title{
  font-size:12px;font-weight:600;color:#fff;margin-bottom:4px;line-height:1.4;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;
}
.vq-citation-tooltip-url{
  font-size:11px;color:rgba(255,255,255,0.5);margin-bottom:8px;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.vq-citation-tooltip-open{
  display:block;margin-top:8px;font-size:11px;color:#7c6eef;text-decoration:none;
  border-top:1px solid rgba(255,255,255,0.08);padding-top:8px;
}
.vq-citation-tooltip-open:hover{color:#a594f9;}
/* ── /qredit card ── */
.slash-qredit-balance{font-size:28px;font-weight:700;color:#fff;padding:8px 0 12px;}
.slash-qredit-symbol{font-size:16px;color:rgba(255,255,255,.4);font-weight:500;}
.slash-qredit-history{display:grid;gap:1px;}
.slash-qredit-row{display:grid;grid-template-columns:70px 1fr 80px;align-items:center;padding:7px 0;border-bottom:1px solid rgba(255,255,255,.04);font-size:12px;}
.slash-qredit-amt{font-weight:600;}
.slash-qredit-amt.is-in{color:#00e676;}
.slash-qredit-amt.is-out{color:#ff5252;}
.slash-qredit-reason{color:rgba(255,255,255,.5);}
.slash-qredit-ts{color:rgba(255,255,255,.3);text-align:right;}
.slash-qredit-empty{color:rgba(255,255,255,.3);font-size:12px;padding:8px 0;}
.slash-qredit-footer{margin-top:12px;}
.slash-qredit-add-btn{border:0;background:rgba(92,75,232,.2);color:#a78bfa;padding:8px 16px;border-radius:8px;font-size:13px;cursor:pointer;}
.slash-qredit-add-btn:hover{background:rgba(92,75,232,.35);}
/* ── /help card ── */
.slash-help-search{width:100%;padding:8px 12px;border:1px solid rgba(255,255,255,.1);border-radius:8px;background:rgba(255,255,255,.05);color:#fff;font-size:13px;margin-bottom:8px;box-sizing:border-box;}
.slash-help-search::placeholder{color:rgba(255,255,255,.3);}
.slash-help-cats{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px;}
.slash-help-cat-btn{border:1px solid rgba(255,255,255,.1);background:transparent;color:rgba(255,255,255,.6);padding:4px 12px;border-radius:16px;font-size:12px;cursor:pointer;}
.slash-help-cat-btn:hover,.slash-help-cat-btn.is-active{background:rgba(92,75,232,.3);color:#c4b8ff;border-color:rgba(92,75,232,.4);}
.slash-help-list{display:grid;gap:2px;}
.slash-help-item{padding:10px 12px;border-radius:8px;cursor:pointer;transition:background .1s;}
.slash-help-item:hover{background:rgba(255,255,255,.04);}
.slash-help-q{font-size:13px;color:rgba(255,255,255,.8);font-weight:500;}
.slash-help-a{font-size:12px;color:rgba(255,255,255,.5);margin-top:6px;line-height:1.6;}
.slash-help-empty{text-align:center;padding:16px;font-size:13px;color:rgba(255,255,255,.35);}
.slash-help-ask-btn{border:0;background:rgba(92,75,232,.2);color:#a78bfa;padding:6px 14px;border-radius:8px;font-size:12px;cursor:pointer;margin-top:6px;}
/* ── /goal card ── */
.slash-goal-item{display:flex;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid rgba(255,255,255,.04);}
.slash-goal-item.is-expired{opacity:.5;}
.slash-goal-name{font-size:14px;color:#fff;font-weight:500;flex:1;min-width:0;}
.slash-goal-meta{font-size:11px;color:rgba(255,255,255,.4);}
.slash-goal-del{border:0;background:transparent;color:rgba(255,255,255,.3);font-size:14px;cursor:pointer;padding:2px 6px;}
.slash-goal-del:hover{color:#ff5252;}
.slash-goal-form{display:grid;gap:8px;margin-top:10px;}
.slash-goal-input{padding:8px 12px;border:1px solid rgba(255,255,255,.1);border-radius:8px;background:rgba(255,255,255,.05);color:#fff;font-size:13px;}
.slash-goal-input::placeholder{color:rgba(255,255,255,.3);}
.slash-goal-save-btn{border:0;background:rgba(92,75,232,.3);color:#c4b8ff;padding:10px;border-radius:8px;font-size:14px;font-weight:600;cursor:pointer;}
.slash-goal-save-btn:hover{background:rgba(92,75,232,.5);}
.slash-goal-limit{font-size:12px;color:rgba(255,255,255,.4);padding:8px 0;}
/* ── /theme list ── */
.slash-theme-list{display:grid;gap:4px;}
.slash-theme-item{display:grid;grid-template-columns:40px 1fr auto;align-items:center;gap:10px;padding:10px 12px;border-radius:12px;cursor:pointer;border:1px solid rgba(255,255,255,.06);background:rgba(255,255,255,.03);transition:background .15s,border-color .15s;}
.slash-theme-item:hover{background:rgba(255,255,255,.07);}
.slash-theme-item.is-selected{border-color:rgba(92,75,232,.5);background:rgba(92,75,232,.08);}
.slash-theme-preview{width:36px;height:36px;border-radius:10px;border:1px solid rgba(255,255,255,.1);display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;overflow:hidden;flex-shrink:0;}
.slash-theme-preview span{display:block;}
.slash-theme-info{display:flex;flex-direction:column;gap:1px;min-width:0;}
.slash-theme-label{font-size:14px;font-weight:600;color:rgba(255,255,255,.88);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.slash-theme-desc{font-size:11px;color:rgba(255,255,255,.38);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.slash-theme-check{font-size:18px;color:#818cf8;}
/* ── /export card ── */
.slash-export-section{margin-bottom:12px;}
.slash-export-label{font-size:12px;color:rgba(255,255,255,.4);margin-bottom:6px;font-weight:600;}
.slash-export-options{display:grid;gap:4px;}
.slash-export-radio,.slash-export-check{display:flex;align-items:center;gap:8px;font-size:13px;color:rgba(255,255,255,.7);cursor:pointer;padding:4px 0;}
.slash-export-radio input,.slash-export-check input{accent-color:#5c4be8;}
.slash-export-btn{width:100%;border:0;background:rgba(92,75,232,.3);color:#c4b8ff;padding:12px;border-radius:10px;font-size:14px;font-weight:600;cursor:pointer;margin-top:4px;}
.slash-export-btn:hover{background:rgba(92,75,232,.5);}
/* ── VQ Board overlay ── */
/* ═══ Quick Board — Clean Redesign ═══ */
.vqboard-overlay{
  position:fixed;inset:0;z-index:9000;
  background:#fff;
  display:flex;flex-direction:column;
  opacity:0;pointer-events:none;
  transition:opacity .25s ease;
}
.vqboard-overlay.is-open{opacity:1;pointer-events:auto;}

/* Header */
.vqboard-header{
  display:flex;align-items:center;justify-content:space-between;
  padding:0 20px;height:52px;
  background:rgba(255,255,255,.9);
  backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);
  border-bottom:1px solid #e2e8f0;
  flex:0 0 auto;z-index:2;
}
.vqboard-header-title{
  display:flex;align-items:center;gap:8px;
  font-size:14px;font-weight:800;color:#0f172a;letter-spacing:-.01em;
}
.vqboard-header-title .ms{font-size:18px;color:#0f172a;}
.vqboard-close{
  width:36px;height:36px;display:inline-grid;place-items:center;
  border:0;border-radius:10px;background:transparent;color:#94a3b8;cursor:pointer;
  transition:all .15s;
}
.vqboard-close:hover{background:#f1f5f9;color:#0f172a;}
.vqboard-close .ms{font-size:20px;}

/* Body (2-pane) */
.vqboard-body{
  flex:1 1 auto;min-height:0;
  display:flex;gap:0;overflow:hidden;
}

/* Chat panel */
.vqboard-chat{
  flex:0 0 360px;max-width:400px;min-width:280px;
  display:flex;flex-direction:column;
  border-right:1px solid #e2e8f0;background:#fff;
}
.vqboard-chat-scroll{
  flex:1 1 auto;overflow-y:auto;padding:20px;min-height:0;
}
.vqboard-chat-msgs{display:flex;flex-direction:column;gap:10px;}
.vqboard-msg{
  max-width:85%;padding:12px 16px;
  font-size:14px;line-height:1.55;word-break:break-word;
}
.vqboard-msg.is-user{
  align-self:flex-end;
  background:#0f172a;color:#fff;
  border-radius:var(--radius-lg, 16px) 18px 4px 18px;
}
.vqboard-msg.is-ai{
  align-self:flex-start;
  background:#f1f5f9;color:#0f172a;
  border-radius:var(--radius-lg, 16px) 18px 18px 4px;
  font-weight:500;
}

/* Canvas panel */
.vqboard-canvas-wrap{
  flex:1 1 auto;min-width:0;display:flex;flex-direction:column;
  padding:0;background:#f8fafc;
}
.vqboard-canvas-toolbar{
  display:flex;align-items:center;gap:6px;
  padding:10px 16px;flex:0 0 auto;
  border-bottom:1px solid #e2e8f0;
  background:rgba(255,255,255,.7);
  backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);
}
.vqboard-tool-btn{
  display:inline-flex;align-items:center;gap:5px;
  padding:7px 14px;
  border:1.5px solid #e2e8f0;border-radius:10px;
  background:#fff;color:#64748b;
  font-size:12px;font-weight:600;cursor:pointer;
  transition:all .15s;
}
.vqboard-tool-btn:hover{
  border-color:#cbd5e1;background:#f8fafc;color:#0f172a;
}
.vqboard-tool-btn .ms{font-size:15px;}
.vqboard-canvas{
  flex:1 1 auto;min-height:0;
  background:#fff;
  margin:16px;border-radius:16px;
  border:2px solid #e2e8f0;
  box-shadow:none;
  overflow-y:auto;padding:28px;
}
.vqboard-canvas-empty{
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  height:100%;color:#cbd5e1;font-size:13px;gap:10px;font-weight:500;
}
.vqboard-canvas-empty .ms{font-size:56px;color:#e2e8f0;}

/* Footer / input bar */
.vqboard-footer{
  display:flex;align-items:center;gap:8px;
  padding:12px 16px;
  background:#fff;border-top:1px solid #e2e8f0;
  flex:0 0 auto;
}
.vqboard-mic{
  width:40px;height:40px;display:inline-grid;place-items:center;
  border:0;border-radius:12px;background:#f1f5f9;color:#64748b;cursor:pointer;
  flex:0 0 auto;transition:all .15s;
}
.vqboard-mic:hover{background:#e2e8f0;color:#0f172a;}
.vqboard-mic.is-recording{
  background:#ef4444;color:#fff;
  animation:vqboard-pulse 1.2s ease infinite;
}
.vqboard-mic .ms{font-size:20px;}
@keyframes vqboard-pulse{
  0%,100%{box-shadow:0 0 0 0 rgba(239,68,68,.3);}
  50%{box-shadow:0 0 0 8px rgba(239,68,68,0);}
}
.vqboard-input{
  flex:1 1 auto;min-width:0;padding:10px 16px;
  border:2px solid #e2e8f0;border-radius:var(--radius, 12px);
  font-size:14px;font-weight:500;
  background:#fff;color:#0f172a;resize:none;
  font-family:inherit;transition:border-color .15s;
}
.vqboard-input:focus{
  border-color:#94a3b8;outline:none;
}
.vqboard-input::placeholder{color:#cbd5e1;font-weight:400;}
.vqboard-send{
  width:40px;height:40px;display:inline-grid;place-items:center;
  border:0;border-radius:12px;background:var(--vq-accent,#756DB3);color:var(--vq-accent-contrast,#fff);cursor:pointer;
  flex:0 0 auto;transition:background .15s;
}
.vqboard-send:hover{background:var(--vq-accent-hover,#6961A8);}
.vqboard-send .ms{font-size:18px;}

/* Draw layer */
.vqboard-draw-layer{
  position:absolute;inset:16px;
  z-index:20;pointer-events:none;
  border-radius:16px;
}
.vqboard-draw-layer.is-active{
  pointer-events:auto;cursor:crosshair;
}
.vqboard-draw-layer path{
  fill:none;stroke:#0f172a;stroke-width:2.5;
  stroke-linecap:round;stroke-linejoin:round;
}
.vqboard-canvas-wrap{position:relative;}
.vqboard-tool-btn.is-active{
  background:#0f172a !important;color:#fff !important;
  border-color:#0f172a !important;
}
.vqboard-tool-btn.is-active .ms{color:#fff !important;}

/* Draggable items */
.vqboard-draggable{
  position:relative;
  transition:box-shadow .15s ease;
}
.vqboard-draggable:hover{
  box-shadow:0 0 0 2px rgba(100,146,255,.25);
  border-radius:12px;
}
.vqboard-drag-handle{
  position:absolute;top:-2px;left:50%;transform:translateX(-50%);
  width:28px;height:16px;
  display:flex;align-items:center;justify-content:center;
  cursor:grab;opacity:0;transition:opacity .15s;
  border-radius:0 0 6px 6px;background:rgba(241,245,249,.9);
  z-index:3;
}
.vqboard-draggable:hover .vqboard-drag-handle{opacity:1;}
.vqboard-item-del{
  position:absolute;top:4px;right:4px;
  width:24px;height:24px;
  display:inline-grid;place-items:center;
  border:0;border-radius:8px;background:rgba(241,245,249,.9);
  color:#94a3b8;cursor:pointer;
  opacity:0;transition:opacity .15s, color .15s;
  z-index:3;
}
.vqboard-draggable:hover .vqboard-item-del{opacity:1;}
.vqboard-item-del:hover{background:#fef2f2;color:#ef4444;}
.vqboard-resizer{
  position:absolute;bottom:2px;right:2px;
  width:14px;height:14px;cursor:se-resize;
  opacity:0;transition:opacity .15s;z-index:3;
  background:linear-gradient(135deg, transparent 50%, #cbd5e1 50%);
  border-radius:0 0 4px 0;
}
.vqboard-draggable:hover .vqboard-resizer{opacity:1;}

/* Empty state & templates */
.vqboard-empty-icon .ms{
  font-size:52px;color:#e2e8f0;display:block;margin-bottom:4px;
}
.vqboard-empty-title{
  font-size:18px;font-weight:800;color:#0f172a;letter-spacing:-.02em;margin-bottom:2px;
}
.vqboard-empty-sub{
  font-size:13px;color:#94a3b8;font-weight:500;margin-bottom:20px;
}
.vqboard-templates{
  display:grid;grid-template-columns:repeat(3, 1fr);gap:10px;
  max-width:400px;width:100%;
}
.vqboard-tpl-btn{
  display:flex;flex-direction:column;align-items:center;gap:6px;
  padding:16px 8px;
  border:2px solid #e2e8f0;border-radius:var(--radius, 12px);
  background:#fff;color:#64748b;
  font-size:12px;font-weight:600;cursor:pointer;
  transition:all .18s ease;
}
.vqboard-tpl-btn:hover{
  border-color:#cbd5e1;background:#f8fafc;color:#0f172a;
  transform:translateY(-2px);
}
.vqboard-tpl-btn .ms{font-size:24px;color:#94a3b8;transition:color .15s;}
.vqboard-tpl-btn:hover .ms{color:#0f172a;}

/* Mobile */
@media(max-width:768px){
  .vqboard-body{flex-direction:column-reverse;}
  .vqboard-chat{
    flex:0 0 auto;max-width:none;max-height:45%;
    border-right:0;border-top:1px solid #e2e8f0;
  }
  .vqboard-canvas-wrap{flex:1 1 auto;}
  .vqboard-canvas{margin:10px;padding:20px;}
  .vqboard-templates{grid-template-columns:repeat(2, 1fr);}
}
/* ═══ Quick Sede ═══ */
.sede-overlay{
  position:fixed;inset:0;z-index:9100;
  background:var(--bg, #f5f5f7);
  display:flex;
  opacity:0;pointer-events:none;
  transition:opacity .2s ease;
}
.sede-overlay.is-open{opacity:1;pointer-events:auto;}
/* Sidebar */
.sede-sidebar{
  width:260px;flex:0 0 260px;
  background:var(--panel, #fff);
  border-right:1px solid var(--border, rgba(0,0,0,.08));
  display:flex;flex-direction:column;
}
.sede-sidebar-header{
  padding:16px;border-bottom:1px solid var(--border);
  display:flex;align-items:center;justify-content:space-between;
}
.sede-sidebar-title{font-size:15px;font-weight:800;color:var(--text);}
.sede-new-btn{
  height:32px;padding:0 12px;border:0;border-radius:8px;
  background:var(--accent, #6366f1);color:#fff;
  font-size:12px;font-weight:600;cursor:pointer;
  display:inline-flex;align-items:center;gap:4px;
}
.sede-new-btn:hover{opacity:.85;}
.sede-session-list{
  flex:1;overflow-y:auto;padding:8px;
  display:flex;flex-direction:column;gap:2px;
}
.sede-session-item{
  padding:10px 12px;border-radius:10px;
  border:0;background:transparent;text-align:left;
  cursor:pointer;color:var(--text);font-size:13px;
  transition:background .12s;display:flex;flex-direction:column;gap:2px;
}
.sede-session-item:hover{background:var(--chip-bg, rgba(0,0,0,.04));}
.sede-session-item.is-active{background:var(--chip-bg, rgba(0,0,0,.06));font-weight:600;}
.sede-session-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.sede-session-date{font-size:10px;color:var(--muted);font-weight:400;}
/* Main chat area */
.sede-main{flex:1;display:flex;flex-direction:column;min-width:0;}
.sede-topbar{
  display:flex;align-items:center;gap:12px;
  padding:10px 20px;border-bottom:1px solid var(--border);
  background:var(--panel, #fff);flex:0 0 auto;
}
.sede-topbar-title{flex:1;font-size:15px;font-weight:700;color:var(--text);}
.sede-topbar-model{font-size:11px;color:var(--muted);font-weight:600;
  background:var(--chip-bg);padding:3px 10px;border-radius:99px;}
.sede-close-btn{
  width:36px;height:36px;display:inline-grid;place-items:center;
  border:0;border-radius:8px;background:transparent;color:var(--muted);cursor:pointer;
}
.sede-close-btn:hover{background:var(--chip-bg);color:var(--text);}
.sede-chat-scroll{
  flex:1;overflow-y:auto;padding:20px;min-height:0;
}
.sede-chat-msgs{
  max-width:800px;margin:0 auto;
  display:flex;flex-direction:column;gap:16px;
}
.sede-msg{
  max-width:90%;padding:12px 16px;border-radius:16px;
  font-size:14px;line-height:1.7;word-break:break-word;
}
.sede-msg.is-user{
  align-self:flex-end;background:var(--accent, #6366f1);color:#fff;
  border-bottom-right-radius:4px;
}
.sede-msg.is-ai{
  align-self:flex-start;background:var(--panel, #fff);color:var(--text);
  border:1px solid var(--border);border-bottom-left-radius:4px;
  box-shadow:0 1px 3px rgba(0,0,0,.04);
}
.sede-msg.is-ai pre{
  background:rgba(0,0,0,.04);border-radius:8px;padding:12px;
  overflow-x:auto;font-size:13px;margin:8px 0;
}
.sede-msg.is-ai code{font-family:'Fira Code',monospace,inherit;font-size:13px;}
.sede-empty{
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  height:100%;color:var(--muted);gap:12px;text-align:center;
}
