body[data-chat-fontsize] #appAiChatShell .app-chat-bubble,
body[data-chat-fontsize][data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] #appAiChatShell .app-chat-md,
body[data-chat-fontsize] #appAiChatShell .app-chat-md,
body[data-chat-fontsize] #appAiChatShell .app-chat-md p,
body[data-chat-fontsize] #appAiChatShell .app-chat-md li,
body[data-chat-fontsize][data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] #appAiChatShell .app-chat-input,
body[data-chat-fontsize] #appAiChatShell .app-chat-input{font-size:var(--chat-font-base,16px) !important;}
body[data-chat-fontsize] #appAiChatShell .app-chat-session-item{font-size:calc(var(--chat-font-base,16px) - 2px) !important;}
/* Settings modal */
.chat-settings-overlay{position:fixed;inset:0;z-index:10000;display:none;align-items:center;justify-content:center;background:rgba(15,23,42,.18);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);}
.chat-settings-overlay.is-open{display:flex;}
.chat-settings-card{width:min(440px,calc(100% - 32px));max-height:min(580px,80vh);background:#fff;border-radius:16px;border:1px solid rgba(226,232,240,.8);box-shadow:0 4px 6px rgba(15,23,42,.03),0 24px 64px rgba(15,23,42,.10);overflow:hidden;display:flex;flex-direction:column;animation:csIn .2s cubic-bezier(.22,1,.36,1);}
body[data-chat-dark="1"] .chat-settings-card{background:#1a1a1a;color:#fff;border:1px solid rgba(255,255,255,.1);box-shadow:0 4px 6px rgba(0,0,0,.1),0 24px 64px rgba(0,0,0,.4);}
@keyframes csIn{from{opacity:0;transform:scale(.97) translateY(6px);}to{opacity:1;transform:none;}}
.chat-settings-header{display:flex;align-items:center;justify-content:space-between;padding:18px 20px 14px;border-bottom:1px solid rgba(226,232,240,.6);flex-shrink:0;}
body[data-chat-dark="1"] .chat-settings-header{border-color:rgba(255,255,255,.08);}
.chat-settings-title{font-size:17px;font-weight:700;margin:0;letter-spacing:-.01em;color:#0f172a;}
body[data-chat-dark="1"] .chat-settings-title{color:#fff;}
.chat-settings-close{width:30px;height:30px;display:inline-grid;place-items:center;border:0;background:transparent;cursor:pointer;border-radius:8px;color:#64748b;font-size:20px;transition:background .12s ease;}
.chat-settings-close:hover{background:rgba(0,0,0,.06);}
body[data-chat-dark="1"] .chat-settings-close{color:rgba(255,255,255,.5);}
body[data-chat-dark="1"] .chat-settings-close:hover{background:rgba(255,255,255,.08);}
.chat-settings-body{padding:16px 20px 24px;display:grid;gap:20px;flex:1;overflow-y:auto;}
.chat-settings-section{display:grid;gap:8px;}
.chat-settings-section-title{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:#64748b;}
body[data-chat-dark="1"] .chat-settings-section-title{color:rgba(255,255,255,.4);}
.chat-settings-row{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:44px;}
.chat-settings-row-label{font-size:14px;font-weight:500;color:#1e293b;}
body[data-chat-dark="1"] .chat-settings-row-label{color:rgba(255,255,255,.85);}
/* Segmented control */
.chat-settings-seg{display:inline-flex;border-radius:10px;overflow:hidden;border:1px solid #e2e8f0;background:#f8fafc;}
body[data-chat-dark="1"] .chat-settings-seg{border-color:rgba(255,255,255,.1);background:rgba(255,255,255,.05);}
.chat-settings-seg-btn{padding:7px 16px;font-size:13px;font-weight:500;border:0;background:transparent;cursor:pointer;color:#64748b;transition:background .15s,color .15s,box-shadow .15s;}
body[data-chat-dark="1"] .chat-settings-seg-btn{color:rgba(255,255,255,.5);}
.chat-settings-seg-btn.is-active{background:#6366f1;color:#fff;box-shadow:0 1px 3px rgba(99,102,241,.25);}
body[data-chat-dark="1"] .chat-settings-seg-btn.is-active{background:#6366f1;color:#fff;}
.chat-settings-seg-btn:not(.is-active):hover{background:rgba(0,0,0,.04);}
body[data-chat-dark="1"] .chat-settings-seg-btn:not(.is-active):hover{background:rgba(255,255,255,.08);}
/* Toggle switch */
.chat-settings-toggle{position:relative;width:44px;height:24px;border-radius:12px;background:#cbd5e1;border:0;cursor:pointer;transition:background .2s;flex-shrink:0;}
body[data-chat-dark="1"] .chat-settings-toggle{background:rgba(255,255,255,.15);}
.chat-settings-toggle.is-on{background:#6366f1;}
body[data-chat-dark="1"] .chat-settings-toggle.is-on{background:#6366f1;}
.chat-settings-toggle::after{content:"";position:absolute;top:2px;left:2px;width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.15);transition:transform .2s cubic-bezier(.22,1,.36,1);}
.chat-settings-toggle.is-on::after{transform:translateX(20px);}
/* Select */
.chat-settings-select{padding:8px 12px;border-radius:10px;border:1px solid #e2e8f0;background:#fff;color:#1e293b;font-size:13.5px;cursor:pointer;font-family:inherit;outline:none;transition:border-color .15s,box-shadow .15s;}
.chat-settings-select:focus{border-color:#6366f1;box-shadow:0 0 0 3px rgba(99,102,241,.1);}
body[data-chat-dark="1"] .chat-settings-select{border-color:rgba(255,255,255,.12);background:#111;color:#fff;}
body[data-chat-dark="1"] .chat-settings-select:focus{border-color:#6366f1;box-shadow:0 0 0 3px rgba(99,102,241,.2);}

.sede-empty-icon{font-size:48px;color:var(--border);}
.sede-composer{
  display:flex;align-items:flex-end;gap:8px;
  padding:12px 20px;border-top:1px solid var(--border);
  background:var(--panel, #fff);flex:0 0 auto;
  max-width:840px;width:100%;margin:0 auto;
}
.sede-input{
  flex:1;min-width:0;padding:10px 14px;
  border:1px solid var(--input-border, rgba(0,0,0,.12));border-radius:var(--radius, 12px);
  font-size:14px;background:var(--input-bg, #fff);color:var(--text);
  resize:none;font-family:inherit;max-height:160px;
}
.sede-input::placeholder{color:var(--muted);}
.sede-send-btn{
  width:40px;height:40px;display:inline-grid;place-items:center;
  border:0;border-radius:50%;background:var(--accent, #6366f1);color:#fff;
  cursor:pointer;flex:0 0 auto;
}
.sede-send-btn:hover{opacity:.85;}
.sede-send-btn .ms{font-size:20px;}
@media(max-width:768px){
  .sede-sidebar{display:none;}
}

/* ═══════════════════════════════════════════════════════════════
   SEDE INLINE CHAT — Welcome / Messages / 2-Pane / Composer
   Theme: follows existing CSS custom properties (--bg, --panel, etc.)
   ═══════════════════════════════════════════════════════════════ */

/* Container: permanent 3-pane when data-chat-mode="sede" */
#appAiChatShell[data-chat-mode="sede"] .sede-chat-wrap{
  display:flex !important;flex-direction:row !important;flex:1 !important;min-height:0 !important;
  font-family:'Fira Code','SF Mono','Cascadia Code',Consolas,'Courier New',monospace !important;
}
#appAiChatShell:not([data-chat-mode="sede"]) .sede-chat-wrap{display:none !important;}

/* ── File Tree Pane (left, collapsible) ── */
.sede-file-tree-pane{
  display:none !important;
}
.sede-file-tree-pane.is-collapsed{width:0;flex-basis:0;overflow:hidden;border-right:none;}
.sede-file-tree-header{
  display:flex;align-items:center;justify-content:space-between;padding:8px 12px;
  font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;
  color:var(--muted,rgba(255,255,255,.4));border-bottom:1px solid var(--border,rgba(255,255,255,.08));
  flex-shrink:0;
}
.sede-file-tree-actions{display:flex;gap:2px;}
.sede-file-tree-actions button{
  background:none;border:none;color:var(--muted,rgba(0,0,0,.35));cursor:pointer;
  width:26px;height:26px;display:flex;align-items:center;justify-content:center;border-radius:6px;
  transition:color .15s,background .15s;
}
.sede-file-tree-actions button:hover{background:var(--chip-bg,rgba(0,0,0,.05));color:var(--text,#333);}
.sede-file-tree-actions button .ms{font-size:16px;}
.sede-file-tree-body{flex:1;overflow-y:auto;padding:4px 0;}
.sede-file-tree-empty{padding:16px 12px;font-size:12px;color:var(--muted,rgba(255,255,255,.3));}
.sede-tree-file{
  padding:4px 12px;font-size:12px;cursor:pointer;display:flex;align-items:center;gap:6px;
  color:var(--text,#d0d0d0);border-radius:4px;margin:1px 4px;white-space:nowrap;overflow:hidden;
}
.sede-tree-file:hover{background:rgba(255,255,255,.06);}
.sede-tree-file.is-active{background:rgba(255,255,255,.1);font-weight:600;}
.sede-tree-file .ms{font-size:14px;flex-shrink:0;color:var(--muted,rgba(255,255,255,.4));}
.sede-tree-folder{
  padding:4px 12px;font-size:12px;cursor:pointer;display:flex;align-items:center;gap:6px;
  color:var(--muted,rgba(255,255,255,.5));font-weight:600;
}
.sede-tree-folder:hover{background:rgba(255,255,255,.04);}
.sede-tree-folder .ms{font-size:14px;flex-shrink:0;}
.sede-tree-folder-children.is-collapsed{display:none;}
.sede-file-tree-footer{
  padding:8px 12px;font-size:11px;color:var(--muted,rgba(255,255,255,.3));
  border-top:1px solid var(--border,rgba(255,255,255,.08));flex-shrink:0;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}

/* ── Resize Handles ── */
.sede-resize-handle{
  width:6px;flex:0 0 6px;cursor:col-resize;background:transparent;position:relative;z-index:2;
  transition:background .15s;
}
.sede-resize-handle:hover,.sede-resize-handle.is-dragging{background:var(--accent,#6366f1);}

/* ── Center Pane: Editor + Terminal ── */
.sede-center-pane{
  flex:0 0 60%;display:flex;flex-direction:column;min-width:300px;min-height:0;overflow:hidden;
  order:2;
}

/* ── Right Pane (now LEFT): Chat / Preview / Logs (tabbed) ── */
.sede-right-pane{
  flex:0 0 40%;display:flex;flex-direction:column;min-width:280px;min-height:0;overflow:hidden;
  border-left:none;border-right:1px solid var(--border,rgba(255,255,255,.08));
  order:1;
}
.sede-right-tab-bar{
  display:flex;align-items:center;gap:0;
  border-bottom:1px solid var(--border,rgba(255,255,255,.08));
  background:var(--panel,#1b1b1f);flex-shrink:0;
}
.sede-right-tab{
  padding:8px 14px;font-size:12px;font-weight:500;
  border:none;background:transparent;cursor:pointer;
  color:var(--muted,rgba(0,0,0,.35));border-bottom:2px solid transparent;
  display:inline-flex;align-items:center;justify-content:center;gap:0;
  transition:color .15s,background .15s;border-radius:0;
}
.sede-right-tab:hover{color:var(--text,#333);background:var(--chip-bg,rgba(0,0,0,.03));}
.sede-right-tab.is-active{color:var(--text,#333);border-bottom-color:var(--accent,#6366f1);}
.sede-right-tab-content{display:none;flex:1;flex-direction:column;min-height:0;overflow:hidden;}
.sede-right-tab-content.is-active{display:flex;}

/* ── Live Preview ── */
.sede-live-preview{flex:1;display:flex;flex-direction:column;min-height:0;background:#fff;}
.sede-live-preview-empty{
  flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;
  background:var(--panel,#1b1b1f);
}
.sede-live-preview iframe{width:100%;flex:1;border:none;min-height:0;}

/* ── Log Panel — Claude Code風 (Light) ── */
.sede-log-panel{flex:1;display:flex;flex-direction:column;min-height:0;background:#fafafa;overflow:hidden;}
.sede-log-panel-body{
  flex:1;overflow-y:auto;padding:12px 16px;font-size:13px;line-height:1.5;
  font-family:'Fira Code','SF Mono',Consolas,monospace;color:#1e293b;
}
/* ── Tool-call style log items ── */
.sede-log-panel-body .sede-oplog-item{
  position:relative;display:flex;align-items:flex-start;gap:8px;padding:3px 0;
  animation:sedeLogSlideIn .2s ease both;
}
.sede-log-chat-item{animation:sedeLogSlideIn .25s ease both;}
/* Agent spinner in chat */
.sede-agent-spinner-wrap{
  display:flex;align-items:center;gap:10px;padding:12px 0;
}
.sede-agent-spinner-wrap .sede-spinner-icon{
  width:16px;height:16px;border:2px solid rgba(0,0,0,.1);border-top-color:#6366f1;
  border-radius:50%;animation:sedeSpin .6s linear infinite;flex-shrink:0;
}
.sede-agent-spinner-wrap .sede-agent-spinner-text{color:#64748b !important;}
@keyframes sedeLogSlideIn{
  from{opacity:0;transform:translateY(4px);}
  to{opacity:1;transform:translateY(0);}
}
.sede-log-panel-body .sede-oplog-item:not(:last-child)::before{
  content:'';position:absolute;left:3px;top:16px;bottom:-3px;width:1px;
  background:rgba(0,0,0,.08);
}
.sede-log-panel-body .sede-oplog-item .sede-oplog-dot{
  width:7px;height:7px;border-radius:50%;margin-top:5px;flex-shrink:0;
  background:rgba(0,0,0,.15);position:relative;z-index:1;
}
.sede-log-panel-body .sede-oplog-item .sede-oplog-dot.is-active{
  background:#22c55e;animation:sedeDotPulse 1s ease infinite;
}
.sede-log-panel-body .sede-oplog-item .sede-oplog-dot.is-done{
  background:rgba(0,0,0,.12);
}
.sede-log-panel-body .sede-oplog-text{color:#334155;font-size:12.5px;}
.sede-log-panel-body .sede-oplog-text code{
  background:#1e1e2e !important;color:#e2e8f0 !important;padding:2px 6px;border-radius:4px;
  font-size:12px;font-family:inherit;
}
/* ── Tool call badges ── */
.sede-log-panel-body .sede-oplog-text .ms{
  color:#6366f1;
}
/* Chat messages in log panel */
.sede-log-chat-item{
  position:relative;display:flex;align-items:flex-start;gap:8px;padding:4px 0 6px;
}
.sede-log-chat-item:not(:last-child)::before{
  content:'';position:absolute;left:3px;top:16px;bottom:-4px;width:1px;
  background:rgba(0,0,0,.08);
}
.sede-log-chat-item .sede-log-chat-dot{
  width:7px;height:7px;border-radius:50%;margin-top:5px;flex-shrink:0;
  background:#6366f1;position:relative;z-index:1;
}
.sede-log-chat-item .sede-log-chat-body{
  flex:1;min-width:0;font-size:13px;line-height:1.6;color:#1e293b;
  font-family:-apple-system,BlinkMacSystemFont,system-ui,sans-serif;
}
.sede-log-chat-item .sede-log-chat-body strong{color:#0f172a;font-weight:600;}
.sede-log-chat-item .sede-log-chat-body em{font-style:italic;color:#64748b;}
.sede-log-chat-item .sede-log-chat-body code{
  background:#1e1e2e !important;color:#e2e8f0 !important;padding:2px 6px;border-radius:4px;
  font-size:12px;font-family:'Fira Code',Consolas,monospace;
}
.sede-log-chat-item .sede-log-chat-body pre{
  background:#1e1e2e !important;border-radius:6px;padding:8px 10px;margin:6px 0;
  overflow-x:auto;font-size:12px;line-height:1.5;border:1px solid rgba(0,0,0,.08);
}
.sede-log-chat-item .sede-log-chat-body pre code{background:none;padding:0;border-radius:0;color:#333;}
.sede-log-chat-item .sede-log-chat-body ul,.sede-log-chat-item .sede-log-chat-body ol{
  margin:4px 0;padding-left:18px;color:#1a1a1a;
}
.sede-log-chat-item .sede-log-chat-body li{margin:2px 0;}
.sede-log-chat-item .sede-log-chat-body p{margin:0 0 4px;color:#1a1a1a;}
.sede-log-chat-item .sede-log-chat-body a{color:var(--accent,#6366f1);text-decoration:underline;}
/* Collapsible log sections */
.sede-log-section{margin:4px 0;}
.sede-log-section summary{
  display:flex;align-items:center;gap:8px;cursor:pointer;padding:4px 0;
  font-size:12px;color:rgba(255,255,255,.4);list-style:none;
}
.sede-log-section summary::-webkit-details-marker{display:none;}
.sede-log-section summary .ms{font-size:14px;transition:transform .2s;}
.sede-log-section[open] summary .ms{transform:rotate(90deg);}
.sede-log-section .sede-log-section-body{padding:4px 0 4px 18px;border-left:1px solid rgba(255,255,255,.06);margin-left:3px;}

/* ── Mobile: stack panes ── */
@media(max-width:768px){
  .sede-file-tree-pane{display:none !important;}
  .sede-resize-handle{display:none !important;}
  #appAiChatShell[data-chat-mode="sede"] .sede-chat-wrap{flex-direction:column !important;}
  .sede-center-pane{flex:1 !important;min-height:40% !important;}
  .sede-right-pane{flex:0 0 50% !important;min-width:0 !important;border-left:none !important;border-top:1px solid var(--border,rgba(255,255,255,.08)) !important;}
}

/* ── Operation Log (Claude Code style) ── */
.sede-oplog{padding:0;margin:0;list-style:none;display:flex;flex-direction:column;gap:2px;}
.sede-oplog-item{
  display:flex;align-items:flex-start;gap:10px;padding:6px 0;
  font-size:14px;line-height:1.6;color:var(--text);
  font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text",system-ui,"Hiragino Sans","Hiragino Kaku Gothic ProN","Noto Sans JP",sans-serif;
  animation:sedeLogFadeIn .3s ease;
}
@keyframes sedeLogFadeIn{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:translateY(0);}}

/* 会話メッセージもフェードイン */
.sede-log-chat{animation:sedeLogFadeIn .3s ease;}
.sede-oplog-dot{
  width:8px;height:8px;border-radius:50%;margin-top:7px;flex-shrink:0;
  background:#94a3b8;transition:background .2s;
  position:relative;z-index:1;
}
.sede-oplog-dot.is-active{background:#22c55e;animation:sedeDotPulse 1s ease infinite;}
.sede-oplog-dot.is-done{background:var(--border, #e2e8f0);}
@keyframes sedeDotPulse{0%,100%{opacity:1;}50%{opacity:.4;}}

/* ドット間の縦線 */
.sede-oplog-item{position:relative;}
.sede-oplog-item:not(:last-child)::before{
  content:'';position:absolute;left:3.5px;top:18px;bottom:-8px;
  width:1px;background:var(--border, rgba(0,0,0,.1));
}

/* スピナー（生成中） */
.sede-spinner{
  display:inline-flex;align-items:center;gap:8px;padding:8px 0;
  font-size:14px;color:var(--muted);font-family:Inter,system-ui,sans-serif;
}
.sede-spinner-icon{
  width:16px;height:16px;border:2px solid var(--border);border-top-color:var(--text);
  border-radius:50%;animation:sedeSpin .6s linear infinite;flex-shrink:0;
}
.sede-spinner-text{transition:opacity .3s ease;}
@keyframes sedeSpin{to{transform:rotate(360deg);}}
.sede-oplog-text{flex:1;min-width:0;word-break:break-word;}
.sede-oplog-text code{background:#1e1e2e !important;color:#e2e8f0 !important;padding:2px 6px;border-radius:4px;font-size:13px;font-family:'Fira Code',Consolas,monospace;}
.sede-oplog-text .cmd{font-weight:700;}
.sede-oplog-text .arg{font-weight:400;opacity:.6;}
.sede-oplog-text .add{color:#22c55e;font-weight:600;}
.sede-oplog-text .del{color:#ef4444;font-weight:600;}

/* ── AI Chat Message in Log ── */
.sede-log-chat{
  padding:4px 0 8px 18px;
  font-size:14px;line-height:1.7;color:var(--text);
  font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text",system-ui,"Hiragino Sans","Hiragino Kaku Gothic ProN","Noto Sans JP",sans-serif;
}
.sede-log-chat code{background:var(--chip-bg, rgba(0,0,0,.06));padding:2px 6px;border-radius:4px;font-size:13px;font-family:'Fira Code',Consolas,monospace;}
.sede-log-chat p{margin:0 0 4px 0;}

/* ── Log Result Line (Grep results etc) ── */
.sede-log-result{
  padding:2px 0 2px 18px;
  font-size:13px;line-height:1.5;color:var(--muted);
  font-family:'Fira Code',Consolas,monospace;
}

/* ── AI Message in Fix Log ── */
.sede-oplog-item .sede-fix-msg{
  color:var(--text);font-family:Inter,'Hiragino Sans',sans-serif;font-style:normal;
  font-size:12.5px;line-height:1.5;padding:2px 0;
}

/* ── Fix Log Collapsible Group ── */
.sede-fix-log-group{margin:8px 0;border-radius:10px;border:1px solid var(--border);overflow:hidden;}
.sede-fix-log-group summary{
  display:flex;align-items:center;gap:8px;padding:10px 14px;
  font-size:14px;font-weight:600;font-family:Inter,system-ui,sans-serif;
  color:var(--text);cursor:pointer;list-style:none;background:var(--panel);
  user-select:none;
}
.sede-fix-log-group summary::-webkit-details-marker{display:none;}
.sede-fix-log-group summary::before{content:'▶';font-size:10px;color:var(--muted);transition:transform .15s;flex-shrink:0;}
.sede-fix-log-group[open] summary::before{transform:rotate(90deg);}
.sede-fix-log-group summary code{background:var(--chip-bg);padding:2px 6px;border-radius:4px;font-size:13px;}
.sede-fix-log-group .sede-fix-log-body{padding:12px 14px;border-top:1px solid var(--border);background:var(--bg);}

/* ── Inline Diff in Chat (Claude Code style) ── */
.sede-diff-inline{
  margin:8px 0;border-radius:10px;overflow:hidden;
  border:1px solid rgba(255,255,255,.1);background:#0d1117;
  font-family:'Fira Code','SF Mono',Consolas,monospace;font-size:12px;line-height:1.55;
}
.sede-diff-inline-header{
  display:flex;align-items:center;gap:8px;padding:8px 12px;
  background:rgba(255,255,255,.03);border-bottom:1px solid rgba(255,255,255,.08);
  color:rgba(255,255,255,.5);font-size:11px;font-weight:600;
}
.sede-diff-inline-header .sede-diff-fname{color:#a5b4fc;font-weight:700;}
.sede-diff-inline-body{padding:2px 0;max-height:400px;overflow-y:auto;}
.sede-diff-inline-line{
  display:flex;align-items:stretch;min-height:20px;padding:0 10px;
  transition:background .1s;
}
.sede-diff-inline-line:hover{background:rgba(255,255,255,.03);}
.sede-diff-inline-num{
  width:40px;flex-shrink:0;text-align:right;padding-right:10px;
  color:rgba(255,255,255,.18);user-select:none;font-size:11px;line-height:1.55;
}
.sede-diff-inline-marker{
  width:16px;flex-shrink:0;text-align:center;font-weight:700;user-select:none;
}
.sede-diff-inline-code{flex:1;min-width:0;white-space:pre;overflow-x:auto;color:rgba(255,255,255,.65);tab-size:2;}
.sede-diff-inline-line.is-add{background:rgba(46,160,67,.15);}
.sede-diff-inline-line.is-add .sede-diff-inline-marker{color:#3fb950;}
.sede-diff-inline-line.is-add .sede-diff-inline-code{color:#aff5b4;}
.sede-diff-inline-line.is-add .sede-diff-inline-num{color:rgba(63,185,80,.4);}
.sede-diff-inline-line.is-del{background:rgba(248,81,73,.15);}
.sede-diff-inline-line.is-del .sede-diff-inline-marker{color:#f85149;}
.sede-diff-inline-line.is-del .sede-diff-inline-code{color:#ffa198;text-decoration:line-through;opacity:.7;}
.sede-diff-inline-line.is-del .sede-diff-inline-num{color:rgba(248,81,73,.3);}
.sede-diff-inline-line.is-hunk{background:rgba(56,139,253,.08);border-top:1px solid rgba(56,139,253,.1);}
.sede-diff-inline-line.is-hunk .sede-diff-inline-code{color:rgba(121,192,255,.7);font-weight:600;font-style:italic;}

/* ── Diff Approval Card ── */
.sede-diff-card{
  margin:8px 0;padding:12px 14px;border-radius:10px;
  background:var(--panel);border:1px solid var(--border);
  font-family:Inter,system-ui,sans-serif;font-size:14px;
}
.sede-diff-card-head{font-weight:600;color:var(--text);margin-bottom:6px;display:flex;align-items:center;gap:8px;font-size:14px;}
.sede-diff-card-stats{color:var(--muted);font-size:11px;margin-bottom:8px;}
.sede-diff-card-stats .is-add{color:#22c55e;}
.sede-diff-card-stats .is-del{color:#ef4444;}
.sede-diff-card-btns{display:flex;gap:6px;}
.sede-diff-card-btn{
  padding:5px 14px;border-radius:6px;border:1px solid var(--border);
  font-size:11px;font-weight:600;cursor:pointer;background:var(--panel);color:var(--text);
  font-family:inherit;transition:background .12s;
}
.sede-diff-card-btn:hover{background:var(--chip-bg);}
.sede-diff-card-btn.is-apply{background:#22c55e;color:#fff;border-color:#22c55e;}
.sede-diff-card-btn.is-apply:hover{background:#16a34a;}
.sede-diff-card-btn.is-reject{color:#ef4444;border-color:rgba(239,68,68,.3);}
.sede-diff-card.is-resolved{padding:8px 14px;}
.sede-diff-card.is-resolved .sede-diff-card-head{margin-bottom:0;}

/* ── Approve Bar (sticky above input) ── */
.sede-approve-bar{
  position:sticky;bottom:0;z-index:10;
  background:var(--panel);border-top:1px solid var(--border);
  padding:10px 14px;display:flex;align-items:center;gap:12px;
  font-size:14px;font-family:Inter,system-ui,sans-serif;
  box-shadow:0 -2px 8px rgba(0,0,0,.06);
}
.sede-approve-bar .sede-approve-file{font-weight:600;flex:1;display:flex;align-items:center;gap:6px;}
.sede-approve-bar .add{color:#22c55e;font-weight:600;}
.sede-approve-bar .del{color:#ef4444;font-weight:600;}

/* ── Right Pane ── */
.sede-editor-area{flex:1;display:flex;flex-direction:column;min-height:0;overflow:hidden;}
.sede-editor-empty{
  flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;
  color:var(--muted);font-size:13px;text-align:center;gap:8px;
}
.sede-editor-empty .ms{font-size:48px;display:block;opacity:.3;}
.sede-file-tabs{
  display:flex;align-items:center;gap:0;padding:0 8px;
  border-bottom:1px solid var(--border);background:var(--panel);flex-shrink:0;overflow-x:auto;
}
.sede-file-tab{
  padding:8px 14px;font-size:12px;font-weight:500;cursor:pointer;
  color:var(--muted);border-bottom:2px solid transparent;white-space:nowrap;
  font-family:'Fira Code',Consolas,monospace;transition:color .12s;
}
.sede-file-tab:hover{color:var(--text);}
.sede-file-tab.is-active{color:var(--text);border-bottom-color:var(--accent);font-weight:600;}
.sede-editor-toolbar{
  display:flex;align-items:center;gap:4px;padding:4px 10px;
  border-bottom:1px solid var(--border);background:var(--panel);flex-shrink:0;
}
.sede-editor-toolbar .sede-code-lang-badge{
  font-size:10px;font-weight:700;padding:2px 8px;border-radius:4px;
  background:var(--chip-bg);color:var(--muted);text-transform:uppercase;letter-spacing:.04em;margin-right:auto;
}
.sede-editor-toolbar-btn{
  width:30px;height:30px;display:inline-grid;place-items:center;
  border:none;border-radius:6px;background:transparent;cursor:pointer;
  color:var(--muted,rgba(0,0,0,.35));transition:color .15s,background .15s;
}
.sede-editor-toolbar-btn:hover{color:var(--text,#333);background:var(--chip-bg,rgba(0,0,0,.05));}
.sede-editor-toolbar-btn:active{background:var(--chip-bg,rgba(0,0,0,.08));}
.sede-editor-toolbar-btn.is-active{color:#22c55e;}
.sede-editor-toolbar-btn .ms{font-size:17px;}
/* Override composer toolbar buttons inside Sede */
#appAiChatShell[data-chat-mode="sede"] .app-chat-toolbar-btn{
  width:30px !important;height:30px !important;border-radius:6px !important;
  color:var(--muted,rgba(0,0,0,.3)) !important;background:transparent !important;
}
#appAiChatShell[data-chat-mode="sede"] .app-chat-toolbar-btn:hover{
  color:var(--text,#333) !important;background:rgba(0,0,0,.05) !important;
}
#appAiChatShell[data-chat-mode="sede"] .app-chat-toolbar-btn .ms{font-size:18px !important;}
#appAiChatShell[data-chat-mode="sede"] .app-chat-send{
  width:30px !important;height:30px !important;border-radius:6px !important;
}
/* Sede right tab bar inside Sede */
#appAiChatShell[data-chat-mode="sede"] .sede-right-tab-bar{
  background:var(--panel,#f8f8f8) !important;border-bottom:1px solid var(--border,rgba(0,0,0,.08)) !important;
}
.sede-code-view{flex:1;overflow:auto;min-height:0;position:relative;background:var(--panel);}
.sede-code-view pre{margin:0;padding:12px 12px 12px 52px;min-height:100%;font-size:13px;line-height:1.65;}
.sede-code-view code{display:block;font-family:'Fira Code',Consolas,monospace;tab-size:2;}
.sede-code-view .sede-line-numbers{
  position:absolute;left:0;top:0;padding:12px 0;font-size:13px;line-height:1.65;
  font-family:'Fira Code',Consolas,monospace;
  color:var(--muted, rgba(0,0,0,.25));text-align:right;width:44px;
  user-select:none;pointer-events:none;border-right:1px solid var(--border);
}
.sede-code-view .sede-line-numbers div{padding:0 6px;line-height:1.65;}
.sede-scroll-bottom-btn{position:sticky;bottom:12px;left:50%;transform:translateX(-50%);z-index:10;width:36px;height:36px;border-radius:50%;background:var(--accent,#6366f1);color:#fff;border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 8px rgba(0,0,0,.2);opacity:.9;transition:opacity .15s;}
.sede-scroll-bottom-btn:hover{opacity:1;}
.sede-scroll-bottom-btn .ms{font-size:20px;}
.sede-diff-line-add{background:rgba(34,197,94,.1);}
.sede-diff-line-del{background:rgba(239,68,68,.1);text-decoration:line-through;opacity:.7;}
.sede-diff-marker{display:inline-block;width:16px;text-align:center;font-weight:700;user-select:none;}
.sede-diff-marker.is-add{color:#22c55e;}
.sede-diff-marker.is-del{color:#ef4444;}

/* ── Terminal ── */
.sede-terminal{
  flex-shrink:0;height:30%;min-height:80px;max-height:50%;
  display:flex;flex-direction:column;
  border-top:2px solid var(--border);background:#0d1117;color:#e6edf3;overflow:hidden;
}
.sede-terminal-head{
  display:flex;align-items:center;gap:6px;padding:6px 10px;
  font-size:11px;font-weight:600;color:rgba(255,255,255,.5);
  border-bottom:1px solid rgba(255,255,255,.08);flex-shrink:0;cursor:ns-resize;
}
.sede-terminal-head .ms{font-size:14px;}
.sede-terminal-body{
  flex:1;overflow-y:auto;padding:8px 12px;font-size:12px;line-height:1.6;
  font-family:'Fira Code',Consolas,monospace;white-space:pre-wrap;word-break:break-all;
}
.sede-terminal-body .is-err{color:#f87171;}
.sede-terminal-body .is-ok{color:#4ade80;}
.sede-terminal-body .is-cmd{color:#60a5fa;font-weight:600;}

/* ── Terminal Input ── */
.sede-terminal-input-wrap{
  display:flex;align-items:center;gap:6px;padding:4px 12px;
  background:#0d1117;
}
.sede-terminal-prompt{color:#4ade80;font-family:'Fira Code',Consolas,monospace;font-size:12px;font-weight:700;flex-shrink:0;}
.sede-terminal-input{
  flex:1;background:none;border:none;outline:none;padding:0;margin:0;
  color:#e6edf3;font-family:'Fira Code',Consolas,monospace;font-size:12px;line-height:1.6;
  caret-color:#4ade80;
}
.sede-terminal-input::placeholder{color:rgba(255,255,255,.2);}

/* ── Code Editor Edit Mode ── */
.sede-code-edit-area{
  width:100%;height:100%;min-height:300px;resize:none;border:none;outline:none;
  background:#0d1117;color:#e6edf3;padding:12px 12px 12px 52px;
  font-family:'Fira Code',Consolas,monospace;font-size:13px;line-height:1.65;
  tab-size:2;white-space:pre;overflow:auto;
}
.sede-code-edit-bar{
  display:flex;align-items:center;gap:6px;padding:6px 12px;
  background:rgba(34,197,94,.08);border-bottom:1px solid rgba(34,197,94,.2);
  font-size:11px;font-family:'Fira Code',Consolas,monospace;color:#22c55e;
}
.sede-code-edit-bar button{
  padding:3px 10px;border-radius:4px;border:1px solid rgba(34,197,94,.3);
  font-size:11px;font-weight:600;cursor:pointer;font-family:inherit;
  background:transparent;color:#22c55e;transition:background .12s;
}
.sede-code-edit-bar button:hover{background:rgba(34,197,94,.15);}
.sede-code-edit-bar .is-save{background:#22c55e;color:#fff;border-color:#22c55e;}
.sede-code-edit-bar .is-save:hover{background:#16a34a;}

/* ── Preview ── */
.sede-preview{
  position:absolute;inset:0;z-index:5;background:var(--bg);display:flex;flex-direction:column;
}
.sede-preview-bar{
  display:flex;align-items:center;gap:8px;padding:6px 12px;
  border-bottom:1px solid var(--border);background:var(--panel);flex-shrink:0;
}
.sede-preview-bar-btn{
  padding:4px 10px;border-radius:6px;border:1px solid var(--border);
  font-size:11px;font-weight:600;cursor:pointer;background:var(--panel);color:var(--text);
  font-family:'Fira Code',Consolas,monospace;
}
.sede-preview-bar-btn.is-active{background:var(--accent);color:#fff;border-color:var(--accent);}
.sede-preview-bar-close{margin-left:auto;}
.sede-preview-frame-wrap{flex:1;display:flex;align-items:center;justify-content:center;overflow:hidden;padding:8px;}
.sede-preview-frame{border:none;background:#fff;box-shadow:0 4px 24px rgba(0,0,0,.1);width:100%;height:100%;}
.sede-preview-frame.is-mobile{width:375px;height:812px;border-radius:40px;border:8px solid #1d1d1f;}

/* ── Welcome Screen ── */
.sede-welcome{
  flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;
  gap:20px;padding:40px 24px 16px;text-align:center;min-height:0;
}
.sede-welcome-icon{
  width:72px;height:72px;border-radius:50%;
  background:var(--chip-bg, rgba(0,0,0,.05));
  display:inline-grid;place-items:center;
}
.sede-welcome-icon .ms{font-size:36px;color:var(--accent, #6366f1);}
.sede-welcome-greeting{
  font-size:22px;font-weight:700;color:var(--text, #1d1d1f);
  font-family:'Fira Code','SF Mono',Consolas,monospace;
  max-width:500px;line-height:1.5;
}
.sede-welcome-sub{
  font-size:13px;color:var(--muted, rgba(29,29,31,.56));max-width:400px;line-height:1.6;
}
.sede-welcome-chips{
  display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin-top:8px;
}
.sede-welcome-chip{
  padding:8px 16px;border-radius:10px;font-size:13px;font-weight:500;cursor:pointer;
  background:var(--panel, #fff);color:var(--text, #1d1d1f);
  border:1px solid var(--border, rgba(0,0,0,.08));
  font-family:'Fira Code',Consolas,monospace;
  transition:background .15s,border-color .15s;
}
.sede-welcome-chip:hover{background:var(--chip-bg, rgba(0,0,0,.04));border-color:var(--accent, #6366f1);}

/* ── Template Grid ── */
.sede-template-grid{
  display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:16px;
  max-height:420px;overflow-y:auto;padding:4px 2px;width:100%;max-width:560px;
}
@media(max-width:600px){.sede-template-grid{grid-template-columns:repeat(2,1fr);}}
.sede-template-card{
  display:flex;flex-direction:column;align-items:center;gap:6px;padding:14px 8px;
  border-radius:12px;cursor:pointer;border:1px solid var(--border,rgba(255,255,255,.08));
  background:var(--panel,rgba(255,255,255,.03));transition:background .15s,border-color .15s,transform .15s;
  text-align:center;min-height:0;
}
.sede-template-card:hover{
  background:rgba(255,255,255,.06);border-color:var(--accent,#6366f1);transform:translateY(-2px);
}
.sede-template-card-icon{
  width:40px;height:40px;border-radius:10px;display:flex;align-items:center;justify-content:center;
  font-size:20px;flex-shrink:0;
}
.sede-template-card-title{font-size:12px;font-weight:600;color:var(--text,#e0e0e0);line-height:1.3;}
.sede-template-card-desc{font-size:10px;color:var(--muted,rgba(255,255,255,.4));line-height:1.3;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;}

/* ── Chat Messages Area ── */
.sede-chat-scroll-inline{
  flex:1;overflow-y:auto;min-height:0;padding:16px 20px;
  scroll-behavior:auto;
}
.sede-chat-list{
  max-width:820px;margin:0 auto;display:flex;flex-direction:column;gap:4px;
}

/* Messages */
.sede-chat-msg{
  display:flex;flex-direction:column;gap:2px;padding:2px 0;
  animation:sedeMsgIn .2s ease;
}
@keyframes sedeMsgIn{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:none;}}

.sede-chat-msg.is-user{align-items:flex-end;}
.sede-chat-msg.is-user .sede-chat-bubble{
  background:var(--accent, #6366f1);color:#fff;
  border-radius:16px 16px 4px 16px;
  max-width:75%;padding:10px 16px;
  font-size:14px;line-height:1.7;word-break:break-word;
}

.sede-chat-msg.is-ai{align-items:flex-start;}
.sede-chat-msg.is-ai .sede-chat-bubble{
  max-width:100%;padding:12px 0 12px 16px;
  font-size:14px;line-height:1.7;word-break:break-word;
  color:var(--text, #1d1d1f);
  border-left:3px solid var(--accent, #6366f1);
}

/* AI markdown */
.sede-chat-msg.is-ai .sede-chat-bubble p{margin:0 0 8px;}
.sede-chat-msg.is-ai .sede-chat-bubble p:last-child{margin-bottom:0;}
.sede-chat-msg.is-ai .sede-chat-bubble ul,.sede-chat-msg.is-ai .sede-chat-bubble ol{margin:4px 0 8px 18px;padding:0;}
.sede-chat-msg.is-ai .sede-chat-bubble li{margin:2px 0;}
.sede-chat-msg.is-ai .sede-chat-bubble code:not([class*="hljs"]){
  background:#1e1e2e !important;color:#e2e8f0 !important;padding:2px 6px;border-radius:4px;font-size:13px;
  font-family:'Fira Code',Consolas,monospace;
}
.sede-chat-msg.is-ai .sede-chat-bubble pre{
  background:#1a1a2e !important;border:1px solid rgba(255,255,255,.1) !important;
  border-radius:10px;padding:0;margin:10px 0;overflow:hidden;position:relative;
}
.sede-chat-msg.is-ai .sede-chat-bubble pre code{
  display:block;padding:14px 16px;overflow-x:auto;font-size:13px;line-height:1.65;
  font-family:'Fira Code','SF Mono',Consolas,monospace;color:#e2e8f0 !important;background:transparent !important;
}
.sede-code-header{
  display:flex;align-items:center;gap:8px;padding:6px 12px;
  background:rgba(255,255,255,.05);border-bottom:1px solid rgba(255,255,255,.08);
  font-size:11px;font-weight:600;color:var(--muted);
  font-family:'Fira Code',Consolas,monospace;
}
.sede-code-header .sede-code-lang{
  flex:1;text-transform:uppercase;letter-spacing:.04em;
}
.sede-code-header button{
  background:none;border:none;cursor:pointer;color:var(--muted);padding:2px 6px;
  border-radius:4px;font-size:12px;display:inline-flex;align-items:center;gap:3px;
  font-family:inherit;transition:color .12s,background .12s;
}
.sede-code-header button:hover{
  color:var(--text);background:var(--chip-bg, rgba(0,0,0,.06));
}

/* Role label */
.sede-chat-role{
  font-size:11px;font-weight:600;color:var(--muted, rgba(29,29,31,.56));
  padding:0 2px;text-transform:uppercase;letter-spacing:.04em;
  font-family:'Fira Code',Consolas,monospace;
}

/* Typing indicator */
.sede-chat-msg.is-typing .sede-chat-bubble{color:var(--muted);}
.sede-typing-dots{display:inline-flex;gap:3px;align-items:center;padding:4px 0;}
.sede-typing-dots span{
  width:6px;height:6px;border-radius:50%;background:var(--muted);
  animation:sedeTyping .8s ease infinite;
}
.sede-typing-dots span:nth-child(2){animation-delay:.15s;}
.sede-typing-dots span:nth-child(3){animation-delay:.3s;}
@keyframes sedeTyping{0%,80%,100%{opacity:.3;transform:scale(.8);}40%{opacity:1;transform:scale(1);}}

/* ── Auto-Continue Progress Bar ── */
.sede-progress-bar{
  display:flex;flex-direction:column;gap:6px;padding:10px 14px;margin-bottom:8px;
  border-radius:10px;background:rgba(99,102,241,.06);border:1px solid rgba(99,102,241,.12);
  font-family:'Fira Code',Consolas,monospace;font-size:12px;
  transition:opacity .5s ease;
}
body[data-chat-dark="1"] .sede-progress-bar{background:rgba(99,102,241,.1);border-color:rgba(99,102,241,.2);}
.sede-progress-track{height:4px;border-radius:2px;background:rgba(0,0,0,.06);overflow:hidden;}
body[data-chat-dark="1"] .sede-progress-track{background:rgba(255,255,255,.08);}
.sede-progress-fill{height:100%;border-radius:2px;background:linear-gradient(90deg,#6366f1,#8b5cf6);width:8%;transition:width .4s ease;}
.sede-progress-info{display:flex;align-items:center;gap:10px;color:rgba(99,102,241,.8);}
body[data-chat-dark="1"] .sede-progress-info{color:rgba(165,180,252,.8);}
.sede-progress-counter{font-weight:600;min-width:50px;}
.sede-progress-msg{transition:opacity .3s ease;flex:1;}
.sede-progress-done{color:#10b981;font-weight:600;}
.sede-progress-error{color:#ef4444;font-weight:500;}
.sede-progress-bar.is-complete .sede-progress-fill{background:linear-gradient(90deg,#10b981,#34d399);}
.sede-progress-bar.is-fade{opacity:0;pointer-events:none;}
@keyframes sedeParticle{0%{opacity:1;transform:translateY(0) scale(1);}100%{opacity:0;transform:translateY(-20px) scale(0);}}
.sede-progress-bar.is-complete::after{
  content:"";display:block;height:0;
  background:radial-gradient(circle,#10b981 1px,transparent 1px);
  background-size:8px 8px;
  animation:sedeParticle .8s ease forwards;
}

/* ── 2-Pane Code Editor ── */
.sede-twopane{display:flex;flex:1;min-height:0;overflow:hidden;}
.sede-twopane .sede-pane-chat{
  flex:0 0 40%;display:flex;flex-direction:column;min-width:0;
  border-right:1px solid var(--border, rgba(0,0,0,.08));
}
.sede-twopane .sede-pane-code{
  flex:0 0 60%;display:flex;flex-direction:column;min-width:0;
  animation:sedeCodeSlide .3s cubic-bezier(.22,1,.36,1);
}
@keyframes sedeCodeSlide{from{transform:translateX(30%);opacity:0;}to{transform:none;opacity:1;}}

/* Code Pane Toolbar */
.sede-code-toolbar{
  display:flex;align-items:center;gap:8px;padding:8px 14px;
  border-bottom:1px solid var(--border);background:var(--panel, #fff);flex-shrink:0;
  font-family:'Fira Code',Consolas,monospace;
}
.sede-code-filename{
  font-size:13px;font-weight:600;color:var(--text);flex:1;min-width:0;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.sede-code-lang-badge{
  font-size:10px;font-weight:700;padding:2px 8px;border-radius:4px;
  background:var(--chip-bg, rgba(0,0,0,.05));color:var(--muted);
  text-transform:uppercase;letter-spacing:.04em;
}
.sede-code-toolbar-btn{
  width:32px;height:32px;display:inline-grid;place-items:center;
  border:none;border-radius:6px;background:transparent;cursor:pointer;
  color:var(--muted);transition:color .12s,background .12s;
}
.sede-code-toolbar-btn:hover{color:var(--text);background:var(--chip-bg, rgba(0,0,0,.06));}
.sede-code-toolbar-btn .ms{font-size:18px;}
/* ▶ Run button — green accent */
.sede-run-btn{color:#10b981 !important;}
.sede-run-btn:hover{background:rgba(16,185,129,.1) !important;color:#059669 !important;}
/* Tab status indicator */
.sede-exec-status{font-size:11px;font-weight:500;display:inline-flex;align-items:center;gap:3px;margin-left:auto;padding:0 8px;}
.sede-exec-status.is-running{color:#6366f1;}
.sede-exec-status.is-running .ms{font-size:14px;animation:spin 1s linear infinite;}
@keyframes spin{to{transform:rotate(360deg);}}
.sede-exec-status.is-success{color:#10b981;}
.sede-exec-status.is-error{color:#ef4444;}
.sede-status-dot{width:8px;height:8px;border-radius:50%;display:inline-block;}
.sede-status-dot.is-success{background:#10b981;}
.sede-status-dot.is-error{background:#ef4444;}
/* ── Sede Steer Area ── */
.sede-steer-area{padding:8px 12px;border-radius:var(--radius, 12px);border:1px solid rgba(99,102,241,.2);background:rgba(99,102,241,.04);margin-bottom:8px;}
.sede-steer-area.hidden{display:none !important;}
.sede-steer-header{display:flex;align-items:center;gap:6px;font-size:12px;font-weight:600;color:#6366f1;margin-bottom:6px;}
.sede-steer-header .ms{font-size:16px;}
.sede-steer-title{flex:1;}
.sede-steer-close{background:none;border:none;cursor:pointer;color:#94a3b8;width:24px;height:24px;display:inline-grid;place-items:center;border-radius:6px;}
.sede-steer-close:hover{background:rgba(0,0,0,.06);color:#6b7280;}
.sede-steer-close .ms{font-size:16px;}
.sede-steer-body{display:flex;gap:8px;align-items:flex-end;}
.sede-steer-input{flex:1;padding:8px 12px;border:1px solid rgba(99,102,241,.2);border-radius:10px;font-size:13px;font-family:'Fira Code',Consolas,monospace;resize:none;outline:none;background:transparent;color:inherit;}
.sede-steer-input:focus{border-color:#6366f1;}
.sede-steer-btn{display:inline-flex;align-items:center;gap:4px;padding:8px 14px;border-radius:10px;background:#6366f1;color:#fff;border:none;font-size:13px;font-weight:600;cursor:pointer;flex-shrink:0;}
.sede-steer-btn:hover{background:#1a40b5;}
.sede-steer-btn .ms{font-size:16px;}
/* Sede stop button */
.sede-stop-btn{display:inline-grid !important;place-items:center;width:32px;height:32px;border-radius:50%;background:#ef4444;color:#fff;border:none;cursor:pointer;}
.sede-stop-btn:hover{background:#dc2626;}
.sede-stop-btn .ms{font-size:16px;}
.sede-stop-btn.hidden{display:none !important;}
/* ── Voice co-create ── */
.sede-voice-btn{position:relative;transition:color .2s,background .2s;}
.sede-voice-btn.is-active{color:#ef4444 !important;background:rgba(239,68,68,.1);border-radius:8px;}
.sede-voice-btn.is-active .ms{animation:sede-mic-pulse 1.5s ease-in-out infinite;}
@keyframes sede-mic-pulse{0%,100%{opacity:1;}50%{opacity:.5;}}
.sede-voice-banner{display:flex;align-items:center;gap:8px;padding:8px 14px;margin:0 0 6px;border-radius:10px;background:rgba(239,68,68,.06);border:1px solid rgba(239,68,68,.15);font-size:13px;color:#dc2626;transition:opacity .3s;}
.sede-voice-banner .ms{font-size:16px;color:#ef4444;}
.sede-voice-banner-text{flex:1;min-width:0;}
.sede-voice-banner-transcript{font-size:12px;color:#666;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%;}
.sede-voice-banner-close{background:none;border:none;cursor:pointer;color:#999;padding:2px;line-height:1;}
.sede-voice-banner-close:hover{color:#ef4444;}
.sede-voice-verify{display:flex;align-items:center;gap:6px;padding:6px 12px;border-radius:8px;background:rgba(34,197,94,.06);border:1px solid rgba(34,197,94,.15);font-size:12px;color:#16a34a;margin-top:4px;}
.sede-voice-verify .ms{font-size:14px;}
.sede-voice-verify.is-fail{background:rgba(239,68,68,.06);border-color:rgba(239,68,68,.15);color:#dc2626;}
body[data-chat-dark="1"] .sede-voice-banner{background:rgba(239,68,68,.1);border-color:rgba(239,68,68,.2);color:#f87171;}
body[data-chat-dark="1"] .sede-voice-banner-transcript{color:rgba(255,255,255,.5);}
/* Dark mode */
body[data-chat-dark="1"] .sede-steer-area{background:rgba(99,102,241,.08);border-color:rgba(99,102,241,.2);}
body[data-chat-dark="1"] .sede-steer-input{background:rgba(0,0,0,.2);color:#fff;border-color:rgba(99,102,241,.2);}
body[data-chat-dark="1"] .sede-steer-close{color:rgba(255,255,255,.4);}
body[data-chat-dark="1"] .sede-steer-close:hover{background:rgba(255,255,255,.08);color:#fff;}
/* ── Live Preview ── */
.sede-preview-wrap{display:flex;flex-direction:column;border-top:1px solid var(--border, rgba(0,0,0,.08));flex:1;min-height:180px;}
.sede-preview-header{padding:6px 12px;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.04em;color:var(--muted);display:flex;align-items:center;gap:6px;background:rgba(0,0,0,.02);}
.sede-preview-close{margin-left:auto;background:none;border:none;cursor:pointer;color:var(--muted);padding:2px;}
.sede-preview-close:hover{color:var(--text);}
.sede-preview-iframe{flex:1;border:none;width:100%;min-height:200px;background:#fff;border-radius:0 0 0 0;}
body[data-chat-dark="1"] .sede-preview-wrap{border-color:rgba(255,255,255,.06);}
body[data-chat-dark="1"] .sede-preview-header{background:rgba(255,255,255,.03);color:rgba(255,255,255,.4);}
body[data-chat-dark="1"] .sede-preview-iframe{background:#1a1a1a;}
/* ── Terminal ── */
.sede-terminal-wrap{border-top:1px solid var(--border, rgba(0,0,0,.08));display:flex;flex-direction:column;max-height:200px;}
.sede-terminal-header{padding:6px 12px;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.04em;color:var(--muted);display:flex;align-items:center;gap:6px;background:rgba(0,0,0,.02);}
.sede-terminal-output{flex:1;overflow-y:auto;padding:8px 12px;background:#0d1117;color:#fff;font-family:'Fira Code',Consolas,monospace;font-size:12px;line-height:1.6;white-space:pre-wrap;word-break:break-all;}
.sede-term-prompt{color:#fff;font-weight:700;margin-right:6px;}
.sede-term-stdout{color:#fff;}
.sede-term-stderr{color:#ff6b6b;}
.sede-terminal-status{padding:4px 12px;font-size:11px;font-weight:600;display:flex;align-items:center;gap:4px;}
.sede-terminal-status .ms{font-size:13px;}
.sede-terminal-status.is-success{background:#065f46;color:#6ee7b7;}
.sede-terminal-status.is-error{background:#7f1d1d;color:#fca5a5;}
/* ── Confirmation Dialog ── */
.sede-run-confirm-overlay{position:fixed;inset:0;z-index:10001;background:rgba(0,0,0,.5);backdrop-filter:blur(4px);display:flex;align-items:center;justify-content:center;}
.sede-run-confirm-card{background:var(--panel, #fff);border-radius:16px;border:1px solid var(--border, rgba(0,0,0,.08));box-shadow:0 16px 48px rgba(0,0,0,.2);width:min(440px,calc(100% - 32px));padding:20px;display:grid;gap:14px;}
.sede-run-confirm-warn{padding:10px 14px;border-radius:10px;background:#fef2f2;border:1px solid #fecaca;color:#991b1b;font-size:13px;font-weight:600;display:flex;align-items:center;gap:8px;}
.sede-run-confirm-warn .ms{font-size:18px;color:#ef4444;}
.sede-run-confirm-title{font-size:15px;font-weight:700;color:var(--text, #1d1d1f);}
.sede-run-confirm-meta{display:flex;gap:16px;font-size:12px;color:var(--muted);font-family:'Fira Code',monospace;}
.sede-run-confirm-preview{max-height:120px;overflow:auto;background:#f8fafc;border-radius:8px;padding:10px;font-size:12px;margin:0;border:1px solid #e2e8f0;}
.sede-run-confirm-actions{display:flex;justify-content:flex-end;gap:8px;}
.sede-run-confirm-btn{display:inline-flex;align-items:center;gap:4px;padding:8px 16px;border-radius:10px;border:none;font-size:13px;font-weight:600;cursor:pointer;transition:background .15s;}
.sede-run-confirm-btn.is-cancel{background:#f1f5f9;color:#64748b;}
.sede-run-confirm-btn.is-cancel:hover{background:#e2e8f0;}
.sede-run-confirm-btn.is-run{background:#10b981;color:#fff;}
.sede-run-confirm-btn.is-run:hover{background:#059669;}
.sede-run-confirm-btn .ms{font-size:16px;}
/* ── VSCode-style error/success line markers ── */
.sede-line-highlight.is-error{background:rgba(239,68,68,.08) !important;color:#ef4444 !important;}
.sede-line-highlight.is-success{background:rgba(16,185,129,.05) !important;}
.sede-line-icon{font-size:12px !important;margin-right:2px;}
.sede-line-icon.is-error{color:#ef4444 !important;}
/* ── Auto-run suggestion banner ── */
.sede-autorun-banner{display:flex;align-items:center;gap:10px;padding:10px 14px;margin:8px 0;border-radius:10px;background:rgba(16,185,129,.06);border:1px solid rgba(16,185,129,.15);font-size:13px;font-weight:500;color:#059669;}
.sede-autorun-btn{margin-left:auto;display:inline-flex;align-items:center;gap:4px;padding:6px 14px;border-radius:8px;background:#10b981;color:#fff;border:none;font-size:12px;font-weight:600;cursor:pointer;}
.sede-autorun-btn:hover{background:#059669;}
.sede-autorun-btn .ms{font-size:14px;}
/* Dark mode overrides */
body[data-chat-dark="1"] .sede-terminal-header{background:rgba(255,255,255,.03);color:rgba(255,255,255,.4);}
body[data-chat-dark="1"] .sede-terminal-wrap{border-color:rgba(255,255,255,.06);}
body[data-chat-dark="1"] .sede-run-confirm-card{background:#1a1a1a;border-color:rgba(255,255,255,.1);}
body[data-chat-dark="1"] .sede-run-confirm-title{color:#fff;}
body[data-chat-dark="1"] .sede-run-confirm-preview{background:#111;border-color:rgba(255,255,255,.08);color:#e2e8f0;}
body[data-chat-dark="1"] .sede-run-confirm-warn{background:rgba(239,68,68,.1);border-color:rgba(239,68,68,.2);color:#fca5a5;}
body[data-chat-dark="1"] .sede-run-confirm-btn.is-cancel{background:rgba(255,255,255,.08);color:rgba(255,255,255,.6);}
body[data-chat-dark="1"] .sede-autorun-banner{background:rgba(16,185,129,.08);border-color:rgba(16,185,129,.15);color:#6ee7b7;}

/* Code Editor Area */
.sede-code-editor{
  flex:1;overflow:auto;min-height:0;position:relative;
  background:var(--panel, #fff);
}
.sede-code-editor pre{margin:0;padding:14px 16px 14px 56px;min-height:100%;}
.sede-code-editor code{
  display:block;font-size:13px;line-height:1.65;
  font-family:'Fira Code','SF Mono',Consolas,monospace;tab-size:2;
}
.sede-line-numbers{
  position:absolute;left:0;top:0;padding:12px 0;
  font-size:13px;line-height:1.65;
  color:var(--muted, rgba(29,29,31,.4));text-align:right;
  width:48px;user-select:none;pointer-events:none;
  font-family:'Fira Code',Consolas,monospace;
  border-right:1px solid var(--border, rgba(0,0,0,.06));
}
.sede-line-numbers div{padding:0 8px;line-height:1.65;}

/* Diff mode */
.sede-diff-add{background:rgba(34,197,94,.12) !important;}
.sede-diff-del{background:rgba(239,68,68,.12) !important;text-decoration:line-through;opacity:.7;}

/* ── Sede Composer (reuses Quick Chat .app-chat-composer component) ── */
.sede-composer-inline{
  flex-shrink:0;padding:12px 20px calc(12px + env(safe-area-inset-bottom, 0px));
  border-top:none;
  background:transparent;
  max-width:820px;width:100%;margin:0 auto;
}
/* Sede-specific: monospace font in input */
.sede-composer-form .app-chat-input{font-family:'Fira Code','SF Mono','Cascadia Code',Consolas,monospace !important;font-size:14px !important;}
.sede-composer-inline .app-chat-disclaimer{font-family:inherit !important;
}
/* FIX: Centered composer when welcome screen is visible — margin-bottom:auto pairs with
   .sede-welcome margin-top:auto to center greeting+input as a group */
.sede-composer-inline.is-centered{
  border-top:none !important;
  padding-top:0 !important;
  max-width:600px;
  margin:0 auto auto;width:100%;
  background:transparent !important;
}
.sede-composer-inner{
  max-width:820px;margin:0 auto;display:flex;align-items:flex-end;gap:8px;
}
.sede-composer-left{display:flex;gap:4px;align-items:flex-end;}
.sede-composer-btn{
  width:36px;height:36px;display:inline-grid;place-items:center;
  border:none;border-radius:10px;background:transparent;cursor:pointer;
  color:var(--muted);transition:color .12s,background .12s;
}
.sede-composer-btn:hover{color:var(--text);background:var(--chip-bg, rgba(0,0,0,.06));}
.sede-composer-btn .ms{font-size:20px;}
.sede-composer-textarea{
  flex:1;min-width:0;padding:8px 14px;
  border:1px solid var(--border, rgba(0,0,0,.1));border-radius:var(--radius, 12px);
  font-size:14px;line-height:1.5;background:var(--input-bg, #fff);color:var(--text, #1d1d1f);
  resize:none;max-height:160px;
  font-family:'Fira Code','SF Mono',Consolas,monospace;
  outline:none;transition:border-color .15s;
}
.sede-composer-textarea:focus{border-color:var(--accent, #6366f1);}
.sede-composer-textarea::placeholder{color:var(--muted);}
.sede-composer-send{
  width:36px;height:36px;display:inline-grid;place-items:center;
  border:none;border-radius:50%;cursor:pointer;flex-shrink:0;
  background:var(--accent, #6366f1);color:#fff;transition:opacity .12s;
}
.sede-composer-send:hover{opacity:.85;}
.sede-composer-send:disabled{opacity:.35;cursor:default;}
.sede-composer-send .ms{font-size:20px;}

/* ── Sede Slash Command Suggest ── */
.sede-cmd-suggest{
  position:absolute;bottom:100%;left:0;right:0;
  margin-bottom:4px;
  background:var(--panel-bg, #1e1e1e);
  border:1px solid var(--border, rgba(255,255,255,.1));
  border-radius:10px;
  box-shadow:0 4px 16px rgba(0,0,0,.35);
  overflow:hidden;
  z-index:60;
  display:none;
  font-family:'Fira Code','SF Mono','Cascadia Code',Consolas,monospace;
}
.sede-cmd-suggest.is-visible{display:block;}
.sede-cmd-item{
  display:flex;align-items:center;gap:10px;
  padding:8px 14px;cursor:pointer;
  transition:background .1s;
  font-size:13px;line-height:1.4;
}
.sede-cmd-item:hover,.sede-cmd-item.is-active{
  background:var(--chip-bg, rgba(255,255,255,.08));
}
.sede-cmd-name{
  color:var(--accent, #7cacf8);font-weight:600;
  min-width:80px;white-space:nowrap;
}
.sede-cmd-desc{
  color:var(--muted, rgba(255,255,255,.5));
  font-family:Inter,'Hiragino Sans',sans-serif;
  font-size:12px;
}
.sede-cmd-icon{
  font-size:15px;width:20px;text-align:center;
  color:var(--muted, rgba(255,255,255,.5));
}

/* ── Mobile: stack panes ── */
@media(max-width:768px){
  #appAiChatShell[data-chat-mode="sede"] .sede-chat-wrap{flex-direction:column !important;}
  .sede-left-pane{flex:1 !important;border-right:none !important;border-bottom:1px solid var(--border);}
  .sede-right-pane{flex:0 0 50% !important;}
  .sede-terminal{height:25% !important;min-height:60px !important;}
}

/* ── Code Runner: Run Button + Results ── */
/* Sede run button in code header */
.sede-run-btn{
  background:none;border:none;cursor:pointer;color:#22c55e;padding:2px 8px;
  border-radius:4px;font-size:12px;display:inline-flex;align-items:center;gap:3px;
  font-family:inherit;font-weight:600;transition:color .12s,background .12s;
}
.sede-run-btn:hover{color:#16a34a;background:rgba(34,197,94,.1);}
/* Quick Chat run button */
.app-chat-md-code-run-btn{
  position:absolute;top:4px;right:72px;
  padding:3px 10px;border-radius:6px;border:none;
  font-size:12px;font-weight:600;cursor:pointer;
  background:rgba(34,197,94,.15);color:#16a34a;
  font-family:'Fira Code',Consolas,monospace;
  transition:background .15s,color .15s;
}
.app-chat-md-code-run-btn:hover{background:rgba(34,197,94,.25);color:#15803d;}
body[data-chat-dark="1"] .app-chat-md-code-run-btn{
  background:rgba(34,197,94,.2);color:#4ade80;
}
body[data-chat-dark="1"] .app-chat-md-code-run-btn:hover{
  background:rgba(34,197,94,.3);color:#86efac;
}
/* Run result area */
.sede-run-result{
  margin:8px 0;border-radius:10px;overflow:hidden;
  border:1px solid var(--border, rgba(0,0,0,.08));
  font-family:'Fira Code',Consolas,monospace;
  animation:sedeMsgIn .2s ease;
}
.sede-run-result.is-loading{border-color:rgba(59,130,246,.3);}
.sede-run-result.is-error{border-color:rgba(239,68,68,.3);}
.sede-run-result.is-warning{border-color:rgba(234,179,8,.3);}
.sede-run-result-head{
  display:flex;align-items:center;gap:6px;padding:8px 12px;
  font-size:12px;font-weight:600;
  background:var(--chip-bg, rgba(0,0,0,.03));color:var(--text);
}
.sede-run-result.is-loading .sede-run-result-head{color:#3b82f6;}
.sede-run-result.is-error .sede-run-result-head{color:#ef4444;}
.sede-run-result.is-warning .sede-run-result-head{color:#eab308;}
.sede-run-result-head .sede-run-result-close{
  margin-left:auto;background:none;border:none;cursor:pointer;
  color:var(--muted);padding:2px;border-radius:4px;
  transition:color .12s,background .12s;
}
.sede-run-result-head .sede-run-result-close:hover{color:var(--text);background:var(--chip-bg);}
.sede-run-output{
  margin:0;padding:10px 14px;font-size:13px;line-height:1.6;
  color:var(--text);background:var(--panel, #fff);
  overflow-x:auto;white-space:pre-wrap;word-break:break-all;
  max-height:300px;overflow-y:auto;
}
.sede-run-output.is-stderr{color:#ef4444;}
/* Dark mode for run results */
body[data-chat-dark="1"] .sede-run-result{border-color:rgba(255,255,255,.1);}
body[data-chat-dark="1"] .sede-run-result-head{background:rgba(255,255,255,.04);color:rgba(255,255,255,.7);}
body[data-chat-dark="1"] .sede-run-result.is-loading .sede-run-result-head{color:#60a5fa;}
body[data-chat-dark="1"] .sede-run-result.is-error .sede-run-result-head{color:#f87171;}
body[data-chat-dark="1"] .sede-run-output{background:#0d0d0d;color:rgba(255,255,255,.85);}
body[data-chat-dark="1"] .sede-run-output.is-stderr{color:#f87171;}
body[data-chat-dark="1"] .sede-run-btn{color:#4ade80;}
body[data-chat-dark="1"] .sede-run-btn:hover{color:#86efac;background:rgba(34,197,94,.15);}
/* Run result action buttons (fix/add/done) */
.sede-run-actions{
  display:flex;gap:6px;padding:8px 12px;flex-wrap:wrap;
  border-top:1px solid var(--border, rgba(0,0,0,.06));
}
.sede-run-action-btn{
  padding:6px 14px;border-radius:8px;border:1px solid var(--border, rgba(0,0,0,.1));
  font-size:12px;font-weight:600;cursor:pointer;
  font-family:'Fira Code',Consolas,monospace;
  background:var(--panel, #fff);color:var(--text);
  transition:background .15s,border-color .15s;
}
.sede-run-action-btn:hover{background:var(--chip-bg, rgba(0,0,0,.04));}
.sede-run-action-btn.is-fix{border-color:rgba(239,68,68,.3);color:#dc2626;}
.sede-run-action-btn.is-fix:hover{background:rgba(239,68,68,.06);}
.sede-run-action-btn.is-add{border-color:rgba(59,130,246,.3);color:#2563eb;}
