.app-chat-process-summary-item{padding:8px 10px;border-radius:8px;background:#f9fafb;}
.app-chat-process-filter-row{padding:0 16px 10px;display:flex;align-items:center;gap:8px;}
.app-chat-process-filter-selects{
  display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;flex:1;
}
.app-chat-process-list{padding:4px 16px 16px;overflow-y:auto;display:grid;gap:8px;}
.app-chat-process-card{
  padding:12px 14px;border-radius:10px;
  border:1px solid rgba(0,0,0,.05);background:#f9fafb;
  transition:background .12s ease;
}
.app-chat-process-card:hover{background:#f3f4f6;}
.app-chat-process-tech-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;}
.app-chat-process-code{
  max-height:240px;overflow-y:auto;border-radius:6px;
  background:#1e1e1e;color:#d4d4d4;border:0;padding:12px;font-size:12px;line-height:1.6;
}
.app-chat-process-footer{
  padding:10px 16px;border-top:1px solid rgba(0,0,0,.06);
  display:flex;align-items:center;justify-content:space-between;gap:10px;
}
.app-chat-process-history-switch{display:flex;align-items:center;gap:8px;}
.app-chat-process-history-switch select{
  min-width:150px;padding:5px 8px;border-radius:6px;
  border:1px solid rgba(0,0,0,.1);background:#ffffff;font-size:12px;color:#374151;
}

/* ══════════ Disclaimer text under input ══════════ */
body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-meta{
  text-align:center;font-size:11px;color:#9ca3af;padding:4px 0;
}

/* ══════════ Mobile ══════════ */
