  body[data-app-tab="chat"] #appChatPage{
    max-width:none;min-height:calc(100dvh - 8px);padding-top:2px;
  }
  body[data-app-tab="chat"] .app-chat-shell{
    min-height:calc(100dvh - 10px) !important;border-radius:0 !important;
