    transform:translateX(-100%) !important;opacity:0 !important;pointer-events:none !important;
    transition:transform .32s cubic-bezier(.32,1,.23,1),opacity .24s ease !important;
    z-index:9999 !important;
    background:#fff !important;border-right:0 !important;border-radius:0 16px 16px 0 !important;
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] #appAiChatShell[data-sidebar-open="1"] #appChatSidebar{
    transform:translateX(0) !important;opacity:1 !important;pointer-events:auto !important;
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] #appAiChatShell[data-sidebar-open="1"] .app-chat-bottom-dock{
    opacity:0;pointer-events:none;transform:translateY(8px);
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] #appAiChatShell[data-sidebar-open="1"] .app-chat-scroll{
    pointer-events:none;
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] #appChatSidebarToggleBtn{
