  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-head{padding:8px 16px 0 !important;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-pane-note span{font-size:10px;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] #appChatPromptShelf{width:calc(100% - 32px);margin:0 auto 8px;}

  /* Messages */
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-msg{
    padding:20px 16px;
    grid-template-columns:30px minmax(0,1fr);gap:0 12px;
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-role-icon{
    width:30px !important;height:30px !important;
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-role-icon .ms{font-size:15px;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-list{gap:0;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-list::after{height:0;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-msg.is-user{max-width:100%;}

  /* Empty state */
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-empty-state{padding:0 16px 24px;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-empty-hero h3{font-size:26px;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-empty-chip-grid{
    grid-template-columns:1fr !important;gap:24px;
  }

  /* Process panel */
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-panel{
    position:fixed;right:10px;left:10px;
    bottom:max(10px,env(safe-area-inset-bottom,0px));
    margin:0;height:min(82vh,720px);max-height:none;
    border-radius:var(--radius-lg, 16px);border:1px solid rgba(0,0,0,.1);
    box-shadow:0 16px 40px rgba(0,0,0,.16);z-index:14;
    transform:translateY(0);transition:transform .18s ease,opacity .18s ease;
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-panel[data-collapsed="1"]{height:100px;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-panel[data-collapsed="1"] .app-chat-process-filter-row,
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-panel[data-collapsed="1"] .app-chat-process-list,
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-panel[data-collapsed="1"] .app-chat-process-footer{display:none;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-panel[data-collapsed="1"] .app-chat-process-summary{padding-bottom:14px;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] #appAiChatShell[data-sidebar-open="1"] .app-chat-process-panel{
    opacity:0;pointer-events:none;transform:translateY(12px);
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-header{padding:12px 14px 10px;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-summary{
    padding:8px 14px;grid-template-columns:repeat(2,minmax(0,1fr));
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-filter-row{padding:0 14px 10px;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-filter-selects{grid-template-columns:1fr;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-list{padding:4px 14px 14px;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-card{padding:12px;border-radius:10px;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-tech-grid{grid-template-columns:1fr;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-code{max-height:180px;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-footer{
    padding:10px 14px;align-items:flex-start;flex-direction:column;
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-history-switch{width:100%;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-history-switch select{min-width:0;width:100%;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-header-controls{justify-items:stretch;}
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-process-mode-toggle{width:100%;}

  .app-chat-rejection-card{padding:12px;border-radius:12px;}
  .app-chat-support-grid{grid-template-columns:1fr;}

  /* Bottom dock */
  .app-chat-bottom-dock{
    width:calc(100% - 20px);
    margin-bottom:max(14px, calc(env(safe-area-inset-bottom,0px) + 8px));
    gap:6px;transition:opacity .18s ease,transform .18s ease;
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-composer{
    padding:0 !important;border-radius:24px !important;
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-pending-attachments{margin-bottom:6px;}
  /* attachment width controlled by FINAL OVERRIDE */
  .app-chat-attachment-body strong{
    white-space:nowrap;
  }
  .app-chat-preset-card{width:100%;padding:12px;border-radius:var(--radius, 12px);}
  .app-chat-preset-card-head{flex-direction:column;align-items:flex-start;}
  .app-chat-process-toggle-row,.app-chat-process-history{width:100%;}

  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-input{
    min-height:44px !important;padding:12px 14px !important;border-radius:24px !important;
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-send,
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-send.btn.primary{
    width:30px !important;height:30px !important;flex:0 0 30px !important;
    min-width:0 !important;min-height:0 !important;
    margin:0 7px 7px 0 !important;border-radius:50% !important;
  }
  body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-send .ms{font-size:16px;}
}


/* font-size bridge: enforce setting reflection on core UI */
.brand-title,
.brand-sub,
.icon-label,
.btn,
.navbtn,
.textbtn,
.menu-item,
.settings-row .label,
.settings-row .value,
.app-settings-row,
.note,
.auth-gate-status,
.app-page-head p,
.app-page-head h2,
.app-inbox-title,
.app-inbox-preview,
.app-ins-k,
.app-ins-v,
.drawer-share-status{
  font-size: calc(1em * var(--ui-font-scale));
}

/* Notifications: chat-thread refresh */
:root{
  --inbox-thread-bg:#ffffff;
  --inbox-bubble-bg:var(--chat-bubble-ai, var(--panel));
  --inbox-bubble-border:var(--chat-border, var(--border));
  --inbox-avatar-bg:var(--chat-surface-soft, var(--panel2));
  --inbox-avatar-text:color-mix(in srgb, var(--text) 70%, transparent);
  --inbox-high-chip-bg:rgba(37,99,235,.10);
  --inbox-high-chip-border:rgba(37,99,235,.22);
}
:root[data-theme-mode="dark"]{
  --inbox-thread-bg:#171b24;
  --inbox-bubble-bg:#171b24;
  --inbox-bubble-border:rgba(255,255,255,.14);
  --inbox-avatar-bg:#1e2430;
  --inbox-avatar-text:rgba(245,246,247,.86);
  --inbox-high-chip-bg:rgba(143,182,255,.15);
  --inbox-high-chip-border:rgba(143,182,255,.26);
}

#appNotificationsPage{
  gap: 12px;
}
body[data-app-tab="notifications"] #appNotificationsPage{
  display: grid !important;
}
#appNotificationsPage #appInboxListPane,
#appNotificationsPage #appInboxDetailPane{
  border: 1px solid var(--inbox-bubble-border);
  border-radius: 20px;
  background: var(--inbox-thread-bg);
  box-shadow: 0 10px 26px rgba(15,23,42,.07);
}
#appNotificationsPage #appInboxListPane{
  max-height: min(74dvh, 780px);
  overflow: auto;
  -webkit-overflow-scrolling: touch;
  padding: 12px;
}
#appNotificationsPage #appInboxDetailPane{
  max-height: min(74dvh, 780px);
  overflow: auto;
  -webkit-overflow-scrolling: touch;
}
#appNotificationsPage .app-inbox-list{
  display: grid;
  gap: 12px;
  align-content: start;
}
#appNotificationsPage .app-inbox-item{
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  margin: 0;
  max-width: 100%;
}
#appNotificationsPage .app-inbox-avatar{
  width: 34px;
  height: 34px;
  border-radius: 999px;
  border: 1px solid var(--inbox-bubble-border);
  background: var(--inbox-avatar-bg);
  color: var(--inbox-avatar-text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .04em;
  flex-shrink: 0;
}
#appNotificationsPage .app-inbox-avatar .ms{
  font-size: 16px;
  line-height: 1;
}
#appNotificationsPage .app-inbox-body{
  min-width: 0;
  display: grid;
  gap: 6px;
}
#appNotificationsPage .app-inbox-bubble{
  position: relative;
  border: 1px solid var(--inbox-bubble-border) !important;
  border-radius: 16px !important;
  background: var(--inbox-bubble-bg) !important;
  box-shadow: 0 6px 18px rgba(15,23,42,.05);
  padding: 10px 12px;
}
#appNotificationsPage .app-inbox-item.unread .app-inbox-bubble{
  border-color: color-mix(in srgb, var(--accent, #2563eb) 36%, var(--inbox-bubble-border)) !important;
}
#appNotificationsPage .app-inbox-unread-dot{
  position: absolute;
  left: -4px;
  top: -4px;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent, #2563eb) 78%, #ffffff);
  box-shadow: 0 0 0 2px var(--inbox-thread-bg);
}
#appNotificationsPage .app-inbox-item:not(.unread) .app-inbox-unread-dot{
  display: none;
}
#appNotificationsPage .app-inbox-bubble-head{
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}
#appNotificationsPage .app-inbox-title{
  margin: 0;
  color: var(--text);
  font-size: 14px;
  line-height: 1.45;
  font-weight: 700;
}
#appNotificationsPage .app-inbox-category{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid var(--inbox-bubble-border);
  background: var(--chat-surface-soft, var(--panel2));
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}
#appNotificationsPage .app-inbox-item.priority-high .app-inbox-category{
  background: var(--inbox-high-chip-bg);
  border-color: var(--inbox-high-chip-border);
}
#appNotificationsPage .app-inbox-preview{
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.55;
  word-break: break-word;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
#appNotificationsPage .app-inbox-bubble-meta{
  margin-top: 7px;
  display: flex;
  justify-content: flex-end;
}
#appNotificationsPage .app-inbox-time{
  font-size: 11px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
#appNotificationsPage .app-inbox-action-row{
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}
#appNotificationsPage .app-inbox-read-state{
  font-size: 11px;
  color: var(--muted);
  margin-right: auto;
}
#appNotificationsPage .app-inbox-action-btn{
  min-height: 30px;
  border-radius: 999px;
  padding: 0 12px;
}
#appNotificationsPage .app-inbox-inline-actions{
  display: flex;
  align-items: center;
  gap: 8px;
}
#appNotificationsPage .app-inbox-inline-actions.hidden{
  display: none;
}
#appNotificationsPage .app-inbox-action-btn.is-approve{
  background: color-mix(in srgb, var(--primary) 82%, #ffffff);
  color: #ffffff;
  border-color: color-mix(in srgb, var(--primary) 42%, transparent);
}
#appNotificationsPage .app-inbox-action-btn.is-reject{
  background: color-mix(in srgb, var(--panel2) 88%, #ffffff);
  color: var(--text);
}

#appNotificationsPage .app-inbox-detail-shell{
  min-height: 100%;
}
#appNotificationsPage .app-inbox-detail-head{
  position: sticky;
  top: 0;
  z-index: 4;
  border-bottom: 1px solid var(--inbox-bubble-border);
  background: var(--inbox-thread-bg);
  padding: 12px 12px 10px;
}
#appNotificationsPage .app-inbox-detail-head-actions{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
#appNotificationsPage .app-inbox-close-btn{
  appearance: none;
  border: 1px solid var(--inbox-bubble-border);
  background: var(--inbox-thread-bg);
  color: var(--text);
  width: 32px;
  height: 32px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
#appNotificationsPage .app-inbox-close-btn .ms{
  font-size: 18px;
}
#appNotificationsPage .app-detail-title{
  margin: 10px 0 6px;
  font-size: 20px;
  line-height: 1.4;
}
#appNotificationsPage .app-detail-meta{
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 0;
}
#appNotificationsPage .app-inbox-detail-chip{
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 2px 9px;
  border-radius: 999px;
  border: 1px solid var(--inbox-bubble-border);
  background: var(--chat-surface-soft, var(--panel2));
  color: var(--muted);
  font-size: 11px;
}
#appNotificationsPage .app-inbox-detail-chip.is-high{
  background: var(--inbox-high-chip-bg);
  border-color: var(--inbox-high-chip-border);
}
#appNotificationsPage .app-detail-content{
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  padding: 14px 14px 18px;
}
#appNotificationsPage .app-detail-content .notify-detail-text{
  font-size: 14px;
  line-height: 1.72;
}
#appNotificationsPage .app-empty{
  padding: 14px 4px 8px;
}

/* =========================
   UI v2 (feature flag: ui_v2)
   ========================= */
.app-v2-sidebar-head,
.app-v2-sidebar-foot,
.app-v2-home-head,
.app-v2-stat-grid,
.app-v2-board-grid{
  display: none;
}
.app-v2-only{
  display: none !important;
}
.app-v2-sidebar-backdrop,
.app-v2-sidebar-toggle{
  display: none;
}
.app-v2-sidebar-nav{
  display: contents;
}
body[data-ui-v2="1"]{
  --app-v2-sidebar-w: 300px;
  --app-v2-sidebar-gap: 16px;
  --app-v2-sidebar-offset: calc(var(--app-v2-sidebar-w) + (var(--app-v2-sidebar-gap) * 2));
  --app-v2-topbar-h: 56px;
  --app-safe-top: max(0px, env(safe-area-inset-top, 0px));
  --app-v2-top-offset: calc(var(--app-v2-topbar-h) + 12px);
  --app-v2-content-max: 1220px;
  --app-v2-sidebar-radius: 30px;
  /* 直書きの #f5f5f7 をやめる。html / body と同じ 1 つの値へ。
     ここだけ違う色だと、面が届かない所（下端・上端）にその差が帯で出る。 */
  background-color: var(--vq-bg-canvas, #F7F6FB);
}
body[data-ui-v2="1"],
body[data-ui-v2="1"] .app{
  min-height: 100dvh;
}
body[data-ui-v2="1"] .app{
  align-items: stretch;
  justify-content: flex-start;
}
body[data-ui-v2="1"].app-v2-sidebar-lock{
  overflow: hidden;
}
body[data-ui-v2="1"].app-follow-list-lock,
body[data-ui-v2="1"].app-profile-edit-lock{
  overflow: hidden;
}
body[data-ui-v2="1"] .topbar{
  position: fixed;
  top: max(var(--app-v2-sidebar-gap), env(safe-area-inset-top, 0px));
  left: calc(var(--app-v2-sidebar-offset) + 2px);
  right: var(--app-v2-sidebar-gap);
  z-index: 44;
  border: 1px solid rgba(0,0,0,.06);
  border-radius: 22px;
  background: rgba(255,255,255,.72);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  box-shadow: 0 2px 16px rgba(0,0,0,.06), 0 0 0 0.5px rgba(0,0,0,.03);
}
body[data-ui-v2="1"] .topbar-inner{
  max-width: none;
  min-height: 0;
