body[data-ui-v2="1"] textarea,
body[data-ui-v2="1"] select{
  border: 0 !important;
  border-radius: var(--radius, 12px) !important;
  background: var(--ds-surface-soft) !important;
  color: var(--ds-text) !important;
  box-shadow: inset 0 0 0 1px var(--ds-divider);
}
body[data-ui-v2="1"] .spell-input::placeholder,
body[data-ui-v2="1"] textarea::placeholder{
  color: color-mix(in srgb, var(--ds-text-soft) 86%, transparent);
}

/* Table cleanup: remove heavy grid lines */
body[data-ui-v2="1"] .table-wrap{
  border: 0 !important;
  border-radius: var(--ds-radius-md);
  background: var(--ds-surface) !important;
  box-shadow: var(--ds-shadow-xs);
  overflow: hidden;
}
body[data-ui-v2="1"] .table-wrap table{
  border-collapse: separate;
  border-spacing: 0;
}
body[data-ui-v2="1"] .table-wrap th{
  background: var(--ds-surface-soft) !important;
  color: var(--ds-text-soft) !important;
  font-size: 11px;
  letter-spacing: .04em;
  border-bottom: 1px solid var(--ds-divider) !important;
}
body[data-ui-v2="1"] .table-wrap td{
  border-bottom: 0 !important;
  color: var(--ds-text) !important;
}
body[data-ui-v2="1"] .table-wrap tbody tr + tr td{
  border-top: 1px solid var(--ds-divider);
}
body[data-ui-v2="1"] .table-wrap tbody tr:nth-child(even) td{
  background: color-mix(in srgb, var(--ds-surface-soft) 54%, transparent);
}
@media (hover: hover) and (pointer: fine){
  body[data-ui-v2="1"] .table-wrap tbody tr:hover td{
    background: color-mix(in srgb, var(--ds-primary) 8%, var(--ds-surface));
  }
}

/* Mobile safety: prevent page-level horizontal scrolling */
@media (max-width: 760px){
  body[data-ui-v2="1"]{
    overflow-x: hidden;
    /* ここが「スマホで指を動かしても何も起きない」の原因だった。
       overflow-x:hidden を付けると body 自身が巻物の箱になる。
       そこへ html,body{height:100%} が効いて body の高さが画面ぴったりに固定され、
       中身がはみ出しても **画面(html)側には巻くものが無い** 状態になっていた。
       body を中身の高さまで伸ばし、巻くのは画面側に戻す。 */
    height: auto;
    min-height: 100%;
  }
  body[data-ui-v2="1"] main{
    padding-left: 12px !important;
    padding-right: 12px !important;
  }
  body[data-ui-v2="1"] .app-v2-board-grid,
  body[data-ui-v2="1"] .app-v2-stat-grid,
  body[data-ui-v2="1"] .app-home-progress-cards,
  body[data-ui-v2="1"] .app-insights-grid{
    grid-template-columns: 1fr !important;
  }
  body[data-ui-v2="1"] .app-home-task-list,
  body[data-ui-v2="1"] .app-home-learning-grid,
  body[data-ui-v2="1"] .app-home-hub-grid,
  body[data-ui-v2="1"] .app-home-hero{
    grid-template-columns: 1fr !important;
  }
  body[data-ui-v2="1"] .home-preset-row .seg{
    max-width: 100%;
  }
}
@media (max-width: 1080px){
  body[data-ui-v2="1"] .app-home-hub-grid{
    grid-template-columns: 1fr;
  }
  body[data-ui-v2="1"] .app-home-hub-side{
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 820px){
  body[data-ui-v2="1"] .app-home-hub-side{
    grid-template-columns: 1fr;
  }
}
@media (max-width: 640px){
  body[data-ui-v2="1"] .app-home-hero{
    padding: 18px 16px;
    border-radius: 24px;
  }
  body[data-ui-v2="1"] .app-home-hero-actions{
    gap: 8px;
  }
  body[data-ui-v2="1"] .app-home-task-list{
    grid-template-columns: 1fr;
  }
  body[data-ui-v2="1"] .app-home-practice-card #modeActions{
    grid-template-columns: 1fr;
  }
  body[data-ui-v2="1"] .app-home-section-head{
    flex-direction: column;
    align-items: stretch;
  }
}

