  --uq-radius-xl: 24px;
  --uq-btn-height: 44px;
  --uq-btn-radius: 16px;
  --uq-btn-pill: 999px;
  --uq-overlay: rgba(11, 14, 22, .44);
  --uq-surface: rgba(255, 255, 255, .96);
  --uq-surface-strong: #ffffff;
  --uq-surface-soft: #f5f7fc;
  --uq-surface-muted: rgba(244, 247, 255, .92);
  --uq-border: rgba(15, 23, 42, .10);
  --uq-border-strong: rgba(15, 23, 42, .16);
  --uq-text: #101826;
  --uq-text-soft: #647089;
  --uq-primary: #355fda;
