  --uq-primary-text: #ffffff;
  --uq-secondary-bg: #eef3ff;
  --uq-secondary-bg-hover: #e8efff;
  --uq-secondary-text: #243557;
  --uq-ghost-bg: rgba(39, 52, 81, .06);
