  --uq-shadow-soft: 0 14px 40px rgba(15, 23, 42, .12);
  --uq-shadow-float: 0 22px 56px rgba(15, 23, 42, .18);
  --uq-shadow-press: 0 10px 24px rgba(15, 23, 42, .10);
