}
:root[data-theme-mode="dark"]{
  --uq-overlay: rgba(3, 7, 14, .62);
  --uq-surface: rgba(20, 27, 40, .96);
  --uq-surface-strong: #161d2b;
  --uq-surface-soft: #1b2435;
  --uq-surface-muted: rgba(29, 39, 58, .94);
  --uq-border: rgba(226, 232, 240, .10);
  --uq-border-strong: rgba(226, 232, 240, .16);
  --uq-text: #ecf1fb;
  --uq-text-soft: #a7b4cb;
  --uq-primary: #84a9ff;
  --uq-primary-hover: #95b6ff;
  --uq-primary-text: #0c1424;
  --uq-secondary-bg: #202c43;
  --uq-secondary-bg-hover: #263552;
  --uq-secondary-text: #edf3ff;
  --uq-ghost-bg: rgba(255, 255, 255, .05);
  --uq-ghost-bg-hover: rgba(255, 255, 255, .09);
  --uq-danger: #d6757b;
  --uq-danger-hover: #de858b;
  --uq-danger-text: #200d10;
  --uq-shadow-soft: 0 16px 44px rgba(0, 0, 0, .32);
  --uq-shadow-float: 0 26px 62px rgba(0, 0, 0, .42);
  --uq-shadow-press: 0 12px 30px rgba(0, 0, 0, .28);
