/* =========================================================
   VocabuQuiz OS Phase 1
   ---------------------------------------------------------
   Existing quiz/pages stay intact. This layer adds an OS-like
   shell, launcher, dock, and settings scaffold around them.
   ========================================================= */
:root{
  --vq-os-bg:#09111f;
  --vq-os-bg-soft:#0f172a;
  --vq-os-panel:rgba(12,18,30,.74);
  --vq-os-panel-strong:rgba(15,23,42,.84);
  --vq-os-panel-edge:rgba(255,255,255,.08);
  --vq-os-panel-edge-strong:rgba(255,255,255,.12);
  --vq-os-text:#eef2ff;
  --vq-os-text-soft:rgba(226,232,240,.72);
  --vq-os-accent:#76a6ff;
  --vq-os-accent-soft:rgba(118,166,255,.16);
  --vq-os-shadow:0 28px 56px rgba(2,6,23,.26);
  --vq-os-shadow-soft:0 18px 40px rgba(2,6,23,.2);
}
body[data-vq-os="1"]{
  --vq-os-wallpaper-a: radial-gradient(circle at 18% 18%, rgba(94, 234, 212, .14), transparent 28%);
  --vq-os-wallpaper-b: radial-gradient(circle at 82% 22%, rgba(96, 165, 250, .16), transparent 30%);
  --vq-os-wallpaper-c: linear-gradient(180deg, rgba(15, 23, 42, .98), rgba(9, 17, 31, .98));
}
body[data-vq-os="1"][data-vq-os-wallpaper="grid"]{
  --vq-os-wallpaper-a:
    linear-gradient(90deg, rgba(148,163,184,.08) 1px, transparent 1px) 0 0/34px 34px,
    linear-gradient(rgba(148,163,184,.06) 1px, transparent 1px) 0 0/34px 34px;
  --vq-os-wallpaper-b: radial-gradient(circle at 84% 20%, rgba(96,165,250,.12), transparent 30%);
}
body[data-vq-os="1"][data-vq-os-wallpaper="quiet"]{
  --vq-os-wallpaper-a: radial-gradient(circle at 20% 24%, rgba(255,255,255,.06), transparent 26%);
  --vq-os-wallpaper-b: radial-gradient(circle at 80% 14%, rgba(148,163,184,.1), transparent 28%);
}
body[data-vq-os="1"][data-vq-os-theme="slate"]{
  --vq-os-bg:#0c1322;
  --vq-os-bg-soft:#111a2b;
  --vq-os-panel:rgba(20,29,46,.74);
  --vq-os-panel-strong:rgba(17,24,39,.86);
  --vq-os-accent:#63b3ff;
  --vq-os-accent-soft:rgba(99,179,255,.16);
}
body[data-vq-os="1"][data-vq-os-theme="dusk"]{
  --vq-os-bg:#120f1f;
  --vq-os-bg-soft:#19152d;
  --vq-os-panel:rgba(28,24,46,.74);
  --vq-os-panel-strong:rgba(31,27,54,.84);
  --vq-os-accent:#7cc6ff;
  --vq-os-accent-soft:rgba(124,198,255,.16);
}
.vq-os-shell{
  position:relative;
  margin:0 0 20px;
  border-radius:32px;
  overflow:hidden;
  border:1px solid rgba(255,255,255,.08);
  background:
    var(--vq-os-wallpaper-a),
    var(--vq-os-wallpaper-b),
    var(--vq-os-wallpaper-c);
  box-shadow:var(--vq-os-shadow);
  color:var(--vq-os-text);
  isolation:isolate;
}
.vq-os-shell::after{
  content:"";
  position:absolute;
  inset:0;
  background:linear-gradient(180deg, var(--legacy-surface), var(--legacy-surface-soft));
  pointer-events:none;
}
.vq-os-home{
  position:relative;
  z-index:1;
  display:grid;
  gap:18px;
  padding:22px 22px 16px;
}
body[data-app-tab]:not([data-app-tab="home"]) #vqOsHomeSurface{
  display:none;
}
.vq-os-home-top{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:14px;
}
.vq-os-kicker{
  font-size:11px;
  letter-spacing:.14em;
  text-transform:uppercase;
  color:var(--vq-os-text-soft);
}
.vq-os-title{
  margin:8px 0 0;
  font-size:clamp(28px, 4vw, 40px);
  line-height:1.06;
  letter-spacing:-.03em;
}
.vq-os-copy{
  margin:10px 0 0;
  max-width:62ch;
  font-size:13px;
  line-height:1.75;
  color:var(--vq-os-text-soft);
}
.vq-os-meta{
  display:flex;
  flex-wrap:wrap;
  justify-content:flex-end;
  gap:8px;
}
.vq-os-pill{
  display:inline-flex;
  align-items:center;
  gap:6px;
  min-height:30px;
  padding:0 12px;
  border-radius:999px;
  border:1px solid var(--vq-os-panel-edge);
  background:rgba(255,255,255,.05);
  color:var(--vq-os-text);
  font-size:12px;
  box-shadow:0 8px 24px rgba(0,0,0,.16);
}
.vq-os-widget-grid{
  display:grid;
  grid-template-columns:repeat(3, minmax(0, 1fr));
  gap:14px;
}
.vq-os-widget{
  display:grid;
  gap:10px;
  padding:16px 16px 15px;
  min-height:152px;
  border-radius:24px;
  border:1px solid var(--vq-os-panel-edge);
  background:linear-gradient(180deg, var(--legacy-surface), var(--legacy-surface-soft));
  box-shadow:var(--vq-os-shadow-soft), inset 0 1px 0 rgba(255,255,255,.08);
  backdrop-filter:blur(10px);
}
.vq-os-widget-kicker{
  font-size:11px;
  letter-spacing:.12em;
  text-transform:uppercase;
  color:var(--vq-os-text-soft);
}
.vq-os-widget-title{
  font-size:20px;
  line-height:1.18;
  font-weight:760;
}
.vq-os-widget-copy{
  font-size:12px;
  line-height:1.68;
  color:var(--vq-os-text-soft);
}
.vq-os-widget-meta{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
}
.vq-os-metric{
  display:inline-flex;
  align-items:center;
  min-height:28px;
  padding:0 10px;
  border-radius:999px;
  background:rgba(255,255,255,.06);
  border:1px solid rgba(255,255,255,.06);
  font-size:12px;
  color:var(--vq-os-text);
}
.vq-os-widget-actions{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-top:auto;
}
.vq-os-launcher-head{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:12px;
}
.vq-os-launcher-kicker{
  font-size:11px;
  letter-spacing:.12em;
  text-transform:uppercase;
  color:var(--vq-os-text-soft);
}
.vq-os-launcher-title{
  margin-top:4px;
  font-size:20px;
  font-weight:760;
}
.vq-os-inline-action{
  color:var(--vq-os-text) !important;
  background:rgba(255,255,255,.06) !important;
  border-color:rgba(255,255,255,.08) !important;
}
.vq-os-launcher{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(120px, 1fr));
  gap:12px;
}
.vq-os-app-tile{
  appearance:none;
  width:100%;
  text-align:left;
  cursor:pointer;
  display:grid;
  gap:10px;
  padding:14px;
  min-height:132px;
  border-radius:22px;
  border:1px solid var(--vq-os-panel-edge);
  background:linear-gradient(180deg, var(--legacy-surface), var(--legacy-surface-soft));
  color:var(--vq-os-text);
  box-shadow:var(--vq-os-shadow-soft), inset 0 1px 0 rgba(255,255,255,.08);
  transition:transform .22s ease, border-color .22s ease, box-shadow .22s ease, background .22s ease;
}
.vq-os-app-tile:hover{
  transform:translateY(-1px);
  border-color:var(--vq-os-panel-edge-strong);
  box-shadow:0 24px 44px rgba(2,6,23,.24), inset 0 1px 0 rgba(255,255,255,.1);
}
.vq-os-app-tile:active{
  transform:translateY(1px);
}
.vq-os-app-tile.is-disabled{
  opacity:.72;
}
.vq-os-app-icon{
  width:46px;
  height:46px;
  border-radius:16px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  background:rgba(255,255,255,.1);
  border:1px solid rgba(255,255,255,.08);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.1);
}
.vq-os-app-icon .ms{
  font-size:22px;
}
.vq-os-app-name{
  font-size:15px;
  font-weight:760;
}
.vq-os-app-copy{
  font-size:12px;
  line-height:1.58;
  color:var(--vq-os-text-soft);
}
.vq-os-app-meta{
  display:flex;
  flex-wrap:wrap;
  gap:6px;
  margin-top:auto;
}
.vq-os-app-badge{
  display:inline-flex;
  align-items:center;
  min-height:24px;
  padding:0 9px;
  border-radius:999px;
  border:1px solid rgba(255,255,255,.08);
  background:rgba(255,255,255,.06);
  font-size:11px;
  color:var(--vq-os-text-soft);
}
.vq-os-app-badge.is-live{
  background:var(--vq-os-accent-soft);
  border-color:rgba(118,166,255,.2);
  color:#dce9ff;
}
.vq-os-dock{
  position:sticky;
  bottom:calc(16px + env(safe-area-inset-bottom, 0px));
  z-index:3;
  display:flex;
  justify-content:center;
  gap:10px;
  padding:0 22px 18px;
}
.vq-os-dock-inner{
  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:10px;
  padding:10px;
  border-radius:24px;
  border:1px solid rgba(255,255,255,.08);
  background:rgba(8,12,22,.72);
  box-shadow:0 20px 40px rgba(2,6,23,.24), inset 0 1px 0 rgba(255,255,255,.06);
  backdrop-filter:blur(12px);
}
.vq-os-dock-btn{
  appearance:none;
  border:1px solid transparent;
  width:54px;
  height:54px;
  border-radius:var(--radius-lg, 16px);
  background:rgba(255,255,255,.06);
  color:var(--vq-os-text);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  cursor:pointer;
  position:relative;
  box-shadow:0 12px 22px rgba(2,6,23,.14), inset 0 1px 0 rgba(255,255,255,.08);
  transition:transform .22s ease, background .22s ease, border-color .22s ease;
}
.vq-os-dock-btn:hover{
  transform:translateY(-1px);
  background:rgba(255,255,255,.1);
  border-color:rgba(255,255,255,.1);
}
.vq-os-dock-btn:active{
  transform:translateY(1px);
}
.vq-os-dock-btn.is-active{
  background:var(--vq-os-accent-soft);
  border-color:rgba(118,166,255,.24);
}
.vq-os-dock-btn .ms{
  font-size:22px;
}
.vq-os-dock-dot{
  position:absolute;
  left:50%;
  bottom:6px;
  width:6px;
  height:6px;
  border-radius:999px;
  transform:translateX(-50%);
  background:rgba(255,255,255,.56);
}
.vq-os-window-host{
  position:relative;
  z-index:1;
  margin:0 22px 18px;
  padding:14px 16px;
  display:grid;
  gap:6px;
  border-radius:24px;
  border:1px solid var(--vq-os-panel-edge);
  background:linear-gradient(180deg, var(--legacy-surface), var(--legacy-surface-soft));
  box-shadow:var(--vq-os-shadow-soft);
}
.vq-os-window-host.hidden{
  display:none;
}
.vq-os-window-kicker{
  font-size:11px;
  letter-spacing:.12em;
  text-transform:uppercase;
  color:var(--vq-os-text-soft);
}
.vq-os-window-title{
  font-size:16px;
  font-weight:760;
}
.vq-os-window-copy{
  font-size:12px;
  line-height:1.64;
  color:var(--vq-os-text-soft);
}
#vqOsHomeSurface,
#vqOsWindowHost{
  display:none !important;
}
.vq-os-shell{
  border:none;
  background:none;
  box-shadow:none;
  overflow:visible;
}
.vq-os-shell::after{
  display:none;
}
.vq-os-boot{
  position:absolute;
  inset:0;
  z-index:4;
  display:grid;
  place-items:center;
  background:radial-gradient(circle at center, rgba(32,44,73,.84), rgba(6,10,18,.94));
  transition:opacity .42s ease;
}
.vq-os-boot.hidden{
  opacity:0;
  pointer-events:none;
}
.vq-os-boot-inner{
  display:grid;
  gap:10px;
  text-align:center;
  padding:28px;
}
