}
.app-qredit-card-visual{
  --app-qredit-card-tilt-x:-5deg;
  --app-qredit-card-tilt-y:9deg;
  --app-qredit-card-glow-x:22%;
  --app-qredit-card-glow-y:18%;
  position:relative;
  width:min(100%, 520px);
  margin:0 auto;
  transform-style:preserve-3d;
}
.app-qredit-card-visual.is-idle .app-qredit-card-surface{
  transition:transform .6s cubic-bezier(.22,1,.36,1), box-shadow .24s ease;
}
.app-qredit-card-float{
  position:relative;
  transform-style:preserve-3d;
  animation:appQreditCardFloat 9.6s cubic-bezier(.37,0,.22,1) infinite;
}
.app-qredit-card-surface{
  position:relative;
  aspect-ratio:1.58;
  border-radius:29px;
  border:1px solid rgba(202, 210, 221, .92);
  padding:24px 24px 22px;
  background:
    radial-gradient(circle at var(--app-qredit-card-glow-x) var(--app-qredit-card-glow-y), rgba(255,255,255,.98), rgba(255,255,255,.76) 34%, rgba(239,242,246,.92) 68%, rgba(233,236,240,.86) 100%),
    linear-gradient(145deg, rgba(255,255,255,.98), rgba(241,244,248,.96));
  box-shadow:
    0 30px 62px rgba(15, 23, 42, .12),
    0 12px 24px rgba(148, 163, 184, .10),
    inset 0 1px 0 rgba(255,255,255,.98),
    inset 0 -18px 42px rgba(226,232,240,.34);
  overflow:hidden;
  transform-style:preserve-3d;
  transform:rotateX(var(--app-qredit-card-tilt-x)) rotateY(var(--app-qredit-card-tilt-y));
}
.app-qredit-card-surface::before{
  content:"";
  position:absolute;
  inset:-30% -44%;
  background:linear-gradient(112deg, transparent 24%, rgba(255,255,255,.18) 40%, rgba(255,255,255,.74) 49%, rgba(255,255,255,.28) 56%, transparent 72%);
  transform:translate3d(-34%, 0, 1px) rotate(10deg);
  animation:appQreditCardSheen 8.8s cubic-bezier(.4,0,.2,1) infinite;
  mix-blend-mode:screen;
  pointer-events:none;
}
.app-qredit-card-surface::after{
  content:"";
  position:absolute;
  inset:0;
  background:
    radial-gradient(circle at 82% 18%, rgba(31,79,168,.09), transparent 34%),
    radial-gradient(circle at 18% 84%, rgba(148,163,184,.16), transparent 42%);
  pointer-events:none;
}
.app-qredit-card-shadow{
  position:absolute;
  left:10%;
  right:10%;
  bottom:-18px;
  height:26px;
  background:radial-gradient(ellipse at center, rgba(15, 23, 42, .22), rgba(15, 23, 42, 0) 72%);
  filter:blur(11px);
  opacity:.36;
  transform:translateZ(-32px);
}
