@keyframes appQreditCardFloat{
  0%, 100%{ transform:translate3d(0, 0, 0); }
  50%{ transform:translate3d(0, -12px, 0); }
}
@keyframes appQreditCardIntroIn{
  0%{
    opacity:0;
    transform:translate3d(0, 18px, 0) scale(.985);
  }
  100%{
    opacity:1;
    transform:none;
  }
}
@keyframes appQreditCardSheen{
  0%, 20%{ transform:translate3d(-36%, 0, 1px) rotate(10deg); opacity:0; }
  28%{ opacity:.76; }
  55%{ transform:translate3d(42%, 0, 1px) rotate(10deg); opacity:0; }
  100%{ transform:translate3d(42%, 0, 1px) rotate(10deg); opacity:0; }
}
@keyframes appQreditCardPopIn{
  0%{
    opacity:0;
    transform:translate3d(0, 10px, 0) scale(.92);
  }
  100%{
    opacity:1;
    transform:none;
  }
}
@keyframes appQreditCardPaymentPulse{
  0%{
    transform:scale(.985) translateY(6px);
    opacity:.72;
  }
  100%{
    transform:none;
    opacity:1;
  }
}
