.app-qredit-card-terms-scroll{
  max-height:min(42dvh, 430px);
  overflow:auto;
  padding:22px 22px 24px;
  overscroll-behavior:contain;
  -webkit-overflow-scrolling:touch;
}
.app-qredit-card-terms-copy{
  display:grid;
  gap:18px;
}
.app-qredit-card-terms-section{
  display:grid;
  gap:8px;
}
.app-qredit-card-terms-section h4{
  margin:0;
  color:#111827;
  font-size:15px;
  line-height:1.45;
  font-weight:710;
}
.app-qredit-card-terms-section p{
  margin:0;
  color:#5f6d7e;
  font-size:14px;
  line-height:1.76;
}
.app-qredit-card-stage{
  width:min(100%, 620px);
  margin:0 auto;
  padding:12px 18px 30px;
  perspective:2200px;
  perspective-origin:50% 48%;
  overflow:visible;
}
.app-qredit-card-stage--interactive{
  cursor:grab;
  user-select:none;
  touch-action:none;
}
.app-qredit-card-stage.is-dragging{
  cursor:grabbing;
}
.app-qredit-card-visual{
  --app-qredit-card-depth:6px;
  --app-qredit-card-depth-opacity:.78;
  --app-qredit-card-scale:1;
  --app-qredit-card-glow-x:50%;
  --app-qredit-card-glow-y:34%;
  --app-qredit-card-aura-opacity:.18;
  --app-qredit-card-aura-scale:1.02;
  --app-qredit-card-mist-opacity:.20;
  --app-card-shell-bg:linear-gradient(145deg, rgba(255,255,255,.98), rgba(237,242,247,.96));
  --app-card-rim:rgba(210,218,228,.94);
  --app-card-shadow-color:rgba(15,23,42,.14);
  --app-card-shadow-soft:rgba(148,163,184,.11);
  --app-card-inset-shadow:rgba(226,232,240,.36);
  --app-card-front-bg:linear-gradient(145deg, rgba(255,255,255,.99), rgba(240,244,249,.97));
  --app-card-back-bg:linear-gradient(145deg, rgba(247,249,252,.99), rgba(235,240,246,.97));
  --app-card-text:#0f172a;
  --app-card-muted:#64748b;
  --app-card-label:#7b8795;
  --app-card-panel-bg:rgba(255,255,255,.56);
  --app-card-panel-border:rgba(210,218,228,.78);
  --app-card-rank-bg:rgba(255,255,255,.68);
  --app-card-rank-border:rgba(204,212,223,.88);
  --app-card-rank-text:#516072;
  --app-card-mark-bg:linear-gradient(180deg, var(--legacy-surface), var(--legacy-surface-soft));
  --app-card-mark-border:rgba(211,218,228,.96);
  --app-card-mark-color:#1f4fa8;
  --app-card-sign-bg:rgba(255,255,255,.84);
  --app-card-sign-line:rgba(180,190,202,.56);
  --app-card-sign-text:#182437;
  --app-card-micro:rgba(86,100,118,.84);
  --app-card-aura:rgba(117,151,205,.34);
  --app-card-aura-soft:rgba(255,255,255,.34);
  --app-card-mist:rgba(255,255,255,.30);
  position:relative;
  width:min(100%, 560px);
  margin:0 auto;
  transform-style:preserve-3d;
  will-change:transform;
}
.app-qredit-card-visual::before,
.app-qredit-card-visual::after{
  content:"";
  position:absolute;
  inset:-10% -14%;
  pointer-events:none;
  z-index:0;
  transition:opacity .22s ease, transform .22s ease;
}
.app-qredit-card-visual::before{
  background:
    radial-gradient(circle at var(--app-qredit-card-glow-x) var(--app-qredit-card-glow-y), var(--app-card-aura), transparent 58%),
    radial-gradient(circle at 28% 22%, var(--app-card-aura-soft), transparent 42%);
  filter:blur(34px);
  opacity:var(--app-qredit-card-aura-opacity);
  transform:scale(var(--app-qredit-card-aura-scale));
}
.app-qredit-card-visual::after{
  inset:4% -8% -4%;
  background:
    radial-gradient(circle at var(--app-qredit-card-glow-x) calc(var(--app-qredit-card-glow-y) + 8%), var(--app-card-mist), transparent 60%),
    radial-gradient(circle at 70% 20%, rgba(255,255,255,.18), transparent 34%);
  filter:blur(42px);
  opacity:var(--app-qredit-card-mist-opacity);
}
.app-qredit-card-visual--interactive .app-qredit-card-float{
  animation:none;
}
.app-qredit-card-visual--interactive .app-qredit-card-surface{
  transition:transform .12s linear, box-shadow .24s ease;
}
.app-qredit-card-surface{
  position:relative;
  width:100%;
  aspect-ratio:1.58;
  padding:0;
  border-radius:34px;
  border:none;
  background:transparent;
  overflow:visible;
  transform-style:preserve-3d;
  box-shadow:none;
  transform:none;
}
.app-qredit-card-surface::before,
.app-qredit-card-surface::after{
  display:none;
}
.app-qredit-card-render-shell{
  position:relative;
  width:100%;
  aspect-ratio:1.58;
  border-radius:34px;
  z-index:1;
}
.app-qredit-card-renderer{
  position:relative;
  width:100%;
  height:100%;
  border-radius:inherit;
  overflow:hidden;
  background:transparent;
}
.app-qredit-card-renderer canvas{
  display:block;
  width:100% !important;
  height:100% !important;
  border-radius:inherit;
}
.app-qredit-card-render-status{
  position:absolute;
  inset:0;
  display:flex;
  align-items:center;
  justify-content:center;
  padding:18px;
  border-radius:inherit;
  color:#64748b;
  font-size:13px;
  line-height:1.6;
  text-align:center;
  background:linear-gradient(180deg, var(--legacy-surface), var(--legacy-surface-soft));
  border:1px solid rgba(226,232,240,.72);
  backdrop-filter:saturate(1.04) blur(14px);
  z-index:2;
}
.app-qredit-card-visual.is-ready .app-qredit-card-render-status{
  display:none;
}
.app-qredit-card-shadow{
  position:absolute;
  left:14%;
  right:14%;
  bottom:-8%;
  height:18%;
  pointer-events:none;
  z-index:0;
  background:radial-gradient(circle at 50% 50%, rgba(15,23,42,.22), rgba(15,23,42,.10) 42%, transparent 74%);
  filter:blur(28px);
  opacity:.74;
  transform:translateZ(0);
}
.app-qredit-card-core{
  position:absolute;
  inset:0;
  border-radius:inherit;
  transform-style:preserve-3d;
  transform-origin:center center;
  will-change:transform;
  transform:scale(var(--app-qredit-card-scale)) rotateX(var(--app-qredit-card-tilt-x)) rotateY(var(--app-qredit-card-tilt-y));
  filter:drop-shadow(0 18px 34px rgba(15,23,42,.12)) drop-shadow(0 6px 14px rgba(15,23,42,.08));
}
.app-qredit-card-core::before{
  content:"";
  position:absolute;
  inset:0;
  border-radius:inherit;
  pointer-events:none;
  background:transparent;
  border:1px solid var(--app-card-rim);
  box-shadow:
    inset 0 calc(var(--app-qredit-card-depth) * .38) calc(var(--app-qredit-card-depth) * .6) rgba(255,255,255,.12),
    inset 0 calc(var(--app-qredit-card-depth) * -.52) calc(var(--app-qredit-card-depth) * .72) rgba(15,23,42,.09),
    inset calc(var(--app-qredit-card-depth) * .34) 0 calc(var(--app-qredit-card-depth) * .5) rgba(255,255,255,.06),
    inset calc(var(--app-qredit-card-depth) * -.34) 0 calc(var(--app-qredit-card-depth) * .56) rgba(15,23,42,.08);
  opacity:var(--app-qredit-card-depth-opacity);
  transform:translateZ(0);
}
.app-qredit-card-face{
  position:absolute;
  inset:0;
  display:grid;
  grid-template-rows:auto 1fr auto;
  gap:22px;
  border-radius:inherit;
  overflow:hidden;
  backface-visibility:hidden;
  -webkit-backface-visibility:hidden;
  transform-style:preserve-3d;
  border:1px solid var(--app-card-rim);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.14), inset 0 0 0 1px rgba(255,255,255,.04);
  background:var(--app-card-front-bg);
}
.app-qredit-card-face--front{
  color:var(--app-card-text);
  transform:translateZ(calc(var(--app-qredit-card-depth) / 2));
}
.app-qredit-card-face--back{
  background:var(--app-card-back-bg);
  color:var(--app-card-text);
  transform:rotateY(180deg) translateZ(calc(var(--app-qredit-card-depth) / 2));
}
.app-qredit-card-face-inner{
  position:relative;
  z-index:1;
  height:100%;
  padding:24px 24px 22px;
  transform:translateZ(1.5px);
}
.app-qredit-card-face-inner--front{
  display:grid;
  grid-template-rows:auto 1fr auto;
  gap:20px;
}
.app-qredit-card-face-inner--back{
  display:grid;
  grid-template-rows:auto 1fr auto;
  gap:14px;
  align-content:space-between;
  transform:none;
}
.app-qredit-card-face--front::before,
.app-qredit-card-face--back::before{
  content:"";
  position:absolute;
  inset:0;
  background:
    radial-gradient(circle at 16% 18%, rgba(255,255,255,.24), transparent 26%),
    radial-gradient(circle at 86% 18%, rgba(255,255,255,.14), transparent 28%),
    linear-gradient(145deg, rgba(255,255,255,.06), transparent 42%);
  pointer-events:none;
}
.app-qredit-card-face--back::before{
  background:
    linear-gradient(180deg, rgba(255,255,255,.12), rgba(255,255,255,.04) 18%, transparent 44%, rgba(15,23,42,.05) 100%),
    radial-gradient(circle at 18% 18%, rgba(255,255,255,.12), transparent 30%),
    linear-gradient(145deg, rgba(255,255,255,.04), transparent 52%);
}
.app-qredit-card-front-main{
  align-self:end;
  display:grid;
  gap:14px;
}
.app-qredit-card-front-footer{
  display:grid;
  grid-template-columns:minmax(0, 1fr) auto;
  gap:14px;
  align-items:end;
}
.app-qredit-card-front-panel{
  border:1px solid var(--app-card-panel-border);
  background:var(--app-card-panel-bg);
  backdrop-filter:saturate(1.05) blur(8px);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.12);
}
.app-qredit-card-helper-chips{
  width:min(100%, 640px);
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  justify-content:center;
}
.app-qredit-card-stage-helper{
  margin-top:14px;
  text-align:center;
  color:#6b798a;
  font-size:12px;
  line-height:1.55;
}
.app-qredit-card-view-switch{
  width:min(100%, 420px);
  display:flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  flex-wrap:wrap;
}
.app-qredit-card-view-chip{
  appearance:none;
  min-height:34px;
  padding:0 14px;
  border-radius:999px;
  border:1px solid rgba(209,216,226,.95);
  background:rgba(255,255,255,.78);
  color:#566476;
  font-size:12px;
  line-height:1;
  font-weight:650;
  transition:border-color .2s ease, background-color .2s ease, box-shadow .2s ease, transform .2s ease;
}
.app-qredit-card-view-chip:hover,
.app-qredit-card-view-chip:focus-visible{
  border-color:rgba(173,186,202,.98);
  background:rgba(255,255,255,.92);
  box-shadow:0 10px 20px rgba(15,23,42,.06);
  transform:translateY(-1px);
}
.app-qredit-card-view-chip.is-active{
  border-color:rgba(31,79,168,.24);
  background:rgba(247,250,255,.94);
  color:#1f4fa8;
  box-shadow:0 0 0 4px rgba(31,79,168,.08), 0 10px 20px rgba(15,23,42,.05);
}
.app-qredit-card-helper-chip{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-height:32px;
  padding:0 12px;
  border-radius:999px;
  border:1px solid rgba(209,216,226,.95);
  background:rgba(255,255,255,.78);
  color:#566476;
  font-size:12px;
  font-weight:620;
  line-height:1;
}
.app-qredit-card-theme-picker{
  width:min(100%, 680px);
  display:grid;
  gap:14px;
}
.app-qredit-card-theme-copy{
  display:grid;
  gap:6px;
  text-align:center;
}
.app-qredit-card-theme-copy h3{
  margin:0;
  color:#111827;
  font-size:17px;
  line-height:1.35;
  font-weight:700;
  letter-spacing:-.02em;
}
.app-qredit-card-theme-copy p{
  margin:0;
  color:#64748b;
  font-size:13px;
  line-height:1.65;
}
.app-qredit-card-theme-grid{
  display:grid;
