/* =========================================================
   melta UI Phase 1 Foundation
   tokens + safe auth/modal migration
   ========================================================= */
:root{
  /* ── melta color.primary (VQ v2 indigo palette) ── */
  --melta-primary-50:#eef2ff;
  --melta-primary-100:#e0e7ff;
  --melta-primary-200:#c7d2fe;
  --melta-primary-300:#a5b4fc;
  --melta-primary-400:#818cf8;
  --melta-primary-500:#6366f1;
  --melta-primary-600:#4f46e5;
  --melta-primary-700:#4338ca;
  --melta-primary-800:#3730a3;
  --melta-primary-900:#312e81;
  --melta-primary-950:#1e1b4b;

  /* ── melta color.semantic (light) ── */
  --melta-bg-page:#f9fafb;
  --melta-bg-page-alt:#f3f4f6;
  --melta-bg-surface:#ffffff;
  --melta-bg-surface-alt:#f9fafb;
  --melta-text-heading:#0f172a;
  --melta-text-default:#3d4b5f;
  --melta-text-body:#3d4b5f;
  --melta-text-muted:#64748b;
  --melta-border-default:#e2e8f0;
  --melta-border-strong:#cbd5e1;
  --melta-input-bg:#ffffff;
  --melta-input-border:#cbd5e1;

  /* ── melta color.status ── */
  --melta-success:#059669;
  --melta-success-subtle:#ecfdf5;
  --melta-success-text:#047857;
  --melta-warning:#d97706;
  --melta-warning-subtle:#fffbeb;
  --melta-warning-text:#b45309;
  --melta-danger:#ef4444;
  --melta-danger-subtle:#fef2f2;
  --melta-danger-text:#dc2626;

  /* ── melta radius (4 steps) ── */
  --melta-radius-sm:4px;
  --melta-radius-md:8px;
  --melta-radius-lg:12px;
  --melta-radius-full:9999px;

  /* ── melta spacing (4px grid) ── */
  --melta-space-1:4px;
  --melta-space-2:8px;
  --melta-space-3:12px;
  --melta-space-4:16px;
  --melta-space-5:20px;
  --melta-space-6:24px;
  --melta-space-8:32px;
  --melta-space-10:40px;
  --melta-space-12:48px;
  --melta-space-14:56px;
  --melta-space-16:64px;

  /* ── melta elevation (4 steps) ── */
  --melta-shadow-none:none;
  --melta-shadow-sm:0 1px 2px rgba(0,0,0,.05);
  --melta-shadow-md:0 4px 6px rgba(0,0,0,.1);
  --melta-shadow-overlay:0 20px 25px rgba(0,0,0,.10);

  /* ── melta motion ── */
  --melta-duration-fast:150ms;
  --melta-duration-normal:200ms;
  --melta-duration-slow:300ms;
  --melta-ease-default:cubic-bezier(0.4, 0, 0.2, 1);
  --melta-ease-in:cubic-bezier(0.4, 0, 1, 1);
  --melta-ease-out:cubic-bezier(0, 0, 0.2, 1);

  /* ── melta z-index (5 steps) ── */
  --melta-z-base:0;
  --melta-z-dropdown:20;
  --melta-z-sticky:30;
  --melta-z-overlay:40;
  --melta-z-modal:50;

  /* ── melta focus ring ── */
  --melta-ring:0 0 0 2px rgba(99,102,241,.18);
}
:root[data-theme-mode="dark"]{
  /* ── melta color.semantic (dark) ── */
  --melta-bg-page:#0f172a;
  --melta-bg-page-alt:#1e293b;
  --melta-bg-surface:#1e293b;
  --melta-bg-surface-alt:#0f172a;
  --melta-text-heading:#f1f5f9;
  --melta-text-default:#cbd5e1;
  --melta-text-body:#cbd5e1;
  --melta-text-muted:#94a3b8;
  --melta-border-default:#334155;
  --melta-border-strong:#475569;
  --melta-input-bg:#0f172a;
  --melta-input-border:#475569;

  /* ── melta color.status (dark) ── */
  --melta-success-subtle:rgba(5,150,105,0.12);
  --melta-success-text:#6ee7b7;
  --melta-warning-subtle:rgba(217,119,6,0.12);
  --melta-warning-text:#fcd34d;
  --melta-danger-subtle:rgba(239,68,68,0.12);
  --melta-danger-text:#fca5a5;

  /* ── melta elevation (dark - stronger opacity) ── */
  --melta-shadow-sm:0 1px 2px rgba(0,0,0,.24);
  --melta-shadow-md:0 4px 6px rgba(0,0,0,.32);
  --melta-shadow-overlay:0 20px 25px rgba(0,0,0,.36);
}
.melta-card{
  background:var(--melta-bg-surface);
  color:var(--melta-text-default);
  border:1px solid var(--melta-border-default);
  border-radius:var(--melta-radius-lg);
  box-shadow:var(--melta-shadow-sm);
  padding:var(--melta-space-6);
}
.melta-card-compact{padding:var(--melta-space-4);}
.melta-card-flush{padding:0;}

/* ── melta-card header / body / footer ── */
.melta-card-header{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:var(--melta-space-3);
}
.melta-card-header+.melta-card-body{margin-top:var(--melta-space-3);}
.melta-card-title{
  font-size:1rem;
  font-weight:600;
  color:var(--melta-text-heading);
  line-height:1.4;
}
.melta-card-title-lg{font-size:1.125rem;}
.melta-card-desc{
  margin-top:var(--melta-space-1);
  font-size:.875rem;
  color:var(--melta-text-muted);
  line-height:1.5;
}
.melta-card-footer{
  display:flex;
  justify-content:flex-end;
  align-items:center;
  gap:12px;
  padding:12px var(--melta-space-6);
  border-top:1px solid var(--melta-border-default);
  margin:0 calc(var(--melta-space-6) * -1);
  margin-bottom:calc(var(--melta-space-6) * -1);
  border-radius:0 0 var(--melta-radius-lg) var(--melta-radius-lg);
}
.melta-card-compact .melta-card-footer{
  padding:10px var(--melta-space-4);
  margin:0 calc(var(--melta-space-4) * -1);
  margin-bottom:calc(var(--melta-space-4) * -1);
}

/* ── melta-card interactive (link card) ── */
.melta-card-link{
  display:block;
  text-decoration:none;
  color:inherit;
  transition:box-shadow var(--melta-duration-fast) var(--melta-ease-default);
  cursor:pointer;
}
@media(hover:hover)and(pointer:fine){
  .melta-card-link:hover{box-shadow:var(--melta-shadow-md);}
}

/* ── melta-card grid ── */
.melta-card-grid{
  display:grid;
  grid-template-columns:repeat(1,1fr);
  gap:var(--melta-space-6);
}
@media(min-width:640px){.melta-card-grid{grid-template-columns:repeat(2,1fr);}}
