.melta-input{
  width:100%;
  min-height:52px;
  border:1px solid var(--melta-input-border);
  border-radius:var(--melta-radius-md);
  background:var(--melta-input-bg);
  color:var(--melta-text-heading);
  padding:0 14px;
  box-shadow:none;
  transition:
    border-color var(--melta-duration-fast) var(--melta-ease-default),
    box-shadow var(--melta-duration-fast) var(--melta-ease-default),
    background-color var(--melta-duration-fast) var(--melta-ease-default);
}
.melta-input::placeholder{
  color:var(--melta-text-muted);
}
.melta-input:focus{
  outline:none;
  border-color:var(--melta-primary-500);
  box-shadow:var(--melta-ring);
}
@media(hover:hover)and(pointer:fine){
  .melta-input:hover:not(:focus):not([disabled]):not(.is-error){
    border-color:var(--melta-border-strong);
  }
}

/* ── melta-input sizes ── */
.melta-input-s{
  min-height:32px;
  padding:0 12px;
  font-size:.875rem;
}
.melta-input-l{
  min-height:56px;
  padding:0 16px;
  font-size:1.125rem;
}

/* ── melta-input states ── */
.melta-input.is-error{
  border-color:var(--melta-danger);
  box-shadow:none;
}
.melta-input.is-error:focus{
  border-color:var(--melta-danger);
  box-shadow:0 0 0 2px rgba(239,68,68,.18);
}
.melta-input[disabled],.melta-input.is-disabled{
  background:var(--melta-bg-page);
  border-color:var(--melta-border-default);
  color:var(--melta-text-muted);
  cursor:not-allowed;
}
.melta-input[readonly]{
  background:var(--melta-bg-page);
  border-color:var(--melta-border-default);
  color:var(--melta-text-default);
}
.melta-input::-webkit-search-cancel-button{-webkit-appearance:none;}
.melta-input{caret-color:var(--melta-primary-500);}

/* ── melta-select (native + custom chevron) ── */
.melta-select-wrap{
  position:relative;
  display:inline-block;
  width:100%;
}
.melta-select{
  width:100%;
  min-height:52px;
  appearance:none;
  -webkit-appearance:none;
  border:1px solid var(--melta-input-border);
  border-radius:var(--melta-radius-md);
  background-color:var(--melta-input-bg);
  color:var(--melta-text-heading);
  padding:0 40px 0 14px;
  font-size:1rem;
  box-shadow:none;
  cursor:pointer;
  transition:
    border-color var(--melta-duration-fast) var(--melta-ease-default),
    box-shadow var(--melta-duration-fast) var(--melta-ease-default);
}
.melta-select:focus{
  outline:none;
  border-color:var(--melta-primary-500);
  box-shadow:var(--melta-ring);
}
@media(hover:hover)and(pointer:fine){
  .melta-select:hover:not(:focus):not([disabled]):not(.is-error){
    border-color:var(--melta-border-strong);
  }
}
.melta-select.is-error{border-color:var(--melta-danger);}
.melta-select.is-error:focus{
  border-color:var(--melta-danger);
  box-shadow:0 0 0 2px rgba(239,68,68,.18);
}
.melta-select[disabled]{
  background-color:var(--melta-bg-page);
  border-color:var(--melta-border-default);
  color:var(--melta-text-muted);
  cursor:not-allowed;
}
.melta-select-wrap .melta-select-chevron{
  position:absolute;
  right:12px;
  top:50%;
  transform:translateY(-50%);
  width:16px;height:16px;
  color:var(--melta-text-muted);
  pointer-events:none;
}
.melta-select[disabled]~.melta-select-chevron{
  color:var(--melta-border-default);
}
.melta-select-s{min-height:32px;padding:0 36px 0 12px;font-size:.875rem;}
.melta-select-l{min-height:56px;padding:0 44px 0 16px;font-size:1.125rem;}

/* ── melta-label ── */
.melta-label{
  display:block;
  font-size:.875rem;
  font-weight:500;
  color:var(--melta-text-default);
  margin-bottom:4px;
  line-height:1.4;
}
.melta-label-required::after{
  content:" *";
  color:var(--melta-danger);
}

/* ── melta-field-error ── */
.melta-field-error{
  display:flex;
  align-items:center;
  gap:4px;
  margin-top:4px;
  font-size:.75rem;
  line-height:1.4;
  color:var(--melta-danger-text);
}
.melta-field-error svg{
  width:14px;height:14px;
  flex-shrink:0;
  fill:none;
  stroke:currentColor;
  stroke-width:2;
}

/* ── melta form layout ── */
.melta-form-stack{
  display:flex;
  flex-direction:column;
  gap:20px;
}
.melta-form-stack-tight{gap:16px;}
.melta-form-group{
  display:flex;
  flex-direction:column;
  gap:32px;
}
.melta-form-actions{
  display:flex;
  justify-content:flex-end;
  gap:12px;
  padding-top:16px;
}
.melta-form-actions-border{
  border-top:1px solid var(--melta-border-default);
  margin-top:8px;
}
.melta-form-inline{
  display:flex;
  flex-wrap:wrap;
  align-items:flex-end;
  gap:16px;
}
.melta-form-inline .melta-label{line-height:normal;}
.melta-form-inline .melta-input,
.melta-form-inline .melta-select{
  height:44px;
  min-height:44px;
  line-height:normal;
}

.melta-btn{
  min-height:40px;
  border:1px solid transparent;
  border-radius:var(--melta-radius-md);
  padding:0 16px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  font-size:1rem;
  font-weight:500;
