    color var(--melta-duration-fast) var(--melta-ease-default),
    box-shadow var(--melta-duration-fast) var(--melta-ease-default);
}
.melta-btn:focus-visible{
  outline:none;
  box-shadow:var(--melta-ring);
}
.melta-btn[disabled],.melta-btn.is-disabled{
  opacity:.5;
