  pointer-events:none;
}

/* ── melta-btn sizes ── */
.melta-btn-s{
  min-height:32px;
  padding:0 12px;
  font-size:.875rem;
  gap:6px;
}
.melta-btn-l{
  min-height:48px;
  padding:0 24px;
  font-size:1rem;
  gap:8px;
}

/* ── melta-btn variants ── */
.melta-btn-primary{
  background:var(--melta-primary-500);
  color:#fff;
  border-color:transparent;
}
@media(hover:hover)and(pointer:fine){
  .melta-btn-primary:hover:not([disabled]){background:var(--melta-primary-700);}
}
.melta-btn-primary:active:not([disabled]){background:var(--melta-primary-800);}
.melta-btn-primary:focus-visible{box-shadow:0 0 0 2px rgba(99,102,241,.18);}

.melta-btn-secondary{
  background:var(--melta-bg-surface);
  color:var(--melta-primary-500);
  border-color:var(--melta-primary-500);
}
@media(hover:hover)and(pointer:fine){
  .melta-btn-secondary:hover:not([disabled]){
    background:var(--melta-primary-50);
    color:var(--melta-primary-600);
    border-color:var(--melta-primary-600);
  }
}
.melta-btn-secondary:active:not([disabled]){background:var(--melta-primary-100);}

.melta-btn-neutral{
  background:var(--melta-bg-surface);
  color:var(--melta-text-default);
  border-color:var(--melta-border-default);
}
@media(hover:hover)and(pointer:fine){
  .melta-btn-neutral:hover:not([disabled]){background:var(--melta-bg-page);}
}
.melta-btn-neutral:active:not([disabled]){background:var(--melta-bg-page-alt);}

.melta-btn-danger{
  background:var(--melta-danger);
  color:#fff;
  border-color:transparent;
}
@media(hover:hover)and(pointer:fine){
  .melta-btn-danger:hover:not([disabled]){background:#dc2626;}
}
.melta-btn-danger:active:not([disabled]){background:#b91c1c;}
.melta-btn-danger:focus-visible{box-shadow:0 0 0 2px rgba(239,68,68,.18);}

.melta-btn-subtle{
  background:transparent;
  color:var(--melta-text-default);
  border-color:transparent;
}
@media(hover:hover)and(pointer:fine){
  .melta-btn-subtle:hover:not([disabled]){background:var(--melta-bg-page-alt);}
}
.melta-btn-subtle:active:not([disabled]){background:var(--melta-border-default);}

/* ── melta icon+text button (asymmetric padding) ── */
.melta-btn-icon-text{padding-left:12px;padding-right:16px;}
.melta-btn-icon-text.melta-btn-l{padding-left:20px;padding-right:24px;}
.melta-btn-icon-text.melta-btn-s{padding-left:10px;padding-right:12px;}

/* ── melta icon button (square) ── */
.melta-icon-btn{
  width:40px;height:40px;min-height:40px;
  padding:0;
  display:inline-flex;align-items:center;justify-content:center;
  border:1px solid transparent;
  border-radius:var(--melta-radius-md);
  background:transparent;
  color:var(--melta-text-default);
  cursor:pointer;
  transition:
    background-color var(--melta-duration-fast) var(--melta-ease-default),
    color var(--melta-duration-fast) var(--melta-ease-default);
}
.melta-icon-btn:focus-visible{
  outline:none;
  box-shadow:var(--melta-ring);
}
.melta-icon-btn[disabled]{opacity:.5;cursor:not-allowed;pointer-events:none;}
@media(hover:hover)and(pointer:fine){
  .melta-icon-btn:hover:not([disabled]){background:var(--melta-bg-page-alt);}
}
.melta-icon-btn-s{width:32px;height:32px;min-height:32px;}
.melta-icon-btn-l{width:48px;height:48px;min-height:48px;}
.melta-icon-btn svg{flex-shrink:0;}
.melta-icon-btn-s svg{width:16px;height:16px;}
.melta-icon-btn svg,
.melta-icon-btn-l svg{width:20px;height:20px;}

