  justify-content:flex-end;
  align-items:center;
  gap:12px;
  padding-top:var(--melta-space-4);
  border-top:1px solid var(--melta-border-default);
}

/* =========================================================
   melta Toast (Phase 3-4)
   4 variants · icon · auto-dismiss support · aria
   ========================================================= */
.melta-toast-region{
  position:fixed;
  top:16px;
  right:16px;
  z-index:4200;
  display:flex;
  flex-direction:column;
  gap:12px;
  pointer-events:none;
  max-width:400px;
  width:calc(100% - 32px);
}
.melta-toast{
  display:flex;
  align-items:flex-start;
  gap:12px;
  padding:var(--melta-space-4);
  border-radius:var(--melta-radius-md);
  border:1px solid;
  box-shadow:var(--melta-shadow-sm);
  pointer-events:auto;
  opacity:0;
  transform:translateX(24px);
  transition:
    opacity var(--melta-duration-normal) var(--melta-ease-out),
    transform var(--melta-duration-normal) var(--melta-ease-out);
}
.melta-toast.show{
  opacity:1;
  transform:translateX(0);
}
.melta-toast.hide{
  opacity:0;
  transform:translateX(24px);
  transition-timing-function:var(--melta-ease-in);
}

/* ── toast variants ── */
