/* ── toast inner elements ── */
.melta-toast-icon{
  width:24px;height:24px;
  flex-shrink:0;
}
.melta-toast-icon svg{width:24px;height:24px;}
.melta-toast-content{flex:1;min-width:0;}
.melta-toast-msg{
  font-size:.875rem;
  font-weight:500;
  line-height:1.5;
}
