}
.melta-toast-close{
  width:28px;height:28px;
  flex-shrink:0;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  border:none;
  background:transparent;
  color:currentColor;
  opacity:.5;
  cursor:pointer;
  border-radius:var(--melta-radius-sm);
  transition:opacity var(--melta-duration-fast) var(--melta-ease-default),
    background-color var(--melta-duration-fast) var(--melta-ease-default);
  margin:-4px -4px -4px 0;
}
.melta-toast-close:hover{opacity:.8;background:rgba(0,0,0,.06);}
.melta-toast-close svg{width:16px;height:16px;}

@media(prefers-reduced-motion:reduce){
  .melta-toast,.melta-toast.show,.melta-toast.hide{
    transition:none;
    transform:none;
  }
}

/* =========================================================
   melta Table (Phase 3-6)
   wrapper · header · rows · cells · responsive
   ========================================================= */
.melta-table-wrap{
