.melta-nav-group-label{
  padding:8px 16px 4px;
  font-size:.6875rem;
  font-weight:500;
  color:var(--melta-text-muted);
  text-transform:uppercase;
  letter-spacing:.05em;
}

/* ── full melta sidebar (for new sidebars / future migration) ── */
.melta-sidebar{
  width:256px;
  flex-shrink:0;
  display:flex;
  flex-direction:column;
  height:100%;
  background:var(--melta-bg-surface);
  border-right:1px solid var(--melta-border-default);
}
.melta-sidebar-header{
  padding:var(--melta-space-4) var(--melta-space-4) var(--melta-space-3);
  border-bottom:1px solid var(--melta-border-default);
}
.melta-sidebar-nav{
  flex:1;
  overflow-y:auto;
  padding:var(--melta-space-2) var(--melta-space-2);
  display:flex;
  flex-direction:column;
  gap:2px;
}
.melta-sidebar-footer{
  margin-top:auto;
  padding:var(--melta-space-3) var(--melta-space-4);
  border-top:1px solid var(--melta-border-default);
}

/* ── sidebar divider ── */
.melta-sidebar-divider{
  height:1px;
  background:var(--melta-border-default);
  margin:var(--melta-space-2) var(--melta-space-2);
}

/* ── mobile drawer ── */
.melta-sidebar-drawer{
  position:fixed;
  inset:0;
  z-index:4100;
  pointer-events:none;
}
.melta-sidebar-drawer.is-open{pointer-events:auto;}
.melta-sidebar-drawer .melta-sidebar-overlay{
  position:absolute;
  inset:0;
  background:rgba(0,0,0,.5);
  opacity:0;
  transition:opacity var(--melta-duration-normal) var(--melta-ease-out);
}
.melta-sidebar-drawer.is-open .melta-sidebar-overlay{opacity:1;}
.melta-sidebar-drawer .melta-sidebar{
  position:absolute;
  top:0;left:0;bottom:0;
  transform:translateX(-100%);
  transition:transform var(--melta-duration-slow) var(--melta-ease-out);
  box-shadow:var(--melta-shadow-overlay);
}
.melta-sidebar-drawer.is-open .melta-sidebar{transform:translateX(0);}
@media(prefers-reduced-motion:reduce){
  .melta-sidebar-drawer .melta-sidebar-overlay,
  .melta-sidebar-drawer .melta-sidebar{transition:none;}
}

/* =========================================================
   melta Tabs (Phase 3-8)
   underline · bar · states · aria-ready
   ========================================================= */

/* ── tab list container ── */
.melta-tablist{
  display:flex;
  border-bottom:1px solid var(--melta-border-default);
