/* ── Quiz container ── */
#viewQuiz{
  background:#fff !important;
  min-height:100vh;
  min-height:100dvh;
  padding:0 !important;
}
#viewQuiz.active{
  display:flex !important;
  flex-direction:column !important;
}

/* ── Top progress strip (fixed) ── */
#viewQuiz::before{
  content:"";
  position:fixed;
  top:0; left:0;
  height:4px;
  background:linear-gradient(90deg, #6492ff, #6366f1);
  width:var(--quiz-progress, 0%);
  transition:width .6s cubic-bezier(.16,1,.3,1);
  z-index:60;
  border-radius:0 3px 3px 0;
}

/* ── Header bar ── */
#viewQuiz .quiz-header{
  position:sticky !important;
  top:0 !important;
  z-index:40 !important;
  background:rgba(255,255,255,.88) !important;
  backdrop-filter:blur(16px) saturate(160%) !important;
  -webkit-backdrop-filter:blur(16px) saturate(160%) !important;
  border-bottom:1px solid rgba(226,232,240,.6) !important;
  max-width:none !important;
  margin:0 !important;
  padding:12px 20px !important;
  display:flex !important;
  align-items:center !important;
  gap:12px !important;
}
#viewQuiz .progress{
  border:none !important;
  background:transparent !important;
  backdrop-filter:none !important;
  -webkit-backdrop-filter:none !important;
  box-shadow:none !important;
  padding:0 !important;
  font-size:14px !important;
  font-weight:700 !important;
  color:#0f172a !important;
  letter-spacing:-.01em !important;
}
#viewQuiz #modePill{
  margin-left:auto !important;
  border:none !important;
  background:#f1f5f9 !important;
  backdrop-filter:none !important;
  -webkit-backdrop-filter:none !important;
  box-shadow:none !important;
  color:#64748b !important;
  font-size:11px !important;
  font-weight:600 !important;
  letter-spacing:.05em !important;
  text-transform:uppercase !important;
  padding:5px 12px !important;
  border-radius:999px !important;
}
#viewQuiz #timerPill{
  border:none !important;
  background:transparent !important;
  backdrop-filter:none !important;
  -webkit-backdrop-filter:none !important;
  box-shadow:none !important;
  color:#0f172a !important;
  font-size:clamp(20px, 3.8vw, 32px) !important;
  font-weight:800 !important;
  font-variant-numeric:tabular-nums !important;
  padding:0 4px !important;
}

/* ── Card area ── */
#viewQuiz .card{
  max-width:640px !important;
  width:100% !important;
  margin:0 auto !important;
  padding:44px 36px 36px !important;
  border:none !important;
  border-radius:0 !important;
  background:transparent !important;
  box-shadow:none !important;
  flex:1 1 auto !important;
  display:flex !important;
  flex-direction:column !important;
  justify-content:center !important;
  min-height:0 !important;
  overflow:visible !important;
  position:relative !important;
  z-index:1 !important;
  animation:qzFadeUp .32s cubic-bezier(.16,1,.3,1) both !important;
}
#viewQuiz .card.fade-out{
  opacity:0 !important;
  transform:translateY(-6px) !important;
  transition:opacity .15s ease, transform .15s ease !important;
  animation:none !important;
}
@keyframes qzFadeUp{
  0%{ opacity:0; transform:translateY(16px); }
  100%{ opacity:1; transform:translateY(0); }
}

/* ── Meta line ── */
#viewQuiz .meta{
  display:flex !important;
  align-items:center !important;
  justify-content:space-between !important;
  margin-bottom:12px !important;
}
