  text-align:center !important;
}

/* ── Choice section ── */
#viewQuiz .choice-wrap{
  border-top:none !important;
  margin-top:28px !important;
  padding-top:0 !important;
}
#viewQuiz .choice-label{
  display:none !important;
}
#viewQuiz .choices{
  display:flex !important;
  flex-direction:column !important;
  gap:10px !important;
}
#viewQuiz .choice-btn{
  display:flex !important;
  align-items:center !important;
  gap:14px !important;
  width:100% !important;
  border:2px solid #e2e8f0 !important;
  border-radius:16px !important;
  background:#fff !important;
  box-shadow:none !important;
  padding:16px 18px !important;
  cursor:pointer !important;
  transition:border-color .18s ease, background .18s ease, transform .12s ease !important;
  animation:qzChoiceIn .3s cubic-bezier(.16,1,.3,1) both !important;
}
#viewQuiz .choice-btn:nth-child(1){ animation-delay:0s !important; }
#viewQuiz .choice-btn:nth-child(2){ animation-delay:.05s !important; }
#viewQuiz .choice-btn:nth-child(3){ animation-delay:.10s !important; }
#viewQuiz .choice-btn:nth-child(4){ animation-delay:.15s !important; }
#viewQuiz .choice-btn:nth-child(5){ animation-delay:.20s !important; }
#viewQuiz .choice-btn:nth-child(6){ animation-delay:.25s !important; }
#viewQuiz .choice-btn:nth-child(7){ animation-delay:.30s !important; }
#viewQuiz .choice-btn:nth-child(8){ animation-delay:.35s !important; }
#viewQuiz .choice-btn:nth-child(9){ animation-delay:.40s !important; }
#viewQuiz .choice-btn:nth-child(10){ animation-delay:.45s !important; }
#viewQuiz .choice-btn:nth-child(11){ animation-delay:.50s !important; }
#viewQuiz .choice-btn:nth-child(12){ animation-delay:.55s !important; }
#viewQuiz .choice-btn:nth-child(13){ animation-delay:.60s !important; }
#viewQuiz .choice-btn:nth-child(14){ animation-delay:.65s !important; }
#viewQuiz .choice-btn:nth-child(15){ animation-delay:.70s !important; }
@keyframes qzChoiceIn{
  0%{ opacity:0; transform:translateY(10px) scale(.97); }
  100%{ opacity:1; transform:translateY(0) scale(1); }
}
#viewQuiz .choice-btn:hover{
  border-color:#95b6ff !important;
  background:#f8faff !important;
  transform:translateY(-1px) !important;
}
#viewQuiz .choice-btn:active{
  transform:scale(.985) !important;
}
#viewQuiz .choice-btn .k{
  width:36px !important;
  height:36px !important;
  min-width:36px !important;
  border-radius:12px !important;
  background:#f1f5f9 !important;
  color:#64748b !important;
  font-size:14px !important;
  font-weight:800 !important;
  display:inline-flex !important;
  align-items:center !important;
  justify-content:center !important;
  transition:background .18s, color .18s !important;
}
#viewQuiz .choice-btn .choice-text{
  font-size:16px !important;
  font-weight:700 !important;
  color:#0f172a !important;
  line-height:1.4 !important;
}
#viewQuiz .choice-btn .choice-state{
  margin-left:auto !important;
}

/* Correct choice */
#viewQuiz .choice-btn.correct{
  border-color:#10b981 !important;
  background:rgba(16,185,129,.06) !important;
  animation:qzCorrectBounce .45s cubic-bezier(.34,1.56,.64,1) both !important;
}
#viewQuiz .choice-btn.correct .k{
  background:#10b981 !important;
  color:#fff !important;
}
#viewQuiz .choice-btn.correct .choice-text{
  color:#065f46 !important;
  font-weight:600 !important;
}
@keyframes qzCorrectBounce{
  0%{ transform:scale(1); }
  50%{ transform:scale(1.025); }
  100%{ transform:scale(1); }
}

/* Wrong choice */
#viewQuiz .choice-btn.wrong{
  border-color:#ef4444 !important;
  background:rgba(239,68,68,.05) !important;
  animation:qzWrongShake .35s ease both !important;
}
#viewQuiz .choice-btn.wrong .k{
  background:#ef4444 !important;
  color:#fff !important;
}
#viewQuiz .choice-btn.wrong .choice-text{
  color:#991b1b !important;
}
@keyframes qzWrongShake{
  0%,100%{ transform:translateX(0); }
  25%{ transform:translateX(-5px); }
  50%{ transform:translateX(5px); }
  75%{ transform:translateX(-3px); }
}

/* ── Answer reveal ── */
#viewQuiz .answer-wrap{
