}
#viewResult .actions .btn:hover{
  border-color:#cbd5e1 !important;
  background:#f8fafc !important;
}
#viewResult .actions .btn .label{
  font-size:14px !important;
  font-weight:700 !important;
  color:#0f172a !important;
}
#viewResult .actions .btn .desc{
  font-size:12px !important;
  color:#94a3b8 !important;
  margin-top:1px !important;
}

/* ── Answer Review ── */
.result-review-section{ margin-top:24px !important; }
.result-review-header{
  display:flex;align-items:center;justify-content:space-between;
  flex-wrap:wrap;gap:10px;margin-bottom:14px;
}
.result-review-title{
  font-size:15px !important;font-weight:800 !important;
  color:#0f172a !important;margin:0 !important;letter-spacing:-.01em !important;
}
.result-review-controls{
  display:flex;align-items:center;gap:8px;flex-wrap:wrap;
}
.result-review-filter{
  display:flex;background:#f1f5f9;border-radius:10px;padding:3px;
}
.result-review-filter-btn{
  appearance:none;border:0;background:transparent;
  padding:6px 14px;font-size:12px;font-weight:600;
  color:#64748b;border-radius:8px;cursor:pointer;transition:all .15s ease;
}
