.result-review-list{ display:flex;flex-direction:column;gap:6px; }

.result-review-item{
  border:2px solid #e2e8f0;border-radius:var(--radius, 12px);background:#fff;
  overflow:hidden;transition:border-color .2s ease;
}
.result-review-item.is-wrong{ border-color:rgba(239,68,68,.3); }
.result-review-item[open]{ box-shadow:0 2px 8px rgba(0,0,0,.04); }
.result-review-item[open].is-wrong{ border-color:rgba(239,68,68,.4); }

.result-review-item > summary{
  display:flex !important;align-items:center !important;gap:10px !important;
  padding:12px 16px !important;cursor:pointer !important;
  list-style:none !important;user-select:none;
  transition:background .15s ease !important;font-size:13px !important;
}
.result-review-item > summary::-webkit-details-marker{ display:none !important; }
.result-review-item > summary:hover{ background:#f8fafc !important; }

.result-review-num{
  flex-shrink:0;font-size:11px;font-weight:800;
  color:#94a3b8;min-width:32px;letter-spacing:.02em;
}
.result-review-prompt{
  flex:1;font-size:13px;font-weight:600;color:#0f172a;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.result-review-badge{
  flex-shrink:0;font-size:11px;font-weight:700;
  padding:3px 10px;border-radius:999px;letter-spacing:.02em;
}
.result-review-badge.is-correct{ background:rgba(16,185,129,.1);color:#059669; }
.result-review-badge.is-wrong{ background:rgba(239,68,68,.1);color:#dc2626; }
.result-review-badge.is-timeout{ background:rgba(245,158,11,.1);color:#d97706; }
.result-review-chevron{
  flex-shrink:0;font-size:18px;color:#94a3b8;transition:transform .2s ease;
}
.result-review-item[open] .result-review-chevron{ transform:rotate(180deg); }

.result-review-body{
  padding:0 16px 14px;border-top:1px solid #e2e8f0;
}
.result-review-row{
  display:flex;align-items:baseline;gap:8px;
  padding:8px 0;font-size:13px;line-height:1.5;
}
.result-review-row + .result-review-row{
  border-top:1px solid rgba(226,232,240,.5);
}
.result-review-label{
  flex-shrink:0;width:72px;font-size:11px;font-weight:700;
  color:#94a3b8;text-transform:uppercase;letter-spacing:.04em;
}
.result-review-value{ flex:1;color:#0f172a;word-break:break-word; }
.result-review-value code{
  font-family:ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size:12px;background:#f8fafc;border:1px solid #e2e8f0;
  border-radius:6px;padding:1px 6px;
}
.result-review-value.is-correct-val{ color:#059669; }
.result-review-value.is-wrong-val{ color:#dc2626; }
.result-review-explanation{
  font-size:12px;color:#64748b;line-height:1.6;
  background:#f8fafc;border-radius:10px;padding:10px 14px;margin-top:4px;
