/* ITEM — borderless row, hover only */
.app-library-item{
  padding:10px 10px !important;
  border-radius:8px !important;
  border:none !important;
  background:transparent !important;
  box-shadow:none !important;
  gap:10px !important;
  transition:background .1s !important;
}
.app-library-item:hover{
  background:#f8fafc !important;
  transform:none !important;
  box-shadow:none !important;
  border-color:transparent !important;
}
.app-library-item-main{
  gap:10px !important;
}
.app-library-item-copy{
  gap:4px !important;
}
.app-library-item .title{
  font-size:14px !important;
  font-weight:600 !important;
  letter-spacing:0 !important;
  color:#0f172a !important;
}
.app-library-item-top{
  gap:8px !important;
}
.app-library-item-title-wrap{
  gap:3px !important;
}
.app-library-item-meta{
  font-size:12px !important;
  gap:3px !important;
  color:#64748b !important;
}
.app-library-item-badges{
  gap:4px !important;
}
.app-library-item-updated{
  font-size:11px !important;
  color:#94a3b8 !important;
  white-space:nowrap !important;
}

/* ICON — smaller, flat */
.app-library-item .app-preset-card-icon{
  width:36px !important;
  height:36px !important;
  border-radius:8px !important;
  box-shadow:none !important;
  flex-shrink:0 !important;
}
.app-library-item .app-preset-card-icon .ms{
  font-size:18px !important;
}
/* 画像アイコン（appearance.iconImage）と絵文字（1〜2 文字）。
   Material Symbols の名前は上の .ms が受け持つ。 */
.app-preset-card-icon > img{
  width:100%; height:100%; object-fit:cover; display:block; border-radius:inherit;
}
.app-preset-card-icon .app-preset-card-icon-emoji{
  font-size:18px; line-height:1; display:inline-block;
}

/* BADGES — compact, square-ish */
.app-library-state-badge{
  min-height:20px !important;
  padding:0 6px !important;
  font-size:10px !important;
  border-radius:4px !important;
  font-weight:600 !important;
  letter-spacing:.03em !important;
}

/* ACTIONS */
.app-library-item-actions{
  gap:6px !important;
}
.app-library-item-actions .navbtn,
.app-library-item-actions .btn,
.app-library-item-actions .textbtn{
  min-height:30px !important;
  height:30px !important;
  font-size:12px !important;
  padding-left:10px !important;
  padding-right:10px !important;
}

/* MORE MENU — Quick Chat統一スタイル */
.app-library-more summary{
  width:32px !important;
  height:32px !important;
  border-radius:10px !important;
  border:1.5px solid #e2e8f0 !important;
  background:#fff !important;
  color:#64748b !important;
  box-shadow:none !important;
  transform:none !important;
  transition:border-color .15s, background .15s !important;
}
.app-library-more summary .ms{
  font-size:18px !important;
}
.app-library-more[open] summary,
.app-library-more summary:hover{
  background:#fff !important;
  border-color:#cbd5e1 !important;
  box-shadow:0 2px 8px rgba(15,23,42,.06) !important;
  transform:none !important;
  color:#334155 !important;
}
.app-library-more-menu{
  border-radius:var(--radius-lg, 16px) !important;
  padding:8px 4px !important;
  box-shadow:0 2px 8px rgba(15,23,42,.06), 0 12px 36px rgba(15,23,42,.12) !important;
  border:0 !important;
  background:#fff !important;
  gap:0 !important;
  min-width:180px !important;
  overflow:auto !important;
  animation:ddMenuIn .16s cubic-bezier(.22,1,.36,1) both !important;
}
.app-library-more-action{
  border-radius:0 !important;
  font-size:15px !important;
  font-weight:500 !important;
  min-height:auto !important;
  padding:13px 16px !important;
  color:#1e293b !important;
  background:transparent !important;
  border:none !important;
  width:100% !important;
  text-align:left !important;
  justify-content:flex-start !important;
  letter-spacing:-.005em !important;
  line-height:1.45 !important;
  transition:background .08s !important;
}
.app-library-more-action:hover{
  background:#f5f7fa !important;
  color:#0f172a !important;
  box-shadow:none !important;
  transform:none !important;
}
.app-library-more-action.is-danger{
  color:#dc2626 !important;
}
.app-library-more-action.is-danger:hover{
  background:#fff1f2 !important;
  color:#b91c1c !important;
}

/* SECTION COLLAPSE TOGGLE */
.app-library-section-toggle-btn{
  width:28px !important;
  height:28px !important;
  border-radius:6px !important;
  border:none !important;
  background:transparent !important;
  color:#94a3b8 !important;
  display:inline-flex !important;
  align-items:center !important;
  justify-content:center !important;
  cursor:pointer !important;
  flex-shrink:0 !important;
  padding:0 !important;
  transition:background .1s, color .1s !important;
}
.app-library-section-toggle-btn:hover{
  background:#f1f5f9 !important;
  color:#475569 !important;
}
.app-library-section-toggle-btn .ms{
  font-size:18px !important;
  transition:transform .2s ease !important;
}
.app-library-section.is-collapsed .app-library-section-toggle-btn .ms{
  transform:rotate(180deg) !important;
}
.app-library-section.is-collapsed > :not(.app-library-section-head){
  display:none !important;
}
.app-library-section.is-collapsed > .app-library-section-head{
  border-bottom:none !important;
}

/* EMPTY STATE */
.app-library-empty{
  border-radius:8px !important;
  padding:20px 14px !important;
  font-size:13px !important;
}

/* RESPONSIVE */
@media(max-width:860px){
  .app-library-search-row{
    max-width:none !important;
  }
}
@media(max-width:720px){
  .app-library-toolbar{
    padding:8px 10px !important;
  }
  .app-library-item{
    grid-template-columns:1fr !important;
  }
  .app-library-item-actions{
    justify-content:flex-start !important;
  }
  .app-library-more-menu{
    left:0 !important;
    right:auto !important;
  }
}
@media(max-width:520px){
  .app-library-page .app-library-filters{
    gap:6px !important;
  }
  .app-library-section-head{
    padding:10px 12px !important;
  }
  .app-library-list{
    padding:3px !important;
  }
}

/* ══════════════════════════════════════
   Preset Engine — Apple-style Redesign
   ══════════════════════════════════════ */

/* OVERLAY — lighter backdrop */
.app-preset-engine-overlay{
  background:rgba(255,255,255,.62) !important;
  backdrop-filter:blur(20px) !important;
  -webkit-backdrop-filter:blur(20px) !important;
}

/* SHELL — clean white, less shadow */
.app-preset-engine-shell{
  border-radius:20px !important;
  border:1px solid #e2e8f0 !important;
  background:#fff !important;
  box-shadow:0 8px 32px rgba(15,23,42,.08), 0 2px 8px rgba(15,23,42,.04) !important;
}

/* TOPBAR — compact, no kicker */
.app-preset-engine-topbar{
  padding:14px 20px !important;
  border-bottom:1px solid #f1f5f9 !important;
  background:#fff !important;
  backdrop-filter:none !important;
  -webkit-backdrop-filter:none !important;
}
.app-preset-engine-topkicker{
  display:none !important;
}
.app-preset-engine-toptitle{
  font-size:15px !important;
  font-weight:600 !important;
  color:#0f172a !important;
}

/* STAGE — flat white background */
.app-preset-engine-stage{
  background:#fff !important;
  padding:24px clamp(18px,3vw,28px) calc(24px + env(safe-area-inset-bottom,0px)) !important;
}

/* PROGRESS BAR — Apple stepper style */
.app-preset-engine-progress{
  width:min(640px,100%) !important;
}
.app-preset-engine-progress-track{
  gap:0 !important;
  padding:0 !important;
}
.app-preset-engine-progress-track::before{
  top:14px !important;
  left:28px !important;
  right:28px !important;
  height:2px !important;
  background:#e2e8f0 !important;
}
.app-preset-engine-progress-step{
  gap:6px !important;
  padding:0 !important;
}
.app-preset-engine-progress-dot{
  width:28px !important;
  height:28px !important;
  border:2px solid #cbd5e1 !important;
  background:#fff !important;
  box-shadow:none !important;
  position:relative !important;
  display:grid !important;
  place-items:center !important;
  font-size:12px !important;
  font-weight:700 !important;
  color:#94a3b8 !important;
}
.app-preset-engine-progress-step.is-active .app-preset-engine-progress-dot{
  border-color:#6366f1 !important;
  background:#6366f1 !important;
  color:#fff !important;
}
.app-preset-engine-progress-step.is-done .app-preset-engine-progress-dot{
  border-color:#22c55e !important;
  background:#22c55e !important;
  color:#fff !important;
}
.app-preset-engine-progress-label{
  font-size:11px !important;
  font-weight:500 !important;
  color:#94a3b8 !important;
}
.app-preset-engine-progress-step.is-active .app-preset-engine-progress-label{
  color:#6366f1 !important;
  font-weight:600 !important;
}
.app-preset-engine-progress-step.is-done .app-preset-engine-progress-label{
  color:#22c55e !important;
  font-weight:600 !important;
}

/* STEP HEAD — clean typography */
.app-preset-engine-head{
  width:min(640px,100%) !important;
}
.app-preset-engine-kicker{
  font-size:12px !important;
  font-weight:600 !important;
  color:#6366f1 !important;
  letter-spacing:.06em !important;
}
.app-preset-engine-title{
  font-size:clamp(24px,3.2vw,32px) !important;
  letter-spacing:-.02em !important;
  color:#0f172a !important;
  line-height:1.15 !important;
}
.app-preset-engine-sub{
  font-size:14px !important;
  color:#64748b !important;
