   A. Native <select> — closed state
   ============================================ */
select,
.select,
select.select,
.settings-select,
select.settings-select,
.melta-select{
  appearance:none !important;
  -webkit-appearance:none !important;
  min-height:44px !important;
  padding:0 42px 0 14px !important;
  border:1.5px solid #e2e8f0 !important;
  border-radius:12px !important;
  background:#fff !important;
  color:#0f172a !important;
  font-size:14px !important;
  font-weight:500 !important;
  line-height:1.4 !important;
  letter-spacing:-.005em !important;
  box-shadow:none !important;
  cursor:pointer !important;
  transition:border-color .16s ease,box-shadow .16s ease !important;
  background-image:var(--dd-chevron) !important;
  background-position:calc(100% - 14px) center !important;
  background-size:16px 16px !important;
  background-repeat:no-repeat !important;
}
/* S size for settings rows */
.settings-select,
select.settings-select{
  min-height:40px !important;
  font-size:13px !important;
  padding:0 38px 0 12px !important;
  border-radius:10px !important;
}
/* Focus */
select:focus,
.select:focus,
.settings-select:focus,
.melta-select:focus{
  border-color:#6366f1 !important;
  box-shadow:0 0 0 3px rgba(99,102,241,.12) !important;
  outline:none !important;
}
/* Hover */
@media(hover:hover){
  select:hover:not(:focus):not(:disabled),
  .select:hover:not(:focus):not(:disabled),
  .settings-select:hover:not(:focus):not(:disabled),
  .melta-select:hover:not(:focus):not(:disabled){
    border-color:#95b6ff !important;
  }
}
/* Disabled */
select:disabled,
.select:disabled,
.settings-select:disabled{
  opacity:.5 !important;
  cursor:not-allowed !important;
  background:#f8fafc !important;
}

/* ============================================
   B. xselect trigger — closed state
   ============================================ */
.xselect-trigger{
  min-height:48px !important;
  padding:0 44px 0 16px !important;
  border:1.5px solid #e2e8f0 !important;
  border-radius:var(--radius, 12px) !important;
  background:#fff !important;
  color:#0f172a !important;
  font-size:15px !important;
  font-weight:500 !important;
  line-height:1.4 !important;
  letter-spacing:-.005em !important;
  box-shadow:none !important;
  transition:border-color .16s ease,box-shadow .16s ease !important;
}
.xselect.settings-select .xselect-trigger{
  min-height:42px !important;
  font-size:13px !important;
  padding:0 38px 0 12px !important;
  border-radius:12px !important;
}
.xselect-trigger::after{
  right:16px !important;
  width:9px !important;
  height:9px !important;
  border-right:2px solid #94a3b8 !important;
  border-bottom:2px solid #94a3b8 !important;
  opacity:.7 !important;
  transition:transform .2s cubic-bezier(.22,1,.36,1) !important;
}
.xselect-trigger:hover,
:is(body, #authGate, #settingsOverlay, #viewQuiz, #appChatPage, #appInboxPage) .xselect-trigger:hover{
  filter:none !important;
  border-color:#cbd5e1 !important;
  background:#fff !important;
  box-shadow:none !important;
}
.xselect-trigger:focus-visible{
  border-color:#6366f1 !important;
  box-shadow:0 0 0 3px rgba(99,102,241,.12) !important;
  outline:none !important;
}
.xselect.is-open .xselect-trigger,
:is(body, #authGate, #settingsOverlay, #viewQuiz, #appChatPage, #appInboxPage) .xselect.is-open .xselect-trigger{
  border-color:#cbd5e1 !important;
  box-shadow:0 2px 8px rgba(15,23,42,.06) !important;
}
.xselect.is-disabled .xselect-trigger{
  opacity:.5 !important;
  background:#f8fafc !important;
  cursor:not-allowed !important;
}
.xselect-label{
  color:#0f172a !important;
  overflow:hidden !important;
  text-overflow:ellipsis !important;
  white-space:nowrap !important;
}

/* ============================================
   C. xselect menu — OPENED dropdown panel
   ============================================ */
.xselect-menu,
body .xselect-menu,
:is(body, #authGate, #settingsOverlay, #viewQuiz, #appChatPage, #appInboxPage) .xselect-menu{
  border:0 !important;
  border-radius:var(--radius-lg, 16px) !important;
  background:#fff !important;
  box-shadow:
    0 2px 8px rgba(15,23,42,.06),
    0 12px 36px rgba(15,23,42,.12) !important;
  padding:8px 4px !important;
  max-height:360px !important;
  overflow-y:auto !important;
  overscroll-behavior:contain !important;
  animation:ddMenuIn .18s cubic-bezier(.22,1,.36,1) both !important;
}
.xselect-menu[data-placement="top"]{
  animation-name:ddMenuInUp !important;
}
@keyframes ddMenuIn{
  from{opacity:0;transform:translateY(-4px)}
  to{opacity:1;transform:translateY(0)}
}
@keyframes ddMenuInUp{
  from{opacity:0;transform:translateY(4px)}
  to{opacity:1;transform:translateY(0)}
}

/* Scrollbar */
.xselect-menu::-webkit-scrollbar{ width:4px; }
.xselect-menu::-webkit-scrollbar-track{ background:transparent; margin:8px 0; }
.xselect-menu::-webkit-scrollbar-thumb{ background:rgba(0,0,0,.08); border-radius:2px; }

/* Group header */
.xselect-group{
  font-size:11px !important;
  font-weight:600 !important;
  color:#94a3b8 !important;
  letter-spacing:.04em !important;
  padding:10px 16px 4px !important;
  user-select:none !important;
  text-transform:none !important;
}

/* ---- Option row — must match :is(body,...) specificity ---- */
:is(body, #authGate, #settingsOverlay, #viewQuiz, #appChatPage, #appInboxPage) .xselect-option,
.xselect-option,
body .xselect-option,
body[data-ui-v2="1"] .xselect-option{
  position:relative !important;
  width:100% !important;
  min-height:auto !important;
  padding:13px 16px !important;
  border:0 none !important;
  border-color:transparent !important;
  border-radius:0 !important;
  background:transparent !important;
  box-shadow:none !important;
  outline:none !important;
  font-size:15px !important;
  font-weight:500 !important;
  color:#1e293b !important;
  line-height:1.45 !important;
  text-align:left !important;
  display:block !important;
  cursor:pointer !important;
  transition:background .1s ease !important;
  margin:0 !important;
  white-space:normal !important;
  word-break:break-word !important;
  filter:none !important;
  transform:none !important;
}
/* Hover */
@media(hover:hover)and(pointer:fine){
  :is(body, #authGate, #settingsOverlay, #viewQuiz, #appChatPage, #appInboxPage) .xselect-option:hover,
  body .xselect-option:hover,
  body[data-ui-v2="1"] .xselect-option:hover{
    background:#f5f7fa !important;
    border:0 none !important;
    border-color:transparent !important;
    border-radius:0 !important;
    box-shadow:none !important;
    transform:none !important;
  }
}
/* Active */
:is(body, #authGate, #settingsOverlay, #viewQuiz, #appChatPage, #appInboxPage) .xselect-option:active,
body .xselect-option:active{
  background:#f0f2f5 !important;
}
/* ---- Selected item ---- */
:is(body, #authGate, #settingsOverlay, #viewQuiz, #appChatPage, #appInboxPage) .xselect-option.is-selected,
body .xselect-option.is-selected,
body[data-ui-v2="1"] .xselect-option.is-selected{
  background:#f0f5ff !important;
  color:#1a40b5 !important;
  font-weight:600 !important;
  border:0 none !important;
  border-color:transparent !important;
  border-radius:0 !important;
  box-shadow:none !important;
}
/* No checkmark */
:is(body, #authGate, #settingsOverlay, #viewQuiz, #appChatPage, #appInboxPage) .xselect-option.is-selected::after,
:is(body, #authGate, #settingsOverlay, #viewQuiz, #appChatPage, #appInboxPage) .xselect-option::after,
body .xselect-option::after,
body .xselect-option.is-selected::after{
  content:none !important;
  display:none !important;
  width:0 !important;
  height:0 !important;
  border:0 !important;
}
/* Disabled */
.xselect-option[disabled]{
  opacity:.35 !important;
  cursor:not-allowed !important;
}

/* ============================================
   D. Mobile
   ============================================ */
@media(max-width:640px){
  select,.select,.settings-select,.melta-select{
    min-height:44px !important;
    font-size:15px !important;
  }
  .xselect-trigger{
    min-height:44px !important;
    font-size:15px !important;
  }
  .xselect-option{
    min-height:40px !important;
    font-size:14px !important;
    padding:9px 32px 9px 10px !important;
  }
  .xselect-menu{
    padding:5px !important;
    max-height:50vh !important;
  }
}

/* ============================================
   E. Exclusions
   ============================================ */
/* 3D battle — dark theme, keep as-is */
#rt3dOverlay select,
#rt3dOverlay .b3d-select{
  appearance:none !important;
  border-radius:12px !important;
  min-height:40px !important;
}
/* Auth gate v2 inputs already handled separately */
#authGate .auth-line-select{
  border-radius:10px !important;
}

/* ── End Dropdown / Select — DEFINITIVE ── */

/* ══════════════════════════════════════════════
   Auth Gate v2 — Commercial-grade redesign
   ══════════════════════════════════════════════ */

/* --- Container: split layout --- */
#authGate.auth-gate{
  background:linear-gradient(135deg, #e8ecf4 0%, #dde3f0 50%, #e4e8f2 100%) !important;
  padding:0 !important;
  align-items:stretch !important;
}
.auth-gate-card{
  background:transparent !important;
  border:none !important;
  border-radius:0 !important;
  box-shadow:none !important;
  backdrop-filter:none !important;
  max-width:100% !important;
  width:100% !important;
  max-height:none !important;
  padding:0 !important;
  overflow:visible !important;
}

/* --- Hide shared head (hero has branding) --- */
.auth-gate-head{ display:none !important; }

/* --- Panels: clean white interior --- */
.auth-gate-panel:not([data-auth-panel="welcome"]){
  padding:clamp(28px,5vw,40px) clamp(24px,4vw,36px) !important;
  border:none !important;
