  box-shadow:none !important;
}
#authLoginPanel{
  box-shadow:none !important;
}
.auth-gate-panel:not([data-auth-panel="welcome"]) .auth-panel-copy{
  gap:6px !important;
}

/* --- v2 Branding (centered, per-panel) --- */
.auth-v2-brand{
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:12px;
  margin-bottom:8px;
}
.auth-v2-brand .auth-gate-brand-mark{
  width:56px !important;height:56px !important;border-radius:16px !important;
  display:inline-flex;align-items:center;justify-content:center;
  background:linear-gradient(135deg,#6366f1 0%,#4f46e5 100%) !important;
  box-shadow:0 4px 16px rgba(99,102,241,.2) !important;
}
.auth-v2-brand .auth-gate-brand-monogram{
  font-size:16px !important;font-weight:800 !important;color:#fff !important;letter-spacing:.06em !important;
}
.auth-v2-brand-name{
  font-size:1.5rem;
  font-weight:740;
  color:#0f172a;
  letter-spacing:-.01em;
}

/* --- v2 Centered copy --- */
.auth-v2-copy-center{
  text-align:center !important;
}
.auth-v2-copy-center .auth-panel-title{
  font-size:1.5rem !important;
}
.auth-v2-copy-center .auth-panel-sub{
  color:var(--melta-text-secondary,#64748b) !important;
  max-width:none !important;
}

/* --- v2 CTA (full-width primary) --- */
.auth-v2-cta{
  width:100% !important;
  min-height:52px !important;
  border-radius:var(--radius, 12px) !important;
  font-size:1rem !important;
  font-weight:600 !important;
  justify-content:center !important;
  background:linear-gradient(135deg, #6366f1, #4f46e5) !important;
  color:#fff !important;
