  color:#6366f1 !important;
  min-height:auto !important;
  padding:2px 4px !important;
  transition:opacity .15s ease !important;
}
.auth-v2-switch-link:hover{
  opacity:.7 !important;
}

/* --- v2 Grade notice banner (warning) --- */
.auth-v2-grade-notice{
  display:flex;
  align-items:flex-start;
  gap:8px;
  padding:10px 14px;
  margin:0 0 12px;
