}
.auth-v2-grade-notice strong{
  font-weight:600;
  color:#78350f;
}

/* --- v2 Progress bar --- */
.auth-v2-progress{
  height:3px;
  background:#f1f5f9;
  margin:-clamp(28px,5vw,40px) -clamp(24px,4vw,36px) clamp(20px,3vw,28px);
}
.auth-v2-progress-bar{
  height:100%;
  background:linear-gradient(90deg, #6366f1, #818cf8);
  border-radius:0 2px 2px 0;
  transition:width .4s cubic-bezier(.22,1,.36,1);
}

/* --- v2 Grade chips --- */
.auth-v2-grade-chips{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:8px;
}
.auth-v2-grade-chip{
  min-height:44px;
  border:1.5px solid var(--melta-border-default,#e2e8f0);
  border-radius:10px;
  background:#fff;
  color:var(--melta-text-primary,#1e293b);
