  transition:border-color .16s,background .16s,color .16s,box-shadow .16s;
}
.auth-v2-grade-chip:hover:not(.is-active){
  border-color:#a5b4fc;
  background:#eef2ff;
}
.auth-v2-grade-chip.is-active{
  border-color:#6366f1;
  background:#eef2ff;
  color:#4f46e5;
  box-shadow:0 0 0 3px rgba(99,102,241,.12);
}

/* --- v2 Field hint --- */
.auth-v2-field-hint{
  font-size:12px;
  color:var(--melta-text-secondary,#64748b);
  margin-top:-4px;
}
/* --- v2 ID availability check --- */
.auth-v2-id-check{
  font-size:12px;
  font-weight:500;
  min-height:16px;
  margin-top:-2px;
  transition:color .2s;
}
.auth-v2-id-check.is-checking{ color:var(--melta-text-secondary,#64748b); }
.auth-v2-id-check.is-ok{ color:#16a34a; }
.auth-v2-id-check.is-error{
  display:flex;
  align-items:center;
  gap:5px;
  color:#dc2626;
}
.auth-v2-id-check.is-error::before{
  content:'!';
  flex:0 0 14px;
  width:14px;
  height:14px;
  border-radius:50%;
  background:#fee2e2;
  color:#dc2626;
  font-size:9px;
  font-weight:800;
  line-height:14px;
  text-align:center;
}

/* --- v2 Question number --- */
.auth-v2-q-num{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:32px;height:32px;
  border-radius:10px;
  background:var(--melta-primary-50,#f0f5ff);
  color:var(--melta-primary-500,#6366f1);
  font-size:12px;
  font-weight:700;
  margin-bottom:4px;
}

/* --- v2 Choice chip grid --- */
.auth-v2-choice-grid{
  display:grid;
  gap:10px;
}
.auth-v2-choice-3col{ grid-template-columns:repeat(3,1fr); }
.auth-v2-choice-2col{ grid-template-columns:repeat(2,1fr); }
.auth-v2-choice-chip-wide{ grid-column:1 / -1; }

.auth-v2-choice-chip{
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:6px;
