  color:#4f46e5;
}

/* --- v2 Footer layout --- */
.auth-v2-foot-left,
.auth-v2-foot-right{
  display:flex;
  align-items:center;
  gap:8px;
}

/* --- v2 Password strength --- */
.auth-v2-pw-strength{
  display:flex;
  align-items:center;
  gap:10px;
  margin-top:2px;
}
.auth-v2-pw-bar{
  flex:1;
  height:4px;
  background:#f1f5f9;
  border-radius:2px;
