.auth-v2-pw-label[data-level="0"]{ color:var(--melta-text-secondary,#64748b); }
.auth-v2-pw-label[data-level="1"]{ color:#ef4444; }
.auth-v2-pw-label[data-level="2"]{ color:#f59e0b; }
.auth-v2-pw-label[data-level="3"]{ color:#22c55e; }
.auth-v2-pw-label[data-level="4"]{ color:#16a34a; }

/* --- v2 Password requirements --- */
.auth-v2-pw-reqs{
  display:grid;
  grid-template-columns:1fr 1fr;
