}
.auth-v2-pw-req .ms{
  font-size:14px;
}
.auth-v2-pw-req.is-met{
  color:#22c55e;
}

/* --- v2 Creating panel --- */
.auth-v2-creating{
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:16px;
  padding:40px 20px;
  min-height:300px;
}
.auth-v2-creating-icon{
  position:relative;
  width:72px;height:72px;
}
.auth-v2-creating-icon .auth-gate-brand-mark{
  position:absolute;
  top:50%;left:50%;
  transform:translate(-50%,-50%);
  width:48px !important;height:48px !important;
  border-radius:var(--radius, 12px) !important;
  background:linear-gradient(135deg,#6366f1 0%,#1a40b5 100%) !important;
  box-shadow:0 4px 16px rgba(99,102,241,.18) !important;
  animation:authV2Float 2.4s ease-in-out infinite;
}
.auth-v2-creating-icon .auth-gate-brand-monogram{
  font-size:13px !important;
}
.auth-v2-creating-ring{
  position:absolute;top:0;left:0;
  width:72px;height:72px;
  color:var(--melta-primary-500,#6366f1);
  stroke-dasharray:60 120;
  animation:authV2Spin 2.4s linear infinite;
}
@keyframes authV2Float{
  0%,100%{transform:translate(-50%,-50%) translateY(0)}
  50%{transform:translate(-50%,-50%) translateY(-3px)}
}
@keyframes authV2Spin{
  to{transform:rotate(360deg)}
}
.auth-v2-creating-text{
  font-size:1.1rem;
  font-weight:650;
  color:var(--melta-text-primary,#1e293b);
}
.auth-v2-creating-sub{
  font-size:13px;
  color:var(--melta-text-secondary,#64748b);
  margin-top:-8px;
}
.auth-v2-creating-dots{
  display:flex;gap:6px;margin-top:4px;
}
.auth-v2-creating-dots span{
  width:6px;height:6px;border-radius:50%;
