  animation:ddMenuIn .16s cubic-bezier(.22,1,.36,1) both !important;
}
div[data-dd-v2="1"]::-webkit-scrollbar{ width:4px; }
div[data-dd-v2="1"]::-webkit-scrollbar-track{ background:transparent; }
div[data-dd-v2="1"]::-webkit-scrollbar-thumb{ background:rgba(0,0,0,.08); border-radius:2px; }

button[data-dd-v2="1"]{
  appearance:none !important;
  -webkit-appearance:none !important;
  display:block !important;
  width:100% !important;
  box-sizing:border-box !important;
  margin:0 !important;
  padding:13px 16px !important;
  border:0 !important;
  border-radius:0 !important;
  background:transparent !important;
  background-image:none !important;
  box-shadow:none !important;
  outline:none !important;
  filter:none !important;
  transform:none !important;
  font-family:inherit !important;
  font-size:15px !important;
  font-weight:500 !important;
  line-height:1.45 !important;
  letter-spacing:normal !important;
  color:#1e293b !important;
  text-align:left !important;
  cursor:pointer !important;
  white-space:normal !important;
  word-break:break-word !important;
  -webkit-tap-highlight-color:transparent !important;
  transition:background .1s ease !important;
}
button[data-dd-v2="1"]:hover{
  background:#f5f7fa !important;
  border:0 !important;
  border-radius:0 !important;
  box-shadow:none !important;
  transform:none !important;
  filter:none !important;
}
