/* ── Fullscreen: chat fills entire viewport ── */
body.app-chat-fullscreen .app-tabbar{
  transform:translateX(calc(-100% - 20px)) !important;
  opacity:0 !important;pointer-events:none !important;
  transition:transform .3s cubic-bezier(.4,0,.2,1),opacity .25s ease !important;
}
/* ── Mobile: hide app top bar (#topbar) when Quick Chat or Sede is active ── */
@media(max-width:960px){
  body.app-chat-fullscreen #topbar{display:none !important;}
  body.app-chat-fullscreen #appAiChatShell{top:0 !important;}
  body.app-chat-fullscreen #appAiChatShell .app-chat-topbar{display:flex !important;}
  /* Fill entire viewport on mobile — prevent content from leaking below */
  body.app-chat-fullscreen .app-chat-shell{
    height:100dvh !important;max-height:100dvh !important;overflow:hidden !important;
  }
  body.app-chat-fullscreen .app-chat-main-panel{
    height:100dvh !important;max-height:100dvh !important;display:flex !important;flex-direction:column !important;overflow:hidden !important;
  }
  body.app-chat-fullscreen .app-chat-scroll{
    flex:1 !important;min-height:0 !important;overflow-y:auto !important;
  }
}
/* Allow VQ sidebar to open even in fullscreen chat */
body.app-chat-fullscreen.app-v2-sidebar-open .app-tabbar{
  transform:translateX(0) scale(1) !important;
  opacity:1 !important;pointer-events:auto !important;
}
body.app-chat-fullscreen.app-v2-sidebar-open .app-v2-sidebar-backdrop{
  opacity:1 !important;pointer-events:auto !important;
}
body.app-chat-fullscreen main{
  padding-left:0 !important;padding-right:0 !important;
  padding-top:0 !important;padding-bottom:0 !important;
