/* ══ Mobile: white overlay sidebar ══ */
@media(max-width:960px){
  #appAiChatShell,
  #appAiChatShell.sidebar-collapsed{grid-template-columns:minmax(0,1fr) !important;transition:none !important;}
  #appAiChatShell > .app-chat-history-side{
    position:fixed !important;inset:0 auto 0 0 !important;width:min(300px,85vw) !important;z-index:60 !important;
    background:#fff !important;color:var(--text, #1d1d1f) !important;
    border-right:1px solid rgba(0,0,0,.06) !important;border-radius:0 16px 16px 0 !important;
    box-shadow:6px 0 32px rgba(0,0,0,.12) !important;transform:translateX(-100%) !important;opacity:0 !important;pointer-events:none !important;
    transition:transform .32s cubic-bezier(.32,1,.23,1),opacity .24s ease !important;
  }
  #appAiChatShell.sidebar-collapsed > .app-chat-history-side{
    opacity:0 !important;visibility:hidden !important;
  }
  #appAiChatShell[data-sidebar-open="1"] > .app-chat-history-side{transform:translateX(0) !important;opacity:1 !important;pointer-events:auto !important;visibility:visible !important;}
  #appAiChatShell::before{content:'' !important;display:block !important;position:fixed !important;inset:0 !important;z-index:55 !important;background:rgba(0,0,0,.3) !important;backdrop-filter:blur(2px) !important;opacity:0 !important;pointer-events:none !important;transition:opacity .28s ease !important;}
  #appAiChatShell[data-sidebar-open="1"]::before{opacity:1 !important;pointer-events:auto !important;}
  #appAiChatShell .app-chat-topbar-btn[data-chat-action="toggleSidebar"]{display:inline-grid !important;}
  #appAiChatShell .app-chat-sidebar-collapse-btn{display:none !important;}
  #appAiChatShell .app-chat-sidebar-close-btn{display:inline-grid !important;}
  #appAiChatShell .app-chat-nav-desktop{display:none !important;}
  /* Mobile: hide collapsed icon strip styles */
  #appAiChatShell.sidebar-collapsed .app-chat-sidebar-nav-item{width:100% !important;height:auto !important;justify-content:flex-start !important;padding:8px 10px !important;}
  #appAiChatShell.sidebar-collapsed .app-chat-sidebar-nav-item > span:not(.ms){display:inline !important;}
  #appAiChatShell.sidebar-collapsed .app-chat-sidebar-head-title{display:block !important;}
  #appAiChatShell.sidebar-collapsed .app-chat-sidebar-section-head{display:block !important;}
  #appAiChatShell.sidebar-collapsed .app-chat-session-list{display:block !important;}
  #appAiChatShell.sidebar-collapsed .app-chat-sidebar-user-info{display:block !important;}
  #appAiChatShell.sidebar-collapsed .app-chat-sidebar-user-menu{display:block !important;}
  #appAiChatShell.sidebar-collapsed .app-chat-sidebar-user-btn{width:100% !important;justify-content:flex-start !important;}

  /* ── Mobile: Sede sidebar overlay (same as Quick Chat sidebar) ── */
  #appAiChatShell[data-chat-mode="sede"] .app-sede-sidebar{
    position:fixed !important;inset:0 auto 0 0 !important;width:min(300px,85vw) !important;z-index:60 !important;
    border-radius:0 16px 16px 0 !important;
    box-shadow:6px 0 32px rgba(0,0,0,.12) !important;
    transform:translateX(-100%) !important;opacity:0 !important;pointer-events:none !important;
    transition:transform .32s cubic-bezier(.32,1,.23,1),opacity .24s ease !important;
  }
  #appAiChatShell[data-chat-mode="sede"][data-sidebar-open="1"] .app-sede-sidebar{
    transform:translateX(0) !important;opacity:1 !important;pointer-events:auto !important;visibility:visible !important;
  }
  /* Add close button to Sede sidebar on mobile */
  #appAiChatShell[data-chat-mode="sede"] .app-sede-sidebar .app-chat-sidebar-collapse-btn{display:none !important;}
  #appAiChatShell[data-chat-mode="sede"] .app-sede-sidebar .app-chat-sidebar-close-btn{display:inline-grid !important;}

  /* ── Mobile: Quick Chat sidebar dark mode fix ── */
  body[data-chat-dark="1"] #appAiChatShell > .app-chat-history-side{
    background:#111 !important;border-color:rgba(255,255,255,.06) !important;color:#fff !important;
  }
}

/* ════════════ SEDE SIDEBAR ════════════ */
