/* Dark */
body[data-chat-dark="1"] .sede-history-panel{background:#111 !important;border-color:rgba(255,255,255,.08) !important;box-shadow:-4px 0 16px rgba(0,0,0,.3) !important;}
body[data-chat-dark="1"] .sede-history-head{border-color:rgba(255,255,255,.06) !important;color:#fff !important;}
body[data-chat-dark="1"] .sede-history-item{border-color:rgba(255,255,255,.06) !important;color:rgba(255,255,255,.8) !important;}
body[data-chat-dark="1"] .sede-history-item:hover{background:rgba(255,255,255,.04) !important;}
body[data-chat-dark="1"] .sede-history-rollback{background:transparent !important;border-color:rgba(255,255,255,.1) !important;color:rgba(255,255,255,.7) !important;}

/* ── Sede Project Modal ── */
.sede-project-modal{
  position:fixed !important;inset:0 !important;z-index:200001 !important;
  display:flex !important;align-items:center !important;justify-content:center !important;
  background:rgba(15,23,42,.25) !important;backdrop-filter:blur(8px) !important;
  animation:sedeFadeIn .15s ease !important;
}
@keyframes sedeFadeIn{from{opacity:0}to{opacity:1}}
.sede-project-modal-card{
  width:min(520px,calc(100% - 32px)) !important;max-height:80vh !important;
  background:var(--panel, #fff) !important;border-radius:16px !important;
  border:1px solid var(--border) !important;box-shadow:0 12px 40px rgba(0,0,0,.12) !important;
  display:flex !important;flex-direction:column !important;overflow:hidden !important;
}
.sede-project-modal-head{
  display:flex !important;align-items:center !important;justify-content:space-between !important;
  padding:16px 20px 12px !important;border-bottom:1px solid var(--border) !important;flex-shrink:0 !important;
}
.sede-project-modal-head h3{font-size:16px !important;font-weight:700 !important;margin:0 !important;color:var(--text) !important;}
.sede-project-modal-close{
  width:30px !important;height:30px !important;display:inline-grid !important;place-items:center !important;
  border:none !important;background:transparent !important;cursor:pointer !important;border-radius:8px !important;
  color:var(--muted) !important;
}
.sede-project-modal-close:hover{background:var(--chip-bg) !important;}
.sede-project-modal-body{padding:16px 20px !important;overflow-y:auto !important;display:flex !important;flex-direction:column !important;gap:14px !important;}
.sede-project-field label{display:block !important;font-size:12px !important;font-weight:600 !important;color:var(--muted) !important;margin-bottom:4px !important;}
.sede-project-field input,.sede-project-field textarea{
  width:100% !important;padding:8px 12px !important;border:1px solid var(--border) !important;
  border-radius:8px !important;font-size:14px !important;background:var(--input-bg, #fff) !important;
  color:var(--text) !important;font-family:inherit !important;outline:none !important;
}
.sede-project-field input:focus,.sede-project-field textarea:focus{border-color:var(--accent) !important;}
.sede-project-dropzone{
  border:2px dashed var(--border) !important;border-radius:10px !important;padding:24px !important;
  text-align:center !important;cursor:pointer !important;transition:border-color .15s !important;
  color:var(--muted) !important;font-size:13px !important;
}
.sede-project-dropzone:hover,.sede-project-dropzone.is-dragover{border-color:var(--accent) !important;background:var(--chip-bg) !important;}
.sede-project-dropzone .ms{font-size:32px !important;display:block !important;margin-bottom:6px !important;opacity:.4 !important;}
.sede-project-file-list{display:flex !important;flex-direction:column !important;gap:4px !important;max-height:120px !important;overflow-y:auto !important;}
.sede-project-file-item{
  display:flex !important;align-items:center !important;gap:6px !important;padding:4px 8px !important;
  border-radius:6px !important;background:var(--chip-bg) !important;font-size:12px !important;color:var(--text) !important;
}
.sede-project-file-item .ms{font-size:14px !important;color:var(--muted) !important;}
.sede-project-file-item button{margin-left:auto !important;background:none !important;border:none !important;cursor:pointer !important;color:var(--muted) !important;font-size:14px !important;}
.sede-project-modal-foot{
  padding:12px 20px !important;border-top:1px solid var(--border) !important;
  display:flex !important;justify-content:flex-end !important;gap:8px !important;flex-shrink:0 !important;
}
.sede-project-modal-foot button{
  padding:8px 20px !important;border-radius:8px !important;font-size:13px !important;
  font-weight:600 !important;cursor:pointer !important;border:1px solid var(--border) !important;
  background:var(--panel) !important;color:var(--text) !important;font-family:inherit !important;
}
.sede-project-modal-foot .is-primary{background:var(--accent) !important;color:#fff !important;border-color:var(--accent) !important;}
.sede-project-modal-foot .is-primary:hover{opacity:.85 !important;}
.sede-project-modal-foot .is-primary:disabled{opacity:.4 !important;cursor:default !important;}
.sede-project-loading{text-align:center !important;padding:20px !important;color:var(--muted) !important;font-size:14px !important;}

/* ── Sede Usage Bar ── */
.app-sede-usage{padding:8px 8px 4px !important;margin-top:auto !important;border-top:1px solid rgba(15,23,42,.07) !important;flex-shrink:0 !important;}
.sede-plan-badge{
  display:inline-flex !important;padding:2px 8px !important;border-radius:4px !important;
  font-size:10px !important;font-weight:700 !important;margin:0 0 6px !important;
  background:rgba(34,197,94,.12) !important;color:#16a34a !important;
  letter-spacing:.02em !important;
}
.sede-usage-item{padding:3px 0 !important;}
.sede-usage-header{display:flex !important;justify-content:space-between !important;align-items:center !important;margin-bottom:3px !important;}
.sede-usage-label{font-size:10px !important;color:#94a3b8 !important;}
.sede-usage-value{font-size:10px !important;font-weight:600 !important;color:var(--text, #1d1d1f) !important;}
.sede-usage-track{height:4px !important;background:rgba(0,0,0,.06) !important;border-radius:2px !important;overflow:hidden !important;}
.sede-usage-fill{height:100% !important;border-radius:2px !important;transition:width .4s ease !important;}
.sede-usage-fill.is-daily{background:linear-gradient(90deg,#6366f1,#8b5cf6) !important;}
.sede-usage-fill.is-monthly{background:linear-gradient(90deg,#22c55e,#16a34a) !important;}
.sede-usage-fill.is-warning{background:linear-gradient(90deg,#ef4444,#dc2626) !important;}
.sede-usage-reset{font-size:9px !important;color:#94a3b8 !important;margin-top:2px !important;}
/* Dark */
body[data-chat-dark="1"] .app-sede-usage{border-color:rgba(255,255,255,.06) !important;}
body[data-chat-dark="1"] .sede-plan-badge{background:rgba(34,197,94,.15) !important;color:#4ade80 !important;}
body[data-chat-dark="1"] .sede-usage-label{color:rgba(255,255,255,.35) !important;}
body[data-chat-dark="1"] .sede-usage-value{color:rgba(255,255,255,.6) !important;}
body[data-chat-dark="1"] .sede-usage-track{background:rgba(255,255,255,.08) !important;}
body[data-chat-dark="1"] .sede-usage-reset{color:rgba(255,255,255,.2) !important;}

/* ── Usage Detail Button ── */
.sede-usage-detail-btn{
  display:flex !important;align-items:center !important;gap:4px !important;
  width:100% !important;padding:6px 8px !important;margin-top:6px !important;
  background:rgba(99,102,241,.08) !important;border:1px solid rgba(99,102,241,.15) !important;
  border-radius:6px !important;color:#6366f1 !important;font-size:11px !important;
  font-weight:600 !important;cursor:pointer !important;transition:all .15s !important;
}
.sede-usage-detail-btn:hover{background:rgba(99,102,241,.15) !important;}

/* ── Usage Modal ── */
.sede-usage-modal-overlay{
  position:fixed !important;inset:0 !important;z-index:9999 !important;
  align-items:center !important;justify-content:center !important;
  background:rgba(0,0,0,.4) !important;backdrop-filter:blur(8px) !important;
  opacity:0;transition:opacity .25s ease !important;
}
.sede-usage-modal-overlay.is-visible{opacity:1 !important;display:flex !important;}
.sede-usage-modal{
  width:680px !important;max-width:96vw !important;
  background:#fff !important;border-radius:16px !important;
  box-shadow:0 20px 60px rgba(0,0,0,.2) !important;
  transform:scale(0.95);transition:transform .25s cubic-bezier(.4,0,.2,1) !important;
  overflow:hidden !important;
}
.sede-usage-modal-overlay.is-visible .sede-usage-modal{transform:scale(1) !important;}
.sede-usage-modal-header{
  display:flex !important;align-items:center !important;gap:10px !important;
  padding:24px 32px !important;border-bottom:1px solid rgba(0,0,0,.06) !important;
}
.sede-usage-modal-title{font-size:20px !important;font-weight:700 !important;color:#1e293b !important;}
.sede-usage-modal-plan{
  font-size:10px !important;font-weight:700 !important;
  padding:2px 8px !important;border-radius:4px !important;
  background:rgba(34,197,94,.12) !important;color:#16a34a !important;
}
.sede-usage-modal-close{
  margin-left:auto !important;background:none !important;border:none !important;
  cursor:pointer !important;color:#94a3b8 !important;padding:4px !important;
  border-radius:6px !important;display:inline-flex !important;transition:all .15s !important;
}
.sede-usage-modal-close:hover{background:rgba(0,0,0,.06) !important;color:#1e293b !important;}
.sede-usage-modal-body{padding:28px 32px !important;}
.sede-usage-modal-section{margin-bottom:4px !important;}
.sede-usage-modal-section-head{
  display:flex !important;justify-content:space-between !important;align-items:center !important;
  margin-bottom:10px !important;
}
.sede-usage-modal-section-head > span:first-child{font-size:13px !important;font-weight:600 !important;color:#1e293b !important;}
.sede-usage-modal-reset{font-size:11px !important;color:#94a3b8 !important;}
.sede-usage-modal-row{
  display:flex !important;align-items:center !important;gap:10px !important;
  margin-bottom:8px !important;
}
.sede-usage-modal-label{font-size:14px !important;color:#64748b !important;width:36px !important;flex-shrink:0 !important;}
.sede-usage-modal-track{
  flex:1 !important;height:12px !important;background:rgba(0,0,0,.06) !important;
  border-radius:4px !important;overflow:hidden !important;
}
.sede-usage-modal-fill{
  height:100% !important;border-radius:4px !important;
  background:linear-gradient(90deg,#6366f1,#8b5cf6) !important;
  transition:width .4s ease !important;
}
.sede-usage-modal-fill.is-warn{background:linear-gradient(90deg,#f59e0b,#d97706) !important;}
.sede-usage-modal-fill.is-danger{background:linear-gradient(90deg,#ef4444,#dc2626) !important;}
.sede-usage-modal-pct{font-size:14px !important;font-weight:600 !important;color:#1e293b !important;width:40px !important;text-align:right !important;}
.sede-usage-modal-divider{
  height:1px !important;background:rgba(0,0,0,.06) !important;margin:12px 0 !important;
}
.sede-usage-modal-upgrade{padding-top:8px !important;}
.sede-usage-modal-upgrade-msg{
  display:flex !important;align-items:center !important;gap:8px !important;
  padding:10px 12px !important;margin-bottom:12px !important;
  background:rgba(245,158,11,.08) !important;border:1px solid rgba(245,158,11,.2) !important;
  border-radius:10px !important;font-size:12px !important;color:#92400e !important;
}
.sede-usage-modal-upgrade-btns{
  display:flex !important;gap:8px !important;
}
.sede-usage-modal-btn{
  flex:1 !important;padding:10px !important;border-radius:10px !important;
  font-size:13px !important;font-weight:600 !important;cursor:pointer !important;
  border:none !important;transition:all .15s !important;
}
.sede-usage-modal-btn.is-primary{
  background:#6366f1 !important;color:#fff !important;
}
.sede-usage-modal-btn.is-primary:hover{background:#4f46e5 !important;}
.sede-usage-modal-btn.is-secondary{
  background:rgba(0,0,0,.04) !important;color:#64748b !important;
}
.sede-usage-modal-btn.is-secondary:hover{background:rgba(0,0,0,.08) !important;}

/* Sede Search modal highlight */
.app-sede-search-highlight{background:#fecaca !important;color:#991b1b !important;border-radius:2px !important;padding:0 1px !important;}

/* ════════════ SETTINGS MODAL ════════════ */
.app-chat-settings-overlay{
  position:fixed !important;inset:0 !important;z-index:200000 !important;
  background:rgba(15,23,42,.18) !important;backdrop-filter:blur(16px) !important;-webkit-backdrop-filter:blur(16px) !important;
  display:flex !important;align-items:center !important;justify-content:center !important;
  animation:chatSearchFadeIn .16s ease !important;
}
.app-chat-settings-panel{
  background:var(--panel, #fff) !important;border-radius:20px !important;
  border:1px solid rgba(226,232,240,.8) !important;
  box-shadow:0 4px 6px rgba(15,23,42,.03),0 24px 64px rgba(15,23,42,.10) !important;
  width:440px !important;max-width:calc(100vw - 32px) !important;
  max-height:min(580px, 80vh) !important;display:flex !important;flex-direction:column !important;
  overflow:hidden !important;animation:chatSearchSlideDown .2s cubic-bezier(.22,1,.36,1) !important;
}
.app-chat-settings-header{
  display:flex !important;align-items:center !important;
  padding:18px 20px 14px !important;border-bottom:1px solid var(--border, rgba(0,0,0,.06)) !important;
}
.app-chat-settings-header-title{
  flex:1 !important;font-size:17px !important;font-weight:700 !important;color:var(--melta-text-heading, #0f172a) !important;letter-spacing:-0.01em !important;
}
.app-chat-settings-close{
  width:30px !important;height:30px !important;display:inline-grid !important;place-items:center !important;
  border-radius:8px !important;cursor:pointer !important;color:var(--muted, rgba(29,29,31,.56)) !important;transition:background .12s ease !important;
}
.app-chat-settings-close:hover{background:rgba(0,0,0,.06) !important;}
.app-chat-settings-body{
  flex:1 !important;overflow-y:auto !important;padding:16px 20px 20px !important;
  display:flex !important;flex-direction:column !important;gap:18px !important;
}
.app-chat-settings-row{
  display:flex !important;flex-direction:column !important;gap:6px !important;
}
.app-chat-settings-label{
  font-size:12px !important;font-weight:600 !important;color:var(--melta-text-muted, #64748b) !important;
  text-transform:uppercase !important;letter-spacing:.06em !important;
}
/* Segment: reuse existing .seg component */
.app-chat-settings-body .seg{
  display:flex !important;width:100% !important;
}
.app-chat-settings-body .seg button{
  flex:1 !important;text-align:center !important;padding:7px 0 !important;
}
/* Select: reuse existing input styling */
.app-chat-settings-body select{
  width:100% !important;padding:8px 12px !important;border-radius:10px !important;
  border:1px solid var(--melta-input-border, #cbd5e1) !important;background:var(--melta-input-bg, #fff) !important;
  font-size:13.5px !important;color:var(--text, #1d1d1f) !important;font-family:inherit !important;
  outline:none !important;cursor:pointer !important;
}
.app-chat-settings-body select:focus{border-color:var(--melta-primary-400, #6492ff) !important;box-shadow:0 0 0 3px rgba(99,102,241,.10) !important;}
/* Toggle: reuse existing .toggle component */
.app-chat-settings-toggle-row{
  display:flex !important;align-items:center !important;justify-content:space-between !important;
}
.app-chat-settings-toggle-row .toggle{
  flex-direction:row-reverse !important;flex:1 !important;justify-content:space-between !important;
}
.app-chat-settings-toggle-row .toggle span{
  font-size:14px !important;font-weight:500 !important;color:var(--text, #1d1d1f) !important;
}

/* ════════════ APP SYSTEM ════════════ */
/* App list modal */
.app-chat-app-overlay{
  position:fixed !important;inset:0 !important;z-index:200000 !important;
  background:rgba(15,23,42,.18) !important;backdrop-filter:blur(16px) !important;-webkit-backdrop-filter:blur(16px) !important;
  display:flex !important;align-items:center !important;justify-content:center !important;
  animation:chatSearchFadeIn .16s ease !important;
}
.app-chat-app-panel{
  background:var(--panel, #fff) !important;border-radius:20px !important;
  border:1px solid rgba(226,232,240,.8) !important;
  box-shadow:0 4px 6px rgba(15,23,42,.03),0 24px 64px rgba(15,23,42,.10) !important;
  width:520px !important;max-width:calc(100vw - 32px) !important;
  max-height:min(560px, 78vh) !important;display:flex !important;flex-direction:column !important;
  overflow:hidden !important;animation:chatSearchSlideDown .2s cubic-bezier(.22,1,.36,1) !important;
}
.app-chat-app-header{
  display:flex !important;align-items:center !important;gap:10px !important;
  padding:18px 20px 14px !important;border-bottom:1px solid var(--border, rgba(0,0,0,.06)) !important;
}
.app-chat-app-header .ms{font-size:22px !important;color:var(--melta-primary-500, #6366f1) !important;}
.app-chat-app-header-title{flex:1 !important;font-size:17px !important;font-weight:700 !important;color:var(--melta-text-heading, #0f172a) !important;}
.app-chat-app-body{flex:1 !important;overflow-y:auto !important;padding:8px 12px 16px !important;}
.app-chat-app-item{
  display:flex !important;align-items:center !important;gap:14px !important;
  padding:14px 12px !important;border-radius:12px !important;
  transition:background .12s ease !important;
}
.app-chat-app-item:hover{background:rgba(0,0,0,.03) !important;}
.app-chat-app-icon{
  width:40px !important;height:40px !important;border-radius:10px !important;
  display:inline-flex !important;align-items:center !important;justify-content:center !important;
  flex-shrink:0 !important;font-size:20px !important;
}
.app-chat-app-info{flex:1 !important;min-width:0 !important;}
.app-chat-app-name{font-size:14px !important;font-weight:600 !important;color:var(--text, #1d1d1f) !important;}
.app-chat-app-desc{font-size:12px !important;color:var(--melta-text-muted, #64748b) !important;margin-top:2px !important;line-height:1.4 !important;}
.app-chat-app-setup-btn{
  flex-shrink:0 !important;padding:6px 14px !important;border-radius:8px !important;
  font-size:12px !important;font-weight:600 !important;cursor:pointer !important;
  border:1px solid var(--melta-border-default, #e2e8f0) !important;background:var(--panel, #fff) !important;color:var(--text, #1d1d1f) !important;
  transition:background .12s ease !important;
}
.app-chat-app-setup-btn:hover{background:#f8fafc !important;}
.app-chat-app-setup-btn.is-done{
  background:#f0fdf4 !important;color:#15803d !important;border-color:#bbf7d0 !important;
  cursor:default !important;pointer-events:none !important;
}
/* App window */
.app-chat-app-window{
  position:fixed !important;z-index:9990 !important;
  background:var(--panel, #fff) !important;border-radius:20px !important;
  border:1px solid rgba(226,232,240,.8) !important;
  box-shadow:0 4px 6px rgba(15,23,42,.03),0 24px 64px rgba(15,23,42,.10) !important;
  display:flex !important;flex-direction:column !important;overflow:hidden !important;
  animation:chatSearchSlideDown .22s cubic-bezier(.22,1,.36,1) !important;
  resize:both !important;
}
.app-chat-app-window-bar{
  display:flex !important;align-items:center !important;gap:8px !important;
  padding:10px 14px !important;border-bottom:1px solid var(--border, rgba(0,0,0,.06)) !important;
  cursor:grab !important;user-select:none !important;flex-shrink:0 !important;
}
.app-chat-app-window-bar-title{flex:1 !important;font-size:13px !important;font-weight:600 !important;color:var(--text, #1d1d1f) !important;}
.app-chat-app-window-btn{
  width:24px !important;height:24px !important;display:inline-grid !important;place-items:center !important;
  border-radius:6px !important;cursor:pointer !important;color:var(--muted, rgba(29,29,31,.56)) !important;
  transition:background .12s ease,color .12s ease !important;
}
.app-chat-app-window-btn:hover{background:rgba(0,0,0,.06) !important;color:var(--text, #1d1d1f) !important;}
.app-chat-app-window-btn .ms{font-size:16px !important;}
.app-chat-app-window-body{flex:1 !important;overflow:auto !important;padding:16px !important;}
/* Minimized app icons in topbar */
.app-chat-topbar-apps{
  display:flex !important;align-items:center !important;gap:2px !important;margin-left:8px !important;
}
.app-chat-topbar-app-icon{
  width:28px !important;height:28px !important;border-radius:8px !important;
  display:inline-flex !important;align-items:center !important;justify-content:center !important;
  font-size:14px !important;cursor:pointer !important;
  transition:transform .18s ease,opacity .18s ease !important;
  box-shadow:0 1px 3px rgba(0,0,0,.08) !important;
}
.app-chat-topbar-app-icon:not(:first-child){margin-left:-6px !important;}
.app-chat-topbar-app-more{
  width:28px !important;height:28px !important;border-radius:8px !important;
  display:inline-flex !important;align-items:center !important;justify-content:center !important;
  font-size:10px !important;font-weight:700 !important;color:var(--melta-text-muted, #64748b) !important;
  background:var(--melta-bg-page, #f9fafb) !important;cursor:pointer !important;margin-left:-6px !important;
}

/* ═══ Sede collapsed icon strip ═══ */
#appAiChatShell.sidebar-collapsed[data-chat-mode="sede"] .app-sede-sidebar{display:flex !important;}
#appAiChatShell.sidebar-collapsed .app-sede-head-title{display:none !important;}
#appAiChatShell.sidebar-collapsed .app-sede-nav{align-items:center !important;padding:4px 0 !important;}
#appAiChatShell.sidebar-collapsed .app-sede-nav-item{
  width:40px !important;height:40px !important;padding:0 !important;justify-content:center !important;border-radius:10px !important;
}
#appAiChatShell.sidebar-collapsed .app-sede-nav-item > span:not(.ms){display:none !important;}
#appAiChatShell.sidebar-collapsed .app-sede-section-head{display:none !important;}
#appAiChatShell.sidebar-collapsed .app-sede-session-list{display:none !important;}
#appAiChatShell.sidebar-collapsed .app-sede-empty{display:none !important;}
