  border-radius:6px !important;cursor:pointer !important;padding:0 !important;font-size:0 !important;box-shadow:none !important;
  transition:background .12s ease,color .12s ease !important;
}
body #appAiChatShell .app-chat-mini-action:hover{background:rgba(0,0,0,.06) !important;color:var(--text, #1d1d1f) !important;}
body #appAiChatShell .app-chat-mini-action.is-active{color:var(--melta-primary-500, #6366f1) !important;}
body #appAiChatShell .app-chat-mini-action .ms{font-size:18px !important;}

/* ══ TTS: 5-bar sound wave + pulse ring ══ */
body #appAiChatShell .app-chat-mini-action.is-tts-playing{
  color:var(--melta-primary-500, #6366f1) !important;position:relative !important;overflow:visible !important;
}
body #appAiChatShell .app-chat-mini-action.is-tts-playing .ms{display:none !important;}
body #appAiChatShell .app-chat-mini-action.is-tts-playing::before{
  content:'' !important;position:absolute !important;inset:-4px !important;border-radius:50% !important;
  border:2px solid var(--melta-primary-300, #95b6ff) !important;
  animation:ttsPulseRing 1.2s ease-out infinite !important;pointer-events:none !important;
}
@keyframes ttsPulseRing{0%{transform:scale(.8);opacity:.6;}100%{transform:scale(1.6);opacity:0;}}
body #appAiChatShell .app-chat-mini-action.is-tts-playing::after{
  content:'' !important;position:absolute !important;top:50% !important;left:50% !important;
  transform:translate(-50%,-50%) !important;width:18px !important;height:14px !important;
  display:flex !important;align-items:flex-end !important;gap:2px !important;
  background:
    linear-gradient(var(--melta-primary-500,#6366f1),var(--melta-primary-500,#6366f1)) 0 100%/2px var(--b1,40%) no-repeat,
    linear-gradient(var(--melta-primary-500,#6366f1),var(--melta-primary-500,#6366f1)) 4px 100%/2px var(--b2,70%) no-repeat,
    linear-gradient(var(--melta-primary-500,#6366f1),var(--melta-primary-500,#6366f1)) 8px 100%/2px var(--b3,50%) no-repeat,
    linear-gradient(var(--melta-primary-500,#6366f1),var(--melta-primary-500,#6366f1)) 12px 100%/2px var(--b4,80%) no-repeat,
    linear-gradient(var(--melta-primary-500,#6366f1),var(--melta-primary-500,#6366f1)) 16px 100%/2px var(--b5,35%) no-repeat !important;
  animation:ttsWave5 .7s ease-in-out infinite alternate !important;
}
@keyframes ttsWave5{
  0%  {--b1:25%;--b2:65%;--b3:40%;--b4:80%;--b5:30%;}
  25% {--b1:55%;--b2:35%;--b3:70%;--b4:45%;--b5:60%;}
  50% {--b1:40%;--b2:75%;--b3:30%;--b4:60%;--b5:80%;}
  75% {--b1:70%;--b2:45%;--b3:65%;--b4:30%;--b5:50%;}
  100%{--b1:30%;--b2:60%;--b3:80%;--b4:50%;--b5:35%;}
}

/* ══ Thumbs up: black fill + bounce + gold star particles ══ */
body #appAiChatShell .app-chat-mini-action.is-good{
  background:#000 !important;color:#fff !important;border-radius:50% !important;
  position:relative !important;overflow:visible !important;
  animation:thumbBounce .4s cubic-bezier(.34,1.56,.64,1) !important;
}
body #appAiChatShell .app-chat-mini-action.is-good .ms{color:#fff !important;}
@keyframes thumbBounce{
  0%{transform:scale(1);}25%{transform:scale(1.4);}50%{transform:scale(.9);}75%{transform:scale(1.1);}100%{transform:scale(1);}
}
/* 8 gold particles */
body #appAiChatShell .app-chat-mini-action.is-good::before,
body #appAiChatShell .app-chat-mini-action.is-good::after{
  content:'' !important;position:absolute !important;top:50% !important;left:50% !important;
  width:5px !important;height:5px !important;border-radius:50% !important;
  pointer-events:none !important;
}
body #appAiChatShell .app-chat-mini-action.is-good::before{
  box-shadow:
    0 0 0 #FFD700, 0 0 0 #FF6B6B, 0 0 0 #4ECDC4, 0 0 0 #FFE66D,
    0 0 0 #FF8A5C, 0 0 0 #A8E6CF, 0 0 0 #DDA0DD, 0 0 0 #87CEEB !important;
  animation:sparkle8 .6s ease-out forwards !important;
}
@keyframes sparkle8{
  0%{box-shadow:0 0 0 #FFD700,0 0 0 #FF6B6B,0 0 0 #4ECDC4,0 0 0 #FFE66D,0 0 0 #FF8A5C,0 0 0 #A8E6CF,0 0 0 #DDA0DD,0 0 0 #87CEEB;opacity:1;}
  100%{box-shadow:-14px -14px 0 #FFD700,14px -14px 0 #FF6B6B,14px 14px 0 #4ECDC4,-14px 14px 0 #FFE66D,0 -18px 0 #FF8A5C,18px 0 0 #A8E6CF,0 18px 0 #DDA0DD,-18px 0 0 #87CEEB;opacity:0;}
}

/* ══ Thumbs down: black fill + shake + dark pulse ══ */
body #appAiChatShell .app-chat-mini-action.is-bad{
  background:#000 !important;color:#fff !important;border-radius:50% !important;
  position:relative !important;
  animation:thumbShake .4s ease !important;
  box-shadow:0 0 0 rgba(0,0,0,0) !important;
}
body #appAiChatShell .app-chat-mini-action.is-bad .ms{color:#fff !important;}
body #appAiChatShell .app-chat-mini-action.is-bad::before{
  content:'' !important;position:absolute !important;inset:-3px !important;border-radius:50% !important;
  pointer-events:none !important;
  box-shadow:0 0 8px rgba(0,0,0,.5) !important;
  animation:darkPulse .8s ease-out forwards !important;
}
@keyframes darkPulse{0%{opacity:1;transform:scale(1);}100%{opacity:0;transform:scale(1.4);}}
@keyframes thumbShake{
  0%,100%{transform:translateX(0);}
  12%{transform:translateX(-6px);}
  25%{transform:translateX(6px);}
  37%{transform:translateX(-5px);}
  50%{transform:translateX(5px);}
  62%{transform:translateX(-3px);}
  75%{transform:translateX(3px);}
}

