/* ════════════ MOBILE ════════════ */
@media(max-width:960px){
  #appAiChatShell{grid-template-columns:1fr !important;border-radius:0 !important;}

  /* ── Topbar: always visible, compact ── */
  #appAiChatShell .app-chat-topbar{
    display:flex !important;align-items:center !important;
    padding:8px 10px !important;gap:6px !important;
    position:sticky !important;top:0 !important;z-index:10 !important;
    background:#fff !important;
    border-bottom:1px solid rgba(0,0,0,.06) !important;
  }
  /* Sidebar toggle (chat history) — left */
  #appAiChatShell .app-chat-topbar-btn[data-chat-action="toggleSidebar"]{
    display:inline-grid !important;
    width:36px !important;height:36px !important;
    border-radius:10px !important;
  }
  /* Model trigger — compact on mobile */
  #appAiChatShell .app-chat-model-trigger{
    font-size:15px !important;
  }
  /* Menu button (VQ main menu) — right */
  #appAiChatShell #appChatMenuBtn{
    display:inline-grid !important;
    width:36px !important;height:36px !important;
    border-radius:10px !important;
  }

  /* ── Dark sidebar overlay — chat history ── */
  #appAiChatShell > .app-chat-history-side{
    position:fixed !important;inset:0 auto 0 0 !important;
    width:min(320px,85vw) !important;
    transform:translateX(-100%) !important;opacity:0 !important;pointer-events:none !important;
    z-index:60 !important;
    transition:transform .32s cubic-bezier(.32,1,.23,1),opacity .24s ease !important;
    box-shadow:6px 0 32px rgba(0,0,0,.3) !important;
    border-radius:0 20px 20px 0 !important;
  }
  #appAiChatShell[data-sidebar-open="1"] > .app-chat-history-side{
    transform:translateX(0) !important;opacity:1 !important;pointer-events:auto !important;
  }
  /* Backdrop for dark sidebar */
  #appAiChatShell::before{
    content:'' !important;display:block !important;
    position:fixed !important;inset:0 !important;z-index:55 !important;
    background:rgba(0,0,0,.3) !important;
    backdrop-filter:blur(2px) !important;-webkit-backdrop-filter:blur(2px) !important;
    opacity:0 !important;pointer-events:none !important;
    transition:opacity .28s ease !important;
  }
  #appAiChatShell[data-sidebar-open="1"]::before{
    opacity:1 !important;pointer-events:auto !important;
  }
  /* Close sidebar on backdrop tap */
  #appAiChatShell .app-chat-sidebar-top{
    padding:12px 14px 10px !important;
  }

  /* ── VQ left panel via toggleMainMenu ── */
  body.app-chat-fullscreen.app-chat-menu-open .app-tabbar{
    z-index:130 !important;
    transform:translateX(0) !important;
    opacity:1 !important;pointer-events:auto !important;
  }
  body.app-chat-fullscreen.app-chat-menu-open .app-v2-sidebar-backdrop{
    opacity:1 !important;pointer-events:auto !important;
    z-index:125 !important;
  }
  body.app-chat-menu-open #appChatPage{
    left:0 !important;
  }

  /* ── Messages — compact ── */
  #appAiChatShell .app-chat-msg{
    padding:16px 14px !important;
    grid-template-columns:28px minmax(0,1fr) !important;gap:0 10px !important;
  }
  #appAiChatShell .app-chat-role-icon{width:28px !important;height:28px !important;}
  #appAiChatShell .app-chat-role-icon .ms{font-size:15px !important;}

  /* ── Empty state ── */
  #appAiChatShell .app-chat-empty-state{padding:0 16px 24px !important;}
  #appAiChatShell .app-chat-empty-hero h3{font-size:22px !important;}
  #appAiChatShell .app-chat-empty-chip-grid{grid-template-columns:1fr !important;gap:14px !important;}

  /* ── Composer — lifted above iPhone home indicator ── */
  #appAiChatShell .app-chat-bottom-dock{
    width:calc(100% - 20px) !important;
    margin:0 auto !important;
    margin-bottom:max(14px, calc(env(safe-area-inset-bottom, 0px) + 8px)) !important;
    padding-bottom:0 !important;
  }
}

/* ════════════════════════════════════════════════
   Apple-feel global polish — rounded, glass, soft
   ════════════════════════════════════════════════ */

/* Overlays & modals — frosted glass */
body[data-ui-v2="1"] .overlay,
body[data-ui-v2="1"] .menu-article{
  border-radius: 20px;
  box-shadow: 0 4px 24px rgba(0,0,0,.08), 0 0 0 0.5px rgba(0,0,0,.04);
}

/* Toggle switch — Apple pill style */
.toggle input{
  border-radius: 999px !important;
  transition: background .25s cubic-bezier(.22,1,.36,1), border-color .25s ease !important;
}
.toggle input:checked{
  background: #34c759 !important;
  border-color: #34c759 !important;
}

/* Smooth scrolling everywhere */
body[data-ui-v2="1"] *{
  scroll-behavior: smooth;
}

/* Settings rows — subtle separator */
body[data-ui-v2="1"] .settings-row{
  transition: background .18s ease;
}
body[data-ui-v2="1"] .settings-row:active{
  background: rgba(0,0,0,.02);
}

/* Focus ring — Apple blue */
body[data-ui-v2="1"] :focus-visible{
  outline: none;
  box-shadow: 0 0 0 3px rgba(0,122,255,.25);
}

/* Progress bars — Apple green */
body[data-ui-v2="1"] .progress-fill{
  border-radius: 999px;
}

/* xselect trigger — Apple pill */
body[data-ui-v2="1"] .xselect-trigger{
  border-radius: var(--radius, 12px) !important;
  box-shadow: 0 1px 3px rgba(0,0,0,.04), 0 0 0 0.5px rgba(0,0,0,.03) !important;
  transition: border-color .2s ease, box-shadow .2s ease !important;
}
body[data-ui-v2="1"] .xselect-trigger:focus,
body[data-ui-v2="1"] .xselect-trigger.is-open{
  box-shadow: 0 1px 4px rgba(0,0,0,.06), 0 0 0 3px rgba(0,122,255,.12) !important;
}

/* xselect dropdown panel — Apple frosted popover */
body[data-ui-v2="1"] .xselect-dropdown{
  border-radius: var(--radius, 12px) !important;
  border: 1px solid rgba(0,0,0,.06) !important;
  background: rgba(255,255,255,.94) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  box-shadow: 0 8px 32px rgba(0,0,0,.1), 0 0 0 0.5px rgba(0,0,0,.04) !important;
}
body[data-ui-v2="1"] .xselect-option{
  border-radius: 10px !important;
  transition: background .15s ease !important;
}

/* Sidebar footer profile card — Apple vibrancy */
body[data-ui-v2="1"] .app-v2-account{
  border-radius: 16px;
  background: rgba(0,0,0,.03);
  border-color: rgba(0,0,0,.06);
}
body[data-ui-v2="1"] .app-v2-account:hover{
  background: rgba(0,122,255,.06);
  border-color: rgba(0,122,255,.12);
}

/* Sidebar logo — Apple blue */
body[data-ui-v2="1"] .app-v2-sidebar-logo{
  background: linear-gradient(135deg, #007aff, #0055d4) !important;
  box-shadow: 0 3px 10px rgba(0,122,255,.28) !important;
}

/* Header border subtle */
body[data-ui-v2="1"] .app-v2-sidebar-head{
  border-bottom-color: rgba(0,0,0,.05) !important;
}
body[data-ui-v2="1"] .app-v2-sidebar-foot{
  border-top-color: rgba(0,0,0,.05) !important;
}

/* ══════════════════════════════════════════════════════════
   FINAL OVERRIDE — Chat composer (cascade-last = always wins)
   ══════════════════════════════════════════════════════════ */

/* ═══ Composer — single source of truth ═══ */
body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] #appAiChatShell .app-chat-composer,
body #appAiChatShell .app-chat-composer{
  display:flex !important;flex-direction:column !important;align-items:stretch !important;
  position:static !important;width:100% !important;
  margin:0 auto !important;padding:0 !important;
  border-radius:24px !important;
  border:1px solid var(--melta-border-default, #e2e8f0) !important;
  background:var(--panel, #fff) !important;
  box-shadow:0 2px 12px rgba(15,23,42,.06),0 8px 32px rgba(15,23,42,.08) !important;
  overflow:hidden !important;min-height:0 !important;
  left:auto !important;bottom:auto !important;transform:none !important;
  backdrop-filter:none !important;z-index:1 !important;
  transition:border-color .2s ease,box-shadow .2s ease !important;
}
body #appAiChatShell .app-chat-composer:focus-within{
  border-color:var(--melta-primary-300, #95b6ff) !important;
  box-shadow:0 2px 12px rgba(15,23,42,.06),0 12px 40px rgba(15,23,42,.12),0 0 0 3px rgba(99,102,241,.08) !important;
}
/* Composer toolbar — bottom row inside composer */
.app-chat-composer-toolbar{
  display:flex !important;align-items:center !important;gap:2px !important;
  padding:4px 8px 6px !important;border-top:1px solid var(--border, rgba(0,0,0,.06)) !important;
}
.app-chat-composer-toolbar-left{display:flex !important;align-items:center !important;gap:2px !important;flex:1 !important;}
.app-chat-composer-toolbar-right{display:flex !important;align-items:center !important;}
.app-chat-toolbar-btn{
  width:32px !important;height:32px !important;display:inline-grid !important;place-items:center !important;
  border-radius:8px !important;cursor:pointer !important;border:0 !important;
  background:transparent !important;box-shadow:none !important;
  color:var(--muted, rgba(29,29,31,.56)) !important;transition:background .12s ease,color .12s ease !important;
}
.app-chat-toolbar-btn:hover{background:rgba(0,0,0,.06) !important;color:var(--text, #1d1d1f) !important;}
.app-chat-toolbar-btn.is-active{color:var(--melta-primary-500, #6366f1) !important;background:rgba(99,102,241,.08) !important;}
.app-chat-toolbar-btn .ms{font-size:20px !important;}
/* Disclaimer */
.app-chat-disclaimer{
  font-size:11px !important;color:#94a3b8 !important;
  text-align:center !important;padding:4px 12px 8px !important;line-height:1.4 !important;
}

/* ═══ Floating composer — absolute over scroll area ═══ */
body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] #appAiChatShell > .app-chat-main-panel,
body #appAiChatShell > .app-chat-main-panel{
