}
body[data-app-tab="chat"] .app-chat-shell,
body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] #appAiChatShell,
body #appAiChatShell,
body[data-app-tab="chat"] #appChatPage[data-collab-pane="ai"] .app-chat-main-panel,
