/* ══════════════════════════════════════════════════════════════
   VQ Preset Generator UI — new namespace (vq-pg-*)
   Uses --ds-* tokens only. No legacy class conflicts.
   ══════════════════════════════════════════════════════════════ */

/* ── Hide legacy process panel — replaced by inline vq-pg-steps ── */
body #appAiChatShell .app-chat-process-panel{
  display:none !important;
}
/* Prevent old process panel from creating 3-column grid */
body #appAiChatShell[data-process-panel-open="1"]{
  grid-template-columns:minmax(0,1fr) !important;
}

/* attachment styling — moved to FINAL OVERRIDE block below */

/* ── Attach button inside composer — left of input ── */
body #appAiChatShell .vq-attach-btn{
  width:36px;height:36px;flex:0 0 36px;
  display:inline-grid;place-items:center;
  border:0;border-radius:50%;
  background:transparent;color:#b0b0b0;
  cursor:pointer;margin:0 0 6px 6px;padding:0;
  transition:background .15s ease,color .15s ease;
  box-shadow:none;align-self:flex-end;
}
body #appAiChatShell .vq-attach-btn:hover{
  background:rgba(0,0,0,.04);color:#666;
}
body #appAiChatShell .vq-attach-btn .ms{font-size:20px;}

/* ── Professor mode gate banner ── */
.vq-pg-professor-gate{
  display:flex;align-items:center;gap:10px;
  padding:12px 16px;
  border-radius:var(--ds-radius-md,16px);
  background:color-mix(in srgb,var(--ds-primary,#2a66f6) 6%,var(--ds-surface,#fff));
  border:1px solid color-mix(in srgb,var(--ds-primary,#2a66f6) 14%,transparent);
  margin-top:8px;
  animation:vq-pg-fadein .3s ease;
}
.vq-pg-professor-gate-icon{
  width:32px;height:32px;border-radius:10px;flex:0 0 32px;
  display:grid;place-items:center;
  background:var(--ds-primary,#2a66f6);color:var(--ds-primary-text,#fff);
}
.vq-pg-professor-gate-icon .ms{font-size:16px;}
.vq-pg-professor-gate-copy{flex:1;min-width:0;font-size:13px;color:var(--ds-text,#121826);line-height:1.5;}
.vq-pg-professor-gate-copy strong{font-weight:600;}
.vq-pg-professor-gate-btn{
  flex:0 0 auto;height:32px;padding:0 14px;border:0;
  border-radius:999px;font-size:12px;font-weight:600;cursor:pointer;
  background:var(--ds-primary,#2a66f6);color:var(--ds-primary-text,#fff);
  transition:opacity .15s ease;
}
.vq-pg-professor-gate-btn:hover{opacity:.85;}

/* ── Step log — Claude Code style (inline in chat bubble) ── */
.vq-pg-steps{
  margin-top:10px;
  border:1px solid var(--ds-divider,rgba(15,23,42,.08));
  border-radius:var(--ds-radius-md,16px);
  background:var(--ds-surface,#fff);
  overflow:hidden;
  animation:vq-pg-fadein .25s ease;
}
.vq-pg-steps-toggle{
  width:100%;display:flex;align-items:center;gap:8px;
  padding:10px 14px;border:0;background:transparent;cursor:pointer;
  font-size:12px;font-weight:600;color:var(--ds-text-soft,#5f6b82);
  text-align:left;
}
.vq-pg-steps-toggle .ms{font-size:16px;transition:transform .2s ease;}
.vq-pg-steps[data-collapsed="1"] .vq-pg-steps-toggle .ms.vq-pg-chev{transform:rotate(-90deg);}
.vq-pg-steps-toggle-count{
  margin-left:auto;font-size:11px;font-weight:500;color:var(--ds-text-soft,#5f6b82);
}
.vq-pg-steps-body{
  padding:0 14px 12px;display:grid;gap:4px;
}
.vq-pg-steps[data-collapsed="1"] .vq-pg-steps-body{display:none;}

/* Individual step */
.vq-pg-step{
  display:flex;align-items:flex-start;gap:8px;
  padding:4px 0;font-size:13px;line-height:1.5;
  color:var(--ds-text,#121826);
  animation:vq-pg-step-in .3s cubic-bezier(.22,1,.36,1);
}
.vq-pg-step-icon{
  width:18px;height:18px;flex:0 0 18px;
  display:grid;place-items:center;margin-top:1px;
}
.vq-pg-step-icon .ms{font-size:16px;}
.vq-pg-step-icon.is-done{color:#22c55e;}
.vq-pg-step-icon.is-active{color:var(--ds-primary,#2a66f6);animation:vq-pg-pulse 1.2s ease infinite;}
.vq-pg-step-icon.is-error{color:#ef4444;}
.vq-pg-step-text{flex:1;min-width:0;}
.vq-pg-step-meta{
  flex:0 0 auto;font-size:11px;color:var(--ds-text-soft,#5f6b82);
  margin-left:auto;white-space:nowrap;
}

/* Steps footer */
.vq-pg-steps-foot{
  display:flex;align-items:center;gap:10px;
  padding:10px 14px;border-top:1px solid var(--ds-divider,rgba(15,23,42,.08));
  font-size:12px;color:var(--ds-text-soft,#5f6b82);
}
.vq-pg-steps-foot-file{
  flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}

/* Progress bar */
.vq-pg-progress{
  height:3px;background:var(--ds-divider,rgba(15,23,42,.08));
  border-radius:999px;overflow:hidden;
}
.vq-pg-progress-bar{
  height:100%;border-radius:999px;
  background:var(--ds-primary,#2a66f6);
  transition:width .4s cubic-bezier(.22,1,.36,1);
}

/* ── Preview card ── */
.vq-pg-card{
  margin-top:12px;
  border:1px solid var(--ds-divider,rgba(15,23,42,.08));
  border-radius:var(--ds-radius-md,16px);
  background:var(--ds-surface,#fff);
  box-shadow:var(--ds-shadow-xs,0 1px 2px rgba(15,23,42,.04));
  overflow:hidden;
  animation:vq-pg-card-in .4s cubic-bezier(.22,1,.36,1);
}
.vq-pg-card-head{
  padding:16px 16px 12px;
  border-bottom:1px solid var(--ds-divider,rgba(15,23,42,.08));
}
.vq-pg-card-title{font-size:15px;font-weight:700;color:var(--ds-text,#121826);display:flex;align-items:center;gap:8px;}
.vq-pg-card-title .ms{font-size:18px;color:var(--ds-primary,#2a66f6);}
.vq-pg-card-meta{
  display:flex;gap:8px;margin-top:6px;flex-wrap:wrap;
}
.vq-pg-card-badge{
  display:inline-flex;align-items:center;gap:4px;
  height:22px;padding:0 8px;border-radius:999px;
  background:var(--ds-surface-soft,#f2f4fa);
  font-size:11px;font-weight:600;color:var(--ds-text-soft,#5f6b82);
}

/* Question list */
.vq-pg-questions{
  padding:8px 0;max-height:400px;overflow-y:auto;
}
.vq-pg-q{
  padding:10px 16px;display:grid;gap:4px;
  border-bottom:1px solid var(--ds-divider,rgba(15,23,42,.08));
  opacity:0;animation:vq-pg-q-in .35s cubic-bezier(.22,1,.36,1) forwards;
}
.vq-pg-q:last-child{border-bottom:0;}
.vq-pg-q-head{
  display:flex;align-items:baseline;gap:6px;
  font-size:13px;color:var(--ds-text,#121826);line-height:1.5;
}
.vq-pg-q-num{
  font-size:11px;font-weight:700;color:var(--ds-primary,#2a66f6);
  flex:0 0 auto;
}
.vq-pg-q-text{flex:1;min-width:0;}
.vq-pg-q-choices{
  display:grid;grid-template-columns:1fr 1fr;gap:3px 12px;
  padding-left:26px;font-size:12px;color:var(--ds-text-soft,#5f6b82);
}
.vq-pg-q-choice{display:flex;align-items:center;gap:4px;}
.vq-pg-q-choice.is-correct{color:var(--ds-text,#121826);font-weight:600;}
.vq-pg-q-choice .ms{font-size:14px;}

/* Card actions */
.vq-pg-card-actions{
  display:flex;gap:8px;padding:12px 16px;
  border-top:1px solid var(--ds-divider,rgba(15,23,42,.08));
  opacity:0;animation:vq-pg-fadein .3s ease .2s forwards;
}
.vq-pg-card-action{
  height:36px;padding:0 16px;border:0;border-radius:999px;
  font-size:13px;font-weight:600;cursor:pointer;
  display:inline-flex;align-items:center;gap:6px;
  transition:opacity .15s ease,background .15s ease;
}
.vq-pg-card-action.is-primary{
  background:var(--ds-primary,#2a66f6);color:var(--ds-primary-text,#fff);
}
.vq-pg-card-action.is-primary:hover{opacity:.85;}
.vq-pg-card-action.is-secondary{
  background:var(--ds-surface-soft,#f2f4fa);color:var(--ds-text,#121826);
}
.vq-pg-card-action.is-secondary:hover{background:color-mix(in srgb,var(--ds-surface-soft,#f2f4fa) 80%,var(--ds-primary,#2a66f6));}
.vq-pg-card-action .ms{font-size:16px;}

/* ── Edit mode ── */
.vq-pg-edit{
  padding:14px 16px;
  border:1px solid color-mix(in srgb,var(--ds-primary,#2a66f6) 18%,var(--ds-divider,rgba(15,23,42,.08)));
  border-radius:var(--ds-radius-md,16px);
  background:color-mix(in srgb,var(--ds-primary,#2a66f6) 3%,var(--ds-surface,#fff));
  display:grid;gap:10px;
  animation:vq-pg-fadein .25s ease;
}
.vq-pg-edit-label{font-size:11px;font-weight:700;color:var(--ds-text-soft,#5f6b82);text-transform:uppercase;letter-spacing:.06em;}
.vq-pg-edit-input{
  width:100%;padding:8px 12px;border:1px solid var(--ds-divider,rgba(15,23,42,.08));
  border-radius:10px;font-size:14px;color:var(--ds-text,#121826);
  background:var(--ds-surface,#fff);outline:none;
  transition:border-color .15s ease,box-shadow .15s ease;
}
.vq-pg-edit-input:focus{
  border-color:color-mix(in srgb,var(--ds-primary,#2a66f6) 40%,transparent);
  box-shadow:0 0 0 3px color-mix(in srgb,var(--ds-primary,#2a66f6) 10%,transparent);
}
.vq-pg-edit-choices{display:grid;gap:6px;}
.vq-pg-edit-choice{
  display:flex;align-items:center;gap:8px;
}
.vq-pg-edit-choice input[type="radio"]{
  width:16px;height:16px;accent-color:var(--ds-primary,#2a66f6);flex:0 0 16px;
}
.vq-pg-edit-actions{
  display:flex;gap:8px;margin-top:4px;
}

/* ── Animations ── */
@keyframes vq-pg-fadein{
  from{opacity:0;transform:translateY(6px);}
  to{opacity:1;transform:translateY(0);}
}
@keyframes vq-pg-card-in{
  from{opacity:0;transform:translateY(16px);}
  to{opacity:1;transform:translateY(0);}
}
@keyframes vq-pg-q-in{
  from{opacity:0;transform:translateX(-8px);}
  to{opacity:1;transform:translateX(0);}
}
@keyframes vq-pg-step-in{
  from{opacity:0;transform:translateY(4px);}
  to{opacity:1;transform:translateY(0);}
}
@keyframes vq-pg-pulse{
  0%,100%{opacity:1;}
  50%{opacity:.4;}
}

/* Question stagger delays (CSS-only, up to 20) */
.vq-pg-q:nth-child(1){animation-delay:.05s;}
.vq-pg-q:nth-child(2){animation-delay:.1s;}
.vq-pg-q:nth-child(3){animation-delay:.15s;}
.vq-pg-q:nth-child(4){animation-delay:.2s;}
.vq-pg-q:nth-child(5){animation-delay:.25s;}
.vq-pg-q:nth-child(6){animation-delay:.3s;}
.vq-pg-q:nth-child(7){animation-delay:.35s;}
.vq-pg-q:nth-child(8){animation-delay:.4s;}
.vq-pg-q:nth-child(9){animation-delay:.45s;}
.vq-pg-q:nth-child(10){animation-delay:.5s;}
.vq-pg-q:nth-child(n+11){animation-delay:.55s;}

/* ════════════ IMAGE SEARCH RESULTS ════════════ */
.response-images{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:8px;margin-top:12px;}
.response-image-wrapper{border-radius:10px;overflow:hidden;aspect-ratio:1/1;cursor:pointer;border:1px solid rgba(0,0,0,.06);transition:transform .15s ease,box-shadow .15s ease;}
.response-image-wrapper:hover{transform:translateY(-2px);box-shadow:0 4px 12px rgba(0,0,0,.1);}
.response-image{width:100%;height:100%;object-fit:cover;display:block;}
body[data-chat-dark="1"] .response-image-wrapper{border-color:rgba(255,255,255,.08);}
body[data-chat-dark="1"] .response-image-wrapper:hover{box-shadow:0 4px 12px rgba(0,0,0,.4);}

/* ── Mobile adjustments ── */
@media(max-width:960px){
  body #appAiChatShell .vq-attach-btn{
    width:30px;height:30px;flex:0 0 30px;margin:0 0 0 6px;
  }
  body #appAiChatShell .vq-attach-btn .ms{font-size:18px;}
  .vq-pg-card-actions{flex-wrap:wrap;}
  .vq-pg-q-choices{grid-template-columns:1fr;}
}

