}
#viewResult .result-stat-card.is-correct .result-stat-icon{ color:#16a34a; background:#f0fbf4; }
#viewResult .result-stat-card.is-wrong .result-stat-icon{ color:#dc3545; background:#fff3f4; }
#viewResult .result-stat-card.is-streak .result-stat-icon{ color:#ea580c; background:#fff7ed; }
#viewResult .result-stat-card.is-time .result-stat-icon{ color:#2563eb; background:#eff6ff; }
#viewResult .result-section,
#viewResult .result-review-section{
