  cursor:pointer;
}
#viewResult .result-review-filter-btn.is-active{
  border-color:#cfe0ff !important;
  background:#f5f9ff !important;
  color:#2868ee !important;
}
#viewResult .result-review-list{
  display:grid;
  gap:10px;
  max-height:min(48dvh, 470px);
  overflow:auto;
  padding-right:2px;
}
#viewResult .result-review-item{
  border:1px solid #dfe7f3;
  border-radius:10px;
  background:#ffffff;
  overflow:hidden;
}
#viewResult .result-review-item.review-hidden{
  display:none !important;
}
#viewResult .result-review-item summary{
  min-height:70px;
  display:grid;
  grid-template-columns:92px minmax(0, 1fr) 96px 28px;
  align-items:center;
  gap:14px;
  padding:10px 16px;
  cursor:pointer;
  list-style:none;
}
#viewResult .result-review-item summary::-webkit-details-marker{
  display:none;
}
#viewResult .result-review-num{
  min-height:32px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  padding:0 10px;
  border:1px solid #cfe0ff;
  border-radius:8px;
  background:#f7fbff;
  color:#2868ee;
  font-size:13px;
  font-weight:850;
}
#viewResult .result-review-prompt{
  color:#1c2941;
  font-size:15px;
  font-weight:800;
  line-height:1.55;
}
#viewResult .result-review-badge{
  min-height:30px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  border-radius:8px;
  font-size:12px;
  font-weight:850;
}
#viewResult .result-review-badge.is-correct{ color:#15803d; background:#edf9f1; border:1px solid #c8ead3; }
#viewResult .result-review-badge.is-wrong{ color:#c2414b; background:#fff4f5; border:1px solid #f3c2c9; }
#viewResult .result-review-badge.is-timeout{ color:#b45309; background:#fff7ed; border:1px solid #fed7aa; }
#viewResult .result-review-chevron{
  color:#647089;
  transition:transform .18s ease;
}
#viewResult .result-review-item[open] .result-review-chevron{
  transform:rotate(180deg);
}
#viewResult .result-review-body{
  border-top:1px solid #edf1f7;
  padding:12px 16px 16px;
}
#viewResult .result-review-answer-grid{
  display:grid;
  grid-template-columns:160px 160px minmax(0, 1fr);
  gap:14px;
  align-items:stretch;
}
#viewResult .result-review-answer,
#viewResult .result-review-explain-cell{
  border:1px solid #e5eaf2;
  border-radius:10px;
  padding:10px 12px;
}
#viewResult .result-review-answer span,
#viewResult .result-review-explain-cell span{
  display:block;
  margin-bottom:5px;
  font-size:11px;
  font-weight:900;
}
#viewResult .result-review-answer strong{
  color:#0f1b31;
  font-size:14px;
  line-height:1.45;
}
#viewResult .result-review-answer.is-user{
  border-color:#f3c2c9;
  background:#fff6f7;
}
#viewResult .result-review-answer.is-user span{ color:#dc3545; }
#viewResult .result-review-answer.is-correct-answer{
  border-color:#c8ead3;
  background:#f2fbf5;
}
#viewResult .result-review-answer.is-correct-answer span{ color:#16a34a; }
#viewResult .result-review-explain-cell{
  background:#fbfdff;
}
#viewResult .result-review-explain-cell span{
  color:#53617a;
}
#viewResult .result-review-explain-cell p{
  margin:0;
  color:#4b5870;
  font-size:13px;
  line-height:1.65;
}
#viewResult .result-review-empty{
  min-height:120px;
  display:grid;
  place-items:center;
  gap:6px;
  color:#526079;
  text-align:center;
}
#viewResult .result-review-empty .ms{
  width:48px;
  height:48px;
  display:grid;
  place-items:center;
  border-radius:50%;
  color:#16a34a;
  background:#f0fbf4;
  font-size:28px;
}
#viewResult .result-actions{
  display:grid !important;
  grid-template-columns:1.1fr 1fr 1fr 1fr;
  gap:16px;
  margin-top:0 !important;
}
#viewResult .actions .btn{
  min-height:58px !important;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  padding:0 18px !important;
  text-align:center;
}
#viewResult .actions .btn .label{
  font-size:16px;
  font-weight:900;
}
#viewResult .actions .btn .desc{
  display:none;
}
#viewResult .actions .btn .ms{
  color:#386bda;
  font-size:22px;
}
#viewResult .actions .btn.primary .ms{
  color:#ffffff;
}
@media (max-width: 980px){
  #viewQuiz.active,
  #viewResult.active{
    padding:14px 14px 22px !important;
  }
  #viewQuiz .quiz-header{
    grid-template-columns:1fr;
    gap:12px;
  }
  #viewQuiz .quiz-home-btn{
    justify-self:start;
  }
  #viewQuiz .progress{
    justify-content:flex-start;
    width:100%;
  }
  #viewQuiz .quiz-progress-track{
    width:100%;
  }
  #viewQuiz .quiz-top-chips{
    justify-content:flex-start;
  }
  #viewQuiz .quiz-question-card,
  #viewQuiz .controls,
  #viewResult .result-dashboard{
    width:100%;
  }
  #viewQuiz .quiz-question-card{
    padding:30px 24px !important;
  }
  #viewResult .result-hero-card{
    grid-template-columns:1fr;
    gap:18px;
  }
  #viewResult .result-hero-divider{
    width:100%;
    height:1px;
  }
  #viewResult .result-meta-chips{
    justify-self:start;
  }
  #viewResult .result-stat-grid,
  #viewResult .result-breakdown-grid,
  #viewResult .result-actions{
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }
  #viewResult .result-review-answer-grid{
    grid-template-columns:1fr;
  }
}
@media (max-width: 620px){
  #viewQuiz .quiz-top-chips{
    display:grid;
    grid-template-columns:repeat(2, minmax(0, 1fr));
    width:100%;
  }
  #viewQuiz .pill,
  #viewQuiz #quizExitBtn{
    width:100%;
  }
  #viewQuiz .prompt{
    font-size:22px !important;
  }
  #viewQuiz .choice-btn{
    min-height:68px !important;
    grid-template-columns:48px minmax(0, 1fr) 22px;
    gap:12px;
    padding:11px 12px !important;
  }
  #viewQuiz .choice-btn .k{
    width:40px !important;
    height:40px !important;
  }
  #viewQuiz .choice-text{
    font-size:16px;
  }
  #viewQuiz .controls,
  #viewQuiz .controls .left,
  #viewQuiz .controls .right{
    display:grid !important;
    width:100%;
