  }
  #viewQuiz .controls{
    grid-template-columns:1fr;
  }
  #viewQuiz .controls .left,
  #viewQuiz .controls .right{
    grid-template-columns:1fr 1fr;
  }
  #viewQuiz .controls :is(.navbtn, .cta){
    min-width:0;
    width:100%;
    padding:0 12px !important;
  }
  #viewQuiz .hint{
    font-size:12px !important;
  }
  #viewResult .result-hero-card,
  #viewResult .result-section,
  #viewResult .result-review-section{
    padding:18px 16px;
  }
  #viewResult .result-hero-metrics,
  #viewResult .result-stat-grid,
  #viewResult .result-breakdown-grid,
  #viewResult .result-actions{
    grid-template-columns:1fr;
  }
  #viewResult .result-hero-metric{
    border-left:0;
    border-top:1px solid #e5eaf2;
    padding-top:12px;
  }
  #viewResult .result-review-header{
    align-items:flex-start;
    flex-direction:column;
  }
  #viewResult .result-review-controls,
  #viewResult .result-review-filter,
  #viewResult .result-review-bulk{
    width:100%;
  }
  #viewResult :is(.result-review-filter-btn, .result-review-bulk-btn){
    flex:1;
  }
  #viewResult .result-review-item summary{
    grid-template-columns:78px minmax(0, 1fr) 24px;
  }
  #viewResult .result-review-badge{
    grid-column:2;
    justify-self:start;
  }
  #viewResult .result-review-chevron{
    grid-column:3;
    grid-row:1 / span 2;
  }
}


/* Switch Mode: scoped additions only */
.hv3-tile--switch .hv3-tile-icon{
  background:linear-gradient(135deg,#eaf2ff,#ffffff);
  color:#2563eb;
}
.hv3-tile--switch .hv3-tile-count{
  color:#2563eb;
}
#viewSwitch{
  width:100%;
  min-height:calc(100vh - 92px);
  min-height:calc(100dvh - 92px);
  padding:34px clamp(16px,4vw,54px) 42px;
  background:linear-gradient(180deg,#f8fbff 0%,#ffffff 48%,#f6f8fb 100%);
  color:#10203f;
  overflow-x:hidden;
}
.vq-switch-shell{
  width:min(100%,1180px);
  margin:0 auto;
}
.vq-switch-top{
  display:grid;
  grid-template-columns:minmax(220px,1fr) minmax(260px,560px) minmax(120px,1fr);
  align-items:end;
  gap:24px;
  margin-bottom:26px;
}
.vq-switch-title h1{
  margin:0;
  font-size:clamp(34px,4vw,54px);
  line-height:1;
  letter-spacing:0;
  color:#10203f;
}
.vq-switch-title p{
  margin:12px 0 0;
  font-size:clamp(16px,1.8vw,22px);
  color:#6b7894;
  font-weight:700;
}
.vq-switch-progress{
  display:grid;
  gap:12px;
}
.vq-switch-progress-text{
  font-size:18px;
  color:#3a4761;
  font-weight:700;
}
.vq-switch-progress-text b{
  color:#2563eb;
}
.vq-switch-progress-track{
  height:10px;
  border-radius:999px;
  background:#e4eaf3;
  overflow:hidden;
}
.vq-switch-progress-fill{
  height:100%;
  width:0%;
  border-radius:999px;
  background:linear-gradient(90deg,#2563eb,#1d6df2);
  transition:width .22s ease-out;
}
.vq-switch-card,
.vq-switch-result-card{
  background:rgba(255,255,255,.94);
  border:1px solid rgba(33,64,120,.12);
  border-radius:24px;
  box-shadow:0 14px 40px rgba(16,32,63,.08);
  padding:clamp(24px,4vw,42px);
}
.vq-switch-pill{
  display:inline-flex;
  align-items:center;
  gap:10px;
  min-height:38px;
  padding:0 18px;
  border-radius:999px;
  background:#eaf2ff;
  color:#2563eb;
  font-size:16px;
  font-weight:800;
}
.vq-switch-instruction{
  margin:28px 0 18px;
  font-size:20px;
  color:#2a3852;
  font-weight:700;
}
.vq-switch-prompt{
  border:1px solid rgba(37,99,235,.22);
  border-radius:16px;
  background:#fbfdff;
  padding:28px 24px;
  text-align:center;
  font-size:clamp(24px,3vw,36px);
  line-height:1.55;
  font-weight:800;
  color:#202b42;
}
.vq-switch-section-title{
  margin:34px 0 16px;
  display:flex;
  align-items:baseline;
  gap:10px;
  color:#17233b;
  font-size:20px;
  font-weight:900;
}
.vq-switch-section-title span{
  color:#7b88a3;
  font-size:16px;
  font-weight:700;
}
.vq-switch-slots,
.vq-switch-bank{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(150px,1fr));
  gap:18px;
}
.vq-switch-slot,
.vq-switch-token{
  min-height:70px;
  border-radius:14px;
  border:1px solid rgba(33,64,120,.14);
  background:#fff;
  color:#17233b;
  box-shadow:0 6px 18px rgba(16,32,63,.07);
  display:flex;
  align-items:center;
  justify-content:center;
  gap:12px;
  padding:14px 18px;
  font-size:20px;
  font-weight:800;
  cursor:pointer;
  transition:transform .16s ease, border-color .16s ease, box-shadow .16s ease, background .16s ease;
}
.vq-switch-slot{
  border-style:dashed;
  border-color:rgba(37,99,235,.45);
  color:#2563eb;
  box-shadow:none;
}
.vq-switch-slot.is-filled{
  border-style:solid;
  border-color:rgba(33,64,120,.16);
  color:#17233b;
  box-shadow:0 6px 18px rgba(16,32,63,.07);
}
.vq-switch-token:hover,
.vq-switch-slot.is-filled:hover{
  transform:translateY(-2px);
  border-color:rgba(37,99,235,.42);
  box-shadow:0 12px 26px rgba(16,32,63,.1);
}
.vq-switch-order{
  min-width:30px;
  height:30px;
  border-radius:999px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  background:#edf4ff;
  color:#2563eb;
  font-size:16px;
}
.vq-switch-divider{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:18px;
  margin:30px 0 24px;
  color:#7b88a3;
  font-weight:800;
}
.vq-switch-divider::before,
.vq-switch-divider::after{
  content:"";
  height:1px;
  background:#e5eaf2;
  flex:1;
}
.vq-switch-feedback{
  margin:24px 0;
  min-height:34px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  color:#7b88a3;
  font-size:18px;
  font-weight:800;
}
.vq-switch-feedback.is-correct{
  color:#16a34a;
}
.vq-switch-feedback.is-wrong{
  color:#dc2626;
}
.vq-switch-bank-empty{
  grid-column:1/-1;
  min-height:72px;
  border-radius:14px;
  border:1px dashed rgba(33,64,120,.18);
  display:flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  color:#7b88a3;
  font-size:18px;
  font-weight:800;
}
.vq-switch-actions,
.vq-switch-result-actions{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:18px;
  margin-top:36px;
}
.vq-switch-action-left{
  display:flex;
  gap:14px;
  flex-wrap:wrap;
}
.vq-switch-btn{
  min-height:54px;
  border-radius:14px;
  border:1px solid rgba(33,64,120,.12);
  background:#fff;
  color:#26344f;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  padding:0 26px;
  font-size:17px;
  font-weight:900;
  box-shadow:0 6px 16px rgba(16,32,63,.06);
  cursor:pointer;
}
.vq-switch-btn.primary{
  background:#2563eb;
  color:#fff;
  border-color:#2563eb;
  box-shadow:0 12px 24px rgba(37,99,235,.22);
  min-width:190px;
}
.vq-switch-result-card{
  display:grid;
  gap:24px;
}
.vq-switch-score{
  text-align:center;
  display:grid;
  justify-items:center;
  gap:10px;
}
.vq-switch-score-icon{
  width:84px;
  height:84px;
  border-radius:999px;
  background:#22c55e;
  color:#fff;
  display:grid;
  place-items:center;
  box-shadow:0 14px 30px rgba(34,197,94,.22);
}
.vq-switch-result-card.is-wrong .vq-switch-score-icon{
  background:#ef4444;
  box-shadow:0 14px 30px rgba(239,68,68,.18);
}
#viewSwitch .vq-switch-result.is-wrong .vq-switch-score-icon{
  background:#ef4444;
  box-shadow:0 14px 30px rgba(239,68,68,.18);
}
.vq-switch-score-icon .ms{
  font-size:48px;
}
.vq-switch-score-main{
  font-size:clamp(38px,5vw,62px);
  color:#10203f;
  font-weight:900;
}
.vq-switch-score-rate{
  font-size:clamp(34px,4vw,54px);
  color:#2563eb;
  font-weight:900;
}
.vq-switch-score-message{
  color:#6b7894;
  font-size:20px;
  font-weight:700;
}
.vq-switch-review-list{
  display:grid;
  gap:14px;
}
.vq-switch-review,
.vq-switch-summary-item{
  border:1px solid rgba(33,64,120,.12);
  border-radius:16px;
  background:#fff;
  padding:16px 18px;
}
.vq-switch-review p,
.vq-switch-summary-body p{
  margin:6px 0 0;
  font-size:18px;
  line-height:1.65;
  color:#26344f;
  font-weight:700;
}
.vq-switch-review-label{
  color:#64748b;
  font-size:14px;
  font-weight:900;
}
.vq-switch-review.is-good,
.vq-switch-review.is-answer{
  background:#f0fdf4;
  border-color:#bbf7d0;
}
.vq-switch-review.is-bad{
  background:#fff1f2;
  border-color:#fecdd3;
}
.vq-switch-review strong{
  display:inline-flex;
  margin-top:8px;
  color:#16a34a;
}
.vq-switch-review.is-bad strong{
  color:#dc2626;
}
.vq-switch-summary-item summary{
  cursor:pointer;
  display:grid;
  grid-template-columns:auto 1fr auto;
  gap:14px;
  align-items:center;
  color:#10203f;
}
.vq-switch-summary-item summary span{
  color:#2563eb;
  background:#eaf2ff;
  border-radius:10px;
  padding:6px 10px;
  font-weight:900;
}
.vq-switch-summary-item summary em{
  font-style:normal;
  color:#16a34a;
  font-weight:900;
}
.vq-switch-summary-item.is-wrong summary em{
  color:#dc2626;
}
.vq-switch-summary-body{
  display:grid;
  gap:8px;
  margin-top:14px;
  padding-top:14px;
  border-top:1px solid #e5eaf2;
}
.vq-switch-summary-body b{
  display:inline-flex;
  min-width:110px;
  color:#64748b;
}
.app-preset-engine-tile-art.mode-switch{
  background:
    linear-gradient(90deg,transparent 0 20%,rgba(99,102,241,.22) 20% 26%,transparent 26% 48%,rgba(99,102,241,.28) 48% 54%,transparent 54% 76%,rgba(99,102,241,.22) 76% 82%,transparent 82%),
    radial-gradient(circle at 28% 50%,rgba(99,102,241,.88) 0 9px,transparent 10px),
    radial-gradient(circle at 52% 50%,rgba(99,102,241,.68) 0 9px,transparent 10px),
    radial-gradient(circle at 76% 50%,rgba(99,102,241,.48) 0 9px,transparent 10px);
}
.app-preset-engine-switch-edit{
  margin:0 0 18px;
  padding:16px;
  border:1px solid var(--border);
  border-radius:var(--radius-lg,18px);
  background:linear-gradient(180deg,rgba(99,102,241,.08),rgba(255,255,255,.92));
  box-shadow:var(--shadow-soft,0 8px 24px rgba(15,23,42,.06));
}
.app-preset-engine-switch-edit-head{
  display:flex;
  gap:12px;
  align-items:flex-start;
  margin-bottom:14px;
}
.app-preset-engine-switch-edit-head > .ms{
  width:36px;
  height:36px;
  border-radius:12px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  color:var(--primary);
  background:var(--primary-light);
}
.app-preset-engine-switch-edit-head strong{
  display:block;
  color:var(--text);
  font-weight:800;
}
.app-preset-engine-switch-edit-head p{
  margin:4px 0 0;
  color:var(--muted);
  font-size:12px;
  line-height:1.7;
}
#viewSwitch .vq-switch-title-block h2{
  margin:0;
  font-size:clamp(32px,4vw,52px);
  line-height:1;
  color:var(--text);
  letter-spacing:0;
}
#viewSwitch .vq-switch-title-block p{
  margin:12px 0 0;
  color:var(--muted);
  font-weight:700;
}
#viewSwitch #switchProgressFill{
  display:block;
  height:100%;
  width:0%;
  border-radius:999px;
  background:var(--primary);
  transition:width .22s ease-out;
}
#viewSwitch .vq-switch-mode-pill{
  display:inline-flex;
  align-items:center;
  gap:8px;
  min-height:34px;
  padding:0 14px;
  border-radius:999px;
  color:var(--primary);
  background:var(--primary-light);
  font-weight:800;
}
#viewSwitch .vq-switch-answer-head,
#viewSwitch .vq-switch-bank-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  margin:28px 0 14px;
  color:var(--text);
  font-weight:800;
}
#viewSwitch .vq-switch-answer-head span,
#viewSwitch .vq-switch-bank-head span{
  color:var(--muted);
  font-size:13px;
}
#viewSwitch .vq-switch-bank-head::before,
#viewSwitch .vq-switch-bank-head::after{
  content:"";
  flex:1;
  height:1px;
  background:var(--border);
}
#viewSwitch .vq-switch-actions-left{
  display:flex;
  gap:12px;
  flex-wrap:wrap;
}
#viewSwitch .vq-switch-result{
  background:var(--surface);
  border:1px solid var(--border);
  border-radius:var(--radius-lg,20px);
  box-shadow:var(--shadow,0 14px 40px rgba(15,23,42,.08));
  padding:clamp(22px,4vw,38px);
  display:grid;
  gap:18px;
}
#viewSwitch .vq-switch-result.hidden{
  display:none;
}
#viewSwitch .vq-switch-score-card{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:22px;
  text-align:left;
  padding:18px;
  border-radius:var(--radius-lg,20px);
  background:linear-gradient(180deg,rgba(99,102,241,.06),rgba(255,255,255,.92));
}
#viewSwitch .vq-switch-review-card{
  border:1px solid var(--border);
  border-radius:var(--radius-lg,20px);
  background:var(--surface);
  padding:18px;
}
@media(max-width:900px){
  #viewSwitch{
    padding:22px 14px 30px;
  }
  .vq-switch-top{
    grid-template-columns:1fr;
    align-items:start;
    gap:18px;
  }
  .vq-switch-card,
  .vq-switch-result-card{
    border-radius:20px;
    padding:22px 16px;
  }
  .vq-switch-slots,
  .vq-switch-bank{
    grid-template-columns:1fr;
    gap:12px;
  }
  .vq-switch-slot,
  .vq-switch-token{
    min-height:58px;
    font-size:17px;
  }
  .vq-switch-actions,
  .vq-switch-result-actions{
    flex-direction:column;
    align-items:stretch;
  }
  .vq-switch-action-left,
  #viewSwitch .vq-switch-actions-left{
    display:grid;
    grid-template-columns:1fr 1fr;
  }
  .vq-switch-btn,
  .vq-switch-btn.primary{
    width:100%;
    min-width:0;
  }
  .vq-switch-prompt{
    font-size:22px;
    padding:22px 14px;
  }
  .vq-switch-summary-item summary{
    grid-template-columns:1fr;
    align-items:start;
  }
}

